\subsubsection{State designs with bounded relative error}
%
%
%
%
%
%
%
%
%
%
%

In Sec.~\ref{sec:rel_error_state}, we provide a construction for a state designs with bounded relative error (defined in Eq.~\eqref{eq:def_state_relative}) using low-depth circuits.
\begin{theorem*}[Relative-error state designs from low-depth Clifford unitaries followed by constant depth magic gates]
Consider a state ensemble $\calE = \{UV\ket{0}^{\otimes N}\}$ generated by the circuit architecture below
\begin{equation*}
\includegraphics[width=10.8cm]{Figure/state_relative_log_depth.pdf}
\end{equation*}
Here, $U$ is a product of random unitaries drawn from exact unitary $k$-designs acting on disjoint qubit clusters of size $\ell$. 
%
The two-layer Clifford unitary $V$ consists of Clifford gates acting on $2\xi$ qubits. 
%
Each Clifford gate is drawn independently from an exact Clifford $k$-design.  On an $N$ qubit system with $N=\omega(k^2+\log(1/\epsilon))$, the ensemble $\calE$ can form a state $k$-design with $\epsilon$ relative error for $\xi=O(\log(N/\epsilon)+k^2)$ and $\ell=O(k\log k)$.
\end{theorem*}


%
%
%
%



%

In Sec.~\ref{sec:rel_error_nogo}, we prove no-go theorems for state $k$-design with bounded relative error. 
%
In particular, we show that a state ensemble generated by Clifford gates acting on matrix product states with a low bond dimension or general short-range entangled states prepared by finite-depth local unitaries in any dimension cannot form a state $k$-design with bounded relative error for $k \geq 4$.
%
The key observation is that the stabilizer R\'enyi entropy of these states is not close enough to that of Haar random states as required by a small relative error.
\begin{theorem*}
Consider an ensemble of states $\calE = \{V\ket{\psi}\}$, where $V$ is a Clifford unitary.
\begin{itemize}
    \item For $\ket{\psi}$ being matrix product states with bond dimension $D$, the state ensemble cannot form a state $k$-design for $k\geq 4$ with $\epsilon$ relative error for $D=\tilde{o}(\sqrt{N/\epsilon})$.
    \item For $\ket{\psi}$ being states prepared by $d$-dimensional local unitary circuits of depth $t$, the ensemble cannot form a state $k$-design with $\epsilon$ relative error for $t = \tilde{o}((\log(N/\epsilon))^{1/d})$.
\end{itemize}
\end{theorem*}


