\section{Preliminaries}\label{sec:prelim}
In this section, we first review the definition of state and unitary $k$-design and their approximation up to additive and relative errors.
%
We then review the algebraic structure of the Clifford commutant.

\subsection{Approximate unitary designs}\label{sec:prelim_design_unitary}
We 
define the $k$-fold channel $\Phi^{(k)}\left( \cdot \right)$ for an ensemble $\calE$ of unitary gates as follows, 
\begin{equation}
\Phi_\calE^{(k)}\left( \cdot \right):=\Ens_{U\sim\calE}\ U^{\otimes k}\left( \cdot \right) U^{\dagger\otimes k}.
\end{equation}
\begin{definition}[Approximate unitary design with bounded additive error]
The ensemble $\calE$ forms an approximate unitary $k$-design with $\epsilon$ {\bf additive} error if
\begin{equation}
\lVert\Phi^{(k)}_\calE-\Phi^{(k)}_{\H}\rVert_\Diamond\leq \epsilon,
\end{equation}
where $\Phi^{(k)}_{\H}$ is the $k$-fold channel associated with the Haar random unitary ensemble.
\end{definition}
The diamond norm $\lVert\cdot\rVert_\Diamond$ for superoperators is defined as follows~\cite{Aharonov:1998zf}:
\begin{equation}
\lVert \Phi \rVert_\Diamond:=\lVert \Phi \otimes \id\rVert_{1\rightarrow 1} :=\max_{\lVert O\rVert_1\leq 1}\lVert [\Phi\otimes\id](O)\rVert_1,
\end{equation}
Here, the superoperator $\Phi$ and the identity channel $\id$ act on operators in the Hilbert space $\calH$ and a second Hilbert space $\calH'$ with the same dimension as $\calH$, respectively~\footnote{We note that $\lVert \Phi \otimes \id\rVert_{1\rightarrow 1}$ is independent of $\calH'$ as long as $\dim{\calH'}\geq \dim{\calH}$.}.
%
%
%
%

Operationally, the diamond norm bounds the additive distinguishability of two channels. For any input density matrix $\rho$ on the Hilbert space $\calH \otimes \calH'$,
\begin{equation}
 \lVert [\Phi_1\otimes \id](\rho)-[\Phi_2\otimes \id](\rho)\rVert_1 \leq \lVert\Phi_1-\Phi_2\rVert_\Diamond,
\label{def add}
\end{equation}
where $\Phi_{1,2}$ and $\id$ act on operators in $\calH$ and $\calH'$, respectively. %
%
%
%
The trace distance is, in turn, related to the success probability of distinguishing two density matrices, $p_{\text{succ}} = 1/2 + \lVert \rho_1 - \rho_2\rVert_1/2$, by the Holevo-Helstrom theorem~\cite{wilde2013quantum}.
%
%
%



\begin{definition}[Approximate unitary design with bounded relative error~\cite{Brandao:2012zoj}]
The unitary ensemble $\calE$ is an approximate unitary $k$-design with $\epsilon$ {\bf relative} error if
\begin{equation}
(1-\epsilon)\Phi^{(k)}_{\H}\preceq \Phi^{(k)}_\calE\preceq(1+\epsilon)\Phi^{(k)}_{\H},
\label{def rel}
\end{equation}
where ``$\preceq$" is the semidefinite ordering between channels: $\Phi_1\preceq\Phi_2$ iff $\Phi_2-\Phi_1$ is a completely positive map.
\end{definition}
In our detailed proofs, we always work with an equivalent formulation of the semidefinite ordering $\Phi_1\preceq\Phi_2$ in terms of the operator inequality below,
\begin{equation}
[\Phi_1\otimes \id](P_{\EPR})\preceq [\Phi_2\otimes \id](P_{\EPR}),
\end{equation}
where $P_{\EPR}$ is the density matrix of EPR states between $\calH$ and $\calH'$~\footnote{Here is a brief explanation. A completely positive channel $\Phi_2-\Phi_1$ maps positive operators to positive operators. When acting on the positive operator $P_{\EPR}$, the resulting operator $[(\Phi_2-\Phi_1)\otimes \id](P_{\EPR})\succeq 0$ is positive. To prove the other direction, the positivity of $[(\Phi_2-\Phi_1)\otimes \id](P_{\EPR})$ implies $(\Phi_2-\Phi_1)(\ketbra{\psi})$ being a positive operator $\forall \ket{\psi}$. Hence, $\Phi_2-\Phi_1$ is a semi-positive map.}.



A $k$-design with bounded relative error has the following operational significance.  First, given a state $\rho$ on $\calH\otimes\calH'$, the probabilities for measurement outcomes on the states $[\Phi_{\calE}^{(k)}\otimes \id](\rho)$ and $[\Phi_{\H}^{(k)}\otimes \id](\rho)$ only differ by a small \emph{multiplicative} factor. 
%
This setup describes quantum experiments where a unitary $U$ drawn from an appropriate ensemble can be queried $k$ times in parallel.  
%
However, a bounded relative error also implies that in a more general adaptive quantum experiment, where $k$ separate queries are made to a unitary $U$, the output states when $U$ is sampled from $\calE$ or from the Haar ensemble are only separated by $2\epsilon$ in trace-distance~\cite{Schuster:2024ajb}.



We remark that relative error is a stronger notion than additive error; an approximate $k$-design with bounded relative error is necessarily an approximate $k$-design with bounded additive error\footnote{Here, we provide an explicit derivation. Assume $\Phi_\calE^{(k)}$ is within $\epsilon$ relative error of $\Phi^{(k)}_{\H}$. We have
\begin{equation}
\begin{aligned}
\lVert \Phi_\calE^{(k)} - \Phi_{\H}^{(k)}\rVert_\Diamond&=\max_{\lVert O\rVert_1\leq 1}\lVert (\Phi_\calE - \Phi_{\H})\otimes \id (O)\rVert_1=2\max_{\lVert O\rVert_1\leq 1}\max_{0\leq M\leq 1}\Tr M[(\Phi_\calE - \Phi_{\H})\otimes \id](O)\\
&\le2\epsilon\max_{\lVert O\rVert_1\leq 1}\max_{0\leq M\leq 1}\abs{\Tr M[\Phi_{\H}\otimes \id](O)}
\leq 2\epsilon \max_{\lVert O\rVert_1\leq 1}\lVert [\Phi_{\H}\otimes \id](O)\rVert_1 \\
&\le2\epsilon\max_{\lVert O\rVert_1\leq 1}\Ens_{U\sim\H}\lVert (U^{\otimes k}\otimes I)O(U^{\dagger \otimes k}\otimes I)\rVert_1=2\epsilon\max_{\lVert O\rVert_1\leq 1}\lVert O\rVert_1=2\epsilon.
\end{aligned}
\end{equation}
The last inequality follows from the convexity of the trace norm.}, though the converse is not necessarily true~\cite{Brandao:2012zoj}. 


In this work, we also consider approximate Clifford $k$-designs, which are defined with respect to the distance from the $k$-fold channel of random Clifford unitaries, $\Phi^{(k)}_{\C}(\cdot) := \Ens_{V\sim\C} V^{\otimes k}(\cdot)V^{\dagger\otimes k}$.

\subsection{Approximate state designs}\label{sec:prelim_design_state}
We define the $k$-th moment of an ensemble $\calE = \{\ket{\psi}\}$ of quantum states  as follows
\begin{equation}
\rho_{\calE}^{(k)} = \Ens_{\psi \sim \calE} \ketbra{\psi}^{\otimes k}.
\end{equation}
\begin{definition}[Approximate state design with bounded additive error]
A state ensemble $\calE = \{\ket{\psi}\}$ forms an approximate state $k$-design with $\epsilon$ additive error if
\begin{equation}
\lVert\rho_\calE^{(k)}-\rho_{\H}^{(k)}\rVert_1\leq \epsilon,
\end{equation}
where $\rho_{\H}^{(k)}$ is the $k$-th moment of the Haar ensemble. 
\end{definition}

We note that the $k$-th moment of the Haar random ensemble takes the explicit form $\rho_{\H}^{(k)}=\frac{1}{d_{\sym}}P_{\sym}$, where $P_{\sym}$ is the projection onto the permutation symmetric subspace of the replicated Hilbert space $\calH^{\otimes k}$, and $d_{\sym} = \binom{d+k-1}{k}$ is the dimension of this subspace, with $d = \dim \calH$.

Operationally, an ensemble $\calE$ being a state $k$-design with $\epsilon$ additive error implies that, for any algorithm that makes $k$ queries of the state $\ket{\psi}$, the output state when $\ket{\psi}$ is sampled from $\calE$ or from an exact $k$-design is at most $\epsilon$ in trace distance (see Appendix~\ref{app:operation_state_additive_error}). 
%
%
%
%
%
While the trace norm is often challenging to compute, it is upper-bounded by the two-norm, which is directly related to the \emph{frame potential}
\begin{equation}
\lVert \rho_\calE^{(k)}-\rho_{\H}^{(k)}\rVert_1\leq \sqrt{d^k}\lVert \rho_\calE^{(k)}-\rho_{\H}^{(k)}\rVert_2 = \sqrt{d^k\big(F_\calE^{(k)}-F_H^{(k)}\big)}.
\end{equation}
where the frame potential for an ensemble of states $\calE$ is defined as
\begin{align}
    F_{\calE}^{(k)} = \Ens_{\psi,\phi \sim \calE} \abs{\braket{\psi}{\phi}}^{2k}.
\end{align}
For the Haar ensemble, the frame potential is given by $F_{\H}^{(k)}=1/d_{\sym}\approx k!/d^k$ for large $d$.
%


We note that an ensemble $\{U\}$ forming a unitary $k$-design with $\epsilon$ additive error implies that $\calE = \{U \ket{0}^{\otimes N}\}$ forms a state
$k$-design with $\epsilon$ additive error because
\begin{align}
\lVert \rho_\calE^{(k)}-\rho_{\H}^{(k)}\rVert_1=\lVert(\Phi_{\calE}^{(k)}-\Phi_{\H}^{(k)})(\ketbra{0}^{\otimes N})\rVert_1\le\lVert\Phi_{\calE}^{(k)}-\Phi_{\H}^{(k)}\rVert_\Diamond\le\epsilon.
%
\end{align} 



In this work, we also consider approximate stabilizer state $k$-designs, which are defined according to the trace distance from the $k$-th moment of random stabilizer states
\begin{equation}
    \rho_{\C}^{(k)} := \Ens_{\psi\sim\C}\ketbra{\psi}^{\otimes k}.
\end{equation}
The notation $\Ens_{\psi\sim\C}$ means averaging over random stabilizer states.



\begin{definition}[Approximate state design with bounded relative error]
A state ensemble $\calE = \{\ket{\psi}\}$ forms an approximate state $k$-design with $\epsilon$ relative error if
\begin{equation}
(1-\varepsilon)\rho_{\H}^{(k)}\preceq \rho_\calE^{(k)}\preceq(1+\varepsilon)\rho_{\H}^{(k)}.\label{eq:approx_state_design_multp_error}
\end{equation}
where $\rho_1 \preceq \rho_2$ denotes that $\rho_2 - \rho_1$ is a positive semidefinite operator.
\end{definition}

The operational meaning of this definition is that there is only a small, multiplicative error between the probability of any given measurement outcome in $\rho_{\H}^{(k)}$ or in $\rho_{\calE}^{(k)}$.

A sufficient condition that guarantees  \eqref{eq:approx_state_design_multp_error}, is $\lVert \rho_\calE^{(k)}-\rho_{\H}^{(k)}\rVert_\infty\leq \binom{d+k-1}{k}^{-1}\varepsilon$.  This is because $\rho_\calE^{(k)}$ is supported only on the permutation symmetric subspace for any ensemble $\calE$, as this operator commutes with any permutation. Furthermore, $\rho_{\H}^{(k)}$ is the maximally mixed state in this subspace, with eigenvalues $\binom{d+k-1}{k}^{-1}$.

We make a few remarks. 
%
First, if the ensemble $\{U\}$ forms a unitary $k$-design within $\epsilon$ relative error, then $\calE = \{U \ket{0}\}$ forms a state $k$-design within $\epsilon$ relative error because
\begin{equation}
(1+\epsilon)\Phi_{\H}^{(k)}-\Phi_{\calE}^{(k)}\succeq 0\quad\Rightarrow\quad (1+\epsilon)\rho_{\H}^{(k)}-\rho_{\calE}^{(k)}=[(1+\epsilon)\Phi_{\H}^{(k)}-\Phi_{\calE}^{(k)}](\ketbra{0}^{\otimes N})\succeq 0.
\end{equation}
Similarly, $\Phi_{\calE}^{(k)} - (1-\epsilon)\Phi_{\H}^{(k)}\succeq 0$ implies the operator inequality $\rho_{\calE}^{(k)}-(1-\epsilon)\rho_{\H}^{(k)}\succeq 0$.
%
Second, a state $k$-design with $\epsilon$ relative error is also a $k$-design with bounded additive error
\begin{align}
    \onenormsm{\rho_{\calE}^{(k)} - \rho_{\H}^{(k)}} &= \max_{0\preceq M_+,M_-\preceq 1} \Tr\left(M_+ (\rho_\calE^{(k)} - \rho_{\H}^{(k)})\right) - \Tr\left(M_-(\rho_\calE^{(k)} - \rho_{\H}^{(k)})\right) \nn\\
    &\leq \epsilon \max_{0\preceq M_+\preceq 1}\Tr\left(M_+ \rho_{\H}^{(k)}\right) + \epsilon \max_{0\preceq M_-\preceq 1}\Tr\left(M_-\rho_{\H}^{(k)}\right) = 2\epsilon.
\end{align}

\subsection{Commutant of Clifford tensor powers}\label{sec:prelim_clifford}

In this section, we review the theory of the commutant of Clifford tensor powers -- the space of operators which commute with the $k$-fold tensor power of any Clifford unitary --  as developed in Ref.~\cite{Gross_2021}. This commutant naturally appears in averages over random Clifford unitaries.
%
We first explain the algebraic structure of the commutant of Clifford tensor powers and then provide formulae for averages over random Clifford unitaries and random stabilizer states, which will be used in this work.
%
We restrict our attention to the Clifford group over qubits.

Operators in the commutant of the $k$-th tensor power of the Clifford group are labeled by {stochastic Lagrangian subspaces}, a linear space defined below.
\begin{definition}[Stochastic Lagrangian subspace]
A linear subspace $T\subseteq \mathbb{Z}_2^{2k}$ is a stochastic Lagrangian subspace iff
\begin{enumerate}
\item $\boldx\cdot\boldx-\boldy\cdot\boldy=0$ mod $4$, $\forall (\boldx,\boldy)\in T$.
\item $\dim T=k$.
\item $\boldone_{2k}:=(\underbrace{1,\cdots,1}_{2k})\in T$.
\end{enumerate}
\end{definition}
We use $\Sigma_{k,k}$ to denote the set of all stochastic Lagrangian subspaces $T\subseteq \mathbb{Z}_2^{2k}$.
%
For each $T$, we have an associated operator in the commutant
\begin{equation}
\mathrm{r}(T)=\sum_{(\boldx,\boldy)\in T}\ket{\boldx}\bra{\boldy},\qquad \ket{\boldx}:=\bigotimes_{i=1}^k\ket{x_i}.
\end{equation}
For a system $S$ with $n$ qubits,
\begin{equation}
r(T)_S:=\mathrm{r}(T)^{\otimes n}.
\end{equation}
We omit the subscript when $S$ represents the entire system. 
%
 %
%
In this work, we only consider the Clifford tensor powers on the subsystem with $n \geq k - 1$ such that the operators $r(T)$ are linearly independent.
%
The number of such independent operators is $|\Sigma_{k,k}|=\prod_{i=0}^{k-2}(2^i+1)=2^{O(k^2)}$.

The operator $\mathrm{r}(T)$ in the commutant follows the decomposition\footnote{The decomposition of $\mathrm{r}(T)$ stems from the structure of the Clifford commutant. The commutant can be written in terms of the double coset with respect to stochastic rotations, i.e. $\Sigma_{k,k} = O_k T_\mathrm{N_1} O_k \cup \cdots \cup O_k T_{\mathrm{N}_K} O_k$, where $T_{\mathrm{N_1}},\cdots T_{\mathrm{N_K}}$ are stochastic Lagrangian subspace associated with a defect subspace, and $O_k$ is the stochastic rotation group.}:
\begin{equation}
\mathrm{r}(T)=\mathrm{r}(T_{O,1})\mathrm{r}(T_\rmN)\mathrm{r}(T_{O,2}).
\end{equation}
The operator $\mathrm{r}(T_O)$ is a unitary operator, and the subspace $T_O = \{(\boldx,O\boldx), \boldx \in \bbZ_2^k\}$, where $O$ belongs to the stochastic rotation group defined below:
\begin{definition}[Stochastic rotation]
A $k\times k$ matrix $O$ with $\mathbb{Z}_2$-valued entries is a stochastic rotation iff
\begin{itemize}
\item $(O\boldx)\cdot(O\boldx)=\boldx\cdot\boldx$ mod $4$, $\forall\boldx\in\mathbb{Z}_2^k$.
\item $O\boldone_k=\boldone_k$.
\end{itemize}
\end{definition}
The stochastic rotations form a group, denoted as $O_k$, which includes the permutation group $S_k$ as a subgroup.
%
In the Clifford commutant, the operator associated with a stochastic rotation takes the form
\begin{equation}
\mathrm{r}(T_O):=\sum_{\boldx}\ket{O\boldx}\bra{\boldx}.
\end{equation}

The operator $\mathrm{r}(T_\rmN)$ is associated with a defect subspace defined below.
\begin{definition}[Defect subspace]\label{def:defect_subspace}
A linear subspace $\rmN\subseteq\mathbb{Z}_2^k$ is a defect subspace iff
\begin{itemize}
\item $\boldx\cdot\boldx=0 \mod 4$, $\forall\boldx\in \rmN$.
\item $\boldone_k\in \rmN^\perp$, i.e. $\boldx\cdot\boldone_k = 0 \mod 4$, $\forall \boldx \in \rmN$.
\end{itemize}
\end{definition}
Here, $\rmN^\perp$ is the orthogonal complement of the defect subspace $\rmN$ in $\bbZ_2^k$, which includes $\rmN$ as a subspace according to Def.~\ref{def:defect_subspace}.
%
The stochastic Lagrangian subspace $T_\rmN$ is given by $T_\rmN = \{(\boldx,\boldx+\boldy), \boldx\in \rmN^\perp, \boldy \in \rmN\}$.

The operator $r(T_\rmN)$ is proportional to the projection operator $P_{\CSS(\rmN)}$ onto the code space of the CSS code with stabilizers $\langle Z^{\boldu}X^{\boldv},\boldu,\boldv\in \rmN\rangle$:
\begin{equation}
\mathrm{r}(T_\rmN)=2^{\dim\rmN}P_{\CSS(\rmN)}.
\end{equation}
The code space is of dimension $2^{k-2\dim\rmN}$ specified by the stabilizer group with $\abs{\rmN}^2$ elements.
%
%

We are now ready to write down the norm of operators in the Clifford commutant:
\begin{equation}
\lVert \mathrm{r}(T)\rVert_1=2^{k-\dim\rmN},\qquad \lVert\mathrm{r}(T)\rVert_\infty=2^{\dim\rmN}.
\end{equation}
Here, we use the decomposition of $\mathrm{r}(T)$ and the fact that the unitary operators, $\mathrm{r}(T_{O,1})$ and $\mathrm{r}(T_{O,2})$, leave the Schatten norms invariant.

The overlap between two stochastic Lagrangian subspaces $T_{1,2}$ is given by
\begin{equation}
\bbrakket{T_1}{T_2} := \Tr[\mathrm{r}(T_1)^\top \mathrm{r}(T_2)]:=2^{k-|T_1,T_2|}=2^{\dim(T_1\cap T_2)}.
\end{equation}
Here, we introduce the vectorized notation $\kket{T}:=\mathrm{vec}(\mathrm{r}(T)) = \sum_{(\boldx,\boldy)\in T} \ket{\boldx}\otimes\ket{\boldy}$.
%
For two different subspaces $T_1\neq T_2$, $\dim(T_1\cap T_2)\leq k-1$, i.e. $|T_1,T_2|\geq 1$.

The $k$-fold channel associated with the Clifford group considered in this work can be expressed in terms of the operators in the Clifford commutant~\cite{Gross_2021,Li:2021dbh}:
\begin{align}
\Phi_{\C}^{(k)}(\cdot)=\Ens_{V\sim\C}V^{\otimes k}(\cdot)V^{\dagger\otimes k}=&\sum_{T_1,T_2}\Wg_{\C}(T_1,T_2)r(T_1)\Tr[r(T_2)^{\top}(\cdot)] \nn \\
:=&\sum_{T_1,T_2}\Wg_{\C}(T_1,T_2)|T_1)(T_2|(\cdot),\label{eq:clifford_commutant_weingarten_def}
\end{align}
where we assume $n\geq k-1$ such that $r(T)$ are linear independent. The coefficients $\Wg_{\C}(T_1,T_2)$ are called \emph{Clifford Weingarten function} satisfying
\begin{align}
    \sum_{T_2}\Wg_{\C}(T_1,T_2)\Tr[r(T_2)^{\top}r(T_3)]=\delta_{T_1,T_3}.
\end{align}
We introduce the notation $|T_1)(T_2|(\cdot) := r(T_1)\Tr[r(T_2)^{\top}(\cdot)]$, representing a superoperator.
%
The decomposition~\eqref{eq:clifford_commutant_weingarten_def} follows from the properties $[\Phi_{\C}^{(k)}(O),V^{\otimes k}]=0$, and $\Phi_{\C}^{(k)}([O,V^{\otimes k}])=0$ for any operator $O$ and Clifford unitary $V$.

The $k$-th moment of random stabilizer state over $n$ qubits is given by~\cite{Gross_2021}
%
\begin{equation}
\rho_{\C}^{(k)}=\frac{1}{Z_{n,k}}\sum_{T}r(T),
\end{equation}
where the prefactor $Z_{n,k} = 2^n\prod_{i=0}^{k-2}(2^n+2^i)$ and has an upper bound $Z_{n,k}\leq 2^{nk}(1 + k 2^{k-n})$ for $n\geq k+\log k-2$~\cite{Haferkamp:2020qel}.
%

