\section{Uniformity condition}\label{sec:uniformity}
In this section, we introduce the approximate uniformity conditions for the $k$-fold channel of a Clifford unitary ensemble and the $k$-th moment of a stabilizer state ensemble.
%
We show that a two-layer random Clifford circuit with each gate operating on log-size qubit blocks can generate a unitary ensemble that satisfies approximate uniformity.
%
This property guarantees that such circuits, when acting on a product state, can generate a stabilizer state $k$-design with bounded additive error (Corollary~\ref{thm:state_additive_clifford_design}).

\begin{definition}[Approximate uniformity condition for Clifford unitaries]
Let $\calE$ be an ensemble of quantum circuits composed of Clifford gates acting on $N$ qubits. The $k$-fold channel for this circuit ensemble satisfies the $\epsilon$-approximate uniformity condition if 
\begin{itemize}
\item The $k$-fold channel takes the form
\begin{equation}
\Phi^{(k)}_\calE=2^{-Nk}\sum_T|T)(T|+
2^{-Nk}
\sum_{\vec{T}_1,\vec{T_2}}f(\vec{T}_1,\vec{T}_2)|\vec{T}_1)(\vec{T}_2|,\label{eq:channel_uniformity}
\end{equation}
%
%
%
where $\vec{T}$ is a vector that labels the spatial configuration of $T$ for each subregion, $|\vec{T}_1)(\vec{T}_2| = \bigotimes_x|T_{1,x})(T_{2,x}|$ is a tensor product of superoperators over spatial regions labeled by $x$, and $|T)(T|$ is a superoperator associated with a spatially uniform configuration of $T$.
%

\item The deviation from uniformity is bounded by $\epsilon$, i.e. $\Delta(\Phi^{(k)}_\calE) :=\sum_{\vec{T}_1,\vec{T_2}}|f(\vec{T}_1,\vec{T}_2)|\le\epsilon$.
\end{itemize}

\end{definition}

\begin{definition}[Approximate uniformity condition for stabilizer states]
Let $\calE$ be an ensemble of Clifford states on $N$ qubits. The $k$-th moment of this state ensemble satisfies the $\epsilon$-approximate uniformity condition if 
\begin{itemize}
\item The $k$-th moment can be written as
\begin{equation}
\rho^{(k)}_{\calE} =2^{-Nk}\sum_T r(T)+2^{-Nk}\sum_{\vec{T}}f(\vec{T})r(\vec{T}),
\end{equation} 
where $r(\vec{T})=\bigotimes_xr(T_x)$, and $r(T)$ is an operator associated with a spatially uniform configuration of $T$.

\item The deviation from uniformity is bounded by $\Delta(\rho_{\calE}^{(k)}) := \sum_{\vec{T}}|f(\vec{T})|\le\varepsilon$.
\end{itemize}
\end{definition}

The approximate uniformity condition for the unitary ensemble $\calE_u = \{V\}$ implies that the unitary ensemble can generate a state ensemble $\calE_s = \{V\ket{0}^{\otimes N}\}$ with approximate uniformity.
%
Specifically, the $k$-th moment of the state ensemble is given by
\begin{equation}
\rho_{\calE_s}^{(k)}=\Phi_{\calE_u}^{(k)}(\ketbra{0}^{\otimes N})=2^{-Nk}\left[\sum_T r(T)+\sum_{\vec{T}_1,\vec{T_2}}f(\vec{T}_1,\vec{T}_2)r(\vec{T}_1)\right].
\end{equation}
Its deviation from uniformity has an upper bound,
\begin{equation}\label{eq:uniformity_unitary_implies_state}
\Delta(\rho_{\calE_s}^{(k)}) =\sum_{\vec{T}_1}\Big|\sum_{\vec{T_2}}f(\vec{T}_1,\vec{T}_2)\Big|\le\sum_{\vec{T}_1,\vec{T_2}}|f(\vec{T}_1,\vec{T}_2)|=\epsilon.
\end{equation}


