We remark that a state ensemble with approximate uniformity is a state $k$-design with bounded additive error. 
\begin{theorem}\label{thm:uniformity_implies_stabilizer_state_design}
Consider a state ensemble satisfying the $\epsilon$-approximate uniformity condition. The state ensemble forms a stabilizer state design with bounded additive error $\epsilon+k2^{-N+k}$ assuming $N\geq k + \log k - 2$.
\end{theorem}
\begin{proof}
The $k$-th moment of the state ensemble with approximate uniformity is given by
\begin{align}
    \rho^{(k)}_{\calE} =2^{-Nk}\left[\sum_T r(T)+\sum_{\vec{T}}f(\vec{T})r(\vec{T})\right].
\end{align}
The additive error has an upper bound (assuming $N\geq k + \log k - 2$)
\begin{equation}
\lVert\rho_\calE^{(k)}-\rho_{\C}^{(k)}\rVert_1\leq |2^{-Nk}Z_{N,k}-1|\cdot\lVert\rho_{\C}^{(k)}\rVert_1+2^{-Nk}\sum_{\vec{T}}|f(\vec{T})|\cdot\lVert r(\vec{T})\rVert_1 \leq k2^{-N+k}+\epsilon,
\end{equation}
where we use the triangle inequality, and the bound on the trace norm $\onenormsm{\mathrm{r}(T)} = 2^{k - \dim\rmN} \leq 2^k$.
%
\end{proof}

Although the approximate uniformity in general does not imply the ensemble to form designs under other approximation measures, it is a crucial property that allows one to convert the ensemble to an approximate design when augmented with magic gates (shown in Sec.~\ref{sec:rel_error} and~\ref{sec:add_error}).
%
In what follows, we show that a Clifford ensemble with approximate uniformity can be generated in low-depth circuits.

The result stems from a gluing lemma; one can obtain a Clifford ensemble with the approximate uniformity condition by gluing small blocks of random Clifford unitaries together.
\begin{lemma}[Gluing lemma for Clifford ensembles with approximate uniformity]\label{thm:uniformity_gluing}
Consider a system of three partitions $A$, $B$, and $C$. 
Clifford unitaries $V_{BC}$ are drawn from an (exact) Clifford $k$-design, and $V_{AB}$ are drawn from an ensemble of Clifford unitaries on $AB$ satisfying the $\epsilon'$-approximate uniformity condition with $\epsilon'<1$. 
\begin{equation*}
\includegraphics[width=11.5cm]{Figure/uniformity_gluing.pdf}
\end{equation*}
%
Assume that $T$ is aligned in the overlapping region $B$, that is, the $k$-fold channel $\Phi^{(k)}_{AB}$ of $\{V_{AB}\}$ can be written as 
\begin{equation}
\Phi^{(k)}_{AB} = 2^{-N_{AB}k}\left[\sum_{T_3}|T_3)(T_3|_{AB}+\sum_{T_3,T_4,\vec{T}_5,\vec{T}_6}f\big((\vec{T}_5,T_3),(\vec{T}_6,T_4)\big)|\vec{T}_5)(\vec{T}_6|_A\otimes |T_3)(T_4|_B\right].
\end{equation}
Then, the unitary ensemble $\calE = \{ V_{BC} V_{AB} \}$ satisfies the uniformity condition up to the error
\begin{equation}
    \epsilon \le\epsilon'+2^{-N_B+O(k^2)}.
\end{equation}
\end{lemma}
\begin{proof}
The $k$-fold channel of ensemble $\calE$ is given by
\begin{equation}
\begin{aligned}
\Phi_\calE^{(k)}&=\Phi_{BC}^{(k)} \circ \Phi_{AB}^{(k)} = 2^{-N_{AB}k}\sum_{T_{1,2,3}}\Wg_{\C}(T_1,T_2)2^{N_B(k-|T_2,T_3|)} \\
&\left[|T_3)(T_3|_A\otimes |T_1)(T_3|_B+\sum_{T_4,\vec{T}_5,\vec{T}_6}f\big((\vec{T}_5,T_3),(\vec{T}_6,T_4)\big)|\vec{T}_5)(\vec{T}_6|_A\otimes |T_1)(\vec{T_4}|_B\right]\otimes |T_1)(T_2|_C,
\end{aligned}
\end{equation}
as shown pictorially below:
\begin{equation*}
\includegraphics[height=5.5cm]{Figure/uniformity_gluing_proof1.pdf}\qquad\qquad\qquad
\includegraphics[height=5.5cm]{Figure/uniformity_gluing_proof2.pdf}
\end{equation*}
where the dashed lines denote the Clifford Weingarten function $\Wg_{\C}(T_1,T_2)$ on $BC$, and the solid lines connecting two variables $T_2$ and $T_3$ denote $\Tr[r(T_2)_B^{\top}r(T_3)_B]=2^{N_B(k-|T_2,T_3|}$.

To show that $\Phi_\calE^{(k)}$ satisfies the uniformity condition, we divide the sum into three parts. 
%
The first part contains the terms without $T_4$, $\vec{T}_5$, and $\vec{T}_6$ satisfying $T_1=T_2=T_3$. The contribution of such configurations to $\Phi_\calE^{(k)}$ is
\begin{equation}
2^{-N_{A}k}\sum_{T}\Wg_{\C}(T,T)|T)(T|.
\end{equation}
The contribution to the error $\Delta(\Phi_\calE^{(k)})$ is bounded by
\begin{equation}
\sum_T \left|2^{N_{BC}k}\Wg_{\C}(T,T)-1\right|\leq 2^{-N_{BC}+O(k^2)},
\end{equation}
where we use the asymptotic behavior $|\Wg_{\C}(T,T)-2^{-N_{BC}k}|\le2^{-N_{BC}k-N_{BC}+O(k^2)}$ of the Clifford Weingarten function in Appendix~\ref{sec:clifford_commutant_wg_asymptotics}.

The second part contains the terms without $T_4$, $\vec{T}_5$, and $\vec{T}_6$, but either $T_1\neq T_2$ or $T_2\neq T_3$. The contribution of such configurations to $\Phi_\calE^{(k)}$ is
\begin{equation}
2^{-N_{A}k-N_B\abs{T_2,T_3}}\sum_{T_1\neq T_3}\sum_{T_2}\Wg_{\C}(T_1,T_2)|T_3)(T_3|_A\otimes |T_1)(T_3|_B\otimes |T_1)(T_2|_C.
\end{equation}
The contribution to the error $\Delta(\Phi_\calE^{(k)})$ is bounded by
\begin{equation}
\sum_{T_1\neq T_3}\sum_{T_2}2^{N_{BC}k}|\Wg_{\C}(T_1,T_2)|2^{-N_B|T_2,T_3|}\leq 2^{-N_B+O(k^2)},
\end{equation}
where we use (1) if $T_1\neq T_2$, the Weingarten function are suppressed as $|\Wg_{\C}(T_1,T_2)|\leq 2^{-N_{BC}k-N_{BC}+O(k^2)}$ as shown in Appendix~\ref{sec:clifford_commutant_wg_asymptotics}; (2) if $T_2\neq T_3$, the factor $2^{-N_B|T_2,T_3|}$ is suppressed as $|T_2,T_3|\geq 1$.

The third part contains the terms with $T_4$, $\vec{T}_5$, and $\vec{T}_6$. The contribution to the error $\Delta(\Phi_\calE^{(k)})$ is bounded by 
\begin{equation}
\begin{aligned}
&\sum_{T_3,T_4,\vec{T}_5,\vec{T}_6}|f\big((\vec{T}_5,T_3),(\vec{T}_6,T_4)\big)|\sum_{T_1,T_2}2^{N_{BC}k}|\Wg_{\C}(T_1,T_2)|2^{-N_B|T_2,T_3|} \\
&\leq \sum_{T_3,T_4,\vec{T}_5,\vec{T}_6}|f\big((\vec{T}_5,T_3),(\vec{T}_6,T_4)\big)|(1+2^{-N_B+O(k^2)}) \\
&\le\epsilon'(1+2^{-N_B+O(k^2)}).
\end{aligned}
\end{equation}
In the second line, the first term (in the small bracket) is from the terms with $T_1=T_2=T_3$. 
%
The second term comes from the terms that $T_1$, $T_2$, and $T_3$ are not aligned.
%
In this case, these terms has a suppression either from $|\Wg_{\C}(T_1,T_2)|$ if $T_1\neq T_2$ or from $2^{-N_B|T_2,T_3|}$ if $T_2\neq T_3$.

To sum up, the deviation from uniformity is bounded by
\begin{equation}
\Delta(\Phi_\calE^{(k)})\le\epsilon'+2^{-N_B+O(k^2)},
\end{equation}
where we use $\epsilon'<1$.
\end{proof}

Using the gluing lemma above, we can construct a global Clifford ensemble with approximate uniformity using two layers of Clifford $k$-design gates acting on qubit blocks.
\begin{theorem}[Approximate uniformity from two-layer Clifford circuits]
\label{thm:uniformity_log_depth}
Consider an ensemble $\calE_u = \{V\}$ of two-layer Clifford circuits with each gate drawn independently from an exact Clifford $k$-design. 
%
The Clifford ensemble $\calE_u$ and the stabilizer state ensemble $\calE_s = \{V\ket{0}^{\otimes N}\}$ satisfy the $\epsilon$-approximate uniformity condition with $\epsilon=N2^{-\xi-\log\xi+O(k^2)}$, where $\xi$ is the size of the smallest overlapping regions in the two-layer Clifford circuit.
\end{theorem}
\begin{proof}
We bound the deviation from uniformity by applying the gluing lemma sequentially for the two-layer Clifford circuit.
%
The error is accumulated by $2^{-\xi + O(k^2)}$ for each application.
%
We need to apply the gluing lemma at most $N/\xi$ times, where $\xi$ is the size of the smallest overlapping regions in the two-layer circuit.
%
Thus, the deviation of the $k$-fold channel $\Phi_{\calE_u}^{(k)}$ from uniformity has an upper bound $\Delta(\Phi_{\calE_u}^{(k)}) \leq N2^{-\xi-\log\xi+O(k^2)}$.
%
This implies the state ensemble $\calE_s = \{V\ket{0}^{\otimes N}\}$ satisfies the approximate uniformity up to error $\epsilon = N2^{-\xi-\log\xi+O(k^2)}$.
%
\end{proof}
According to Theorem~\ref{thm:uniformity_log_depth}, to achieve the $\epsilon$-approximate uniformity, it suffices to have overlapping regions of size $\xi = \log (N/\epsilon) + O(k^2)$.
%
Namely, one can realize it in shallow 1D Clifford circuits of depth $d = O(\log (N/\epsilon)+k^2)$~\cite{Bravyi:2020xdv}.

As a corollary, since the uniformity condition implies a stabilizer $k$-design with bounded additive errors (Theorem~\ref{thm:uniformity_implies_stabilizer_state_design}), one can generate an additive-error stabilizer state design using log-depth Clifford circuits.
\begin{corollary}[Additive-error stabilizer state designs from low-depth Clifford circuits]
\label{thm:state_additive_clifford_design}
Let $V$ be a two-layer brickwork Clifford circuit, where each gate is drawn from an exact Clifford $k$-design. 
%
Let $\xi$ be the smallest size of the overlapping regions of the Clifford unitaries. 
%
Then the state ensemble $\{V\ket{0}^{\otimes N}\}$ forms an approximate stabilizer state $k$-design with additive error $\varepsilon\leq N2^{-\xi-\log\xi+O(k^2)}$, assuming $N\geq k+\log k-2$.
In other words, one can achieve $\varepsilon$ additive error for $\xi=\log (N/\varepsilon)+O(k^2)$, or equivalently, in depth $O(\log (N/\varepsilon)+k^2)$ using 1D circuits or in depth $O(\log\log (N/\varepsilon)+\log k)$ using all-to-all circuits and $O(N(\log (N/\varepsilon)+k^2))$ ancillas~\cite{Jiang:2019aom}.
\begin{equation*}%
\includegraphics[width=9.8cm]{Figure/state_additive_clifford.pdf}   
\end{equation*}
\end{corollary}
