\begin{theorem}[Relative-error state designs from low-depth Clifford unitaries followed by constant depth magic gates]
\label{thm:state_relative_log_depth}
Consider a state ensemble $\calE = \{UV\ket{0}^{\otimes N}\}$ generated by the circuit architecture below
\begin{equation*}
\includegraphics[width=10.8cm]{Figure/state_relative_log_depth.pdf}
\end{equation*}
Here, $U = \bigotimes_{x,i} U_{x,i}$ is a product of random unitaries drawn from exact unitary $k$-designs, each gate $U_{x,i}$ acts on a disjoint subsystem $M_{x,i}$ of size $N_{x,i}$ within $M_x$. 
%
The two-layer Clifford unitary $V$ consists of multi-qubit Clifford unitaries drawn independently from exact Clifford $k$-designs.

The ensemble $\calE$ forms a state $k$-design with relative error 
\begin{align}
%
\epsilon = N2^{-\xi-\log\xi+O(k^2)}+2^{O(k^2)-N}\left[k!(1+k^22^{-\ell})\right]^{N/\ell},
\end{align}
where $\xi$ is the size of the smallest overlapping regions of the Clifford unitaries, and $\ell = \min\{N_{x,i}\} \geq k \log k$ is the size of the smallest subsystem that $U_{x,i}$ acts on.
%
%

This implies that, with $\xi=O(\log(N/\epsilon)+k^2)$ and $\ell=O(k\log k)$, the ensemble $\calE$ can form a state $k$-design with $\epsilon$ relative error, assuming $N=\omega(k^2+\log(1/\epsilon))$.

\end{theorem}
\begin{proof}
%
%
%

To begin, the $k$-th moment of the state ensemble generated by a two-layer Clifford unitary can be expressed as
\begin{align}
    \rho_{\calE_0}^{(k)}=2^{-Nk}\left[\sum_T r(T) + \sum_{\vec{T}}f(\vec{T})r(\vec{T})\right],
\end{align}
where $\vec{T}$ is a vector of $T_x$, each of which emerged from averaging the $k$-fold channel associated with a Clifford gate in the second layer at location $x$.
The operator $r(\vec{T})=\bigotimes_x r(T_x)_{M_x}$, where $M_x$ labels the qubit block that the Clifford gate at location $x$ acts on.
%
It satisfies the $\epsilon'$-approximate uniformity condition with $\epsilon'=N2^{\xi-\log\xi+O(k^2)}$ due to Theorem~\ref{thm:uniformity_log_depth}.

Next, we apply the $k$-design random unitary gates over subsystems $M_{x,i}$ of size $N_{x,i}$ within each qubit block $M_x$. 
%
Recall that the $k$-fold channel of each Haar random unitary is given by
\begin{align}
    \Ens_{U \sim \H}U^{\otimes k} (\cdot) U^{\dagger \otimes k} = \sum_{\sigma, \tau\in S_k}\Wg(\sigma,\tau) r(\sigma) \Tr[r(\tau)^\top (\cdot)],
\end{align}
where each $\sigma$ and $\tau$ belongs to the permutation group $S_k$, corresponding to a subset of the Clifford commutant.
%
The resulting $k$-th moment takes the form 
\begin{align}\label{eq:bounded_relative_1}
\rho_{\calE}^{(k)} = 2^{-Nk}\sum_{\vec{\sigma},\vec{\tau}}\left[\sum_Tr(\vec{\sigma}) \Wg(\vec{\sigma},\vec{\tau})  \bbrakket{\vec{\tau}}{T} + \sum_{\vec{T}}f(\vec{T})r(\vec{\sigma})\Wg(\vec{\sigma},\vec{\tau})\bbrakket{\vec{\tau}}{\vec{T}}\right]
\end{align}
where $\vec{\sigma}$ ($\vec{\tau}$) is a vector labeling configurations of permutations $\sigma_{x,i}$,  $\tau_{x,i}\in S_{k}$ at location $x,i$, and $\Wg(\vec{\sigma},\vec{\tau}) := \prod_{x,i}\Wg(\sigma_{x,i},\tau_{x,i})$, $\bbrakket{\vec{\tau}}{T}:=\prod_{x,i}\bbrakket{\tau_{x,i}}{T}$, $\bbrakket{\vec{\tau}}{\vec{T}}:=\prod_{x,i}\bbrakket{\tau_{x,i}}{T_x}$.
%
%

To bound the relative error between $\rho_{\calE}^{(k)}$ and $\rho_{\H}^{(k)}$, we divide the contribution to $\rho_{\calE}^{(k)}$ into three parts:
\begin{itemize}
    \item The first part is given by the first term in Eq. (\ref{eq:bounded_relative_1}), choosing $T = \pi\in S_{k}$. The summation over $\vec{\tau}$ results in a delta function, i.e. $\sum_{\tau_{x,i}}\Wg(\sigma_{x,i},\tau_{x,i})\bbrakket{\tau_{x,i}}{\pi}=\delta_{\sigma_{x,i},\pi}$, which identifies each $\sigma_{x,i}$ with $\pi$. This part of the contribution is
    \begin{align}
        \rho_\rmI^{(k)} = 2^{-Nk}\sum_{\pi\in S_k} r(\pi).
    \end{align}
    \item The second part is given by the first term in Eq. (\ref{eq:bounded_relative_1}), taking $T\notin S_{k}$
    \begin{align}
    \rho_{\rmII}^{(k)} = 2^{-Nk}\sum_{\vec{\sigma},\vec{\tau}}\sum_{T\notin S_k} r(\vec{\sigma}) \Wg(\vec{\sigma},\vec{\tau}) \bbrakket{\vec{\tau}}{T},    
    \end{align}
    which has a bounded $\infty$-norm
    \begin{align}
        \lVert \rho_{\rmII}^{(k)}\rVert_\infty \leq & 2^{-Nk}\sum_{\vec{\sigma},\vec{\tau}}\sum_{T\notin S_k} \lVert r(\vec{\sigma})\rVert_\infty\abs{\Wg(\vec{\sigma},\vec{\tau})} \bbrakket{\vec{\tau}}{T} \nonumber \\
        \leq & 2^{-Nk} 2^{O(k^2)-N} \prod_{x,i} k! (1 + k^2 2^{-N_{x,i}}) \nonumber \\
        \leq & 2^{-Nk} 2^{O(k^2)-N} \left[ k! (1 + k^2 2^{-\ell})\right]^{N/
        \ell}.\label{eq:rel_error_state_rhoII}
    \end{align}
    In the second inequality, we use $\lVert r(\vec{\sigma})\rVert_\infty = 1$, $\bbrakket{\vec{\tau}}{T} \leq 2^{-N}$, and $\sum_{\sigma_{x,i},\tau_{x,i}} |\Wg(\sigma_{x,i},\tau_{x,i})|\leq k!(1+k^2 2^{-N_{x,i}})$ for $k^2<2^{N_{x,i}}$~\cite{Aharonov:2021das}.
    In the third inequality, we take $\ell = \min\{N_{x,i}\}$ to be the size of the smallest qubit cluster.
    \item The third part contains the remaining terms in the summation
    \begin{align}
        \rho_{\rmIII}^{(k)} = 2^{-Nk} \sum_{\vec{\sigma},\vec{\tau}}\sum_{\vec{T}}f(\vec{T})r(\vec{\sigma})\Wg(\vec{\sigma},\vec{\tau})\bbrakket{\vec{\tau}}{\vec{T}}. 
    \end{align}
    Its $\infty$-norm has an upper bound
    \begin{align}
        \infnormsm{\rho_{\rmIII}^{(k)}} \leq 2^{-Nk} \sum_{\vec{T}} \abs{f(\vec{T})} \prod_{x,i} \bigg\lVert\sum_{\sigma_{x,i},\tau_{x,i}}r(\sigma_{x,i})\Wg(\sigma_{x,i},\tau_{x,i})\bbrakket{\tau_{x,i}}{T_x}\bigg\rVert_{\infty}.\label{eq:rel_error_state_rhoIII}
    \end{align}
    Here, we consider the summation over each $\sigma_{x,i}$ and $\tau_{x,i}$. We consider two cases for $T_x \in S_k$ and $T_x \notin S_k$. 
    %
    For $T_x = \pi \in S_k$,
    \begin{align}
    \bigg\lVert\sum_{\sigma_{x,i},\tau_{x,i}}r(\sigma_{x,i})\Wg(\sigma_{x,i},\tau_{x,i})\bbrakket{\tau_{x,i}}{\pi}\bigg\rVert_\infty = \infnorm{r(\pi)} = 1
    \end{align}
    %
    For $T_x \notin S_k$,
    \begin{align}
        \bigg\lVert\sum_{\sigma_{x,i},\tau_{x,i}}r(\sigma_{x,i})\Wg(\sigma_{x,i},\tau_{x,i})\bbrakket{\tau_{x,i}}{T_x}\bigg\rVert_{\infty} &\leq \sum_{\sigma_{x,i},\tau_{x,i}} \abs{\Wg(\sigma_{x,i},\tau_{x,i})} \bbrakket{\tau_{x,i}}{T_x} \nn \\
        &\leq \prod_i 2^{-N_{x,i}}k!(1+k^22^{-N_{x,i}})\leq 1,
    \end{align}
    where we use $|\tau_{x,i},T_{x,i}|\geq 1$ and assume that $\ell \geq k\log k$.
    %
    Hence, we have
    \begin{align}
        \infnormsm{\rho_{\rmIII}^{(k)}} \leq & 2^{-Nk} \sum_{\vec{T}} \abs{f(\vec{T})} \leq 2^{-Nk} \epsilon'.\label{eq:rel_state_rhoIII_infnorm}
    \end{align}

    %
    %
    %
    %
    %
\end{itemize}

Combining these results, we obtain an upper bound on the relative error
\begin{align}
    \epsilon \leq & \frac{\infnormsm{\rho_{\calE}^{(k)} - \rho_{\H}^{(k)}}}{\infnormsm{\rho_{\H}^{(k)}}} \leq \frac{\infnormsm{\rho_{\rmI}^{(k)} - \rho_{\H}^{(k)}} + \infnormsm{\rho_{\rmII}^{(k)}} + \infnormsm{\rho_{\rmIII}^{(k)}}}{\infnormsm{\rho_{\H}^{(k)}}} \nn \\
    \leq & k^22^{-Nk} + 2^{O(k^2)-N}[k!(1+k^22^{-\ell})]^{N/\ell}+ (1 + k^2 2^{-Nk})\epsilon' \nn\\
    %
    \le& 2^{O(k^2)-N}[k!(1+k^22^{-\ell})]^{N/
    \ell}+N2^{-\xi-\log\xi+O(k^2)}.
\end{align}
\end{proof}

We remark that the magic gates does not need to act on every qubit cluster in the final layer.
%
In fact, one can remove a finite fraction of Haar random gates within each qubit block $M_x$, while maintaining a bounded relative error.
%
Consider a qubit block of size $\xi$ that a Clifford gate acts on.
%
Suppose no magic gates act on a subregion $C$ of size $N_C$ inside the qubit block.
%
We can follow a similar analysis of the relative error except that in Eq.~\eqref{eq:rel_error_state_rhoII} and~\eqref{eq:rel_error_state_rhoIII}, the summation involves terms with the non-permutation $r(T)_C$ in region $C$, which can have a greater spectral norm $\infnormsm{r(T)_C} = 2^{N_C\dim \mathrm{N}}$ than those of permutations. 
%
%
%
Using the upper bound of its spectral norm $\lVert r(T)_C\rVert_\infty\le2^{N_Ck/2}$, we obtain a modified multiplicative factor, e.g. in Eq.~\eqref{eq:rel_error_state_rhoII},
\begin{equation}
    2^{-\xi}\prod_i k!(1+k^22^{-\ell})\quad \mapsto\quad 2^{-(\xi-N_C)+N_Ck/2}\prod_i k!(1+k^22^{-\ell}).
\end{equation}
This factor is still bounded for $N_C=\frac{1}{k}\xi$ and $\ell = O(k\log k)$, indicating the possibility to remove at least $1/k$ fraction of Haar random gates. 

In the case with no magic gates in the subregion $C$, it is tempting to distinguish this circuit from Haar random states using magic measures.
%
To begin, one can consider magic measures on the subregion $C$.
%
This cannot work because Page's theorem implies that in the thermodynamic limit $N \to \infty$, the state on $C$ is exponentially close to the maximally mixed state with no magic, assuming that the size of $C$ is less than half of the system.
%
%
%
Alternatively, one might try to measure the magic in the entire system. 
%
Since our circuits form a relative error design, the expectation value of any positive operator is relatively close to the Haar random value.
%
This implies that, for example, measuring the operator (used in Sec.~\ref{sec:rel_error_nogo}) whose logarithm defines the stabilizer Rényi entropy will lead to a result relatively close to the Haar value. 
%
Naively, one may expect the magic in the entire system to deviate from the maximal value by an extensive amount. 
However, magic gates on a subregion are capable of generating a near-maximum stabilizer Rényi entropy when acting on a highly entangled state as shown in Ref.~\cite{Hou:2025bau}. 



\subsection{Unitary designs with bounded relative error}\label{sec:rel_error_unitary}

In this section, we show that an ensemble of Clifford unitaries that satisfies the approximate uniformity condition can be converted to a unitary design with bounded relative error by sandwiching the Clifford unitaries with constant-depth Haar random unitaries.
%
This allows us to construct a unitary $k$-design with $\epsilon$ relative error using one-dimensional circuits with a total depth $O(\log (N/\epsilon)) + 2^{O(k\log k)}$ or using all-to-all circuits with depth $O(\log\log (N/\epsilon)) + 2^{O(k\log k)}$.

\begin{theorem}[Relative-error unitary designs from low-depth Clifford unitaries sandwiched by constant depth magic gates]
Consider an ensemble $\calE = \{U V U'\}$ of unitary circuits given by the architecture below
\begin{equation*}
\includegraphics[width=8.2cm]{Figure/unitary_relative_log_depth.pdf}
\end{equation*}
Here, $U = \bigotimes_{x,i} U_{x,i}$ ($U' = \bigotimes_{x',i'} U'_{x',i'}$) is a product of random unitaries drawn from exact $k$-design acting on disjoint clusters of qubits. Each gate $U_{x,i}$ ($U'_{x',i'}$) acts on a qubit cluster $M_{x,i}$ ($M'_{x',i'}$) of size $N_{x,i}$ ($N'_{x',i'}$). 
%
The two-layer random Clifford unitary $V$ consists of multi-qubit Clifford unitaries drawn independently from exact Clifford $k$-designs.

The unitary ensemble $\calE$ forms a unitary $k$-design with $\epsilon$ relative error 
\begin{align}
    \epsilon = 2^{O(k^2)-2N} \left[k!(1 + k^2 2^{-\ell})\right]^{2N/\ell} + N2^{-\xi-\log \xi+O(k^2)}
\end{align}
where $\xi$ is the size of the smallest overlapping regions of individual Clifford gates, and $\ell = \min\{N_{x,i},N'_{x',i'}\}$ is the size of the smallest qubit cluster.
Here, we have assumed that $\ell \geq k \log k$.
%

This implies that, with $\xi=O(\log(N/\epsilon)+k^2)$ and $\ell=O(k\log k)$, the ensemble $\calE$ can form a state $k$-design with $\epsilon$ relative error assuming $N=\omega(k^2+\log(1/\epsilon))$.
\end{theorem}
\begin{proof}
The relative error of $\Phi_\calE^{(k)}$ to the unitary $k$-design is bounded by~\cite{Schuster:2024ajb}
\begin{align}
    \epsilon &\leq \frac{2^{2Nk}}{k!}\left(1 + \frac{k^2}{2^N}\right)\infnormsm{\varrho_\calE^{(k)} - \varrho_0^{(k)}} + \frac{k^2}{2^N} \nn \\
    &\leq \frac{2^{2Nk}}{k!} \left(1 + \frac{k^2}{2^N}\right) \left( \infnormsm{\varrho_\rmI^{(k)} - \varrho_0^{(k)}} + \infnormsm{\varrho_\rmII^{(k)}} + \infnormsm{\varrho_\rmIII^{(k)}} \right) + \frac{k^2}{2^N},
\end{align}
where $\varrho_\calE^{(k)} = [\Phi^{(k)}_\calE \otimes \id ](P_{\EPR}) := \varrho_\rmI^{(k)} + \varrho_{\rmII}^{(k)} + \varrho_{\rmIII}^{(k)}$, and $\varrho_0^{(k)} = 2^{-2Nk}\sum_\sigma r(\sigma) \otimes r(\sigma)$.
%
We divide the summation over $T$ in the $k$-fold channel associated with the two-layer Clifford unitaries (Eq.~\eqref{eq:channel_uniformity}) into three parts, leading to three contributions to $\varrho_\calE^{(k)}$ given by
\begin{align}
    \varrho_\rmI^{(k)} &= \frac{1}{2^{2Nk}} \sum_{\vec{\sigma}_{1,2},\vec{\tau}_{1,2}}\sum_{\pi \in S_k} \Wg(\vec{\sigma}_1,\vec{\tau}_1)\Wg(\vec{\sigma}_2,\vec{\tau}_2) \bbrakket{\vec{\tau}_1}{\pi}\bbrakket{\pi}{\vec{\sigma}_2} r(\vec{\sigma}_1)\otimes r(\vec{\tau}_2) \nn \\
    &= \frac{1}{2^{2Nk}} \sum_{\pi\in S_k}r(\pi) \otimes r(\pi) = \varrho_0^{(k)}, \\
    \varrho_\rmII^{(k)} &= \frac{1}{2^{2Nk}} \sum_{\vec{\sigma}_{1,2},\vec{\tau}_{1,2}} \sum_{T \notin S_k} \Wg(\vec{\sigma}_1,\vec{\tau}_1)\Wg(\vec{\sigma}_2,\vec{\tau}_2) \bbrakket{\vec{\tau}_1}{T}\bbrakket{T}{\vec{\sigma}_2} r(\vec{\sigma}_1)\otimes r(\vec{\tau}_2), \\
    \varrho_\rmIII^{(k)} &= \frac{1}{2^{2Nk}} \sum_{\vec{\sigma}_{1,2},\vec{\tau}_{1,2}}\sum_{\vec{T}_1,\vec{T}_2} f(\vec{T}_1,\vec{T}_2)\Wg(\vec{\sigma}_1,\vec{\tau}_1)\Wg(\vec{\sigma}_2,\vec{\tau}_2) \bbrakket{\vec{\tau}_1}{\vec{T}_1}\bbrakket{\vec{T}_2}{\vec{\sigma}_2} r(\vec{\sigma}_1)\otimes r(\vec{\tau}_2).
\end{align}
The first and the second part are from the spatially aligned $T \in S_k$ and $T\notin S_k$, respectively.
%
%
According to Theorem~\ref{thm:uniformity_log_depth}, the two-layer Clifford unitaries satisfies the uniformity condition up to error $\sum_{\vec{T}_1,\vec{T}_2}\abs{f(\vec{T}_1,\vec{T}_2)} < \epsilon' = N2^{-\xi-\log\xi + O(k^2)}$.

The $\infty$-norm of the second part is bounded
\begin{align}
    \infnormsm{\varrho_\rmII^{(k)}} \leq 2^{-2Nk} 2^{O(k^2)} \left[\prod_{x,i} 2^{-N_{x,i}} k!(1 + k^2 2^{-N_{x,i}})\right]\left[\prod_{x',i'}2^{-N_{x',i'}} k!(1 + k^2 2^{-N_{x',i'}}) \right]
\end{align}

The $\infty$-norm of the third part has an upper bound, assuming $\ell \geq k \log k$,
\begin{align}
    \infnormsm{\varrho_\rmIII^{(k)}} \leq 2^{-2Nk} \sum_{\vec{T}_1,\vec{T}_2} \abs{f(\vec{T}_1,\vec{T}_2)} \leq 2^{-2Nk} \epsilon'.
\end{align}
The derivation is similar to that for Eq.~\eqref{eq:rel_state_rhoIII_infnorm}.


Altogether, the relative error has an upper bound
\begin{align}
    \epsilon &\leq 2^{O(k^2)} \left[\prod_{x,i} 2^{-N_{x,i}} k!(1 + k^2 2^{-N_{x,i}})\right]\left[\prod_{x',i'}2^{-N_{x',i'}} k!(1 + k^2 2^{-N_{x',i'}}) \right] + N2^{-\xi-\log\xi + O(k^2)} + k^22^{-N}\nn \\
    &\leq 2^{O(k^2)-2N}\left[ k!(1 + k^2 2^{-\ell})\right]^{2N/\ell}  + N2^{-\xi-\log\xi + O(k^2)}+ k^22^{-N},
\end{align}
where $\ell = \min\{N_{x,i},N'_{x',i'}\}$ is the size of the smallest qubit cluster. The $k^22^{-N}$ can be absorbed into $N2^{-\xi-\log\xi + O(k^2)}$.
\end{proof}
We remark that, similar to the case of relative-error state design, one can remove a finite fraction of Haar random gates within each qubit block in our construction while maintaining a bounded relative error.

\begin{corollary}[Circuit depth]\label{thm:unitary_relative_circuit_depth}
On an $N$ qubit system with $N=\omega(k^2+\log(1/\epsilon))$, one can realize approximate unitary and state $k$-design with $\epsilon$ relative error in depth\footnote{We acknowledge Thomas Schuster for explaining the efficient constructions of global random Clifford gates, which helps us better appreciate our results.}
\begin{itemize}
\item $O(\log(N/\epsilon)) + 2^{O(k\log k)}$ with 1D circuits.
\item $O(\log\log(N/\epsilon)) +2^{O(k\log k)}$ with all-to-all circuits using $O(N(\log(N/\epsilon)+k^2))$ ancillas.
\end{itemize}

\end{corollary}
\begin{proof}
The first statement follows from (1) any Clifford unitary over $\xi$ qubits can be realized in depth $d = O(\xi)$~\cite{Bravyi:2020xdv}; (2) any unitary operation over $\ell$ qubits can be realized using $O(\ell 4^\ell)$ two-local gates~\cite{Knill:1995kz}. Hence, depth $O(\ell4^\ell)$ is sufficient for all-to-all circuits, depth $O(\ell^24^\ell)$ is sufficient for 1D circuits.

The second statement follows from~\cite{Jiang:2019aom} which shows that any Clifford unitary on $\xi$ qubits can be implemented with all-to-all circuits in depth $O(\log\xi)$ using $\xi^2$ ancillas.
\end{proof}
%


\subsection{No-go theorems}\label{sec:rel_error_nogo}

Here, we prove no-go theorems for designs with bounded relative error.
%
%
%
We first consider an ensemble of Clifford augmented states generated by applying Clifford unitaries to initial states with low entanglement.
%
A subclass of these states are the Clifford augmented matrix product states (CAMPS)~\cite{qian2023augmenting,qian2024augmenting}.
%
CAMPSs can be efficiently simulated and have the potential to host large-scale entanglement and an extensive amount of magic.
%
However, we show that an ensemble of CAMPSs with bond dimension $D = \tilde{o}(\sqrt{N/\epsilon})$ cannot form a state $k$-design with $\epsilon$ relative error for $k\geq 4$.
%
We further show that in any dimension, finite-depth local unitaries followed by a Clifford unitary cannot generate a state design with bounded relative error.
%
%
%
The no-go theorem also suggests that a unitary ensemble $\{V_1UV_2\}$ with $V_{1,2}$ being Clifford unitaries and $U$ being a generic shallow unitary circuit cannot form a relative-error unitary $k$-design.
%
%
%
%
The no-go theorems challenge the naive expectation that magic placed at the initial layer creates more randomness as the Clifford unitary can spread and scramble magic.


The main idea behind the no-go theorem is that the ensemble of Clifford augmented states is distinguished from the Haar random ensemble by measuring the Pauli $4$-th moment, whose logarithm defines the stabilizer Rényi entropy~\cite{Leone:2021rzd}. 
%
The $4$-th moment is given by the expectation value of a projection operator onto a CSS code defined in the replicated space (see Appendix~\ref{sec:stabilizer_renyi_entropy}), which are positive operators that belong to the Clifford commutant. 
%
The relative error of the $4$-th moment sets a lower bound on the relative error of the state $4$-design.
%
We note that although such states cannot form relative-error state designs, they can form additive-error state designs, as we show in Appendix~\ref{sec:state_additive_initial_magic}.

%
We consider an ensemble $\calE = \{V\ket{\psi_0}\}$ of Clifford augmented states generated by Clifford unitaries $V$ acting on short-range entangled states or one-dimensional matrix product states $\ket{\psi_0}$.
%
We show that the ensemble is distinguished from the ensemble of Haar random states by a positive observable:
%
%
%
%
%
%
\begin{equation}
r(T_S)=2^{-N}\sum_{P\in\calP}P^{\otimes 4},\qquad \calP=\{Z^{\boldu}X^{\boldv},\boldu,\boldv\in\mathbb{F}_2^{N}\}
\end{equation}
The expectation value of this operator is related to the second stabilizer Rényi entropy $\calM_2(\psi)$ of state $\ket{\psi} = V\ket{\psi_0}$,
\begin{align}
    \Tr [r(T_S)\rho_{\calE}^{(4)} ] = \mathbb{E}_{\psi\sim\calE} \frac{1}{2^N} \sum_P \bra{\psi} P\ket{\psi}^4 = \mathbb{E}_{\psi\sim\calE} 2^{-\calM_2(\psi)}.
\end{align}
Note that the operator $r(T_S)$ belongs to the Clifford commutant; its expectation value is invariant under Clifford unitaries:
%
\begin{equation}
\bra{\psi_0}^{\otimes 4}V^{\otimes 4}r(T_S)V^{\dagger\otimes 4}\ket{\psi_0}^{\otimes 4}=\bra{\psi_0}^{\otimes 4}r(T_S)\ket{\psi_0}^{\otimes 4}.
\end{equation}


\begin{theorem}[Lower bound on relative error from non-maximal initial entanglement]
Consider disjoint subsystems $M_i$ of size $N_i$ in an $N$-qubit system, where the union $\cup_i M_i$ need not contain all the qubits.

The state ensemble $\calE=\{V\ket{\psi_0}\}$ generated by Clifford unitary $V$ acting on state $\ket{\psi_0}$ cannot form an approximate state $k$-design (for $k\ge4$) with relative error 
\begin{equation}
\epsilon\leq \frac{1}{24}\left[\Ens_{\calE}\sum_{i}2^{-2\calS^{(2)}_i}(1-2^{\calS^{(2)}_i-N_i})-3\right],
\end{equation}
where $\calS^{(2)}_i=-\log \Tr(\rho_i^2)$ is the second Rényi entropy evaluated on subsystem $M_i$ of the initial state $\ket{\psi_0}$, and $\rho_i$ is the reduced density matrix of $\ket{\psi_0}$ on $M_i$.

\end{theorem}

\begin{proof}
For each member of the state ensemble, we can lower bound the expectation value of $r(T_S)$ by the following procedure. On a single region $M_i$, the summation over all the Pauli operators that support on $M_i$ gives
\begin{equation}
\delta := \sum_{P_i}|\bra{\psi_0}P_i\ket{\psi_0}|^2=2^{N_i}\Tr(\rho_{M_i}^2) = 2^{N_i -\calS_i^{(2)}}.
\end{equation}
We can view $\{\chi_{P_i}=\delta^{-1}|\bra{\psi_0}P_i\ket{\psi_0}|^2\}$ as a probability distribution. Since $\chi_{I}=\delta^{-1}$, the contributions from non-identity Pauli operators are lower bounded by
\begin{equation}
2^{-N}\sum_{P_i\neq I}|\bra{\psi_0}P_i\ket{\psi_0}|^4=2^{-N}\delta^2\sum_{P_i\neq I}|\chi_{P_i}|^2\geq 2^{-N}\delta^2\frac{1-\delta^{-1}}{2^{2N_i}-1}\geq 2^{-N}2^{-2\calS^{(2)}_i}(1-2^{\calS^{(2)}_i-N_i}).
\end{equation}
Summing over all regions $i$, we get
\begin{equation}
\bra{\psi_0}^{\otimes 4}r(T_S)\ket{\psi_0}^{\otimes 4}\geq 2^{-N}\left[1+\sum_{i}2^{-2\calS^{(2)}_i}(1-2^{\calS^{(2)}_i-N_i})\right].
\end{equation}
%
Averaging over the state in the ensemble $\calE$, we have
\begin{equation}\label{eq:nogo_clifford_augmented_states_SRE_bound}
\Tr[r(T_S)\rho_{\calE}^{(4)}]\geq 2^{-N}\left[1+\Ens_{\calE}\sum_{i}2^{-2\calS^{(2)}_i}(1-2^{\calS^{(2)}_i-N_i})\right].
\end{equation}
The Haar value is
\begin{equation}
\Tr[r(T_S)\rho_{\H}^{(4)}]=2^{-N}D_{N,4}^{-1}\sum_{\pi\in S_4,P\in \calP}\Tr[ P^{\otimes 4}r(\pi)]=\frac{4}{2^N+3},
\end{equation}
see~\cite{Leone:2021rzd}. The difference in the expectation value can give a lower bound to the relative error
\begin{equation}\label{eq:nogo_rel_error_bound_from_expectation_value}
\lVert\rho_{\calE}^{(4)}-\rho_{\H}^{(4)}\rVert_\infty\geq\frac{\left|\Tr[r(T_S)(\rho_{\calE}^{(4)}-\rho_{\H}^{(4)})]\right|}{\lVert r(T_S)\rVert_1}\geq 2^{-4N}\left[\Ens_{\calE}\sum_{i}2^{-2\calS^{(2)}_i}(1-2^{\calS^{(2)}_i-N_i})-3\right],
\end{equation}
where we use the H\"older's inequality, and $\lVert r(T_S)\rVert_1=2^{3N}$ (defect subspace dimension $\dim\rmN = 1$, and $k = 4$). 
The relative error is bounded by
\begin{equation}\label{eq:nogo_clifford_augmented_states_infnorm_bound}
\frac{\lVert\rho_{\calE}^{(4)}-\rho_{\H}^{(4)}\rVert_\infty}{\lVert\rho_{\H}^{(4)}\rVert_\infty}\geq\frac{1}{24}\left[\Ens_{\calE}\sum_{i}2^{-2\calS^{(2)}_i}(1-2^{\calS^{(2)}_i-N_i})-3\right].
\end{equation}

If $\calE$ is an approximate state $k$-design with $\epsilon$ relative error for $k\geq 4$, then $(1-\epsilon)\rho_{\H}^{(k)}\preceq\rho_{\calE}^{(k)}\preceq(1+\epsilon)\rho_{\H}^{(k)}$. Taking the partial trace over $k-4$ copies of the system, we find $(1-\epsilon)\rho_{\H}^{(4)}\preceq\rho_{\calE}^{(4)}\preceq(1+\epsilon)\rho_{\H}^{(4)}$. In other words, $\calE$ is an approximate state $4$-design with $\epsilon$ relative error. Since $\rho_{\H}^{(4)}$ has a flat spectrum, the above implies
\begin{equation}
\lVert\rho_{\calE}^{(4)}-\rho_{\H}^{(4)}\rVert_\infty\le\epsilon\lVert\rho_{\H}^{(4)}\rVert_\infty.
\end{equation}
Therefore an ensemble cannot form an approximate state $k$-design for $k \geq 4$ with relative error $\epsilon$ smaller than the right-hand side of~\eqref{eq:nogo_clifford_augmented_states_infnorm_bound}.

\end{proof}

The above proof can be understood as a classical statistical mechanics problem, where the lack of correlations proliferates domain wall excitations. We interpret $\left|\bra{\psi}\bigotimes_i P_i\ket{\psi}\right|^4\equiv W(\{P_i\})$ as the Boltzmann weight of a spin model, where we put a spin on every region $M_i$ that are labeled by the Pauli operators on $M_i$. We ask whether the partition function $Z=\sum_{\{P_i\}}W(\{P_i\})$ is relatively close to the Haar value that is $O(1)$. 

The identity operator $\prod_iI_i$ gives the maximal weight $W(\{I_i\})=1$. On Haar random states, the weights for any spin configuration with non-identity inputs are heavily suppressed, that is to say, if $\{P_i\}\neq \{I_i\}$, then
\begin{equation}\label{eq:nogo_clifford_augmented_states_stat_mech_haar_non_identity}
\Ens_{\psi\sim\H}W(\{P_i\})=D_{N,2}^{-1}\sum_{\pi\in S_4}\Tr[r(\pi) \bigotimes_i P_i^{\otimes 4}]=3\times 2^{-N}[1+O(2^{-N})].
\end{equation}
However, in states that are less entangled, there might be domain wall excitations that corresponds to $\{P_i\}$ with $I$ on all but one site. For every site $M_i$, such domain wall gives a contribution of at least $2^{-2\calS^{(2)}_i}(1-2^{\calS^{(2)}_i-N_i})$, which could be an $O(1)$ number if $N_i=O(1)$ and $N_i-\calS^{(2)}_i=O(1)$. The Boltzmann weights are also $O(1)$, in contrast with the Haar case~\eqref{eq:nogo_clifford_augmented_states_stat_mech_haar_non_identity}. Since there is an $O(N)$ number of such regions, these configurations gives an overall $O(N)$ contribution to the partition function. In stat mech language, the energy cost of these domain walls cannot suppress the large entropy, so they will proliferate.

%

As the first application of the relative error lower bound, we prove a no-go theorem for ensembles of Clifford augmented matrix product states. 

\begin{corollary}[No-go theorem for Clifford augmented MPS]
Consider an ensemble of states $\calE = \{V\ket{\psi}\}$, where $V$ is a Clifford unitary, and $\ket{\psi}$ are matrix product states whose bond dimensions are bounded by $D$.
\begin{equation*}
\includegraphics[width=6cm]{Figure/nogo_clifford_augmented_mps.pdf}
\end{equation*}
The states cannot form an approximate state $k$-design for $k\geq 4$ with $\epsilon$ relative error for\footnote{To be more precise, the condition is $D=o\left(\sqrt{\frac{N/\epsilon}{\log(N/\epsilon)}}\right)$. We used the $\tilde{o}$ notation to suppress factors of $\log(N/\epsilon)$.} $D=\tilde{o}(\sqrt{N/\epsilon})$.
\end{corollary}
\begin{proof}
Since the bond dimension is upper bounded by $D$, the subsystem Rényi entropy is bounded by $2^{\calS^{(2)}_i}\leq D$. Suppose we choose a region $M_i$ such that $N_i=\lceil \log D+1\rceil$, then $N_i-\calS^{(2)}_i\geq 1$. There exists a choice of the regions $M_i$ such that the total number of such region with $N_i=\lceil \log D+1\rceil$ is lower bounded by $\lfloor \frac{N}{\log D+2}\rfloor\geq \frac{N}{\log D+2}-1$. That is to say, the relative error is lower bounded by
\begin{equation}\label{eq:nogo_clifford_augmented_MPS_SRE_bound}
\epsilon\geq\frac{1}{24}\left[\left(\frac{N}{\log D+2}-1\right)\frac{1}{2D^2}-3\right].
\end{equation}
\end{proof}

Our no-go theorem suggests that CAMPSs with bond dimension $\tilde{o}(\sqrt{N/\epsilon})$ cannot form a relative error $k$-design with $k\geq 4$. 
%
This implies that CAMPSs cannot represent the output state of highly random Brownian dynamics or the dynamics of generally time-dependent Hamiltonians~\cite{Onorati:2016met,Jian:2022pvj} that form relative-error unitary designs.
%
On the other hand, an ensemble of MPS with bond dimension $D = O(N^k)$ can form an approximate state $k$-design. 
%
This is because a state $k$-design can be generated in random circuits of depth $d = O(k\log N)$~\cite{Schuster:2024ajb}, whose output states have an exact representation as MPSs with bond dimension $D = O(N^k)$.
%
The representation power of CAMPSs with a bond dimension in between remains an open problem.

The no-go theorem can be extended to Clifford augmented tensor network states in higher dimensions. 
%
For example, for projected entangled pair states (PEPS) of bond dimension $D$ in two dimensions~\cite{cirac2021matrix}, we can choose a $l \times l$ square region with $l = \lceil 4\log D + 1 \rceil$.
%
The relative error would have a similar lower bound
\begin{align}
    \epsilon \geq \frac{1}{24}\left[ \left(\frac{L}{4\log D + 2} - 1\right)^2\frac{1}{2D^{8(4\log D + 2)}} - 3\right].
\end{align}
in a $L\times L$ system. Hence, one cannot achieve $\epsilon$ relative error with a constant bond dimension.


This result gives an upper bound on stabilizer Rényi entropy of Clifford augmented states: taking the log of~\eqref{eq:nogo_clifford_augmented_MPS_SRE_bound}, we find $\calM_2\leq N-O(\log N)$, suggesting that these states have at least logarithmic deviation from the maximum stabilizer Rényi entropy. 

\begin{corollary}[No-go theorem for states prepared by Clifford augmented FDLU]
\label{thm:nogo_clifford_augmented_FDLU}
Consider an ensemble of states $\{VU\ket{0}^{\otimes N}\}$, where $V$ are Clifford unitaries, and $U$ are $d$-dimensional local circuits with circuit depth bounded by $t$. The states cannot form an approximate state $k$-design for $k\geq 4$ with $\epsilon$ relative error for $t=\tilde{o}((\log(N/\epsilon))^{1/d})$, with $d=O(1)$.
\end{corollary}
\begin{proof}
Consider a hyper-cubic subsystem $M_i$ (with each side of length $l$) that contains $N_i=l^d$ qubits. The boundary of $M_i$ has area $2d l^{d-1}$. 
%
For states prepared by local unitary circuits with depth $t$, the entanglement entropy of subsystem $M_i$ has an upper bound 
%
\begin{equation}
\calS^{(2)}_i(t)\leq \calS_i(t)\leq 4 d l^{d-1} t,
\end{equation}
where $S_i(t)$ is the von-Neumann entropy of $M_i$. 

We consider the subsystems with $l = \lceil 4dt + 1\rceil$, so $\calS^{(2)}_i(t)\leq l^d-1$.
%
In a $d$-dimensional system of size $\underbrace{L\times\cdots\times L}_d$, the relative error has a lower bound
\begin{align}
    \epsilon \geq \frac{1}{24}\left[\left(\frac{L}{4dt + 2}-1\right)^d\frac{1}{2\cdot 2^{8dt(4dt +2)^{d-1}}}-3 \right].
\end{align}
Hence, the ensemble cannot form a state $k$-design with $\epsilon$ relative error for $t^d \log t = o(\log(N/\epsilon))$.
%
In particular, one cannot achieve a small $\epsilon$ relative error with $t=O(1)$.
\end{proof}


The no-go theorem for state $k$-design with bounded relative errors also implies a no-go theorem for unitary $k$-design with relative errors (Corollary~\ref{corollary:nogo_unitary_relative}). We start with the Lemma below.
\begin{lemma}[Choi state of relative-error unitary design is relative-error state design\footnote{We thank Thomas Schuster for insightful discussion that helps us improve this statement.}]\label{lemma:unitary_design_implies_state_design}
Let $\{U\}$ be an ensemble on $N$-qubit unitary $U$ that forms an approximate unitary $k$-design with relative error $\epsilon'$. 
%
Let $\ket{\EPR}$ be an EPR state between two copies of the system.
%
Then, the state ensemble $\calE = \{U \otimes I\ket{\EPR}\}$ is an approximate state $k$-design with relative error $\epsilon\le(1+\epsilon')(1+k^22^{-N})(1+k^22^{-2N})-1$, for $k^2\le2^N$.
\end{lemma}
\begin{proof}
The $k$-th moment of the state ensemble $\calE$ is $\rho_{\calE}^{(k)}=\varrho^{(k)} := [\Phi^{(k)}\otimes \id] (P_{\EPR})$, where $\Phi^{(k)}$ is the $k$-fold channel of the unitary ensemble $\{U\}$.
%
The unitary ensemble being a $k$-design with relative error $\epsilon'$ implies that $(1-\epsilon')\varrho_{\H}^{(k)}\preceq\varrho^{(k)}\preceq(1+\epsilon')\varrho_{\H}^{(k)}$.
%
As shown in~\cite{Schuster:2024ajb}, $\varrho_{\H}^{(k)}$ can be approximated by $\varrho_0^{(k)}=2^{-2Nk}\sum_{\sigma,\tau}r(\sigma)_L\otimes r(\tau)_R$, that is to say, $(1-k^22^{-N})\varrho_0^{(k)}\preceq\varrho_{\H}^{(k)}\preceq(1+k^22^{-N})\varrho_0^{(k)}$.
%
Therefore,
\begin{equation}\label{eq:nogo_choi_state_rho0}
(1-k^22^{-N})(1-\epsilon')\varrho_0^{(k)}\preceq\rho_\calE^{(k)}\preceq\varrho_0^{(k)}(1+\epsilon')(1+k^22^{-N}).
\end{equation}

Our goal is to bound the relative error between $\rho_\calE^{(k)}$ and the $k$-th moment of the Haar random state on the doubled system (the left system and the right system) $\rho_{\H,LR}^{(k)}=D_{2N,k}^{-1}\sum_{\pi}r(\pi)_L\otimes r(\pi)_R$.
%
The only difference between $\rho_{\H,LR}^{(k)}$ and $\varrho_0^{(k)}$ is the overall factors, which are relatively close to each other: $2^{-Nk}D_{N,k}-1\leq k^22^{-2N}$, so $(1-k^22^{-2N})\rho_{\H,LR}^{(k)}\preceq \varrho_0^{(k)}\preceq(1+k^22^{-2N})\rho_{\H,LR}^{(k)}$. 
%
Combined with~\eqref{eq:nogo_choi_state_rho0}, we conclude
\begin{equation}
(1-\epsilon)\rho_{\H,LR}^{(k)}\preceq\rho_{\calE}^{(k)}\preceq (1+\epsilon)\rho_{\H,LR}^{(k)},
\end{equation}
with $\epsilon=(1+\epsilon')(1+k^22^{-N})(1+k^22^{-2N})-1$.
\end{proof}
