\begin{corollary}[No-go theorem for Clifford sandwiched FDLU]\label{corollary:nogo_unitary_relative}
Let $V_1$ and $V_2$ be Clifford unitaries, and $U$ be d-dimensional local circuits with depth bounded by $t$.
\begin{equation*}
\includegraphics[width=6cm]{Figure/nogo_clifford_sandwiched_FDLU.pdf}
\end{equation*}
Then, the unitary ensemble $\{V_1 U V_2\}$ does not form a unitary $k$-design for $k\geq 4$ with $\epsilon$ relative error for $t=\tilde{o}((\log(N/\epsilon)^{1/d})$, with $d=O(1)$.
\end{corollary}
\begin{proof}
Consider the state ensemble $\calE = \{\big((V_1 U V_2)_L \otimes I_R\big)\ket{\EPR}\}$.
%
Each state $\ket{\psi} \in \calE$ is a Clifford augmented short-range entangled state, i.e.
\begin{equation}
\ket{\psi}=\big((V_1 U V_2)_L\otimes I_R\big)\ket{\EPR}=\big((V_{1})_L\otimes (V_{2}^{\top})_R\big) (U_L\otimes I_R)\ket{\EPR}.
\end{equation}
Since $\ket{\EPR}$ can be prepared from $\ket{0}^{\otimes 2N}$ in a depth-$1$ circuit, $(U_L\otimes I_R)\ket{\EPR}$ can be prepared using a unitary circuit of depth $t' = t+1$ in a system of $2N$ qubits.
%
According to Corollary~\ref{thm:nogo_clifford_augmented_FDLU}, the relative error of this state ensemble from a $k$-design has a lower bound
\begin{align}
    \epsilon \geq \frac{1}{24}\left[\left(\frac{L}{4dt' + 2}-1\right)^d\frac{1}{2\cdot 2^{8dt'(4dt' +2)^{d-1}}}-3 \right],
\end{align}
where we assume the system is of size $N = L^d$ with each dimension of size $L$.
Hence, according to Lemma~\ref{lemma:unitary_design_implies_state_design}, the relative error $\epsilon'$ between the unitary ensemble and a $k$-design for $k \geq 4$ has a lower bound
\begin{align}
    \epsilon' \geq \frac{\frac{1}{24}\left[\left(\frac{L}{4dt' + 2}-1\right)^d\frac{1}{2\cdot 2^{8dt'(4dt' +2)^{d-1}}}-3 \right] + 1}{(1+16\cdot 2^{-N})(1+16\cdot2^{-2N})} - 1.
\end{align}
For a depth $t$ being a constant, the relative error $\epsilon'$ is unbounded.
%
\end{proof}





\section{Designs with bounded additive error}\label{sec:add_error}
In this section, we construct state and unitary designs with bounded additive errors using Clifford circuits augmented with magic gates.

\subsection{State design with bounded additive errors}
\label{sec:state_additive}
We prove that two layers of Clifford gates followed by $O(k^2+\log(1/\epsilon))$ single-qubit $k$-design random unitaries can generate state $k$-design with bounded additive error.
%
We also prove in Appendix~\ref{sec:state_additive_initial_magic} that one can alternatively place $k$-design random unitaries before the Clifford gates. 
%
In this case, one needs to apply $k$-design unitaries over $O(k^2+\log(1/\epsilon))$ qubits, while each unitary acts on disjoint qubit clusters of size $O(k\log k)$.
%
A physical understanding of these results is provided in Sec.~\ref{sec:stat_mech_state_additive} by mapping the frame potential to statistical mechanics models, where magic plays the role of a symmetry breaking field.


To obtain state $k$-designs with magic gates at the final layer, the first step is to prove that one can get additive-error $k$-designs on $n$ qubits by applying $N_M=O(k^2+\log(1/\epsilon))$ single-qubit Haar random unitaries on random stabilizer states. 
%
The additive error for state designs has an upper bound in terms of the frame potential
\begin{equation}
    \lVert \rho_\calE^{(k)}-\rho_{\H}^{(k)}\rVert_1^2 \leq 2^{N k}\big[F_{\calE}^{(k)}-F_{\H}^{(k)}\big].
\end{equation}
%
Hence, we prove a bounded additive error by providing an upper bound on the frame potential difference.

\begin{lemma}[Additive error state design from applying constant magic to random stabilizer states]\label{thm:state_additive_linear_depth_final_magic}
Consider an $N$-qubit state $\ket{\psi}$ drawn from an approximate stabilizer state $k$-design with $\epsilon'$ additive error. 
Apply $N_M$ single-qubit unitaries, $U_1,\cdots, U_{N_M}$, independently drawn from (exact) unitary $k$-designs to $N_M$ distinct qubits. 
Assume $N\geq k+\log k-2$. 
\begin{equation*}\label{fig:state_additive_linear_depth}
\includegraphics[width=8.9cm]{Figure/state_additive_linear_depth.pdf}    
\end{equation*}
Then, the state ensemble $\calE=\{U_1\cdots U_{N_M}\ket{\psi}\}$ is an approximate state $k$-design with $\epsilon$ additive error, where $\epsilon\leq 2^{O(k^2)}\left(\frac{7}{8}\right)^{\frac{N_M}{4}} + \varepsilon'$.
\end{lemma}
\begin{proof}
First, the additive error of the $k$-th moment of the circuit ensemble can be upper bounded by the triangular inequality
\begin{equation}
\begin{aligned}
\lVert \Phi^{(k)}_{\H}\big(\rho_{\C,\epsilon'}^{(k)}\big)-\rho_{\H}^{(k)}\rVert_1 &\leq \lVert \Phi^{(k)}_{\H}\big(\rho_{\C}^{(k)}\big)-\rho_{\H}^{(k)}\rVert_1 + \lVert \Phi^{(k)}_{\H}\big(\rho_{\C,\epsilon'}^{(k)}\big)-\Phi^{(k)}_{\H}\big(\rho_{\C}^{(k)}\big)\rVert_1 \\
&\leq \lVert \Phi^{(k)}_{\H}\big(\rho_{\C}^{(k)}\big)-\rho_{\H}^{(k)}\rVert_1 + \varepsilon',\label{eq:addtive_error_state_triangle}
\end{aligned}
\end{equation}
where $\rho_{\C,\epsilon'}^{(k)}$ and $\rho_{\C}^{(k)}$ are the $k$-th moments of the stabilizer state $k$-design with additive error $\epsilon'$ and an exact stabilize state $k$-design, respectively.
%
On the second line, we use the monotonicity of 1-norm under quantum channels, \begin{align}
\lVert \Phi^{(k)}_{\H}\big(\rho_{\C}^{(k)}\big)-\Phi^{(k)}_{\H}\big(\rho_{\C,0}^{(k)}\big)\rVert_1 \leq \lVert\rho_{\C}^{(k)}-\rho_{\C,0}^{(k)}\rVert_1 \leq \varepsilon'.
\end{align}


Next, we bound the distance between $\Phi^{(k)}_{\H}\big(\rho_{\C}^{(k)}\big)$ and $\rho_{\H}^{(k)}$ using the $k$-th frame potential.
%
Given that $F_\calE^{(k)} \geq F_{\H}^{(k)}$, we here provide an upper bound for $F_{\calE}^{(k)}$.
%
Specifically,
\begin{equation}
F_{\calE}^{(k)}=\Tr\big[\Phi^{(k)}_{\H}\big(\rho_{\C}^{(k)}\big)\big]^2=\Tr\big[\rho_{\C}^{(k)}\Phi^{(k)}_{\H}\big(\rho_{\C}^{(k)}\big)\big]=\frac{1}{Z_{n,k}^2}\sum_{T_1,T_2}\bbrakket{T_1}{T_2}^{N-M}\bbra{T_1}\hat{\Phi}_{\H}^{(k)}\kket{T_2}^{M}.\label{eq:frame_potential_E}
\end{equation}
where $\hat{\Phi}_{\H}^{(k)}=\Ens_{U\sim\H}U^{\otimes k}\otimes U^{*\otimes k}$, and $\kket{T_1}$ and $\kket{T_2}$ are over single qubits.

A key step of our proof uses Lemma 13 of~\cite{Haferkamp:2020qel}. For $T \notin S_k$,
\begin{equation}
\bbra{T}\hat{\Phi}_{\H}^{(k)}\kket{T}\leq \frac{7}{8} 2^k.
\end{equation}
When $T_1$ is not a permutation, the Cauchy-Schwartz inequality indicates that
\begin{equation}
|\bbra{T_1}\hat{\Phi}_{\H}^{(k)}\kket{T_2}|\le\sqrt{\bbra{T_1}\hat{\Phi}_{\H}^{(k)}\kket{T_1}\bbrakket{T_2}{T_2}}\leq \sqrt{\frac{7}{8}}2^k,
\end{equation}
while for permutations $\pi\in S_k$, $\bbra{\pi}\hat{\Phi}_{\H}^{(k)}\kket{\pi}=2^k$.
%
This indicates that inserting a single-qubit random unitary suppresses the weight $\bbrakket{T_1}{T_2}$ when either $T_1$ or $T_2$ is not a permutation.


We divide the frame potential in Eq.~\eqref{eq:frame_potential_E} into two parts.
%
The contributions from $T_1,T_2\in S_k$ are 
\begin{equation}
F_\rmI^{(k)} := \frac{1}{Z_{N,k}^2}\sum_{\sigma,\tau\in S_k}\bbrakket{\sigma}{\tau}^{N-N_M}\bbra{\sigma}\hat{\Phi}_{\H}^{(k)}\kket{\tau}^{N_M}=\frac{1}{Z_{N,k}^2}\sum_{\sigma,\tau\in S_k}\bbrakket{\sigma}{\tau}^{n}=\frac{k! D_{N,k}}{Z_{N,k}^2},
\end{equation}
where $D_{N,k} = \frac{(2^N+k-1)!}{(2^N-1)!}$.
%
The deviation of $F_\rmI^{(k)}$ from the frame potential $k!2^{-N k}$  of the Haar random state is bounded by 
\begin{equation}
\left|\frac{k!D_{N,k}}{Z_{N,k}^2}-\frac{k!}{2^{N k}}\right|\le2^{O(k^2)-N}.
\end{equation}
The contribution from either $T_1\notin S_k$ or $T_2\notin S_k$ has an upper bound
\begin{equation}
F_\rmII^{(k)} := \frac{1}{Z_{N,k}^2}\sum_{T_1 \text{ or } T_2\notin S_k}\bbrakket{T_1}{T_2}^{N-N_M}\bbra{T_1}\hat{\Phi}_{\H}^{(k)}\kket{T_2}^{N_M} \leq \frac{2^{N k}}{Z_{N,k}^2}2^{O(k^2)}\left(\frac{7}{8}\right)^{N_M/2}.
\end{equation}
Putting these together $F_{\calE}^{(k)} = F_\rmI^{(k)}+F_{\rmII}^{(k)}$, we have
\begin{equation}
\lVert \Phi^{(k)}_{\H}\big(\rho_{\C}^{(k)}\big)-\rho_{\H}^{(k)}\rVert_1^2\leq 2^{N k}\big[F_{\calE}^{(k)}-F_{\H}^{(k)}\big]\le2^{O(k^2)-N}+ 2^{O(k^2)}\left(\frac{7}{8}\right)^{N_M/2}\le2^{O(k^2)}\left(\frac{7}{8}\right)^{N_M/2}.
\end{equation}
Inserting this result in Eq.~\eqref{eq:addtive_error_state_triangle}, we obtain the upper bound on the additive error $\epsilon$.
\end{proof}



\begin{theorem}[Additive-error state designs from low-depth Clifford unitaries followed by constant magic]\label{thm:state_additive_final_magic}
Apply a two-layer brickwork circuit $V$ to the initial state $\ket{0}^{\otimes N}$, where each gate is drawn form an exact Clifford $k$-design. Let $\xi$ be the smallest size of the overlapping regions of the Clifford unitaries. Then apply $N_M$ single-qubit unitaries, $U_1,\cdots, U_{N_M}$, independently drawn from (exact) unitary $k$-designs to $M$ distinct qubits. Assume $N\geq k+\log k-2$. Then the states $\calE=\left(\bigotimes_{i=1}^{N_M}U_i\right)V\ket{0}^{\otimes N}$ form an approximate state $k$-design with additive error $\epsilon\leq 2^{O(k^2)}\left(\frac{7}{8}\right)^{\frac{N_M}{4}} + N2^{-\xi-\log\xi+O(k^2)}$. In other words, one can achieve $\epsilon$ additive error with $N_M=O(k^2+\log(1/\epsilon))$ and $\xi=O(\log(N/\epsilon)+k^2)$.
\begin{equation*}
\includegraphics[width=10.8cm]{Figure/state_additive_final_magic.pdf}
\end{equation*}
\end{theorem}
\begin{proof}
A combination of Lemma~\ref{thm:state_additive_linear_depth_final_magic} and Corollary~\ref{thm:state_additive_clifford_design}.
\end{proof}
We note that if the single qubit random unitaries are drawn from approximate $k$-designs with additive error $\epsilon'$, the additive error has an additional term $(1+\epsilon')^{N_M}-1$, which follows from the triangular inequality and the definition of diamond norm. This term is bounded for $N_M = O(k^2+\log(1/\epsilon))$ as long as $\epsilon'$ is small enough.
%
We also note that in Appendix~\ref{app:gluing_lemma_haar_clifford}, we proved a Lemma to show that one can glue a state $k$-design and a stabilizer state $k$-design using a Clifford $k$-design to form a state $k$-design over a larger region. This Lemma combined with Lemma~\ref{thm:state_additive_linear_depth_final_magic} can give an alternative proof of Theorem~\ref{thm:state_additive_final_magic}.


\begin{corollary}[Circuit depth of additive-error state designs]
On an $N$ qubit system with $N\geq k+\log k-2$, one can realize approximate state $k$-designs with $\epsilon$ additive error using $O(k^2+\log(1/\epsilon))$ magic gates in depth 
\begin{itemize}
\item $O(\log (N/\epsilon)+k^2)$ using 1D circuits.
\item $O(\log\log (N/\epsilon)+\log k)$ using all-to-all circuits with $O(N(\log(N/\epsilon)+k^2))$ ancillas. 
\end{itemize}
\begin{proof}
Similar to the proof of Corollary~\ref{thm:unitary_relative_circuit_depth}.
\end{proof}

\end{corollary}

Our construction of state $k$-designs with additive error only use $O(k^2+\log(1/\epsilon))$ (a system size independent number) of magic gates.
%
One may wonder why the $k$-th moment of the ensemble cannot be distinguished from that of Haar random states by measuring $r(T_S)$ defined in Sec.~\ref{sec:rel_error_nogo}. 
%
This observable is related to stabilizer R\'enyi entropy, which is a measures the magic of pure states.
%
The reason is twofold. 
%
First, the Haar value $\Tr[r(T_S)\rho_{\H}^{(k)}]$ is exponentially small in $N$, leading to an $O(N)$ stabilizer R\'enyi entropy.
%
A small difference between $\Tr[r(T_S)\rho_{\H}^{(k)}]$ and $\Tr[r(T_S)\rho_{\calE}^{(k)}]$ does not mean the stabilizer R\'enyi entropy of the two states are close. 
%
Second, forming an additive-error state design cannot even imply a small difference between $\Tr[r(T_S)\rho_{\H}^{(k)}]$ and $\Tr[r(T_S)\rho_{\calE}^{(k)}]$.
%
To be more precise, we may attempt to use the H\"older's inequality
\begin{equation}
\left|\Tr[r(T_S)(\rho_{\calE}^{(k)}-\rho_{\H}^{(k)})]\right|\leq \lVert r(T_S)\rVert_\infty\cdot\lVert\rho_{\calE}^{(k)}-\rho_{\H}^{(k)}\rVert_1.
\end{equation}
However, $\lVert r(T_S)\rVert_\infty=2^N$, leading to a very loose bound $2^N\epsilon$.


\subsection{Unitary design with bounded additive error}\label{sec:unitary_additive}
We consider the circuit that consists of Haar random gates over $O(k^3)+\log(1/\varepsilon)$ qubits followed by global random Clifford unitaries. 
We prove that the circuit ensemble forms an approximate unitary $k$-design up to $\varepsilon$ additive error.

\begin{theorem}[Additive-error unitary designs from circuits with magic gates over constant-number of qubits]
Consider an $ N$-qubit system with $M$ being a subsystem of size $N_M$. $U$, acting on $M$, is drawn from approximate unitary $k$-design with additive error $\epsilon'$. $V$ is drawn from (exact) Clifford $k$-design acting on all qubits. Then, the ensemble $\calE = \{VU\}$ forms an approximate unitary $k$-design up to additive error $\varepsilon\leq \epsilon'+ 2^{O(k^3)-N_M}(1+k^22^{-N_M})$.
\begin{equation*}
\includegraphics[width=5.5cm]{Figure/unitary_additive.pdf}
\end{equation*}
\end{theorem}
\begin{proof}
Let $\bar{M}$ denote the complement of subsystem $M$, with size $N_{\bar{M}} = N - N_M$. 
Let $\Phi_{\C}^{(k)}$ denote the $k$-th moment of random Clifford unitaries on $N$ qubits. 
Let $\Phi_{\H,M,\epsilon'}^{(k)}$ denote the $k$-fold channel of an approximate unitary design acting on $M$. 
Let $\Phi_{\H,M}^{(k)}$ denote the $k$-fold channel of an exact unitary design acting on $M$. 
By assumption $\lVert\Phi_{\H,M,\epsilon'}^{(k)}-\Phi_{\H,M}^{(k)}\rVert_\Diamond\le\epsilon'$.

The $k$-fold channel of our unitary ensemble is $\Phi_{\calE,\epsilon'}^{(k)}=\Phi_{\C}^{(k)}\circ(\Phi_{\H,M,\epsilon'}^{(k)}\otimes \id_{\bar{M}})$. 
%
We first bound its diamond distance from $\Phi_0^{(k)}=2^{-Nk}\sum_{\pi}|\pi)(\pi|$ using the triangle inequality:
\begin{equation}
\lVert\Phi_{\calE,\epsilon'}^{(k)}-\Phi_0^{(k)}\rVert_\Diamond\leq \lVert\Phi_{\calE,\epsilon'}^{(k)}-\Phi_{\calE,0}^{(k)}\rVert_\Diamond+ \lVert\Phi_{\calE,0}^{(k)}-\Phi_0^{(k)}\rVert_\Diamond,
\end{equation}
where $\Phi_{\calE,0}^{(k)}$ is obtained by replacing $\Phi_{\H,M,\epsilon'}^{(k)}$ with the exact $k$-design $\Phi_{\H,M}^{(k)}$. The first term is bounded by
\begin{equation}
\begin{aligned}
\lVert\Phi_{\calE,\epsilon'}^{(k)}-\Phi_{\calE,0}^{(k)}\rVert_\Diamond&=\max_{\lVert O\rVert_1\leq 1}\lVert\Phi_{\C}\circ(\Phi_{\H,M,\epsilon'}-\Phi_{\H,M})\otimes \id (O) \rVert_1 
 \\
&\le\max_{\lVert O\rVert_1\leq 1}\onenorm{(\Phi_{\H,M,\epsilon'}-\Phi_{\H,M})\otimes \id (O)}  \\
&=\lVert\Phi_{\H,M,\epsilon'}-\Phi_{\H,M}\rVert_\Diamond\le\epsilon'.
\end{aligned}
\end{equation}

Next we bound the distance $\lVert\Phi_{\calE,0}^{(k)}-\Phi_0^{(k)}\rVert_\Diamond$, where
\begin{equation}\label{eq:unitary_additive_moments}
\begin{aligned}
\Phi_{\calE,0}^{(k)}&=\Phi_{\C}^{(k)}\circ(\Phi_{\H,M}^{(k)}\otimes \id_{\bar{M}})\\
&=\sum_{T_1,T_2,\sigma,\tau}\Wg_{\C}(T_1,T_2)2^{N_M(k-|T_2,\sigma|)}\Wg(\sigma,\tau)|T_1)(\tau|^{\otimes N_M}\otimes |T_1)(T_2|^{\otimes N_{\bar{M}}}.
\end{aligned}
\end{equation}
The diamond norm of each term is given by (Appendix~\ref{app:diamond_norm})
\begin{equation}
\lVert|T_1)(\tau|^{\otimes N_M}\otimes |T_1)(T_2|^{\otimes N_{\bar{M}}}\rVert_\Diamond=2^{Nk-N_M\dim\rmN_i+N_{\bar{M}}(\dim\rmN_j-\dim\rmN_i)}  
\end{equation}
which follows from~\eqref{eq:clifford_commutant_diamond_norm_bound} and the fact that the diamond norm is multiplicative under tensor product~\cite{Aharonov:1998zf}. 
We decompose the sum into contributions from four classes of $(T_1,T_2)$ pairs:
\begin{equation}
\begin{aligned}
\rmI&:=\{(T_1,T_2)|\,T_1=T_2\in S_k\} \\
\rmII&:=\{(T_1,T_2)|\,T_2\in S_k, T_1\neq T_2\} \\
\rmIII&:=\{(T_1,T_2)|\, T_1=T_2\notin S_k\}\\
\rmIV&:=\{(T_1,T_2)|\, T_2\notin S_k, T_1\neq T_2\}
\end{aligned}
\end{equation}
Let $\Phi_\rmI^{(k)}$, $\Phi_\rmII^{(k)}$, $\Phi_\rmIII^{(k)}$ and $\Phi_\rmIV^{(k)}$ denote the contributions of the classes of $(T_1,T_2)$ pairs to the sum~\eqref{eq:unitary_additive_moments}. Using the triangle inequality:
\begin{equation}
\lVert\Phi_{\calE,0}^{(k)}-\Phi_0^{(k)}\rVert_\Diamond\leq \lVert\Phi_\rmI^{(k)}-\Phi_0^{(k)}\rVert_\Diamond+\lVert\Phi_\rmII^{(k)}\rVert_\Diamond+\lVert\Phi_\rmIII^{(k)}\rVert_\Diamond+\lVert\Phi_\rmIV^{(k)}\rVert_\Diamond.
\end{equation}
Notice that when $T_2=\pi\in S_k$, we can sum over $\sigma$ to lock $\tau$ to be $\pi$:
\begin{equation}
\sum_{\sigma}2^{N_M(k-|\pi,\sigma|)}\Wg(\sigma,\tau)=\delta_{\pi,\sigma}. 
\end{equation}
Thus,
\begin{equation}
\begin{aligned}
\lVert\Phi_\rmI^{(k)}-\Phi_0^{(k)}\rVert_\Diamond+\lVert\Phi_\rmII^{(k)}\rVert_\Diamond 
&\leq \sum_{\pi}|\Wg_{\C}(\pi,\pi)-2^{-Nk}|\!\cdot\!\lVert|\pi)(\pi|^{\otimes N}\rVert_\Diamond+\sum_{T\neq\pi}|\Wg_{\C}(T,\pi)|\!\cdot\!\lVert|T)(\pi|^{\otimes N}\rVert_\Diamond \\
&\leq k!2^{-N+O(k^2)} + k!2^{-N+O(k^2)}\le2^{-N+O(k^2)} .
\end{aligned}
\end{equation}
We use~\eqref{eq:clifford_weingartens_asymptotics} and~\eqref{eq:clifford_commutant_diamond_norm_bound} to bound the two terms on the first line, and absorb the factor $k!$ into $2^{O(k^2)}$.

In classes III and IV, $T_2$ is not a permutation. In this case, there is an overall suppression because $T_2$ and $\sigma$ are not aligned:
\begin{equation}
\sum_{\sigma,\tau}2^{N_M(k-|T_2,\sigma|)}|\Wg(\sigma,\tau)|\le2^{N_M(k-1)}\sum_{\sigma,\tau}|\Wg(\sigma,\tau)|\le2^{-N_M}k!(1+k^22^{-N_M}),
\end{equation}
where we used $|T_2,\sigma|\geq 1$ and $\sum_{\sigma,\tau}|\Wg(\sigma,\tau)|\leq 2^{-kN_M}k!(1+k^22^{-N_M})$~\cite{Aharonov:2021das}. In class III $T_1=T_2=T \notin S_k$, we use the upper bound on the diamond norm $\lVert|T)(\tau|^{\otimes N_M}\otimes |T)(T|^{\otimes N_{\bar{M}}}\rVert_\Diamond\leq 2^{Nk}$ and obtain
\begin{equation}
\begin{aligned}
\lVert\Phi_\rmIII^{(k)}\rVert_\Diamond&\leq\sum_{T \notin S_k}|\Wg_{\C}(T,T)|\sum_{\sigma,\tau}2^{N_M(k-|T,\sigma|)}|\Wg(\sigma,\tau)|\cdot\lVert|T)(\tau|^{\otimes N_M}\otimes |T)(T|^{\otimes N_{\bar{M}}}\rVert_\Diamond \\
&\leq 2^{-N_M+O(k^2)}k!(1+k^22^{-N_M}).
\end{aligned}
\end{equation}
For $T_1\neq T_2$, the diamond norm can be greater than $2^{Nk}$, but these contributions are suppressed by $\Wg_{\C}(T_1,T_2)$ due to the misalignment of $T_1$ and $T_2$ (the third line in~\eqref{eq:clifford_weingartens_asymptotics}), that is,
\begin{equation}
\begin{aligned}
&\sum_{T_1\neq T_2}|\Wg_{\C}(T_1,T_2)|\cdot\lVert|T_1)(\tau|^{\otimes N_M}\otimes |T_1)(T_2|^{\otimes N_{\bar{M}}}\rVert_\Diamond \leq 2^{O(k^3)} \\
\Rightarrow&\quad \lVert\Phi_\rmIV^{(k)}\rVert_\Diamond\leq 2^{-N_M+O(k^3)}k!(1+k^22^{-N_M}).
\end{aligned}
\end{equation}

Putting these together, we obtain an upper bound
\begin{equation}
\lVert\Phi_{\calE}^{(k)}-\Phi_0^{(k)}\rVert_\Diamond\leq \epsilon'+2^{-N_M+O(k^3)}(1+k^22^{-N_M}),
\end{equation}
where we have absorbed factors of $k!$ into $2^{O(k^3)}$.

As a final step, we use the triangle inequality to bound the additive error of the $k$-fold channel:
\begin{equation}
\lVert\Phi_{\calE}^{(k)}-\Phi_{\H}^{(k)}\rVert_\Diamond\le\lVert\Phi_{\calE}^{(k)}-\Phi_0^{(k)}\rVert_\Diamond+\lVert\Phi_0^{(k)}-\Phi_{\H}^{(k)}\rVert_\Diamond \le\epsilon'+2^{O(k^3)-N_M}(1+k^22^{-N_M}).
\end{equation}


\end{proof}

\begin{corollary}[Circuit depth]
With $O(k^4\poly\log(k/\epsilon))$ two-qubit magic gates, one can realize approximate unitary $k$-designs with $\epsilon$ additive error in depth $O(N+k\poly\log (k/\epsilon))$ using 1D circuits and in depth $O(\log N+k\poly\log (k/\epsilon))$ using all-to-all circuits with $N^2$ ancillas. 
\end{corollary}
\begin{proof}
A sufficient condition for achieving approximate unitary designs with $\epsilon$ additive error is to take $N_M=O(k^3+\log(1/\epsilon))$. To realize an additive-error unitary design on these qubits, circuits with depth $O(\log (N_M/\epsilon)\cdot k\poly\log k)$ suffice~\cite{Schuster:2024ajb}.
\end{proof}

We note that, in this construction, we place the magic gate at the beginning of the circuit for a technical reason to suppress the diamond norm because $\lVert|T_1)(T_2|\rVert_{\Diamond}$ is smaller for $T_2 \in S_k$.
%
We do not exclude the possibility of constructing an additive-error unitary design if all magic gates are placed at the final layer.

We further note that the global Clifford unitary in this construction might be necessary.
%
In a recent paper~\cite{Grevink:2025nez}, it is shown that to form a Clifford $k$-design with bounded additive error, Clifford circuits are required to have $\Omega(N)$ depth in one dimension or $\Omega(\log N)$ depth with all-to-all connectivity. This theorem can be modified to show that shallow-Clifford circuits with the insertion of magic gates acting on a constant number of qubits, even at arbitrary locations within the Clifford circuit, cannot realize a unitary $k$-design with bounded additive error, since the causal light-cone from the magic gates cannot cover a finite fraction of the qubits in the system. 

