\section{Operational meaning of additive-error state designs}\label{app:operation_state_additive_error}

In this appendix, we consider an adaptive experiment that queries a random state $\ket{\psi}$ drawn from an ensemble for $k$ times.
%
If the ensemble forms a state $k$-design with bounded additive error, the output state would have a bounded trace distance from the output of the experiment that queries genuine Haar random states.

Any adaptive experiment that queries the state $k$ times can be achieved by querying the states in parallel.
\begin{equation*}
\includegraphics[width=12cm]{Figure/state_additive_adaptive_experiment.pdf}
\end{equation*}
The most general adaptive experiment that queries $k$ copies of the state $\ket{\psi}$ is shown on the left. 
Let $m$ denote the number of ancillas used in the experiments, and these ancillas are initialized in $\ket{0}^{\otimes m}$. 
%
In the first step, we apply a unitary $W_1$ acting on the ancillas and a copy of $\ket{\psi}$. 
%
In the $t$-th step, we introduce one copy of $\ket{\psi}$ and apply a unitary $W_t$ that couple $\ket{\psi}$ to all the degrees of freedom that we have introduced previously.
%
In the end, the output state of the experiment is $\ket{\psi_{\text{out}}}=W_k\cdots W_1\ket{0}^{\otimes m}\ket{\psi}^{\otimes k}$, which can be viewed as applying a unitary to the initial state $\ket{\psi}^{\otimes k}$, as shown on the right. 
%
If the state $\ket{\psi}$ is drawn from an ensemble $\calE$ that forms an approximate state $k$-design with $\epsilon$ additive error, the trace distance between the output state and the output of an experiment that queries Haar random states is
\begin{equation}
\left\lVert\Ens_{\psi\sim\calE}\ketbra{\psi_{\text{out}}}-\Ens_{\psi\sim\H}\ketbra{\psi_{\text{out}}}\right\rVert_1=\lVert\rho_{\calE}^{(k)}-\rho_{\H}^{(k)}\rVert_1\le\epsilon.
\end{equation}
The first equality is because the trace norm is invariant under unitaries.




\section{Additive-error state designs with magic gates in the first layer}\label{sec:state_additive_initial_magic}

In this appendix, we provide a construction of the state $k$-design with bounded additive errors by inserting magic gates prior to the two-layer Clifford unitary.

\begin{corollary}[Additive-error state designs from constant magic followed by low-depth Clifford unitaries]
\label{thm:state_additive_initial_magic}
Consider a system of $N$ qubits. Let ${M_i}$ denote disjoint subsystems, each containing $N_i$ qubits. Assume $N_i\geq 2\log k$. Let $N_M=\sum_i N_i$ be the total size of these subsystems. The unitaries $U_i$, acting on subsystem $M_i$, are independently drawn from exact unitary $k$-designs. Let $V$ be a two-layer brickwork circuit, where each gate is drawn form an exact Clifford $k$-design. Let $\xi$ be the smallest size of the overlapping regions of the Clifford unitaries. Then the states $V\left(\bigotimes_i U_i\right)\ket{0}^N$ form an approximate state $k$-design with additive error 
\begin{equation}
    \epsilon\leq 2^{-\xi-\log\xi+O(k^2)}+ 2^{O(k^2)}\prod_i2^{-N_i}k!(1+k^22^{-N_i}).
\end{equation} 
In other words, one can achieve $\varepsilon$ additive error with $N_M= O\big(k^2+\log(1/\epsilon)\big)$ and $\xi=O(\log(N/\epsilon)+k^2)$.
\begin{equation*}
\includegraphics[width=8.2cm]{Figure/state_additive_log_depth_initial_magic.pdf}
\end{equation*}
\end{corollary}
\begin{proof}
Before applying the Clifford unitary, the state on $M=\cup_i M_i$is a tensor product of Haar random states on $M_i$, whose $k$-th moment is
\begin{equation}
\rho_{\calE_0}^{(k)}=\left[\sum_{\sigma_i,\tau_i}\bigotimes_i\Wg(\sigma_i,\tau_i)r(\sigma_i)_{M_i}\right]\otimes \ket{0}\bra{0}^{\otimes N-N_M}.
\end{equation}
According to Lemma~\ref{thm:uniformity_log_depth}, the Clifford unitaries $V$ satisfies the $\epsilon'$-approximate uniformity condition with $\epsilon'=2^{-\xi-\log\xi+O(k^2)}$. The $k$-th moment of these Clifford unitaries can be written as
\begin{equation}
\Phi_{\calE_u}^{(k)}=2^{-Nk}\left[\sum_T|T)(T|+\sum_{\vec{T}_1,\vec{T_2}}f(\vec{T}_1,\vec{T}_2)|\vec{T}_1)(\vec{T}_2|\right].
\end{equation}
Applying it to the initial state, the state $k$-th moment becomes
\begin{equation}
\begin{aligned}
\rho_{\calE}^{(k)}&=2^{-Nk}\left[\sum_T r(T)\prod_i\sum_{\sigma_i,\tau_i}2^{N_i(k-|T,\sigma_i|)}\Wg(\sigma_i,\tau_i)\right. \\
&\qquad\qquad\left.+\sum_{\vec{T}_1,\vec{T}_2}f(\vec{T}_1,\vec{T}_2) r(\vec{T}_1)\prod_i\sum_{\sigma_i,\tau_i}\Wg(\sigma_i,\tau_i)2^{N_i(k-|T_{2,i},\sigma_i|)}\right],
\end{aligned}
\end{equation}
where $i$ is the index for subregions $M_i$, and $T_{2,i}$ is the value of $\vec{T}_2$ on region $M_i$. 
%
We decompose $\rho_{\calE}^{(k)}$ into three parts $\rho_{\calE}^{(k)}=\rho_{\rmI}^{(k)}+\rho_{\rmII}^{(k)}+\rho_{\rmIII}^{(k)}$, where
\begin{equation}
\begin{aligned}
&\rho_{\rmI}^{(k)}=2^{-Nk}\sum_{\pi}r(\pi)=2^{-Nk}D_{N,k}\rho_{\H}^{(k)},\\
&\rho_{\rmII}^{(k)}=2^{-Nk}\sum_{T\notin S_k} r(T)\prod_i\sum_{\sigma_i,\tau_i}2^{N_i(k-|T,\sigma_i|)}\Wg(\sigma_i,\tau_i), \\
&\rho_{\rmIII}^{(k)}=2^{-Nk}\sum_{\vec{T}_1,\vec{T}_2}f(\vec{T}_1,\vec{T}_2) r(\vec{T}_1)\prod_i\sum_{\sigma_i,\tau_i}\Wg(\sigma_i,\tau_i)2^{N_i(k-|T_{2,i},\sigma_i|)}.
\end{aligned}
\end{equation}
Using the triangle inequality, the additive error is bounded by
\begin{equation}
\lVert\rho_\calE^{(k)}-\rho_{\H}^{(k)}\rVert_1
\le\lVert\rho_{\rmI}^{(k)}-\rho_{\H}^{(k)}\rVert_1+\lVert\rho_{\rmII}^{(k)}\rVert_1+\lVert\rho_{\rmIII}^{(k)}\rVert_1.
\end{equation}
Each term on the right has an upper bound:
\begin{equation}
\lVert\rho_{\rmI}^{(k)}-\rho_{\H}^{(k)}\rVert_1=|2^{-Nk}D_{N,k}-1|\cdot\lVert\rho_{\H}^{(k)}\rVert_1\leq k^2 2^{-N}.
\end{equation}
\begin{equation}
\begin{aligned}
\lVert\rho_{\rmII}^{(k)}\rVert_1&\leq 2^{-Nk} \sum_{T\notin S_k} \lVert r(T)\rVert_1\prod_i\sum_{\sigma_i,\tau_i}2^{N_i(k-|T,\sigma_i|)}|\Wg(\sigma_i,\tau_i)| \\
&\leq 2^{O(k^2)}\prod_i\sum_{\sigma_i,\tau_i}2^{N_i(k-1)}|\Wg(\sigma_i,\tau_i)|  \leq 2^{O(k^2)} \prod_i2^{-N_i}k!(1+k^22^{-N_i})
\end{aligned}
\end{equation}
Here, we use $\lVert r(T)\rVert_1\leq 2^{Nk}$ and $\sum_{\sigma_i,\tau_i}|\Wg(\sigma_i,\tau_i)|\leq k!(1+k^22^{-N_i})$ for $k^2\leq 2^{N_i}$.
\begin{equation}\label{eq:state_additive_initial_magic_third_term}
\begin{aligned}
&\lVert\rho_{\rmIII}^{(k)}\rVert_1\leq 2^{-Nk} \sum_{\vec{T}_1,\vec{T}_2}|f(\vec{T}_1,\vec{T}_2)|\cdot \lVert r(\vec{T}_1)\rVert_1\prod_i\Big|\sum_{\sigma_i,\tau_i}2^{N_i(k-|T_{2,i},\sigma_i|)}\Wg(\sigma_i,\tau_i)\Big|
\end{aligned}
\end{equation}
If $T_{2,i}\in S_k$, then $\sum_{\sigma_i,\tau_i}\Wg(\sigma_i,\tau_i)2^{N_i(k-|T_{2,i},\sigma_i|)}=1$. If $T_{2,i}\notin S_k$, then
\begin{equation}
\Big|\sum_{\sigma_i,\tau_i}2^{N_i(k-|T_{2,i},\sigma_i|)}\Wg(\sigma_i,\tau_i)\Big|\leq \sum_{\sigma_i,\tau_i}2^{N_i(k-1)}|\Wg(\sigma_i,\tau_i)|\le2^{-N_i}k!(1+k^22^{-N_i})\le1    
\end{equation}
The last inequality is from the assumption $N_i\geq 2k\log k$. Plugging it back to~\eqref{eq:state_additive_initial_magic_third_term} and using $\lVert r(\vec{T}_1)\rVert_1\leq 2^{Nk}$, we have $\lVert\rho_{\rmIII}^{(k)}\rVert_1\le\sum_{\vec{T}_1,\vec{T}_2}|f(\vec{T}_1,\vec{T}_2)| \le\epsilon'=2^{-\xi-\log\xi+O(k^2)} $.

Putting these together, the additive error is bounded by
\begin{equation}
\lVert\rho_\calE^{(k)}-\rho_{\H}^{(k)}\rVert_1\le2^{O(k^2)} \prod_i2^{-N_i}k!(1+k^22^{-N_i})+2^{-\xi-\log\xi+O(k^2)}.
\end{equation}
\end{proof}

In this construction of an additive-error state $k$-design, each state in the ensemble can be described by a Clifford augmented matrix product state.
%
The possibility of such states to realize additive error $4$-designs has been studied in~\cite{lami2025quantum}.
%
Our result demonstrates that such states can realize designs for $k > 4$, and the initial non-stabilizer state can be prepared by local magic gates that only act on a few qubits.

