\section{Collision probabilities in log-depth Clifford circuits}\label{app:collision_prob}

In this appendix, we study the $k$-th collision probability in an ensemble of Clifford unitaries. 
%
We show that this quantity obtained in two-layer random Clifford circuits approximates the one for global random Clifford gates with a bounded relative error.
%
Our result is consistent with the fact that anti-concentration happens at a logarithmic depth shown in Ref.~\cite{Barak:2020svy,Dalzell:2020vxs,Magni:2025zqf,aharonov2023polynomial}.

For a unitary ensemble $\calE= \{V\}$, the $k$-th collision probability for a given computation basis $\ket{\boldx}$ takes the form
\begin{equation}
p_{\calE}^{(k)}(\boldx):=\Ens_{V\sim\calE}|\bra{\boldx}V\ket{0}^{\otimes N}|^{2k}.
\end{equation}
For global random Clifford gates, this quantity is given by
\begin{equation}
p_{\C}^{(k)}:=\Ens_{V\sim\C}|\bra{\boldx}V\ket{0}^{\otimes N}|^{2k}=Z_{N,k}^{-1}|\Sigma_{k,k}|.
\end{equation}

\begin{corollary}[Relative error for the collision probability in log-depth Clifford circuits]
Consider an ensemble $\calE= \{V\}$ of two-layer Clifford circuits with each gate drawn independently from an exact Clifford $k$-design. 
Let $\xi$ be the size of the smallest overlapping regions in the two-layer Clifford circuit. 
The two-layer Clifford circuit achieves a relative error $\epsilon=N2^{-\xi-\log\xi+O(k^2)}$ in the $k$-th collision probability with respect to global random Clifford unitaries, i.e.
\begin{equation}
(1-\epsilon)p_{\C}^{(k)}\leq p_{\calE}^{(k)}(\boldx)\leq (1+\epsilon)p_{\C}^{(k)}\quad \text{for}\ \forall\boldx.
\end{equation}
In other words, one can achieve $\epsilon$ relative error in depth $O(\log(N/\epsilon)+k^2)$.
\end{corollary}
\begin{proof}
The $k$-fold channel of two-layer random Clifford circuits satisfies the approximate uniformity according to Theorem~\ref{thm:uniformity_log_depth}. Hence, it takes the form
\begin{equation}
\Phi_\calE^{(k)}=2^{-Nk}\left[\sum_T|T)(T|+\sum_{\vec{T}_1,\vec{T_2}}f(\vec{T}_1,\vec{T}_2)|\vec{T}_1)(\vec{T}_2|\right]
\end{equation}

The $k$-th collision probability is given by
\begin{equation}
\begin{aligned}
\Ens_{U\sim\calE}|\bra{\boldx}U\ket{0}^{\otimes N}|^{2k}&=\Tr[\ketbra{\boldx}^{\otimes k}\Phi_\calE^{(k)}(\ketbra{0}^{\otimes kN})] \\
&=2^{-Nk}\Bigg[\sum_T \Tr[\ketbra{\boldx}^{\otimes k}r(T)]\Tr[r(T)^{\top}\ketbra{0}^{\otimes kN}] \\
&\qquad+\sum_{\vec{T}_1,\vec{T_2}}f(\vec{T}_1,\vec{T}_2)\Tr[\ketbra{\boldx}^{\otimes k}r(\vec{T}_1)]\Tr[r(\vec{T}_2)^{\top}\ketbra{0}^{\otimes kN}]\Bigg] \\
&= 2^{-Nk}\Bigg[|\Sigma_{k,k}|+\sum_{\vec{T}_1,\vec{T_2}}f(\vec{T}_1,\vec{T}_2)\Bigg].
\end{aligned}
\end{equation}
Here, we note that $\Tr[\ketbra{\boldx}^{\otimes k} r(T)] = \Tr[\ketbra{0}^{\otimes kN} r(T)] = 1$ because any computational basis state $\ket{\boldx}$ is related to $\ket{0}^{\otimes N}$ by a Clifford gate, whose $k$-th tensor power commutes with $r(T)$ in the commutant.

The relative error therefore has an upper bound
\begin{equation}
\begin{aligned}
\frac{\big|p_{\calE}^{(k)}(\boldx)-p_{\C}^{(k)}\big|}{p_{\C}^{(k)}}
\le& |2^{-Nk}Z_{N,k}-1|+2^{-Nk}Z_{N,k}\sum_{\vec{T}_1,\vec{T_2}}|f(\vec{T}_1,\vec{T}_2)| \\
\le& k2^{k-N}+N2^{-\xi-\log\xi+O(k^2)}.
\end{aligned}
\end{equation}
\end{proof}

\section{Growing additive-error state designs with random Clifford gates}\label{app:gluing_lemma_haar_clifford}
We prove that a state $k$ design and a stabilizer state $k$ design can be glued by Clifford unitaries drawn from a Clifford $k$ design to form a state $k$ design over a larger region with bounded additive error.
%


\begin{lemma}[Gluing a state design and a stabilizer state design using unitaries from Clifford design]\label{thm:state_additive_haar_gluing}
Let $A$, $B$, $C$, and $D$ be disjoint subsystems of qubits. $N_A$, $N_B$, $N_C$, $N_D$ denote the size of the subsystems. Assume $N_C\geq k+\log k-2$. $\ket{\psi}_{AB}$ is drawn from a state $k$-design up to additive error $\varepsilon_{AB}$, $\ket{\psi}_{CD}$ is drawn from an exact stabilizer $k$-design. $V_{BC}$ is drawn from a (exact) Clifford $k$-design. Then $V_{BC}\ket{\psi}_{AB}\otimes \ket{\psi}_{CD}$ is an approximate state $k$-design with additive error $\varepsilon\leq \varepsilon_{AB} +2^{O(k^2)}(2^{-N_B}+2^{-N_C})$.
\begin{align*}
\includegraphics[width=14cm]{Figure/state_additive_haar_gluing.pdf}
\end{align*}
\end{lemma}

\begin{proof}
We write the resulting state as $\rho_{\H,AB,\varepsilon}^{(k)}\otimes\rho_{\C,CD}^{(k)}$. It can be approximated up to additive error $\varepsilon$ by
\begin{equation}
\rho_{\H,AB}^{(k)}\otimes\rho_{\C,CD}^{(k)}=D_{N_{AB},k}^{-1}Z_{N_{CD},k}^{-1}\sum_{\sigma,T}{r(\sigma)}_{AB}\otimes r(T)_{CD}
\end{equation}
where $\rho_{\H,AB}^{(k)}$ is the $k$-th moment of an exact $k$-design on $AB$.
%
After applying the random Clifford unitaries, the $k$-th moment of the state becomes
\begin{equation}
\begin{aligned}
&\Phi_{\C,BC}^{(k)}(\rho_{\H,AB}^{(k)}\otimes\rho_{\C,CD}^{(k)})\\
&\quad =D_{N_{AB},k}^{-1}Z_{N_{CD},k}^{-1}\sum_{\sigma,T_1,T_2,T_3}\Wg_{\C}(T_1,T_2)2^{N_B(k-|T_2,\sigma|)+N_C(k-|T_2,T_3|)}r(\sigma)_A\otimes r(T_1)_{BC}\otimes r(T_3)_D
\end{aligned}
\end{equation}
\begin{equation*}
\includegraphics[width=4cm]{Figure/state_additive_haar_gluing_proof.pdf}  
\end{equation*}


The trace distance from the $k$-th moment of Haar random states takes the form
\begin{align}
&\lVert \Phi_{\C,BC}^{(k)}(\rho_{\H,AB}^{(k)}\otimes\rho_{\C,CD}^{(k)})-\rho_{\H,ABCD}^{(k)}\lVert_1 \nonumber \\
&\begin{aligned}
\leq 2^{kN}\Bigg|\sum_{\sigma,T_1,T_3}D_{N_{AB},k}^{-1}Z_{N_{CD},k}^{-1}\sum_{T_2}\Wg_{\C}(T_1,T_2)2^{N_B(k-|T_2,\sigma|)+N_C(k-|T_2,T_3|)}-D_{N,k}^{-1}\delta_{T_1,\sigma}\delta_{T_3,\sigma}\Bigg|
\end{aligned}
\end{align}
where we use $\lVert r(\sigma)_A\otimes r(T_1)_{BC}\otimes r(T_3)_D\rVert_1\leq 2^{kN}$, $N=N_A+N_B+N_C+N_D$. 
For $T_3=\sigma$, the summation over $T_2$ yields a delta function $\delta_{T_1,\sigma}$. The corresponding contribution is
\begin{equation}
\begin{aligned}
%
2^{kN}\sum_{\sigma \in S_k}\left|D_{N_{AB},k}^{-1}Z_{N_{CD},k}^{-1}-D_{N,k}^{-1}\right| \leq & k!\big[(1+k^22^{-N_{AB}})(1+k2^{k-N_{CD}})-1+k^22^{-N}\big] \\
\leq &k!(k^2 2^{-N_{AB}} + k 2^{k-N_{CD}} + (k^3+k^2) 2^{-N}) %
%
\end{aligned}
\end{equation}
For $T_3\notin S_k$, the contribution 
\begin{equation}
\begin{aligned}
& 2^{kN}D_{N_{AB},k}^{-1}Z_{N_{CD},k}^{-1}\big|\Wg_{\C}(T_1,T_2)\big|2^{N_B(k-|T_2,\sigma|)+N_C(k-|T_2,T_3|)}
\end{aligned}
\end{equation}
is either suppressed by $2^{-N_B}$ or $2^{-N_C}$ due to misalignment of inside $2^{N_C(k-|T_2,\sigma|)+N_C(k-|T_2,T_3|)}$, or suppressed by misalignment in $T_1$ and $T_2$ to give $|\Wg_{\C}(T_1,T_2)|\leq 2^{-N_{BC} k-N_{BC}+O(k^2)}$. The number of such terms are upper bounded by $2^{O(k^2)}$. When we sum those up, we at most get $2^{O(k^2)}(2^{-N_B}+2^{-N_C})$. To sum up, we have
\begin{equation}
\lVert \Phi_{\C,BC}^{(k)}(\rho_{\H,AB}^{(k)}\otimes\rho_{\C,CD}^{(k)})-\rho_{\H,ABCD}^{(k)}\lVert_1 
\leq 2^{O(k^2)}(2^{-N_B}+2^{-N_C}).
\end{equation}
Then we use the triangle inequality to bound
\begin{equation}
\begin{aligned}
&\lVert \Phi_{\C,BC}^{(k)}(\rho_{\H,AB,\varepsilon}^{(k)}\otimes\rho_{\C,CD}^{(k)})-\rho_{\H,ABCD}^{(k)}\lVert_1 \\
&\leq \lVert \Phi_{\C,BC}^{(k)}(\rho_{\H,AB,\varepsilon}^{(k)}\otimes\rho_{\C,CD}^{(k)})-\Phi_{\C,BC}^{(k)}(\rho_{\H,AB}^{(k)}\otimes\rho_{\C,CD}^{(k)})\lVert_1  +\lVert \Phi_{\C,BC}^{(k)}(\rho_{\H,AB}^{(k)}\otimes\rho_{\C,CD}^{(k)})-\rho_{\H,ABCD}^{(k)}\lVert_1 \\
&\leq\lVert\rho_{\H,AB,\varepsilon}^{(k)}\otimes\rho_{\C,CD}^{(k)}-\rho_{\H,AB}^{(k)}\otimes\rho_{\C,CD}^{(k)}\lVert_1  +\lVert \Phi_{\C,BC}^{(k)}(\rho_{\H,AB}^{(k)}\otimes\rho_{\C,CD}^{(k)})-\rho_{\H,ABCD}^{(k)}\lVert_1 \\
&\leq \varepsilon+2^{O(k^2)}(2^{-N_B}+2^{-N_C}).
\end{aligned}
\end{equation}
\end{proof}

\section{More on the Clifford commutant}\label{app:clifford_commutant}

\subsection{Asymptotics of Clifford Weingarten functions}
\label{sec:clifford_commutant_wg_asymptotics}
We present the asymptotics of the Weingarten functions of the Clifford group over $n$ qubits.
%
The results are based on properties of an orthogonal basis analyzed in~\cite{Haferkamp:2020qel}. 

To begin, the $k$-fold channel $\Phi^{(k)}_{\C}$ can be formulated as an operator in the doubled Hilbert space via the Choi–Jamiołkowski isomorphism
\begin{equation}
\hat{\Phi}_C^{(k)}:=\Ens_{V\sim\C}V^{\otimes k}\otimes V^{*\otimes k}=\sum_{T_i,T_j}\Wg_{\C}(T_i,T_j)\kket{T_i}^{\otimes n}\bbra{T_j}^{\otimes n}.
\end{equation}
Here, the states $\{\kket{T_i}\}$, vectorization of the operators $r(T)$, are linearly independent but not orthogonal, with inner products given by $\bbrakket{T_i}{T_j}=2^{n(k-|T_i,T_j|)}$. 
%
One can construct an orthogonal basis using the Gram-Schmidt orthogonalization\footnote{The disadvantage of this basis is that it is not a tensor product of operators on single qubits. Therefore, we work in the $\{\kket{T_i}\}$ basis to proceed in the main text.}:
\begin{equation}
\kket{E_i}=\sum_{j=1}^iA_{ij}\kket{T_j}^{\otimes n},\qquad A_{ij}=\sum_{\Pi\in S_i,\Pi(i)=j}\sgn(\Pi)\prod_{l=1}^{j-1}\bbrakket{T_l}{T_{\Pi(l)}}^n.
\end{equation}
It has the following properties~\cite{Haferkamp:2020qel}
\begin{equation}
\begin{aligned}
&|A_{ii}-2^{-nk}|\leq 2^{-nk-n+O(k^2)}), \qquad \forall i\\
&|A_{ij}|\leq 2^{-nk-n+O(k^2)},\qquad |A_{ij}|\leq 2^{-n(k+|\dim\rmN_i-\dim\rmN_j|)+O(k^3)}, \qquad \forall i\neq j .
\end{aligned}
\end{equation}
The normalization is
\begin{equation}
|\bbrakket{E_i}{E_i}-2^{nk}|\leq 2^{nk-2n+O(k^2)}.
\end{equation}
Since $\hat{\Phi}_{\C}^{(k)}$ is a projection operator, it is an equal weight sum of an orthonormal basis:
\begin{equation}
\hat{\Phi}_{\C}^{(k)}=\sum_j\frac{1}{\bbrakket{E_i}{E_i}}\kket{E_i}\bbra{E_i}.
\end{equation}
So the Weingarten functions can be expressed as
\begin{equation}
\Wg_{\C}(T_i,T_j)=\sum_k\frac{1}{\bbrakket{E_k}{E_k}}A_{ki}A_{kj}^*.
\end{equation}
We have the following asymptotics
\begin{equation}\label{eq:clifford_weingartens_asymptotics}
\begin{aligned}
|\Wg_{\C}(T_i,T_i)-2^{-nk}|&\le2^{-nk-n+O(k^2)},\qquad \forall i\\
|\Wg_{\C}(T_i,T_j)|&\leq 2^{-nk-n+O(k^2)},\qquad \forall i\neq j \\
|\Wg_{\C}(T_i,T_j)|&\leq 2^{-n(k+|\dim\rmN_i-\dim\rmN_j|)+O(k^3)},\qquad \forall i\neq j
\end{aligned}
\end{equation}
For $i\neq j$, we used the triangle inequality $|\dim\rmN_i-\dim\rmN_k|+|\dim\rmN_k-\dim\rmN_j|\ge|\dim\rmN_i-\dim\rmN_j|$.

\subsection{Diamond norm}\label{app:diamond_norm}
To bound the additive error of approximate unitary designs, we use the diamond norm for the superoperator $|T_1)(T_2|(\cdot) = \mathrm{r}(T_1)\Tr[\mathrm{r}(T_2)^\top (\cdot)]$ acting on a single qubit:
\begin{equation}
\lVert |T_1)(T_2|\rVert_\Diamond=2^{k+\dim\rmN_2-\dim\rmN_1}.\label{eq:clifford_commutant_diamond_norm_bound}
\end{equation}
To prove this, we first use an upper bound of the diamond norm (Lemma 3 of~\cite{Haferkamp:2020qel}):
\begin{equation}
\begin{aligned}
\lVert|T_1)(T_2|\rVert_\Diamond&=\max_{\lVert O\rVert_1\leq 1}\lVert|T_1)(T_2|\otimes \id(O)\rVert_1=\max_{\lVert O\rVert_1\leq 1}\lVert \mathrm{r}(T_1)\otimes\Tr_1[(\mathrm{r}(T_2)^\top\otimes I) O]\rVert_1 \\
&=\lVert \mathrm{r}(T_1)\rVert_1\max_{\lVert O\rVert_1\leq 1}\lVert \Tr_1[(\mathrm{r}(T_2)^\top\otimes I) O]\rVert_1 \\
&\le\lVert \mathrm{r}(T_1)\rVert_1\max_{\lVert O\rVert_1\leq 1}\lVert (\mathrm{r}(T_2)^\top\otimes I) O\rVert_1 \\
&=\lVert \mathrm{r}(T_1)\rVert_1\lVert \mathrm{r}(T_2)\otimes I\rVert_\infty=\lVert \mathrm{r}(T_1)\rVert_1 \lVert \mathrm{r}(T_2)\rVert_\infty=2^{k+\dim\rmN_2-\dim\rmN_1}.
\end{aligned}
\end{equation}
The notation $\Tr_1$ is the partial trace over the first copy of the system. 
The second line is because the trace norm is multiplicative under the tensor product. 
The third line is because the trace norm is non-increasing under the partial trace. 
The other direction is given by
\begin{equation}
\lVert|T_1)(T_2|\rVert_\Diamond\geq\frac{\lVert|T_1)(T_2|(\mathrm{r}(T_2))\rVert_1}{\lVert\mathrm{r}(T_{2})\rVert_1}=\frac{\lVert 2^k\mathrm{r}(T_1)\rVert_1}{\lVert\mathrm{r}(T_{2})\rVert_1}=2^{k+\dim\rmN_2-\dim\rmN_1}.
\end{equation}

