\section{Stabilizer Rényi entropy}\label{sec:stabilizer_renyi_entropy}
%

The stabilizer Rényi entropies are defined as~\cite{Leone:2021rzd}
\begin{equation}
\calM_{k}=-\log\left(2^{-N}\sum_{\boldu,\boldv\in \mathbb{F}_2^N}|\bra{\psi}P_{\boldu,\boldv}\ket{\psi}|^{k}\right)=-\log\Tr\left(2^{N}P^{(k)}\ket{\psi}\bra{\psi}^{\otimes k}\right),
\end{equation}
where $P_{\boldu,\boldv}=i^{\boldu\cdot\boldv}Z^{\boldu}X^{\boldv}=i^{\boldu\cdot\boldv}\bigotimes_{i=1}^NZ^{u_i}X^{v_i}$, representing all Pauli strings up to global phases. We take $k$ to be an integer multiple of $4$.
%
The Pauli moment $P^{(k)}$ factorizes as a tensor product of single-qubit Pauli moments. The single-qubit Pauli moment is
\begin{equation}
P^{(k)}=4^{-1}\sum_{m,n}(i^{mn}Z^mX^n)^{\otimes k}=4^{-1}\sum_{m,n}Z^{m\boldone_{k}}X^{n\boldone_{k}},\qquad \boldone_{k}=(\underbrace{1,\cdots,1}_{k})\in \mathbb{Z}_2^{k}.
\end{equation}
This is a member of the Clifford commutant corresponding to $r(T_S)=2P_{\CSS(\{\boldone_{k}\})}$, where $P_{\CSS(\{\boldone_{k}\})} = P^{(k)}$ is the projection onto the CSS codespace associated with the defect subspace $\{\boldone_{k}\}$ that contains two elements, $\boldzero_{k}$ and $\boldone_{k}$.
%
In the case of $k=4$, this is the only CSS code projector in the Clifford commutant~\cite{Gross_2021}, playing an important role in the representation theory of the Clifford group~\cite{Zhu:2016gfm}.

