\section{List of notation}\label{sec:list_of_notations}
\begin{itemize}
\item $\Phi_{\calE}^{(k)}$, $\Phi_{\H}^{(k)}$, $\Phi_{\C}^{(k)}$: $k$-fold channels of an unitary ensemble $\calE$, the ensemble of Haar random unitaries, and the ensemble of random Clifford unitaries.
\item $\varrho_{\calE}^{(k)}$, $\varrho_{\H}^{(k)}$: $k$-fold channels of a unitary ensemble $\calE$ and the ensemble of Haar random unitaries acting on EPR pairs.
\item $\varrho_0^{(k)}$: an approximation of $\varrho_{\H}^{(k)}$.
\item $\rho_{\calE}^{(k)}$, $\rho_{\H}^{(k)}$, $\rho_{\C}^{(k)}$: $k$-th moments of a state ensemble $\calE$, the ensemble of Haar random states, and the ensemble random stabilizer states.
\item $\mathrm{r}(T)$: a member of the Clifford commutant on a single qubit.
\item $r(T)_S$: a member of the Clifford commutant on a multi-qubit system $S$.
\item $r(\vec{T})$: $\bigotimes_x r(T_x)$.
\item $\kket{T}$: vectorization of $r(T)$.
\item $\bbrakket{T_1}{T_2}$: $\Tr[r(T_1)^{\top}r(T_2)]$.
\item $|T_1)(T_2|$: a superoperator $|T_1)(T_2|(\cdot)=r(T_1)\Tr[r(T_2)^\top(\cdot)]$.
\item $|\vec{T}_1)(\vec{T}_2|$: $\bigotimes_x |T_{1,x})(T_{2,x}|$.
\item $\sigma$: a permutation that belong to $S_k$.
\item $T\notin S_k$: a stochastic Lagrangian subspace that is not associated with permutations.
\item $r(\sigma)$: a member of the Clifford commutant that is a permutation operator.
\item $\Wg(\sigma,\tau)$: Weingarten functions for Haar random unitaries.
\item $\Wg_{\C}(T_1,T_2)$: Weingarten functions for random Clifford unitaries.
\item $|T_1,T_2|$: distance between $T_1$ and $T_2$ defined via $\Tr[\mathrm{r}(T_1)^\top \mathrm{r}(T_2)]=2^{k-|T_1,T_2|}$
\item $D_{N,k}$: $\prod_{i=0}^{k-1}(2^N+i)$, appears in $\rho_{\H}^{(k)}$.
\item $Z_{N,k}$: $2^N\prod_{i=0}^{k-2}(2^N+2^i)$, appears in $\rho_{\C}^{(k)}$.
\item $\log$: logarithmic function with base $2$.
\item $\lVert\cdot\rVert_p$: Schatten $p$-norm.

\end{itemize}

