\begin{proof}[\textbf{Proof of Theorem  \ref{cocycleGp=p,projGp=p}}]
	By \cite[Theorem 2.13, Corollary 2.14]{Niroomand}, $G$ has the presentation
	\[
	\langle x_r, 1\leq r \leq d  \mid [x_i,x_j]=y_{ij}, y_{12}=x_1^p, x_1^{p^2}=x_j^p=y_{ij}^p=1,~1 \leq i<j \leq d\rangle.
	\]
	\emph{(1)} Here we have  $$X =\langle  x_iG'\otimes y_{jk}+x_jG'\otimes y_{ki}+x_kG'\otimes y_{ij},  ~x_r\otimes y_{12}, 1 \leq i<j<k\leq d, 1\leq r \leq d\rangle.$$
	Now proof goes on the same lines as proof of Theorem \ref{cocycledescription,repgroup_exp p}.\\

\emph{(2)} The group $G/G^p$ has the following presentation
	\[
G/G^p \cong 	\langle x_r, 1\leq r \leq d  \mid [x_i,x_j]=y_{ij}, y_{12}=1, x_1^{p}=x_j^p=y_{ij}^p=1,~1 \leq i<j \leq d\rangle.
	\]
% $H^*$ has order $|G/G^p||\Ho^2(G/G^p,\mathbb C^\times)|=p^{\frac{1}{2}d(d+1)-1+\frac{1}{3}d(d-1)(d+1)-d+1}=p^{\frac{1}{6}d(d+1)(2d+1)-d}.$
Since 
\begin{eqnarray}  \label{eq10}
K_d^* \cong H_d^*/\langle z_{i12} \rangle_{1 \leq i \leq d},
\end{eqnarray}
 $K_d^*$ is  of order
$p^{\frac{1}{6}d(d+1)(2d+1)-d}.$
Now consider the subgroup 
	\begin{eqnarray*}
		L=\langle y_{12}\rangle \times \big\langle {z_{mnr}}\big\rangle _{1\leq m < n <r \leq d} \times \big\langle z_{nmr} \big\rangle _{\substack{1\leq m < n <r \leq d\\ (m,n)\neq (1,2)}} \times \big\langle z_{mmn} \big\rangle _{\substack{1\leq m < n \leq d \\ (m,n)\neq (1,2)}}
		 \times \big\langle z_{nmn} \big\rangle_{\substack{1\leq m < n \leq d \\ (m,n)\neq (1,2)}} 
			\end{eqnarray*}
			of $K_d^*$. Since  
