\section{Ordinary representations of $G^*, H_d^*, K_d^*$ for $d \geq 3$}\label{ordinary}
It follows by the previous discussions that, to complete our study, it is enough to understand   the inequivalent irreducible  complex ordinary representations of the following groups.
	\begin{eqnarray*}
	 G^*&=&\langle 
	x_1,x_2, y_r, 1 \leq r \leq d-2\mid  [x_1,x_2]=z, [z,x_k]=z_k, [y_r, x_k]=w_{rk}, [y_i,y_j]=z_{ij}, \\
	&&\hspace{5cm}  x_k^p=y_r^p=z^p=1, 1\leq i <j \leq d-2,   1\leq k \leq 2
	\rangle.\\
	H_d^*&=&\langle x_i,  1 \leq i \leq d \mid [x_j, x_k]=y_{jk}, [x_i, y_{jk}]=z_{ijk},  z_{rmn}=z_{nmr}z_{mnr}^{-1}, x_i^p=y_{jk}^p=1, \\
 && \hspace{7cm}	1 \leq m<n<r\leq d,  
	1 \leq j < k \leq d \rangle.\\
		K_d^*&=&\langle x_i,  1 \leq i \leq d \mid [x_j, x_k]=y_{jk},  [x_i, y_{jk}]=z_{ijk},   z_{i12}=1, 
	z_{rmn}=z_{nmr}z_{mnr}^{-1}, \\
	&& \hspace{5cm}	x_i^p=y_{jk}^p=1,
1 \leq m<n<r\leq d,  
	1 \leq j < k \leq d \rangle.
\end{eqnarray*}
The results given in \cite[Section 4]{PS}  explain a method for a construction of ordinary representations, which helps us to describe ordinary representations of these groups.


\subsection{$\irr(G^*)$}
By \eqref{eq1}, 
\begin{eqnarray*}
	G^*
	&\cong & \Big(\big(K \times (\mathbb Z/p\mathbb Z)^{2(d-2)+3}\big) \rtimes  \mathbb Z/p\mathbb Z\Big) \rtimes  \mathbb Z/p\mathbb Z.
\end{eqnarray*}
We study $\irr(G^*)$  as follows: Suppose $N^*=\Big(\big(K \times (\mathbb Z/p\mathbb Z)^{2(d-2)+3}\big) \rtimes  \mathbb Z/p\mathbb Z\Big) $.
Then $N^*$ is a normal subgroup of $G^*$ such that $G^*/N^*$ is a cyclic group of order $p$. Hence, we determine the inertia group of the elements of $\irr(N^*)$ in $G^*$, and then the construction is obtained by \cite[Proposition 4.2]{PS}.

We study $\irr(N^*)$  as follows:    $N^*$ has a normal subgroup $N=\big(K \times (\mathbb Z/p\mathbb Z)^{2(d-2)+3}\big)$  such that $N^*/N$ is a cyclic group of order $p$. Since $N$ is of nilpotency class $2$, the irreducible representations of $N$ are obtained from one dimensional representation of the radical of each central character as described in \cite[Section 4.1]{PS}. 
Then it remains to determine the inertia group of these representations of $N$ in $N^*$, and then the construction is obtained by \cite[Proposition 4.2]{PS}.

%We note that  is a normal subgroup of $N^*$ such that $N^*/N$ is cyclic. This helps to understand $\irr(N^*)$.



\subsection{$\irr(H_d^*)$ and $\irr(K_d^*)$}
By \eqref{eq2} and \eqref{eq10},
	\[
	H_d^* 
	 \cong  \big(H_{d-1}^* \times  (\mathbb Z/p\mathbb Z)^{d^2-1}\big) \rtimes \mathbb Z/p\mathbb Z \text{ and }
	K_d^*=\frac{H_d^*}{\langle {z_{i12}} \rangle_{1 \leq i \leq d}}.
	\]
Observe that,	
\[
K_d^* \cong  \big(K_{d-1}^*  \times  (\mathbb Z/p\mathbb Z)^{d^2-2}\big) \rtimes \mathbb Z/p\mathbb Z.
\]
We use inductive process  on $d$ to study $\irr(H_d^*)$ and $\irr(K_d^*)$ for $d \geq 3$. 
For $d=3$,  
	\begin{eqnarray*}
		H_3^*&=&\langle x_i, 1 \leq i \leq 3 \mid [x_j,x_k]=y_{jk}, [x_i, y_{jk}]=z_{ijk}, z_{321}=z_{123}z_{213}^{-1}, \\
	&& \hspace{7cm} x_i^p= y_{jk}^p=1, 1\leq j <k\leq 3 \rangle.\\
	&\cong & \big(\langle x_1,x_2 \mid [x_1,x_2]=y_{12}, [x_1, y_{12}]=z_{112}, [x_2, y_{12}]=z_{212}, x_i^p= y_{jk}^p=1 \rangle\\
	&& \hspace{6cm} \times  (\mathbb Z/p\mathbb Z)^{8}\big) \rtimes \mathbb Z/p\mathbb Z.\\
	K_3^*&=&H_3^*/\langle z_{112}, z_{212}, z_{312}\rangle.\\
	&\cong &  \big(\langle x_1,x_2 \mid [x_1,x_2]=y_{12}, x_1^p=x_2^p= y_{12}^p=1 \rangle \times  (\mathbb Z/p\mathbb Z)^{7}\big) \rtimes \mathbb Z/p\mathbb Z.
		\end{eqnarray*}
		Now consider the  Heisenberg group over $\mathbb Z/p\mathbb Z$, say $H_3(\mathbb Z/p\mathbb Z)$, and $\hat{H}(p,1)$ is a representation group of $H_3(\mathbb Z/p\mathbb Z)$; see \cite[Theorem 1.2]{PS}. Then we have
\[
H_3^* \cong \big(\hat{H}(p,1)  \times  (\mathbb Z/p\mathbb Z)^{8}\big) \rtimes \mathbb Z/p\mathbb Z.
\]
\[
K_3^* \cong \big(H_3(\mathbb Z/p\mathbb Z) \times  (\mathbb Z/p\mathbb Z)^{7}\big) \rtimes \mathbb Z/p\mathbb Z.
\] 
It is easy to see that the groups $H_3^*$ and $K_3^*$ have order $p^{14}$ and $p^{11}$ respectively. 
The groups $H_3^*$ and $K_3^*$ have normal subgroups  $\hat{H}(p,1)  \times  (\mathbb Z/p\mathbb Z)^{8}$ and $H_3(\mathbb Z/p\mathbb Z) \times  (\mathbb Z/p\mathbb Z)^{7}$ respectively such that the corresponding quotients are cyclic groups of order $p$. Hence, the ordinary representations of these groups can be obtained using the theory described in \cite[Section 4]{PS}.



Now assume $d >3$. The groups $H_d^*$ and $K_d^*$ have normal subgroups $N_H=\big(H_{d-1}^* \times  (\mathbb Z/p\mathbb Z)^{d^2-1}\big)$ and $N_K=\big(K_{d-1}^* \times  (\mathbb Z/p\mathbb Z)^{d^2-2}\big)$  respectively. Since  $H_d^*/N_H$ and  $K_d^*/N_K$ are cyclic groups of order $p$, it remains to determine the inertia group of  the elements of $\irr(N_H)$ and $\irr(N_K)$ in $H_d^* $ and $K_d^*$,  respectively. Then, the construction is obtained by \cite[Proposition 4.2]{PS}.










