\title{Beyond the Linear Separability Ceiling}

\author{\textbf{Enrico Vompa}\textmd{, Tanel Tammet, and Mohit Vaishnav} \\ Applied Artificial Intelligence Group, Tallinn University of Technology, Estonia \\ \texttt{\{envomp, tanel.tammet, mohit.vaishnav\}@taltech.ee}}

