\subsubsection{Additional Notation}
Here, we describe additional notation used in the proofs that follow. Given a column vector ${\vx \in \mathbb{R}^n}$ and an ${n \times n}$ square matrix $A$,  $\norm{\vx}_A^2 = \vx^\top A \vx$. The operator norm of a matrix is denoted ${\norm{A}_{p, q} = \sup_{\vx \in \mathbb{R}^n} \norm{A\vx}_q / \norm{\vx}_p}$. To mean $\norm{A}_{p, p}$, we use the notation $\norm{A}_p$. For an element-wise norm, we write $\norm{\mathbf{vec}(A)}_p$, where $\mathbf{vec}(A)$ is the vectorization of the matrix $A$. A vector formed by diagonal entries of a matrix $P$ is denoted $\mathrm{diag}(P)$. 

\subsubsection{Derivation of the EOT dual (\ref{opt:sinkhorn-dual})}
\label{sec:derivation-of-dual}
In this section, we provide the derivations for (\ref{eq:lagrangian-closed-form}-\ref{opt:sinkhorn-dual}). 
Recall the EOT primal problem given by (\ref{opt:sinkhorn-primal}):
\begin{mini*}[2]
  {P \in \gU(\vr, \vc)}{\langle P, C \rangle - \frac{1}{\gamma}H(P).}{}{}
 \end{mini*}
Observe that we can replace negative Shannon entropy $\langle P, \log P \rangle$ in (\ref{opt:sinkhorn-primal}) with the KL divergence (written without assuming $P \in \Delta_{n \times n}$) to the uniform distribution $U = \frac{1}{n^2}\1_{n \times n}$:
\begin{align*}
    D_{\mathrm{KL}}(P|U) &= \langle P, \log P \rangle - \langle P, \log \frac{1}{n^2} \1 \rangle + 1 - \sum_{ij} P_{ij} \\
    &= \langle P, \log P \rangle - \sum_{ij} P_{ij} + 2 \log n + 1.
\end{align*}
That is, replacing the negative Shannon entropy term with the above in the primal objective only increases the objective by a constant $2\log n$ on the feasible set, since $\sum_{ij} P_{ij} = 1$ for all $P \in \gU(\vr, \vc)$. For convenience, we drop the $2\log n$ term and take the primal problem given by
\begin{mini*}[2]
  {P \in \gU(\vr, \vc)}{\langle P, C \rangle + \frac{1}{\gamma}\left(\langle P, \log P \rangle - \sum_{ij} P_{ij} + 1 \right).}{}{}
 \end{mini*}
To derive the dual problem, we write the (scaled) Lagrangian with dual variables ${\vu, \vv \in \mathbb{R}^n}$ corresponding to equality constraints $\vr(P) = \vr$ and $\vc(P) = \vc$:
\begin{align}
\label{eq:lagrangian2}
\gL(P, \vu, \vv) = \gamma \langle P, C \rangle + \langle P, \log P \rangle - \sum_{ij}P_{ij} + 1 + \langle \vu, \vr - \vr(P) \rangle + \langle \vv, \vc - \vc(P) \rangle.
\end{align}
Taking the first derivative with respect to the $ij^{\mathrm{th}}$ entry $P_{ij}$ of $P$:
\begin{align*}
    \frac{\partial \gL}{\partial P_{ij}} &= \gamma C_{ij} + 1 + \log P_{ij} - 1 - u_i - v_j \\
    &= \gamma C_{ij} + \log P_{ij} - u_i - v_j.
\end{align*}
Setting the partial to $0$:
\begin{align*}
    \frac{\partial \gL}{\partial P_{ij}} = 0 & \iff \log P_{ij} = u_i + v_j - \gamma C_{ij} \\
    & \iff P_{ij} = \exp\{u_i + v_j - \gamma C_{ij}\},
\end{align*}
where the last equation is the same as (\ref{eq:lagrangian-closed-form}). Now, plugging the above $P$ into the Lagrangian (\ref{eq:lagrangian2}):
\begin{align*}
    -g(\vu, \vv) &\coloneqq
\gamma \langle P, C \rangle + \langle P, \vu \1^\top + \1 \vv^\top - \gamma C \rangle - \sum_{ij}P_{ij} + 1 + \langle \vu, \vr - \vr(P) \rangle + \langle \vv, \vc - \vc(P) \rangle \\   
&= \langle \vu, P \1 \rangle + \langle \vv, P^\top \1 \rangle - \sum_{ij}P_{ij} + 1 + \langle \vu, \vr - \vr(P) \rangle + \langle \vv, \vc - \vc(P) \rangle \\
&=  1 -\sum_{ij} P(\vu , \vv)_{ij} + \langle \vu, \vr \rangle + \langle \vv, \vc \rangle.  
\end{align*}
Maximizing $-g(\vu, \vv)$ with respect to the dual variables, we obtain the dual problem (\ref{opt:sinkhorn-dual}):
\begin{mini*}[2]
  {\vu, \vv \in \mathbb{R}^{n}}{g(\vu, \vv) = \sum_{ij} P(\vu , \vv)_{ij} - 1 - \langle \vu, \vr \rangle - \langle \vv, \vc \rangle,}{}{}
\label{opt:sinkhorn-dual-repeat}
 \end{mini*}
where we kept the constant $-1$ as a convention. 

As an aside, note that if one assumes instead an $L_1$ normalized form for $P$ via the softmax function (given that the feasible set $\gU(\vr, \vc)$ is a subset of the simplex):
\begin{align*}
    P(\vu, \vv)_{ij} = \frac{\exp\{u_i + v_j - \gamma C_{ij}\}}{\sum_{k, l}\exp\{u_k + v_l - \gamma C_{ij}\}},
\end{align*}
one obtains an alternative form for the dual objective by plugging the above into the Lagrangian (\ref{eq:lagrangian2}):
\begin{align*}
    \tilde{g}(\vu ,\vv) = \log \sum_{ij} \exp\{u_i + v_j - \gamma C_{ij}\} - \langle \vu, \vr \rangle - \langle \vv
    , \vc \rangle.
\end{align*}
Both the sum-of-exponents and log-sum-of-exponents forms of the dual appear in the literature; see for instance \citet{altschuler2017near, dvurechensky2018computational, lin19a} for the former and \citet{lin2022efficiency} for the latter. Both objectives $g$ and $\tilde{g}$ have the same value whenever $P(\vu, \vv)$ as defined in (\ref{eq:lagrangian-closed-form}) is on the simplex, since $x-1 = \log x = 0$ for $x=1$, which is why the constant $-1$ in (\ref{opt:sinkhorn-dual}) was kept as a convention.


\subsubsection{Proof of Thm. \ref{thm:residual}}\label{sec:proof-of-residual}
We start this section with an intuitive example describing the role of the row-stochastic matrix $\Prc$ that was defined in (\ref{eq:matrix-definitions}). The discussion carries over to $P_{\vc\vr}$ by symmetry. Next, we will list some mathematical properties that will be useful in the proofs that follow.

Suppose $\vr$ and $\vc$ are disjointly supported on two sets of particles $\vx_1, \cdots, \vx_{n_1}$ and $\vy_{n_1 + 1}, \cdots, \vy_{n}$ respectively, and let $n_2 \coloneqq n - n_1$. That is, an $n_1 \times n_2$ transport plan $P \in \gU(\vr, \vc)$ maps distributions over $\vx$ and $\vy$ particles. Recall the definition of $\Prc = P_{\vr} P_{\vc}$ in (\ref{eq:matrix-definitions}) as a product of ${P_{\vr} = \Dr^{-1}P \in \mathbb{R}^{n_1 \times n_2}_{>0}}$ and ${P_{\vc} = \Dc^{-1}P^\top \in \mathbb{R}^{n_2 \times n_1}_{>0}}$. Given some initial distribution $\vq \in \Delta_{n_1}$ over $\vx$-particles, $P_{\vr}^\top \vq \in \Delta_{n_2}$ is a distribution over $\vy$-particles after transportation according to $P$. Indeed, we can show easily that $P_\vr^\top \vq$ is on the simplex:
\begin{align*}
    \1^\top P_\vr^\top \vq = \1^\top P^\top \Dr^{-1}  \vq = \vr^\top \Dr^{-1} \vq = \1^\top \vq = 1.
\end{align*}
Similarly, $P_{\vc}^\top P_{\vr}^\top q = \Prc^\top q \in \Delta_{n_1}$ is again a distribution over $\vx$-particles after transporting back according to $P$. This is the stochastic process represented by $\Prc$. Given any initial distribution $\vq$, the process converges to the row-marginal $\vr$ of $P$ if $\Prc$ is applied repeatedly (as the next lemma shows). The second largest eigenvalue $\lambda_2$ of $\Prc$ determines how quickly this convergence occurs (see Lemma \ref{lem:prc-conv} below).

Now, we list useful technical properties of $\Prc$ in our setting. Analogous claims hold for the stochastic matrix $P_{\vc\vr}$ and the column sum $\vc(P)$ by symmetry, but are omitted for brevity.

\begin{restatable}[Properties of $\Prc$]{lemma}{prcprops}
\label{lem:P_rc-properties}
Given a matrix $P \in \mathbb{R}^{n \times n}$ with strictly positive finite entries define ${\Prc = P_\vr P_\vc = \DrP^{-1} P \DcP^{-1} P^\top}$. The following are true:
\begin{enumerate}
    \item $\Prc$ is an irreducible row-stochastic matrix. Its second largest eigenvalue $\lambda_2$ is strictly less than one.
    \item The stationary distribution of $\Prc$ is $\vr(P)$.
    \item $\Prc$ is reversible in the sense that $\DrP \Prc = \Prc^\top \DrP$, which implies all eigenvalues of $\Prc$ are real.
    \item $\Prc \DrP^{-1} = \DrP^{-1}\Prc^\top$.
    \item Given some $\rho \in [0, 1)$, we have $(I - \rho \Prc)^{-1} \DrP^{-1} = \DrP^{-1} (I - \rho \Prc^\top)^{-1}$.
\end{enumerate}
\end{restatable}
\begin{proof}
    We prove each claim in order.
    \begin{enumerate}
        \item The vector of ones is a right-eigenvector of $\Prc$ with eigenvalue $1$:
        \begin{align*}
            \Prc \1 &= \DrP^{-1} P \DcP^{-1} P^\top \1 \\
            &= \DrP^{-1} P \DcP^{-1} \vc(P) \\
            &= \DrP^{-1} P \1 \\
            &= \DrP^{-1} \vr(P) \\
            &= \1.
        \end{align*}
        Since all entries of $P$ are strictly positive, the same is true of $\Prc$. The claim follows.
        \item The vector $\vr(P)$ is a left-eigenvector of $\Prc$ with eigenvalue $1$:
        \begin{align*}
            \vr(P)^\top \Prc &= \vr(P)^\top \DrP^{-1} P \DcP^{-1} P^\top \\
            &= \1^\top P \DcP^{-1} P^\top \\
            &= \vc(P)^\top \DcP^{-1} P^\top \\
            &= \1^\top P^\top \\
            &= \vr(P)^\top.
        \end{align*}
        \item The claim holds since
        \begin{align*}
            \DrP \Prc &= \DrP \DrP^{-1} P \DcP^{-1} P^\top \\
            &= P \DcP^{-1} P^\top \\
            &= P \DcP^{-1} P^\top \DrP^{-1} \DrP \\
            &= \Prc^\top \DrP.
        \end{align*}
        \item The claim follows similarly as the previous claim.
        \item First, notice that Claims 3 and 4 apply analogously to all powers of $\Prc^l$ for $l \geq 0$. Indeed, for Claim 4 we have:
        \begin{align*}
            \Prc^l \DrP^{-1} &= \Prc^{l-1} \Prc \DrP^{-1} \\
            &= \Prc^{l-1} \DrP^{-1} \Prc^\top  \tag{by Claim 4} \\
            &= \Prc^{l-2} \Prc \DrP^{-1} \Prc^\top \\
            &= \Prc^{l-2} \DrP^{-1} (\Prc^\top)^2 \tag{again, by Claim 4} \\
            &= \DrP^{-1} (\Prc^\top)^l \tag{by repeated application of Claim 4}.
        \end{align*}
        Then, from the Neumann series ${(I - \rho \Prc)^{-1} \DrP^{-1} = (\sum_{l = 0}^\infty \rho^l \Prc^l) \DrP^{-1}}$, we obtain the claim by applying the above equality to each element of the sum. \qedhere
    \end{enumerate}
\end{proof}

\begin{restatable}[Properties of the coefficient matrix $\Frr$]{lemma}{frprops}
\label{lem:fr-properties}
Let $\rho \in [0, 1)$, $\Prc$ be a row-stochastic matrix with strictly positive entries and $\min_i \vr(P)_i \geq 0$ for all $i \in [n]$. Given an ${n \times n}$ matrix ${\Frr = \DrP(I - \rho \Prc)}$, the following hold true:
\begin{itemize}
    \item $\Frr$ is a symmetric, positive-definite matrix.
    \item $\lambda_{\max}(\Frr) \leq (1+\rho) \vr(P)_{\max}$ 
    \item $\lambda_{\min}(\Frr) \geq (1-\rho) \vr(P)_{\min}$.
\end{itemize}
\end{restatable}
\begin{proof}
    Observe that 
    \begin{align*}
        \Frr &= \DrP(I - \rho \Prc) = \DrP - \rho P P_\vc \\
        &= \DrP - \rho P \DcP^{-1} P^\top,
    \end{align*}
    is a sum of two symmetric matrices, which is also symmetric. The eigenvalue bounds follow from the Gerschgorin Circle Theorem. Since the smallest eigenvalue is positive, $\Frr$ is positive-definite.
\end{proof}

Before we move on to the proof of Thm. \ref{thm:residual}, we state the following Lemma, which follows immediately from Thm. 2.7 of \citet{fill1991eigenvalue} given that $\Prc$ is reversible by Claim 3 of Lemma \ref{lem:P_rc-properties}.
\begin{restatable}[Convergence to the stationary distribution under $\Prc$]{lemma}{prcconv}
\label{lem:prc-conv}
Given some $\vr \in \Delta_n$,
\begin{align}
    \norm{(\Prc^\top)^l \vr - \vr(P)}_1^2 \leq \lambda_2^{2l} \chi^2(\vr | \vr(P)),
\end{align}
where $\lambda_2 < 1$ is the second largest eigenvalue $\lambda_2$ of $\Prc$. 
\end{restatable}

Now, we provide a more formal version of Thm. \ref{thm:residual} presented in the main text followed by a proof.
\begin{theorem}[continues=thm:residual] Assuming ${\vc = \vc(P)}$ and ${\vd_\vv = -P_\vc \vd_\vu}$, define residuals ${\ve_\vu(\rho) {\coloneqq} \Frr \vd_\vu + \nabla_\vu g}$, and ${\ve \coloneqq \nabla^2 g ~\vd + \nabla g}$. Further, let $\lambda_2 \in (0, 1)$ be the 2nd largest eigenvalue of $\Prc$ and ${\zeta \coloneqq \norm{\nabla_\vu g}_1 / \chi(\vr | \vr(P)) \leq 1}$. For any $\beta \in (0, 1)$, suppose:
\begin{gather}
     \max \left(0, 1 -  \frac{(1-\lambda_2)K}{\lambda_2(1-K)} \right) \leq \rho < 1\label{eq:discount-factor-constraint}, \\
    \norm{\ve_\vu(\rho)}_1 \leq \frac{1-\beta}{2} \eta \norm{\nabla g}_1 \label{eq:eta-hat},
\end{gather}
where $K = \zeta \beta \eta < 1$. Then, 
\begin{align}
\label{eq:forcing2}
    \norm{\ve}_1 = \norm{\ve_\vu(1)}_1 \leq \eta \norm{\nabla g}_1.
\end{align}
\end{theorem}

\begin{proof}
    To establish necessary conditions for bounding $\norm{\ve}_1$, first, we write it out explicitly:
    \begin{align*}
        \ve &= \nabla^2 g \vd + \nabla g \\
        &= \begin{pmatrix}
        \DrP & P \\
        P^\top & \mathbf{D}(\vc(P))
        \end{pmatrix} 
        \begin{pmatrix} \vd_\vu \\ \vd_\vv \end{pmatrix} + \begin{pmatrix} \nabla_\vu g \\ \nabla_\vv g \end{pmatrix}, \\
        &= \begin{pmatrix}
        \DrP & P \\
        P^\top & \mathbf{D}(\vc(P))
        \end{pmatrix} 
        \begin{pmatrix} \vd_\vu \\ -P_\vc \vd_\vu \end{pmatrix} + \begin{pmatrix} \nabla_\vu g \\ \vzero \end{pmatrix}, \tag{by construction} \\
        &= \begin{pmatrix} \DrP \vd_\vu - P P_\vc \vd_\vu \\ \vzero \end{pmatrix} + \begin{pmatrix} \nabla_\vu g \\ \vzero \end{pmatrix} \tag{since $\DcP P_\vc = P^\top$ by definition.} \\
        &= \begin{pmatrix} \DrP(I - \Prc) \vd_\vu \\ \vzero \end{pmatrix} + \begin{pmatrix} \nabla_\vu g \\ \vzero \end{pmatrix}\numberthis \label{eq:explicit-residual}, \\
        &= \begin{pmatrix} \ve_\vu(1) \\ \vzero \end{pmatrix}
    \end{align*}
    which proves the equality on the LHS of (\ref{eq:forcing2}), where the last equality holds given the definitions ${\ve_\vu(\rho) {\coloneqq} \Frr \vd_\vu + \nabla_\vu g}$ and $\Frr = \DrP (I - \rho \Prc)$. Hence, bounding $\norm{\ve_\vu(1)}_1$ suffices.
    Now, given the definition of $\ve_\vu(\rho)$ and the invertibility of $\Frr$ for $\rho < 1$ by Lemma \ref{lem:fr-properties}, we have:
    \begin{align*}
        \vd_\vu = \Frr^{-1} (\ve_\vu(\rho) - \nabla_\vu g).
    \end{align*}
    Plugging into the top half of (\ref{eq:explicit-residual}), we observe that:
    \begin{align*}
        \ve_\vu(1) &= F_\vr(1) \Frr^{-1}(\ve_\vu(\rho) - \nabla_\vu g) + \nabla_\vu g \\
        &= \widehat{I}(\rho)\ve_\vu(\rho) + (I - \widehat{I}(\rho)) \nabla_\vu g,
    \end{align*}
    where we defined $\widehat{I}(\rho) \coloneqq F_\vr(1) \Frr^{-1}$.
    Then, we have
    \begin{align}
    \label{eq:res-bound1}
        \norm{\ve_\vu(1)}_1 \leq \norm{\widehat{I}(\rho)}_1 \norm{\veur}_1 + \norm{(I - \widehat{I}(\rho)) \nabla_\vu g}_1.
    \end{align}
    First, we prove that the operator norm $\norm{\widehat{I}(\rho)}_1 \leq 2$.
    \begin{align*}
        \widehat{I}(\rho) &= \DrP (I - \Prc)(I - \rho \Prc)^{-1} \DrP^{-1} \\
        &= I - (1-\rho) \DrP \Prc (I - \rho \Prc)^{-1} \DrP^{-1} \\
        &= I - (1-\rho) \Prc^\top (I - \rho \Prc^\top)^{-1}, \numberthis \label{eq:Ihat-I}
    \end{align*}
    where the last equality follows from claims 3 and 5 of Lemma \ref{lem:P_rc-properties}. Recalling that $\norm{A}_1$ is the maximum absolute column sum of matrix $A$:
    \begin{align*}
        \norm{\widehat{I}(\rho)}_1 &\leq 1 + (1-\rho)\norm{\Prc^\top}_1 \norm{(I - \rho \Prc^\top)^{-1}}_1 \\ 
        &= 1 + (1-\rho) \norm{(I - \rho \Prc^\top)^{-1}}_1 \\
        &= 1 + (1-\rho) \norm{\sum_{l=0}^\infty \rho^l (\Prc^\top)^l}_1 \\
        &\leq 1 + (1-\rho) \sum_{l=0}^\infty \rho^l \norm{(\Prc^\top)^l}_1 \\
        &= 2 \tag{since $\Prc^l$ is a stochastic matrix for all $l \geq 0$}.
    \end{align*}
    Hence, (\ref{eq:res-bound1}) simplifies to
    \begin{align}
    \label{eq:res-bound2}
        \norm{\ve_\vu(1)}_1 \leq 2 \norm{\veur}_1 + \norm{(I - \widehat{I}(\rho)) \nabla_\vu g}_1.
    \end{align}
    Next, we turn to the second term on the RHS:
    \begin{align*}
        (I - \widehat{I}(\rho)) \nabla_\vu g &= (1-\rho) \Prc^\top (I - \rho \Prc^\top)^{-1} \nabla_\vu g \tag{From (\ref{eq:Ihat-I})} \\
        &= (1-\rho) \sum_{l=0}^\infty \rho^l (\Prc^\top)^{l+1} (\vr(P) - \vr)  \\
        &= (1-\rho) \sum_{l=0}^\infty \rho^l \bigg(\vr(P) - (\Prc^\top)^{l+1} \vr \bigg),
    \end{align*}
    where the last equality is due to the fact that $\vr(P)$ is the stationary distribution of $\Prc$ by Claim 2 of Lemma \ref{lem:P_rc-properties}. Then,
    \begin{align*}
        \norm{(I - \widehat{I}(\rho)) \nabla_\vu g}_1 &\leq (1-\rho) \norm{\sum_{l=0}^\infty \rho^l \bigg(\vr(P) - (\Prc^\top)^{l+1} \vr \bigg)}_1 \\
        &\leq (1-\rho) \sum_{l=0}^\infty \rho^l \norm{\bigg(\vr(P) - (\Prc^\top)^{l+1} \vr \bigg)}_1 \\
        &\leq (1-\rho) \sum_{l=0}^\infty \rho^l \lambda_2^{l+1} \chi(\vr|\vr(P)) \tag{By Lemma \ref{lem:prc-conv}} \\
        &= \frac{(1-\rho)\lambda_2}{1-\rho \lambda_2} \chi(\vr|\vr(P))
    \end{align*}
    Plugging this bound back into (\ref{eq:res-bound2}) and continuing with the main conditions given in the theorem:
    \begin{align*}
        \norm{\ve_\vu(1)}_1 &\leq 2 \norm{\veur}_1 + \frac{(1-\rho)\lambda_2}{1-\rho \lambda_2} \chi(\vr|\vr(P)) \\
        &\leq (1-\beta)\eta \norm{\nabla g}_1 + \frac{(1-\rho)\lambda_2}{1-\rho \lambda_2} \chi(\vr|\vr(P)) \tag{Since (\ref{eq:eta-hat}) holds by construction} \\
        &\leq (1-\beta)\eta \norm{\nabla g}_1 + \beta \eta \norm{\nabla g}_1 \tag{Since (\ref{eq:discount-factor-constraint}) holds by construction} \\
        &= \eta \norm{\nabla g}_1,
    \end{align*}
    which concludes the proof. Above, the parameter ${\beta \in (0, 1)}$ controls a trade-off between how precisely the discounted system is solved and how aggressively the original system is discounted. In Algorithm \ref{alg:newton-solve} of the main text, $\beta$ was fixed at $1/2$ for simplicity. Also, for intuition on the effect of $\lambda_2$, observe that the second term vanishes as $\lambda_2 \rightarrow 0$ (if $\Prc$ mixes quickly) so that the Hessian can be discounted more aggressively with a smaller $\rho$. As we see next, this improves our guarantees on the condition number of the linear system.
\end{proof}

\subsubsection{Proof of Thm. \ref{thm:convergence-alg1}}
\label{sec:proof-of-thm3.2}

\begin{restatable}[Spectrum after preconditioning]{lemma}{condo}
\label{lem:condition-number}
Let ${\widehat{F}_\vr(\rho) \coloneqq M^{-1/2} \Frr} M^{-1/2}$ be the diagonally preconditioned coefficient matrix, where ${M = \mathbf{D}(\mathrm{diag}(\Frr))}$. Further, let $\bm{\mu} = \mathrm{diag}(\Prc)$ be the diagonal entries of the stochastic matrix $\Prc \in \mathbb{R}^{n \times n}_{> 0}$. Then, eigenvalues $\lambda_i(\rho)$ of $\widehat{F}_\vr(\rho)$ satisfy
\begin{gather}
    1 - \frac{\rho(1-\mu_{\min})}{1-\rho \mu_{\min}} \leq \lambda_i(\rho) \leq 1 + \frac{\rho(1-\mu_{\min})}{1-\rho \mu_{\min}}, ~\forall i \in [n] \label{eq:preconditioned-eigenvalues}  \\
    \kappa(\rho) = \frac{\lambda_{\max}(\rho)}{\lambda_{\min}(\rho)} \leq 2\left(\mu_{\min} + \frac{1-\mu_{\min}}{1-\rho}\right) \leq \frac{2}{1-\rho}
\end{gather}
\end{restatable}
\begin{proof}
    The proof of (\ref{eq:preconditioned-eigenvalues}) follows straightforwardly from the Gerschgorin Circle Theorem. Due to diagonal similarity, the spectrum of $\widehat{F}_\vr(\rho)$ coincides with that of $\widetilde{F}_\vr(\rho) = M^{-1} \Frr$.
    Clearly, diagonal entries of $\widetilde{F}_\vr(\rho)$ all equal to 1, so that all Gerschgorin disks are centered around unity. Then, all eigenvalues must be inside the biggest disk, which contains all of the smaller disks. First, consider row $i$ of $\Frr = \DrP(I - \rho \Prc)$:
    \begin{align*}
        \sum_{j \neq i} |\widetilde{F}_\vr(\rho)_{ij}| = \vr(P)_i \rho (1-\mu_i).
    \end{align*}
    Since ${M_{ii} = \Frr_{ii} = \vr(P)_i(1-\rho \mu_i)}$, we then have: 
        \begin{align*}
        \sum_{j \neq i} |\widetilde{F}_\vr(\rho)_{ij}| = \frac{\rho (1-\mu_i)}{(1-\rho \mu_i)},
    \end{align*}
    where the biggest Gerschgorin disk corresponds to $\mu_{\min}$, so that (\ref{eq:preconditioned-eigenvalues}) holds for all $i \in [n]$. Then,
    \begin{align*}
        \kappa(\rho) &\leq \frac{2}{\lambda_{\min}(\rho)} \leq \frac{2}{1 - \frac{\rho (1-\mu_{\min})}{(1-\rho \mu_{\min})}} \\
        &= 2\left(\mu_{\min} + \frac{1-\mu_{\min}}{1-\rho}\right) \\
        &= O\left(\frac{1-\mu_{\min}}{1-\rho}\right) ~~~\mathrm{as}~ \rho \rightarrow 1. \qedhere
    \end{align*}
\end{proof}

\begin{restatable}[Equivalence of norms]{lemma}{normconversion}
\label{lem:norm-conversion}
Suppose $\vd_\vu^*$ satisfies $\Frr\vd_\vu^* = -\nabla_\vu g$. Let $\widehat{F}_\vr(\rho) = M^{-1/2} \Frr M^{-1/2} $ and ${M=\mathbf{D}(\mathrm{diag}(\Frr))}$ as in Lemma \ref{lem:condition-number}. Define the reparametrization $\widehat{\vd}_\vu = M^{1/2}\vd_\vu$ given some $\vd_\vu \in \mathbb{R}^n$, and the residual $\ve_\vu = \Frr \vd_\vu + \nabla_\vu g$. We have,
\begin{align}
    \sqrt{(1-\rho)\vr(P)_{\min}} \leq \frac{\norm{\ve_\vu}_1}{\norm{\widehat{\vd}_\vu - \widehat{\vd}_\vu^*}_{\widehat{F}_\vr(\rho)}} \leq \sqrt{(1+\rho)n}.
\end{align}
\end{restatable}

\begin{proof}
For this proof, we drop $\rho$ from $\Frr$ and $\widehat{F}_\vr(\rho)$ for convenience. First, observe that ${\vd_\vu - \vd_\vu^* = F_\vr^{-1}\ve_\vu}$. Then,
\begin{align*}
    \norm{\widehat{\vd}_\vu - \widehat{\vd}_\vu^*}_{\widehat{F}_\vr}^2 &= \norm{M^{1/2} F_\vr^{-1} \ve_\vu}_{\widehat{F}_\vr}^2 \\
    &= \ve_\vu^\top F_\vr^{-1} M^{1/2} \widehat{F}_\vr M^{1/2} F_\vr^{-1} \ve_\vu \\
    &= \ve_\vu^\top F_\vr^{-1} F_\vr F_\vr^{-1} \ve_\vu \\
    & =  \ve_\vu^\top F_\vr^{-1} \ve_\vu \\
    &\geq \lambda_{\min}(F_\vr^{-1}) \norm{\ve_\vu}_2^2 \\
    &= \frac{\norm{\ve_\vu}_2^2}{\lambda_{\max}(F_\vr)} \\
    & \geq \frac{\norm{\ve_\vu}_2^2}{(1+\rho)\vr(P)_{\max}} \tag{by Lemma \ref{lem:fr-properties}} \\
    & \geq \frac{\norm{\ve_\vu}_2^2}{(1+\rho)} \\
    & \geq \frac{\norm{\ve_\vu}_1^2}{n(1+\rho)} \tag{since $\norm{\vx}_1 \leq \sqrt{n}\norm{\vx}_2, \forall \vx \in \mathbb{R}^n$.},
\end{align*}
which is equivalent to the upper bound of the desired result. The lower bound follows similarly in the reverse direction, using $\lambda_{\min}(F_\vr)$ and $\norm{\vx}_2 \leq \norm{\vx}_1$.
\end{proof}

\begin{restatable}[Convergence of CG]{lemma}{cgconv}
\label{lem:conv-cg}
Suppose diagonally-preconditioned conjugate gradient method is initialized with ${\vd_\vu^{(0)} = \vzero}$ for the linear system ${\Frr \vd_\vu^* = -\nabla_\vu g}$, where $\rho \in [0, 1)$. Let $\mu$ be the largest diagonal entry of $\Prc$. Assuming that $\vr(P)_{\min} \geq \varepsilon_{\mathrm{d}}/(4n)$ for all ${i \in [n]}$ given some constant ${\varepsilon_{\mathrm{d}} > 0}$, the residual satisfies ${\norm{\Frr\vd_\vu + \nabla_\vu g}_1 = \norm{\ve_\vu(\rho)}_1 \leq \hat{\eta} \norm{\nabla_\vu g}_1}$ after at most $\mathrm{ceil}(k)$ steps, where 
\begin{align}
    k \leq \left(\frac{1-\mu \rho}{1-\rho}\right)^{1/2} \log \left(6n (1-\rho)^{-1/2}   \hat{\eta}^{-1} \varepsilon_{\mathrm{d}}^{-1/2} \right) = \widetilde{O}\left(\sqrt{\frac{1-\mu}{1-\rho}}\right) ~\mathrm{as}~ \rho \rightarrow 1.
\end{align}

\end{restatable}

\begin{proof}{Once again, we drop $\rho$ from $\Frr$ and $\widehat{F}_\vr(\rho)$ for convenience. Using the same definitions as Lemma \ref{lem:norm-conversion}, recall the equivalence of the diagonally-preconditioned linear system:
\begin{align*}
    F_\vr \vd_\vu &= -\nabla_\vu g \\
    \iff M^{-1/2}F_\vr \vd_\vu &= -M^{-1/2}\nabla_\vu g \\
    \iff M^{-1/2}F_\vr M^{-1/2} M^{1/2} \vd_\vu &= -M^{-1/2}\nabla_\vu g \\ 
    \iff \widehat{F}_\vr \widehat{\vd}_\vu &= -M^{-1/2}\nabla_\vu g.
\end{align*}

To guarantee $\norm{\ve_\vu}_1 \leq \hat{\eta}\norm{\nabla_\vu g}_1$, it is sufficient to have (given the upper bound in Lemma \ref{lem:norm-conversion}})
\begin{align}
\label{eq:define-varepsilon}
    \norm{\widehat{\vd}_\vu - \widehat{\vd}_\vu^*}_{\widehat{F}_\vr(\rho)} \leq \frac{\hat{\eta}\norm{\nabla_\vu g}_1}{\sqrt{n(1+\rho)}} \coloneqq 2 \varepsilon.
\end{align}
It is well-known the that linear conjugate gradient method ensures $\norm{\widehat{\vd}_\vu - \widehat{\vd}_\vu^*}_{\widehat{F}_\vr(\rho)} \leq 2 \varepsilon$ after at most $\mathrm{ceil}(k)$ steps \citep{Shewchuk94CG}, where
\begin{align}
    k = \frac{1}{2}\sqrt{\kappa(\widehat{F}_\vr)} \log \norm{\widehat{\vd}_\vu^{(0)} - \widehat{\vd}_\vu^*}_{\hat{F_\vr}} \varepsilon^{-1}.
\end{align}
Then, we have
\begin{align*}
    k &\leq \frac{1}{2}\sqrt{\kappa(\widehat{F}_\vr)} \log \norm{\widehat{\vd}_\vu^{(0)} - \widehat{\vd}_\vu^*}_{\hat{F_\vr}} \varepsilon^{-1} \\
    & \leq \frac{1}{2}\sqrt{\kappa(\widehat{F}_\vr)} \log \frac{\norm{\ve_\vu^{(0)}}_1 \varepsilon^{-1}}{\sqrt{(1-\rho) \vr(P)_{\min}}} \tag{by the lower bound in Lemma \ref{lem:norm-conversion}} \\
    & = \frac{1}{2}\sqrt{\kappa(\widehat{F}_\vr)} \log \frac{\norm{\nabla_\vu g}_1 \varepsilon^{-1}}{\sqrt{(1-\rho) \vr(P)_{\min}}} \tag{since $\vd_\vu^{(0)} = \vzero \implies \norm{\ve_\vu^{(0)}}_1 = \norm{\nabla_\vu g}_1$.} \\
    & = \frac{1}{2}\sqrt{\kappa(\widehat{F}_\vr)} \log 2\hat{\eta}^{-1}\sqrt{\frac{(1+\rho)n}{(1-\rho) \vr(P)_{\min}}} \tag{using $\varepsilon$ from (\ref{eq:define-varepsilon})} \\
    & \leq \frac{1}{2}\sqrt{\kappa(\widehat{F}_\vr)} \log 3n^{1/2}(1-\rho)^{-1/2}\hat{\eta}^{-1}\vr(P)_{\min}^{-1/2} \tag{simplifying constants} \\
    & \leq \frac{1}{2}\sqrt{\kappa(\widehat{F}_\vr)} \log 6n(1-\rho)^{-1/2}\hat{\eta}^{-1}\varepsilon_{\mathrm{d}}^{-1/2} \tag{since $\vr(P)_{\min} \geq \varepsilon_{\mathrm{d}} / (4n)$ by assumption}, \\
    & \leq \sqrt{\frac{1-\mu\rho}{2(1-\rho)}} \log 6n(1-\rho)^{-1/2}\hat{\eta}^{-1}\varepsilon_{\mathrm{d}}^{-1/2} \tag{by Lemma \ref{lem:condition-number}}
\end{align*}
which concludes the proof.
\end{proof}

\algoneconv*
\begin{proof}
    An easy way to see why Thm. \ref{thm:convergence-alg1} holds is by noticing that the lower bound condition on $\rho$ given in (\ref{eq:discount-factor-constraint}) will hold after a finite number of iterations depending logarithmically on remaining problem parameters. Then, since by Lemma \ref{lem:conv-cg} each iteration requires $\widetilde{O}((1-\rho)^{-1/2})$ steps of CG (with each step costing $O(n^2)$), and $1-\rho$ will be at most $O(1-\lambda_2)$, the result follows. Now, we provide a more detailed analysis. 

    First, define $\tilde{\rho}^{(l)} = 1 - \rho^{(l)}$ for the $l^{th}$ iteration of Alg. \ref{alg:newton-solve}. Since $\rho^{(0)} = 0 \implies \tilde{\rho}^{(0)} = 1$, we have $\tilde{\rho}^{(l)} = 4^{-l}$ given the update rule in L5. Then, by (\ref{eq:discount-factor-constraint}) of Thm. \ref{thm:residual}, Alg. 1 performs the final iteration (in the worst case) when
    \begin{align*}
        \tilde{\rho}^{(l)} = 4^{-l} &\leq \frac{(1-\lambda_2)K}{\lambda_2(1-K)} = (1-\lambda_2)\tilde{K}.
    \end{align*}
    That is, in the worst case we terminate after $l$ steps, where 
    \begin{align}
    \label{eq:n-steps-of-alg1}
        l = \mathrm{ceil}\left(-\frac{\log(1-\lambda_2)\tilde{K}}{\log(4)}\right).
    \end{align} In the worst case, we are guaranteed by the final step final that,
    \begin{align}
        \tilde{\rho}^{(l)} = 4^{-l} \in \left(\frac{(1-\lambda_2)\tilde{K}}{4}, (1-\lambda_2)\tilde{K}\right].
    \end{align}
    Thus, for each integer $l^\prime \in [l]$, we have
    \begin{align}
    \label{eq:tilde-rho-ineq}
        \tilde{\rho}^{(l^\prime)} = 4^{-l^\prime} > (1-\lambda_2)\tilde{K} 4^{l-l^\prime-1}.
    \end{align}
    Then, the condition number at a given step $l^\prime \geq 0$ satisfies:
    \begin{align*}
        \kappa^{(l^\prime)} &\leq \mu + \frac{1-\mu}{1-\rho^{(l^\prime)}} \tag{From Lemma \ref{lem:condition-number}} \\
        &\leq \mu + 4^{1 + l^\prime - l}\frac{1-\mu}{(1-\lambda_2)\tilde{K}} \tag{From (\ref{eq:tilde-rho-ineq})} \\
        &= 4^{1 + l^\prime - l} \kappa_0,
    \end{align*}
    where
    \begin{align}
        \kappa_0 = O\left(\frac{1-\mu}{(1-\lambda_2)\tilde{K}}\right) ~\mathrm{as}~ \lambda_2 \rightarrow 1
    \end{align}
    By Lemma \ref{lem:conv-cg}, a given step $l^\prime \leq l$ of Alg. \ref{alg:newton-solve} takes at most
    \begin{align*}
        k(l^\prime) &= 2^{1+l^\prime-l} \sqrt{\kappa_0} \log \left(3n \sqrt{\kappa_0} 2^{1+l^\prime-l}   \hat{\eta}^{-1} \varepsilon_{\mathrm{d}}^{-1/2} \right) \\
        &\leq 2^{1+l^\prime-l} \sqrt{\kappa_0} \log \left(6n \sqrt{\kappa_0}    \hat{\eta}^{-1} \varepsilon_{\mathrm{d}}^{-1/2} \right) \tag{since $l^\prime \leq l$} \\
        &= 2^{1+l^\prime-l} \widetilde{O}(\sqrt{\kappa_0}),
    \end{align*}
    steps of the conjugate gradient algorithm. Taking a sum over $l^\prime$:
    \begin{align*}
        \sum_{l^\prime=0}^l k(l^\prime) &=  \widetilde{O}(\sqrt{\kappa_0}) 2^{1-l} \sum_{l^\prime=0}^l 2^{l^\prime} \\
        &= \widetilde{O}(\sqrt{\kappa_0}) 2^{1-l} \left(\frac{2^{l+1}-1}{2-1}\right) \numberthis \label{eq:L-rho-decay-factor} \\
        &= \widetilde{O}(\sqrt{\kappa_0}) (4 - 2^{1-l}) \\
        & \leq \widetilde{O}(\sqrt{\kappa_0}) (4 - \sqrt{(1-\lambda_2)\tilde{K}}) \tag{due to (\ref{eq:n-steps-of-alg1})} \\
        &= \widetilde{O}(\sqrt{\kappa_0}) \numberthis\label{eq:tilde_kappa_o}.
    \end{align*}

Note that the choice of decay factor 4 is not arbitrary; if one chooses instead a factor $L > 1$ and repeats the above steps, one arrives at (cf. (\ref{eq:n-steps-of-alg1})):
\begin{align*}
    l = \mathrm{ceil}\left(-\frac{\log(1-\lambda_2)\tilde{K}}{\log(L)}\right),
\end{align*}
and the following (cf. (\ref{eq:L-rho-decay-factor}))
\begin{align*}
    \sum_{l^\prime=0}^l k(l^\prime) &= \widetilde{O}(\sqrt{\kappa_0}) \sqrt{L}^{1-l} \left(\frac{\sqrt{L}^{l+1}-1}{\sqrt{L}-1}\right) \\ 
    &\leq \widetilde{O}(\sqrt{\kappa_0}) \frac{L-\sqrt{(1-\lambda_2)\tilde{K}}}{\sqrt{L}-1} \\
    &\leq \widetilde{O}(\sqrt{\kappa_0}) \frac{L}{\sqrt{L}-1},
\end{align*}
and $L=4$ is the global minimizer of $h(x) = x / (\sqrt{x}-1)$. The last inequality is strong when convergence is bottlenecked by $\lambda_2 \approx 1$, so that the choice $L=4$ becomes near-optimal when optimality is most needed.

Continuing from (\ref{eq:tilde_kappa_o}), the overall complexity is:
\begin{align*}
    \tilde{O}(\sqrt{\kappa_0}) = \tilde{O}\left(\sqrt{\frac{1-\mu}{(1-\lambda_2)\tilde{K}}} \right).
\end{align*}

The result follows by explicitly writing and simplifying $\tilde{K}^{-1}$:
\begin{align*}
    \tilde{K}^{-1} &= \frac{\lambda_2 (1-K)}{K} \\
    &= \frac{2\lambda_2 (1-\zeta \eta / 2)}{\zeta \eta} \tag{Since we choose $\beta = 0.5$, where $K=\zeta \beta \eta$}. \\
    &\leq \frac{2}{\zeta \eta} \\
    &= 2\frac{\chi(\vr|\vr(P))}{\norm{\nabla_\vu g}_1 \eta},
\end{align*}
where the last equality holds by definition of $\zeta$.
\end{proof}

