\subsubsection{Proof of Thm. \ref{thm:perstep-improv-alg3}}
\label{sec:armijo-and-quadraticrate-proof}

First, we present a simple lemma on the line search condition used in L12 of Algorithm \ref{alg:tns-project}.
\begin{restatable}[Sufficient Decrease Condition]{lemma}{suffdecr}
\label{lem:sufficient-decrease}
Assuming ${\vc = \vc(P)}$, given a descent direction ${\vd = (\vd_\vu, -P_\vc \vd_\vu)}$, the Armijo condition for line search over objective $g$ is satisfied for a step size $\alpha \in (0, 1]$ and constant parameter $c_1 \in (0, 1)$ if and only if:
\begin{align}
\label{eq:armijo}
    \norm{\mathbf{vec}(P(\vu + \alpha \vd_\vu, \vv - \alpha P_\vc \vd_\vu))}_1 -1 \leq (1-c_1) \alpha \langle -\nabla_\vu g, \vd_\vu \rangle.
\end{align}
\end{restatable}
\begin{proof}
    Recall that the Armijo condition requires (see Ch. 3.1 of \citet{Nocedal}):
    \begin{align}
        g(\vu + \alpha \vd_\vu, \vv - \alpha P_\vc \vd_\vu) \leq g(\vu, \vv) + c_1 \alpha \langle \nabla g, \vd \rangle.
    \end{align}
    For brevity, let $P(\alpha) \coloneqq P(\vu + \alpha \vd_\vu, \vv - \alpha P_\vc \vd_\vu)$. We show the equivalence of the above statement to (\ref{eq:armijo}) step by step:
    \begin{align*}
        &g(\vu + \alpha \vd_\vu, \vv - \alpha P_\vc \vd_\vu) \leq g(\vu, \vv) + c_1 \alpha \langle \nabla g, \vd \rangle. \\
        \iff& \norm{\mathbf{vec}(P(\alpha))}_1 -1 - \langle \vu + \alpha \vd_\vu, \vr  \rangle - \langle \vv - \alpha P_\vc \vd_\vu, \vc  \rangle \leq - \langle \vu, \vr  \rangle - \langle \vv, \vc  \rangle + c_1 \alpha \langle \nabla g, \vd \rangle \\
        \iff& \norm{\mathbf{vec}(P(\alpha))}_1 -1 \leq \alpha \big(\langle \vd_\vu, \vr  \rangle - \langle P_\vc \vd_\vu, \vc \rangle \big) + c_1 \alpha \langle \nabla g, \vd \rangle \\
        \iff & \norm{\mathbf{vec}(P(\alpha))}_1 -1 \leq \alpha \big(\langle \vd_\vu, \vr  \rangle - \langle \vd_\vu, P_\vc^\top \vc \rangle \big) + c_1 \alpha \langle \nabla g, \vd \rangle \\
        \iff & \norm{\mathbf{vec}(P(\alpha))}_1 -1 \leq \alpha \big(\langle \vd_\vu, \vr  \rangle - \langle \vd_\vu, \vr(P) \rangle \big) + c_1 \alpha \langle \nabla g, \vd \rangle \tag{Since $P_\vc^\top \vc = \vr(P)$} \\
        \iff & \norm{\mathbf{vec}(P(\alpha))}_1 -1 \leq \alpha \langle \vd_\vu, -\nabla_\vu g  \rangle + c_1 \alpha \langle \nabla_\vu g, \vd_\vu \rangle \tag{Since $\vc(P) = \vc$ by assumption},
    \end{align*}
    which is equivalent to (\ref{eq:armijo}).
\end{proof}

\algthreeimprov*
\begin{proof}
    For convenience, let $\vz \coloneqq (\vu, \vv)$ given some $(\vu, \vv) \in \mathbb{R}^{2n}$ and $\nabla^2 g(t) \coloneqq \nabla^2 g(\vz + t \alpha \vd)$. Recall that from Taylor's Theorem, we have:
    \begin{align*}
        \nabla g(\vz + \alpha \vd) &= \nabla g(\vz) + \alpha \int_0^1 [\nabla^2 g(t) ]\vd ~dt \\
        &= \nabla g(\vz) + \alpha \nabla^2 g(0) \vd + \alpha \int_0^1 \left[\nabla^2 g(t) - \nabla^2 g(0) \right]\vd ~dt \\
        &= (1-\alpha) \nabla g(\vz) +  \alpha \ve + \alpha \int_0^1 \left[\nabla^2 g(t) - \nabla^2 g(0) \right]\vd ~dt.
    \end{align*}
    Now, we define the following:
    \begin{align*}
        \vh(t) \coloneqq \int_0^1 \left[\nabla^2 g(t) - \nabla^2 g(0) \right]\vd.
    \end{align*}
    Then,
    \begin{align*}
      \norm{\nabla g(\vz + \alpha \vd)}_1 &\leq (1-\alpha) \norm{\nabla g(\vz)}_1 + \alpha \norm{\ve}_1 + \alpha \norm{\int_0^1 \vh(t)dt}_1 \\
      &\leq (1 - \alpha + \alpha \eta) \norm{\nabla g(\vz)}_1 + \alpha \norm{\int_0^1 \vh(t)dt}_1 \tag{By construction} \\
      &\leq (1 - \alpha + \alpha \eta) \norm{\nabla g(\vz)}_1 + \alpha \int_0^1 \norm{\vh(t)}_1 dt \numberthis \label{eq:grad-next-bound1}
    \end{align*}
