\section{Sharpness of the regularity exponent} \label{sec:lower}	
In this section,  we discuss the 
sharpness of the regularity exponent $s$ in the estimate \eqref{smooth-pq}. 

	We begin  by recalling the definitions \eqref{agamma}  and \eqref{agamma'} for a discrete set $\mathcal E$. The following lemma shows the existence of a certain $2^{-j}$-separated set,  which will  be used in the proof of the lower bounds in Proposition \ref{prop:neces}. 


\begin{lem}
\label{lem:existA}
Let $ 0\leq \alpha\leq 1 $. For each $j\ge 1$, there exists a  $2^{-j}$-separated subset $\mathcal{E}\subset [1,2] $  such that $\#\mathcal{E}\sim 2^{j\alpha}$, $ \mathcal A_{\alpha}(\mathcal E;  2^{-j})\lesssim 1$,   and $ \tilde{\mathcal A}_{\alpha}(\mathcal E;  2^{-j})\lesssim 1$.
\end{lem}

\begin{proof}
If $ \alpha=0 $, we take $ \mathcal{E}$ to be  a set of one element. Thus it remains to consider the case $ 0<\alpha\leq 1 $. 

Let $ \mu=2^{-1/\alpha}\in (0,1/2]$. We use the standard construction for a Cantor set, see \cite[p. 60]{1995mattila}. At step $ 0 $, set $ I_{0,1}^\mu=[1,2]$. At step $ 1 $, we take a closed interval $ I_{1,1}^\mu$ of length $ \mu $ such that it shares the same left endpoint with the interval $ I_{0,1}^\mu$. Similarly, we let $ I_{1,2}^\mu$ be the interval of length $ \mu $ such that it shares the same right endpoint with the interval $ I_{0,1}^\mu$.  We continue this process for the  closed intervals appearing in the previous step. At stage $ k $, we have $ 2^k $ intervals $ I_{k,1}^\mu,\cdots, I_{k,2^k}^\mu$ of length $ \mu^k $. 

We now choose $k$ such that  $ \mu^k\sim L2^{-j} $ with $ L $ being a fixed large positive constant.  We let $ \mathcal{E} $ be the set of all the right endpoints of these $ 2^k $ intervals $ I_{k,1}^\mu,\cdots, I_{k,2^k}^\mu$. Clearly, $ \mathcal{E} $ is $2^{-j}$-separated with cardinal $\#\mathcal{E}\sim 2^{j\alpha} $. 

To see $ \mathcal A_{\alpha}(\mathcal E;  2^{-j})\lesssim 1$,  let $I\subset [1,2]$ be an interval of length $\sim \mu^l\ge 2^{-j}.$ From the construction, it is clear that  $\mathcal N(\mathcal E\cap I, 2^{-j})$ maximizes when $I$ shares its left or right endpoint with $[1,2]$. In such cases, we have $\mathcal N(\mathcal E\cap I, 2^{-j})\sim 2^{k-l}$. Therefore, 
\[  \mathcal A_{\alpha}(\mathcal E;  2^{-j})\lesssim \Big( \frac{\mu^k}{\mu^l}\Big)^\alpha  2^{k-l}\lesssim 1. \]
Similarly, one can easily see from the self-similar nature of the construction  that ${\mathcal A}_{\alpha}(\mathcal E;  2^{-m})\lesssim 1$ for all $1\le m\le j$.  Hence, 
it follows that $\tilde {\mathcal A}_{\alpha}(\mathcal E;  2^{-j})\lesssim 1$.
\end{proof}

\begin{rem}[Explicit   description of the construction in the proof of Lemma \ref{lem:existA}]
\label{rem:description}  It is not hard to see that, for each $k\in \mathbb{N}$,
\[\mathcal{E}=\Big\{1+\mu^k+\sum_{m=0}^{k-1}(1-\mu)\mu^m P_m\, :\, P_m=0,1\Big\}.\]
This gives a decomposition  $ \mathcal{E} =\bigcup_{l=0}^k\mathcal{E}_l$, where  $\mathcal{E}_k=\{1+\mu^k\}$  and 
\[\mathcal{E}_l=\Big\{1+\mu^k+(1-\mu)\mu^{l}+\sum_{m=l+1}^{k-1}(1-\mu)\mu^m P_m\, :\, P_m=0,1\Big\}, \quad 0\leq l\leq k-1.\]
Then, it follows that $\#\mathcal{E}_l=2^{k-l-1}$ for  $ 0\leq l \leq k-1 $. Observe also that $ \mu^k\sim L2^{-j} $ implies $ k=j\alpha+O(1) $. 
\end{rem}


Before we show  the 
sharpness of the regularity exponent $s$ in the estimate \eqref{smooth-pq}, we first consider the case of discrete dilation sets. 
The desired conclusion will easily  follow from this result for the discrete setting. 


	\begin{prop}
	\label{prop:neces}
		Let $ 0\leq \alpha\leq 1$, $ 1\leq p\leq q\leq \infty$, and  $\mathcal E\subset [1,2]$ be a $2^{-j}$-separated set. Suppose that  the estimate
	\Be 	
	\label{hohoho}
			\|e^{it\sqrt{-\Delta}}P_jf\|_{L^q(\mathbb{R}^d\times \mathcal{E})}\le C2^{js}\|f\|_{L^p(\mathbb{R}^d)}
	\Ee		
holds for a constant $C$, independent of $j\ge 1$, whenever $\mathcal A_{\alpha}(\mathcal E;  2^{-j})\le  C_0 $ for a constant $C_0>0$. Then,  we must have
		\[
			s\geq  s_c(p,q):=\max  \big\{s_1(p,q),\,s_2(p,q),\, s_3(p,q)\big\}. 
	\]
		Moreover, if $ p=q=\frac{2(\alpha+d-1)}{d-1}$ and $\alpha>0$, then it is necessary that $s>{\alpha}/{q}$.
	\end{prop}

	The examples used in the proof of this proposition are adaptations of  the standard examples (see, e.g., \cite[Section 4]{TV2}).

	\begin{proof}
	We prove each of the lower bounds  $s\ge s_1(p,q)$,  $s\ge s_2(p,q)$, and $s\ge s_3(p,q)$,   separately.
	Without loss of generality,  we can replace $ P_jf $ with $ f $ whose Fourier support is contained in $\mathbb{A}_{2^j}=\{\xi: 2^{j-1}\leq|\xi|\leq 2^{j+1}\}$. 


\noindent \textit{Lower bound $s\geq  s_1(p,q):= \frac{d-1}{2}+\frac{1}{p}-\frac{d}{q}$.}
	As  mentioned in the introduction,  this lower bound applies to  a fixed time estimate  \eqref{single} for  the wave operator. 

	 Let $\mathcal{E}=\{1+L2^{-j}\}$ with $j\gg 1$, which trivially satisfies $\ \mathcal A_{\alpha}(\mathcal E;  2^{-j})\le 1$.  Here $ L $ is a fixed large positive constant as in the proof of Lemma \ref{lem:existA}. We take $f$  given by 
	 \Be\label{hhh} \widehat{f}(\xi)=e^{-i|\xi|}\beta_1(|\xi|/2^j) ,\Ee where $ \beta_1 \in C_c^\infty\big((1/4,4)\big) $ is a non-negative  function such that $ \beta_1=1 $ on $ [2^{-1},2]$. Since $\widehat{f}$ is radial, the Fourier inversion formula for radial functions \cite[p.~155]{SW} gives 
		\[f(x)=c2^{j\frac{d+2}{2}}\int_{0}^{\infty}e^{-i2^jr}\beta_1(r)J_{\frac{d-2}{2}}(2^jr|x|)(r|x|)^{-\frac{d-2}{2}}r^{d-1}\,dr\]
		for a constant $c$,  where $ J_{\frac{d-2}{2}}$ is the Bessel function. It is well known that 
		\[J_{\frac{d-2}{2}}(r)=e^{\pm ir}a_{\pm}(r),\]
		where $ a_\pm\in S^{{-1/2}} $ in the sense that $|(\tfrac{d}{dr})^ma_\pm(r)|\lesssim (1+r)^{-m-{1/2}}$ for any $ m\in\mathbb{N}$ (see \cite[Chapter VIII, 1.4.1]{stein1993harmonic}). This gives 
		\begin{align*}
			f(x)&=c2^{j\frac{d+2}{2}}\sum_\pm \int_{0}^\infty e^{i2^jr(\pm |x|-1)}\beta_1(r)a_\pm(2^jr|x|)(r|x|)^{-\frac{d-2}{2}}r^{d-1}\,dr.
		\end{align*}
		By routine integration by parts, it follows that  $|f(x)|\lesssim 2^{j\frac{d+1}{2}}(1+2^j||x|-1|)^{-N}$
		for any $ N\in\mathbb{N}$.  Consequently, it follows that   
		\[  \|f\|_{L^p(\mathbb{R}^d)} \lesssim 2^{j(\frac{d+1}{2}-\frac{1}{p})}.\]

		To obtain a lower bound for $e^{it\sqrt{-\Delta}}f(x) $, we use  the asymptotic  expansion 
		\[J_\frac{d-2}{2}(r)=c_\pm e^{\pm ir}r^{-1/2}+R(r),  \quad r\geq 1,\]
		where $ c_{\pm}\neq 0 $ and $ |R(r)|\lesssim r^{-3/2}$ (see \cite[Chapter VIII, 5.2]{stein1993harmonic}). 

		Let us set 
		\begin{align*} 
		I_\pm(x,t) &=  c_\pm 2^{j\frac{d+1}{2}}|x|^{-\frac{d-1}{2}}\int e^{i2^jr(t-1\pm |x|)}\beta_1(r)r^{\frac{d-1}{2}}\,dr, 
		\\ 
		I_0(x,t)&=2^{j\frac{d+2}{2}}|x|^{-\frac{d-2}{2}}\int e^{i2^jr(t-1)}\beta_1(r)R(2^jr|x|)r^{\frac{d}{2}}\,dr.
		\end{align*}
		Thus, we have
		\begin{align*}
			e^{it\sqrt{-\Delta}}f(x)&=  I_+(x,t) +I_-(x,t)+  I_0(x,t) 	               
		\end{align*}
		when $ |x|\gtrsim 2^{-j} $.  It is easy to see that  $I_0(x,t) = O(2^{j\frac{d+1}{2}}|x|^{-\frac{d-1}{2}} (2^j|x|)^{-1})$ for $ |x|\gtrsim 2^{-j} $.  
		Also note that  
		\[ I_\pm(x,t) =c_\pm 2^{j\frac{d+1}{2}}|x|^{-\frac{d-1}{2}}\phi\big(2^j(t-1\pm |x|)\big),\]
		where   $ \widehat{\phi}(s)=\beta_1(s) s^{(d-1)/2} $.  
		 We take $t=1+L2^{-j} \in\mathcal{E}$ and let 
		 \[ J_t= [t-1-c_02^{-j},t-1].\] 
		Noting that $ \phi\in \mathcal{S}(\mathbb{R}) $ and $ \phi(0)>0 $,  we  choose $ c_0 $ small enough and $ L $ large enough so that $ |I_{+}(x,t)|\ll |I_{-}(x,t)|\sim 2^{j\frac{d+1}{2}}|x|^{-\frac{d-1}{2}}$ if $|x|\in J_t$. Thus, we obtain 
		 \Be
		 \label{hh} |e^{it\sqrt{-\Delta}}f(x)|\gtrsim2^{j\frac{d+1}{2}}|x|^{-\frac{d-1}{2}} \Ee
		 provided that $|x| \in J_t$. As a result, we have
		\begin{align*}
		\|e^{it\sqrt{-\Delta}}f\|_{L^q(\mathbb{R}^d)}\gtrsim 2^{j\frac{d+1}{2}}\Big(\int_{J_t}r^{-\frac{d-1}{2}q}r^{d-1}\,dr\Big)^{1/q}\gtrsim 2^{jd}2^{-j\frac{d}{q}}.
		\end{align*}
		Since $  \|f\|_{L^p(\mathbb{R}^d)} \lesssim 2^{j(\frac{d+1}{2}-\frac{1}{p})}$, the estimate  \eqref{hohoho} with $\mathcal{E}=\{1+L2^{-j}\}$ implies 
		\[2^{jd}2^{-j\frac{d}{q}}\le C 2^{j(s+\frac{d+1}{2}-\frac{1}{p})},\]
		which yields the desired bound $s\geq  s_1(p,q)$  by  letting $ j\to\infty $.

\noindent \textit{Lower bound $s\geq s_2(p,q):= \frac{d+1}{2}\big(\frac{1}{p}-\frac{1}{q}\big)+\frac{\alpha}{q}$.}
Using Lemma \ref{lem:existA}, we can take a $2^{-j}$-separated set $ \mathcal{E}\subset [1,2] $  with cardinality  $\#\mathcal{E}\sim 2^{j\alpha} $ and $ \mathcal A_{\alpha}(\mathcal E;2^{-j})\lesssim 1$.  For each $t\in \mathcal E$, we set 
\[ S_t=\{x:  |x'|\le c 2^{-j/2}, \quad  |x_d+t|\le c 2^{-j}\} \]
with  a small positive constant $c$, which we choose later. 

Recall that $\beta_0\in C_c^\infty((-2^2, 2^2))$ with  $\beta_0=1$ on $[-2, 2]$,  and  $\beta_1 \in C_c^{\infty}((2^{-2}, 2^2))$  with  $\beta_1=1$ on $[2^{-1}, 2]$. 
 Let us consider $f$ given by 
\[\widehat{f}(\xi)=\beta_0\Big(\frac{|\xi'|}{c_12^{j/2}}\Big) \beta_1\Big(\frac{\xi_d}{2^j}\Big), \quad \xi=(\xi',\xi_d), \] which is essentially the Knapp example. Here $ c_1 $ is a small positive constant to be chosen later. It is easy to see that $ \|f\|_{L^p(\mathbb{R}^d)} \sim 2^{j\frac{d+1}{2}(1-\frac1p)}$.  Scaling  $(\xi^{\prime}, \xi_d)\to (2^{j/2}\xi', 2^j  \xi_d)$ gives 
\[e^{it\sqrt{-\Delta}}f(x)=\frac{2^{j(d+1)/2}}{ (2\pi)^{d} }\!\int e^{i2^{j/2}x'\cdot\xi'}e^{i2^j(x_d+t)\xi_d}e^{it\xi_d\tilde \phi_{2^{-j/2}}(\xi'/\xi_d)}\beta_0\Big(\frac{|\xi'|}{c_1}\Big) \beta_1 ({\xi_d})\,d\xi' d\xi_d,\]
where $\tilde \phi_{2^{-j/2}}$ is given by  \eqref{phi-theta}. Note  that $|e^{it\xi_d\tilde \phi_{2^{-j/2}}(\xi'/\xi_d)}-1|\lesssim  2|\xi'|^2/{\xi_d}\lesssim c_1^2$ 
if $ t\in[1,2] $ and   $\xi\in \supp \widehat f(2^{j/2}\cdot,2^{j}\cdot)$. Thus, if $c$  and $ c_1 $ are small enough, we have 
\[ |e^{it\sqrt{-\Delta}}f(x)|\gtrsim 2^{j\frac{d+1}2}\]
 for any $ t\in [1,2]$  if $x\in  S_t$. 
 Hence, $\|e^{it\sqrt{-\Delta}}f\|_{L^q(\mathbb{R}^d)}\gtrsim 2^{j(\frac{d+1}2 -\frac{d+1}{2q})}$ for $ t\in [1,2]$. 

 Since  $\# \mathcal E\sim 2^{\alpha j}$,
 the left hand side of the inequality \eqref{hohoho} is bounded below by  $2^{j(\frac{d+1}2 -\frac{d+1}{2q}+\frac \alpha q)}$.  
Since  $ \|f\|_{L^p(\mathbb{R}^d)} \sim 2^{j\frac{d+1}{2}(1-\frac1p)}$,  the estimate \eqref{hohoho} implies
 \[  2^{j(\frac{d+1}2 -\frac{d+1}{2q}+\frac \alpha q)} \lesssim  2^{sj} 2^{j\frac{d+1}{2}(1-\frac1p)} \] 
 for all $j\ge 1$. Thus, letting $j\to \infty$ gives   $s\geq  s_2(p,q)$.

\noindent \textit{Lower bound $s\geq s_3(p,q):= \frac{d}{p}-\frac{1-\alpha}{q}-\frac{d-1}{2}$.}
Choose again a set  $ \mathcal{E} $ as in Lemma \ref{lem:existA}. Let us consider $f$ given by 
\[  \widehat{f}(\xi)=\beta_1(|\xi|/2^{j}).\]
It is clear that $ \|f\|_{L^p(\mathbb{R}^d)} \sim 2^{jd/p'}$.  

Recall  \eqref{hhh} and \eqref{hh}, which are used to show  the  first lower bound  $s\geq  s_1(p,q)$. Translation $t\to t+1$ 
yields 
$ |e^{it\sqrt{-\Delta}}f(x)|\gtrsim 2^{j(d+1)/2} $ for  $|x| \in  [t-c_02^{-j},t]$ and $ t\in [1,2]$.  
Thus, $\|e^{it\sqrt{-\Delta}}f\|_{L^q(\mathbb{R}^d)}\gtrsim 2^{j(\frac{d+1}2 -\frac{1}{q})}$ for $ t\in [1,2]$.  Moreover, since $\#\mathcal E \sim 2^{\alpha j}$, the estimate \eqref{smooth-pq}  implies 
\[ 2^{j(\frac{d+1}2 -\frac{1}{q}+\frac \alpha q)} \lesssim 2^{js}2^{jd/p'},\] which leads to the lower bound $ s\geq s_3(p,q)$.

\noindent \textit{$\epsilon$-loss for  the marginal point  $ (p,q)=(\frac{2(\alpha+d-1)}{d-1},\frac{2(\alpha+d-1)}{d-1})$.} 
Let $p=q=\frac{2(\alpha+d-1)}{d-1} $ and $ \alpha>0 $. 
We again take the $2^{-j}$-separated set $\mathcal{E} $, which is  constructed in the proof of Lemma~\ref{lem:existA}. Choosing the function $f$ given by \eqref{hhh}, we have
\eqref{hh} for $t\in \mathcal{E}$ and $|x| \in J_t$. Since $\mathcal{E} $ is $2^{-j}$ separated and $ q=\frac{2(\alpha+d-1)}{d-1} $,  it follows that
\begin{align*}
\|e^{it\sqrt{-\Delta}}f\|^q_{L^q(\mathbb{R}^d\times \mathcal{E})}&\gtrsim 2^{j\frac{d+1}{2}q} \sum_{t\in\mathcal{E}}\int_{J_t}r^{-\frac{d-1}{2}q}r^{d-1}\,dr\\
&\simeq 2^{j\frac{d+1}{2}q}2^{-j} \sum_{t\in\mathcal{E}}(t-1)^{-(d-1)(\frac{q}{2}-1)}\\
& \simeq2^{j(\frac{(d+1)q}{2}-1)}\sum_{t\in\mathcal{E}}|t-1|^{-\alpha}.
\end{align*}
Recall that $\mathcal{E}$ can be written as $ \mathcal{E} =\bigcup_{l=0}^k\mathcal{E}_l$ (see Remark \ref{rem:description}) and note that $ t-1\sim \mu^{l} $ when $ t\in \mathcal{E}_l $. Thus,  we have
\[\sum_{t\in\mathcal{E}}|t-1|^{-\alpha}=\sum_{l=0}^{k}\sum_{t\in\mathcal{E}_l}|t-1|^{-\alpha}\sim \sum_{l=0}^k\#\mathcal{E}_l\mu^{-l\alpha}\sim \sum_{l=0}^k2^{k-l}2^l\sim k2^k.\]
Recalling $ k=j\alpha+O(1) $, we see that \eqref{hohoho} implies 
\[2^{j(\frac{d+1}{2}-\frac{1}{q}+\frac{\alpha}{q})}j^{1/q}\lesssim  2^{j(s+\frac{d+1}{2}-\frac{1}{p})}. 
\]
Letting $ j\to\infty $ shows that $s>{\alpha}/{q}$.
\end{proof}


\subsection*{Sharpness of the exponent $s \ge s_c(p,q)$ for \eqref{smooth-pq}}
We can now show that the regularity exponent $ s \ge s_c(p,q) $ if the local smoothing estimate \eqref{smooth-pq} holds for every $ 2^{-j} $-separated subset $ E(2^{-j}) \subset E $, whenever $ E \subset [1,2] $ has bounded $ \alpha $-Assouad characteristic. This follows from the arguments used in the proof of Proposition~\ref{prop:neces}.


In particular, let $ I_{k,1}^\mu, \ldots, I_{k,2^k}^\mu $ be the $ 2^k $ intervals of length $ \mu^k $ appearing at the $ k $-th stage of the construction used in the proof of  Lemma~\ref{lem:existA}. We consider the set
\[
E = \bigcap_{k=0}^\infty \bigcup_{\ell=1}^{2^k} I_{k,\ell}^\mu.
\]
It is easy to see that $ E \subset [1,2] $ has bounded $ \alpha $-Assouad characteristic. Recall that the set $ \mathcal{E} $ consists of the right endpoints of the $ 2^k $ intervals $ I_{k,1}^\mu, \ldots, I_{k,2^k}^\mu $. Clearly, $ \mathcal{E} $ is a $ 2^{-j} $-separated subset of $ E $. Therefore, by the same reasoning as in the proof of Proposition~\ref{prop:neces}, we conclude that $ s \ge s_c(p,q) $.



