\section{Broader impacts and limitations}
Our work presents a novel, generic approach to training-free diffusion guidance by connecting with stochastic optimal control theory. The proposed application is for low-density molecular sampling, with the potential to advance drug discovery finding effective drug candidates for cancer treatments. However, in the wrong hands, it could be misused to illicitly design harmful or addictive substances. Ensuring responsible usage is, therefore, critical to maximizing its positive societal impact. The main limitation of our study is that it has only been validated on molecular generation tasks. Nonetheless, we believe that the SDG framework can be extended to other controlled generation settings across different data modalities. 

\section{Theoretical proofs}

\paragraph{Proposition 3.1}
%
\textit{
Let the cost functional of the control problem in Equation \ref{eq:soc} be $J\left(\mathbf{u}, \mathbf{x}, t\right) = \mathbb{E}_{\mathbb{P}^{\mathbf{u}}}\left[\int_t^T \left(\frac{1}{2} \|\mathbf{u}\left(\mathbf{x}_s^{\mathbf{u}},s\right)\|^2+ \alpha(s)\log p_s\left(\mathbf{x}_s^{\mathbf{u}}\right) \delta(s-t) \right)ds - \beta(t) r(\mathbf{x}_T^{\mathbf{u}}) | \mathbf{x}_t = \mathbf{x}\right]$, then the annealed reward-guided marginal density $p_t^{\mathbf{u}}(\mathbf{x}_t)$, the value function $V\left(\mathbf{x}, t\right)$, and the optimal control  $\mathbf{u}^*\left(\mathbf{x}, t\right)$ corresponding to the controlled-reverse SDE under $\mathbb{P}^{\mathbf{u}}$ can be derived as follows:}
\begin{align}
    &p_t^{\mathbf{u}}(\mathbf{x}_t)= p_t^{1-\alpha(t)}(\mathbf{x}_t)\exp(\beta(t)r(\mathbf{x}_T))\nonumber \\
    &\mathbf{u}^*\left(\mathbf{x}, t\right)=\sigma(t) \nabla_{\mathbf{x}}\log \mathbb{E}_{\mathbb{P}}\left[\frac{p_t^{\mathbf{u}}(\mathbf{x})}{p_t(\mathbf{x})}|\mathbf{x}_t = \mathbf{x}\right] \;\; \text{and} \;\;
    V\left(\mathbf{x}, t\right) =  -\log \mathbb{E}_{\mathbb{P}}\left[\frac{p_t^{\mathbf{u}}(\mathbf{x})}{p_t(\mathbf{x})}|\mathbf{x}_t = \mathbf{x}\right] \nonumber
\end{align}
%
%
\textit{Proof}: We aim to minimize the cost functional of the control problem in Equation \ref{eq:soc}. For low-density sampling, we introduce a state cost that penalizes the density of the current state, expressed as $f\left(\mathbf{x}_s,s\right)=\alpha(s)\log p_s\left(\mathbf{x}_s\right) \delta(s-t)$, where $\alpha(s)$ controls the density annealing schedule. To incorporate reward maximization into the minimization framework, we define the terminal cost as $g\left(\mathbf{x}_T\right)=-\beta(t) r(\mathbf{x}_T)$. where $r(\cdot)$ is the reward function and $\beta(t)$ modulates the guidance strength. Substituting these expressions into the solutions from Lemma~\ref{theo:soc}, we obtain the value function:
%
\begin{align}
V(\mathbf{x}, t) &= - \log \mathbb{E}_{\mathbb{P}} \left[\exp\left(- \int_t^T\alpha(s)\log p_s\left(\mathbf{x}_s\right) \delta(s-t)ds +\beta(t)r(\mathbf{x}_T)\right)| \mathbf{x}_t=\mathbf{x}\right] \nonumber\\
&= - \log \mathbb{E}_{\mathbb{P}} \left[\exp\left(-\alpha(t)\log p_t\left(\mathbf{x}\right) +\beta(t)r(\mathbf{x}_T)\right)| \mathbf{x}_t=\mathbf{x}\right] \nonumber\\
&= - \log \mathbb{E}_{\mathbb{P}} \left[p^{-\alpha(t)}_t\left(\mathbf{x}\right)\exp\left(\beta(t)r(\mathbf{x}_T)\right)| \mathbf{x}_t=\mathbf{x}\right]
\end{align}
%
and the optimal control:
%
\begin{align}
\mathbf{u}^*\left(\mathbf{x}, t\right)=\sigma(t) \nabla_{\mathbf{x}}\log \mathbb{E}_{\mathbb{P}} \left[p^{-\alpha(t)}_t\left(\mathbf{x}\right)\exp\left(\beta(t)r(\mathbf{x}_T)\right)| \mathbf{x}_t=\mathbf{x}\right]
\end{align}
%

We substitute the optimal control into the control problem in Equation~\ref{eq:soc}, resulting in the controlled SDE under $\mathbb{P}^{\mathbf{u}}$:

\scalebox{.9}{
\begin{minipage}{\linewidth}
\begin{align}
   &d\mathbf{x}_t^{\mathbf{u}} = \left(-\mathbf{b}(\mathbf{x}_t^{\mathbf{u}}, t)+\sigma(t)^2\nabla_{\mathbf{x}_t^{\mathbf{u}}}\log p_t(\mathbf{x}_t^{\mathbf{u}}) + \sigma(t)\mathbf{u}\left(\mathbf{x}_t^{\mathbf{u}}, t\right)\right)dt + \sigma(t)d\mathbf{w} \nonumber \\
    &= \left(-\mathbf{b}(\mathbf{x}_t^{\mathbf{u}}, t)+\sigma(t)^2\nabla_{\mathbf{x}_t^{\mathbf{u}}}\log p_t(\mathbf{x}_t^{\mathbf{u}}) + \sigma(t)^2 \nabla_{\mathbf{x}}\log \mathbb{E}_{\mathbb{P}} \left[p^{-\alpha(t)}_t\left(\mathbf{x}\right)\exp\left(\beta(t)r(\mathbf{x}_T)\right)| \mathbf{x}_t^{\mathbf{u}}=\mathbf{x}\right]\right)dt + \sigma(t)d\mathbf{w} \nonumber \\
    &= \left(-\mathbf{b}(\mathbf{x}_t^{\mathbf{u}}, t) + \sigma(t)^2 \nabla_{\mathbf{x}}\log \mathbb{E}_{\mathbb{P}} \left[p^{1-\alpha(t)}_t\left(\mathbf{x}\right)\exp\left(\beta(t)r(\mathbf{x}_T)\right)| \mathbf{x}_t^{\mathbf{u}}=\mathbf{x}\right]\right)dt + \sigma(t)d\mathbf{w} \nonumber \\
     &= \left(-\mathbf{b}(\mathbf{x}_t^{\mathbf{u}}, t) + \sigma(t)^2 \nabla_{\mathbf{x}}\log \mathbb{E}_{\mathbb{P}} \left[p_t^{\mathbf{u}}(\mathbf{x})| \mathbf{x}_t^{\mathbf{u}}=\mathbf{x}\right]\right)dt + \sigma(t)d\mathbf{w} \nonumber \\
\end{align}
\end{minipage}
}
where $p_t^{\mathbf{u}}(\mathbf{x}_t)$ denotes the annealed, reward-guided marginal density under $\mathbb{P}^{\mathbf{u}}$: $p_t^{\mathbf{u}}(\mathbf{x}_t)= p_t^{1-\alpha(t)}(\mathbf{x}_t)\exp(\beta(t)r(\mathbf{x}_T))$. Substituting this expression into the value function and optimal control above, we obtain:

\begin{align}
    \mathbf{u}^*\left(\mathbf{x}, t\right)=\sigma(t) \nabla_{\mathbf{x}}\log \mathbb{E}_{\mathbb{P}}\left[\frac{p_t^{\mathbf{u}}(\mathbf{x})}{p_t(\mathbf{x})}|\mathbf{x}_t = \mathbf{x}\right] \;\; \text{and} \;\;
    V\left(\mathbf{x}, t\right) =  -\log \mathbb{E}_{\mathbb{P}}\left[\frac{p_t^{\mathbf{u}}(\mathbf{x})}{p_t(\mathbf{x})}|\mathbf{x}_t = \mathbf{x}\right]
\end{align}
%
Proof completed.
%

\paragraph{Proposition 3.2}
%
\textit{
Given a traceable family of distributions $q \in \mathcal{Q}$, the value function in Proposition \ref{theo:cost-func} can be upper bounded:}
\begin{align}
    V(\mathbf{x}, t)  &\leq  \widetilde{V}(\mathbf{x}, t, q) \nonumber\\
    &= - \mathbb{E}_{\mathbf{x}_T \sim q_{T|t}(\mathbf{x}_T|\mathbf{x})}\left[\log\left(\frac{p_t^{\mathbf{u}}(\mathbf{x})}{p_t(\mathbf{x})}\right)|\mathbf{x}_t = \mathbf{x}\right] + D_{KL}\left(q(\mathbf{x}_T|\mathbf{x}_t) \| p(\mathbf{x}_T|\mathbf{x}_t)\right)|_{\mathbf{x}_t = \mathbf{x}} \nonumber\\
    &= \alpha(t)\log p_t(\mathbf{x}) - \beta(t) \mathbb{E}_{\mathbf{x}_T \sim q_{T|t}(\mathbf{x}_T|\mathbf{x})}\left[r(\mathbf{x}_T)|\mathbf{x}_t=\mathbf{x}\right] \nonumber\\
    &\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad + D_{KL}\left(q(\mathbf{x}_T|\mathbf{x}_t) \| p(\mathbf{x}_T|\mathbf{x}_t)\right)|_{\mathbf{x}_t=\mathbf{x}} \nonumber
\end{align}

\textit{Proof}: We begin by rewriting the value function in terms of the diffusion posterior $p(\mathbf{x}_T \mid \mathbf{x}_t)$, which denotes the terminal distribution evolved from $\mathbf{x}_t$ under the uncontrolled process $\mathbb{P}$.

\begin{align}
     &V\left(\mathbf{x}, t\right) =  -\log \mathbb{E}_{p(\mathbf{x}_T|\mathbf{x})}\left[\frac{p_t^{\mathbf{u}}(\mathbf{x})}{p_t(\mathbf{x})}|\mathbf{x}_t = \mathbf{x}\right] \nonumber \\
     &= -\log \int \frac{p_t^{\mathbf{u}}(\mathbf{x})}{p_t(\mathbf{x})} p(\mathbf{x}_T|\mathbf{x}) d\mathbf{x}_T, \;\;\;\; \textit{note: } p_t^{\mathbf{u}}(\mathbf{x}) \textit{ implicitly depends on } \mathbf{x}_T \nonumber \\
     &= -\log \int \frac{p_t^{\mathbf{u}}(\mathbf{x})}{p_t(\mathbf{x})} \frac{p(\mathbf{x}_T|\mathbf{x})}{q(\mathbf{x}_T|\mathbf{x})} q(\mathbf{x}_T|\mathbf{x}) d\mathbf{x}_T, \;\;\;\; \textit{where } q(\mathbf{x}_T|\mathbf{x}) \textit{ is a traceable simpler distribution}. \nonumber \\
    &= -\log \mathbb{E}_{q(\mathbf{x}_T|\mathbf{x})}\left[\frac{p_t^{\mathbf{u}}(\mathbf{x})}{p_t(\mathbf{x})} \frac{p(\mathbf{x}_T|\mathbf{x})}{q(\mathbf{x}_T|\mathbf{x})}|\mathbf{x}_t = \mathbf{x}\right] \nonumber \\
    &\leq - \mathbb{E}_{\mathbf{x}_T \sim q_{T|t}(\mathbf{x}_T|\mathbf{x})}\left[\log\left(\frac{p_t^{\mathbf{u}}(\mathbf{x})}{p_t(\mathbf{x})}\right)|\mathbf{x}_t = \mathbf{x}\right] + D_{KL}\left(q(\mathbf{x}_T|\mathbf{x}_t) \| p(\mathbf{x}_T|\mathbf{x}_t)\right)|_{\mathbf{x}_t = \mathbf{x}}, \textit{Jensen's inequality} \nonumber\\    
    &= \alpha(t)\log p_t(\mathbf{x}) - \beta(t) \mathbb{E}_{\mathbf{x}_T \sim q_{T|t}(\mathbf{x}_T|\mathbf{x})}\left[r(\mathbf{x}_T)|\mathbf{x}_t=\mathbf{x}\right] + D_{KL}\left(q(\mathbf{x}_T|\mathbf{x}_t) \| p(\mathbf{x}_T|\mathbf{x}_t)\right)|_{\mathbf{x}_t=\mathbf{x}} \nonumber \\
    &= \widetilde{V}(\mathbf{x}, t, q)
\end{align}
Proof completed.

\paragraph{Proposition 3.2}
%
\textit{
Let $p_{t|T}(\mathbf{x}_t|\mathbf{x}_T)=\mathcal{N}(\eta(t)\mathbf{x}_T, \gamma^2(t)I)$ denote the forward noising kernel, $p_{T|t}(\mathbf{x}_T|\mathbf{x}_t)$ the diffusion posterior, $\mathbf{s}_{\theta}\left(\mathbf{x}_t\right)$ the score model, $\mathcal{D}_t = \{\mathbf{x}_t^i\}_{i=0}^N$ the N-sample batch at the $t^{\text{th}}$ reverse timestep, $q_{T|t}(\mathbf{x}_T|\mathcal{D}_t)$ the Tweedie-based proposal distribution conditioned on $\mathcal{D}_t$, and $q^{\epsilon}_{T|t}(\mathbf{x}_T|\mathcal{D}_t)$ its update under a particle-based transform with stepsize $\epsilon$. Then, the optimal control $\widetilde{\mathbf{u}}^*(\mathbf{x}, t)$ for the surrogate value function $\widetilde{V}(\mathbf{x}, t, q)$ decomposes as:}
\begin{align}
    \frac{\widetilde{\mathbf{u}}^*(\mathbf{x}^i_t,t)}{\sigma(t)} &= \underbrace{\mathbb{E}_{\mathbf{x}^j_T \sim q_{T|t}(\mathbf{x}_T|\mathcal{D}_t)}\left[\left(\mathbf{s}_{\theta}\left(\mathbf{x}^j_T\right)-\eta(t)\mathbf{s}_{\theta}\left(\mathbf{x}^j_t\right)\right)k(\mathbf{x}^i_T, \mathbf{x}^j_T) + \nabla_{\mathbf{x}^j_T}k(\mathbf{x}^i_T, \mathbf{x}^j_T)| \mathcal{D}_t\right]}_{\textbf{Stein correction on } \mathcal{M}_T} \nonumber\\
    & \oplus \quad \underbrace{-\alpha(t) \mathbf{s}_{\theta}\left(\mathbf{x}^i_t\right) + \beta(t) \nabla_{\mathbf{x}^i_t}\mathbb{E}_{\mathbf{x}^i_T \sim q^{\epsilon}_{T|t}(\mathbf{x}_T|\mathcal{D}_t)}\left[r(\mathbf{x}^i_T)|\mathbf{x}^i_t\right]}_{\textbf{low-density guidance on } \mathcal{M}_t}
\end{align}

\textit{Proof}: From Lemma \ref{theo:soc}, we obtain the optimal controller corresponding to the surrogate value function:

\begin{align}
     &\frac{\widetilde{\mathbf{u}}^*(\mathbf{x}^i_t,t)}{\sigma(t)} = -\nabla_{\mathbf{x}^i_t} \widetilde{V}(\mathbf{x}^i_t, t, q) \nonumber \\
     &= \underbrace{-\nabla_{\mathbf{x}^i_t} D_{KL}\left(q(\mathbf{x}^i_T|\mathbf{x}^i_t) \| p(\mathbf{x}^i_T|\mathbf{x}^i_t)\right)}_{\textbf{I}} + \underbrace{-\alpha(t) \mathbf{s}_{\theta}\left(\mathbf{x}^i_t\right) + \beta(t) \nabla_{\mathbf{x}^i_t}\mathbb{E}_{\mathbf{x}^i_T \sim q_{T|t}(\mathbf{x}_T|\mathcal{D}_t)}\left[r(\mathbf{x}^i_T)|\mathbf{x}^i_t\right]}_{\textbf{II}}
\end{align}

where the first term (\textbf{I}) corresponds to the controller component that follows the gradient descent direction of the KL divergence between the approximate and true posteriors with respect to the current noisy state. The second term (\textbf{II}) captures low-density sampling and reward/property guidance based on predicted clean samples. Most existing training-free diffusion guidance methods focus solely on the second term while ignoring the first term. It thus makes them inherently suboptimal. Similar to most of standard training-free framework, we initialize the proposal distribution $q_{T|t}(\mathbf{x}_T|\mathbf{x})$ with its mean value estimated via Tweedie's formula $\frac{\mathbf{x}_t +\gamma^2(t) \mathbf{s}_{\theta}(\mathbf{x}_t, t)}{\eta(t)}$, assuming a forward perturbing kernel $p_{t|T}(\mathbf{x}_t | \mathbf{x}_T) = \mathcal{N}(\eta(t)\mathbf{x}_T, \gamma^2(t)I)$ at the $t^{th}$ timestep.  In this work, we propose a novel training-free guidance method, where the guidance direction is determined by both terms:

\textit{The KL divergence term} (\textbf{I}):
As the true posterior $p(\mathbf{x}^i_T|\mathbf{x}^i_t)$ does not admit a closed-form expression, we can not compute analytically the KL divergence and its gradient. To address this, we leverage the Stein variational inference, a nonparametric approach that identifies the steepest gradient direction to minimize the KL divergence. Assuming a batch of N particle samples at the $t^{th}$ diffusion timestep $\mathcal{D}_t = \{\mathbf{x}_t^i\}_{i=0}^N$, we apply Lemma \ref{theo:stein} to obtain the KSD's direction that minimizes $D_{KL}\left(q(\mathbf{x}^i_T|\mathbf{x}^i_t) \| p(\mathbf{x}^i_T|\mathbf{x}^i_t)\right)$:

\begin{align}
    \phi^*(\mathbf{x}^i_t)=\mathbb{E}_{\mathbf{x}^j_T \sim q_{T|t}(\mathbf{x}_T|\mathbf{x}_t)}[\nabla_{\mathbf{x}^j_t}\log p(\mathbf{x}^j_T|\mathbf{x}_t^j)k(\mathbf{x}^i_T, \mathbf{x}^j_T) + \nabla_{\mathbf{x}^j_t}k(\mathbf{x}^i_T, \mathbf{x}^j_T)] \nonumber
\end{align}

Computing this direction requires numerous Jacobian-vector product evaluations, including $\nabla_{\mathbf{x}^j_T}\log p(\mathbf{x}^j_T|\mathbf{x}_t^j)\frac{\partial \mathbf{x}_T^j}{\partial \mathbf{x}_t^j}$ and $\nabla_{\mathbf{x}^j_T}k(\mathbf{x}^i_T, \mathbf{x}^j_T)\frac{\partial \mathbf{x}_T^j}{\partial \mathbf{x}_t^j}$, which is computationally expensive as the number of particles $N$ increases. To alleviate this computational burden, we propose \textit{a back-and-forth correction trick}: 
\begin{itemize}
    \item Apply Tweedie's formula to map the particle set $\mathcal{D}_t = \{\mathbf{x}_t^i\}_{i=0}^N$ on $\mathcal{M}_t$ backward to $\mathcal{D}_T \leftarrow \left\{ \mathbf{x}_T^i | \mathbf{x}_T^i=\frac{\mathbf{x}_t^i +\gamma^2(t) \mathbf{s}_{\theta}(\mathbf{x}_t^i)}{\eta(t)}, \forall \mathbf{x}_t^i \in \mathcal{D}_t\right\}$ on $\mathcal{M}_T$, which represents the initial proposal distribution $q_{T|t}(\mathbf{x}_T|\mathcal{D}_t)$.
    \item Apply the Stein correction on $\mathcal{D}_T$, which results in an updated distribution $q^{\epsilon}_{T|t}(\mathbf{x}_T|\mathcal{D}_t)$ 
    \item Apply the noising kernel $p_{t|T}(\mathbf{x}_t | \mathbf{x}_T) = \mathcal{N}(\eta(t)\mathbf{x}_T, \gamma^2(t)I)$ to map the Stein-corrected particles on $\mathcal{M}_T$ forward to $\mathcal{M}_t$.
\end{itemize}

At the second step, the Stein correction applies a particle-based transform on the particle set $\mathcal{D}_T$ and follows the KSD's direction, given as:

\begin{align}
    \phi^*(\mathbf{x}^i_T)=\mathbb{E}_{\mathbf{x}^j_T \sim q_{T|t}(\mathbf{x}_T|\mathcal{D}_t)}[\nabla_{\mathbf{x}^j_T}\log p(\mathbf{x}^j_T|\mathbf{x}^j_t)k(\mathbf{x}^i_T, \mathbf{x}^j_T) + \nabla_{\mathbf{x}^j_T}k(\mathbf{x}^i_T, \mathbf{x}^j_T)|\mathcal{D}_t] \nonumber
\end{align}

Our Stein correction only requires the data score $\nabla_{\mathbf{x}^j_T}\log p(\mathbf{x}^j_T|\mathbf{x}^j_t)$, which is analytically computed:

\begin{align}
    \nabla_{\mathbf{x}^j_T}\log p(\mathbf{x}^j_T|\mathbf{x}^j_t) &= \nabla_{\mathbf{x}^j_T}\log p(\mathbf{x}^j_t|\mathbf{x}^j_T) + \nabla_{\mathbf{x}^j_T}\log p(\mathbf{x}^j_T) \nonumber \\
    &= -\eta(t)\frac{\mathbf{x}^j_t - \eta(t)\mathbf{x}^j_T}{\gamma^2(t)} + \mathbf{s}_{\theta}\left(\mathbf{x}^j_T\right) \nonumber \\
    &= -\eta(t)\frac{z}{\gamma(t)} + \mathbf{s}_{\theta}\left(\mathbf{x}^j_T\right)  \nonumber \\
    &= -\eta(t)\frac{z}{\gamma(t)} + \mathbf{s}_{\theta}\left(\mathbf{x}^j_T\right) \nonumber \\
    & = -\eta(t)\mathbf{s}_{\theta}\left(\mathbf{x}^j_t\right) + \mathbf{s}_{\theta}\left(\mathbf{x}^j_T\right) \nonumber
\end{align}

The KSD's direction can be rewritten as:

\begin{align}
    \label{theo:app1}
    \phi^*(\mathbf{x}^i_T)=\mathbb{E}_{\mathbf{x}^j_T \sim q_{T|t}(\mathbf{x}_T|\mathcal{D}_t)}[(-\eta(t)\mathbf{s}_{\theta}(\mathbf{x}^j_t) + \mathbf{s}_{\theta}(\mathbf{x}^j_T))k(\mathbf{x}^i_T, \mathbf{x}^j_T) + \nabla_{\mathbf{x}^j_T}k(\mathbf{x}^i_T, \mathbf{x}^j_T)|\mathcal{D}_t]
\end{align}

The particle update is given by:

\begin{align}
    \mathbf{x}^i_T = \mathbf{x}^i_T + \epsilon(t)*\phi^*(\mathbf{x}^i_T) \nonumber
\end{align}

\textit{The low density reward guidance term} (\textbf{II}):  We use the Stein-corrected particle-based proposal distribution $q^{\epsilon}_{T|t}(\mathbf{x}_T|\mathcal{D}_t)$ to guide the corresponding particles on $\mathcal{M}_t$ toward low-density regions with high rewards or desired properties:

\begin{align}
    \label{theo:app2}
    -\alpha(t) \mathbf{s}_{\theta}\left(\mathbf{x}^i_t\right) + \beta(t) \nabla_{\mathbf{x}^i_t}\mathbb{E}_{\mathbf{x}^i_T \sim q^{\epsilon}_{T|t}(\mathbf{x}_T|\mathcal{D}_t)}\left[r(\mathbf{x}^i_T)|\mathbf{x}^i_t\right]
\end{align}

where the noisy sample $\mathbf{x}^i_t$ on $\mathcal{M}_t$ corresponds to its predicted clean version $\mathbf{x}^i_T$ on $\mathcal{M}_T$ via Tweedie's formula.

From Equations \ref{theo:app1} and \ref{theo:app2}, we conclude the proof. 

\section{Experimental details}
\subsection{Metric value normalization}
For ease of training and evaluation, we normalize the synthetic accessibility score (\textbf{SA}) and the docking score (\textbf{DS}) between $0$ and $1$ as follows:

\begin{align}
    &\hat{\textbf{SA}} = \frac{10 - \textbf{SA}}{9} \quad
    &\hat{\textbf{DS}} = \frac{\textbf{DS}}{\min(\textbf{DS}_{train}) - 0.2} \nonumber
\end{align}

\subsection{Stepsize and annealing schedules}
\paragraph{Stein correction stepsize} We utilize an adaptive stepsize schedule $\epsilon(t)$ similar to the corrector framework from \citet{song2020score}, which is defined as:

\begin{align}
     \epsilon(t) = 2 \eta^2(t) \left(snr \|\mathbf{z}\|_2/\|\mathbf{g}\|_2\right)^2
\end{align}
% in the continuous framework \eta^2(t) = \alpha_i in the discrete vpsde framework and \eta^2(t)=1 for vesde framework.
% \begin{align}
%      \epsilon(t) =  \left\{ \begin{array}{rl} 2\alpha_t \left(r \|\mathbf{z}\|_2/\|\mathbf{g}\|_2\right)^2& \text{VPSDE} \\ 2 \left(r \|\mathbf{z}\|_2/\|\mathbf{g}\|_2\right)^2 & \text{VESDE} \end{array}\right.
% \end{align}
where $snr$ denotes the signal-to-noise ratio, and $\mathbf{g}= \mathbf{s}_{\theta}\left(\mathbf{x}^j_T\right)-\eta(t)\mathbf{s}_{\theta}\left(\mathbf{x}^j_t\right)$, assuming a forward noising kernel as $p_{t|T}(\mathbf{x}_t | \mathbf{x}_T) = \mathcal{N}(\eta(t)\mathbf{x}_T, \gamma^2(t)I)$.

\paragraph{Annealing schedules} For the low-density sampling, we experiment on two scheduling methods: \textit{constant} and \textit{linear}.

\begin{align}
     \alpha(t) =  \left\{ \begin{array}{rl}  \alpha_{\textit{max}}, & \textit{constant}\\ t\times\alpha_{\textit{max}}, &  \textit{linear}\end{array}\right.
\end{align}

For the guidance strength, we adopt the Polyak stepsize method  \cite{hazan2019revisiting, shen2024understanding}:

\begin{align}
     \beta(t) = \beta_{\textit{max}} \times \frac{\|s_{\theta}(\mathbf{x}_t)\|}{\|\nabla_{\mathbf{x}_t}r(\mathbf{x}_T)\|}
\end{align}

\subsection{Pretrained molecular graph models}
%
\citet{jo2022score} introduced a continuous-time score-based diffusion framework for modeling graph distributions via a system of score-based networks. Given a graph representation $\mathcal{G} = (\mathbf{X}, \mathbf{E})$, where $\mathbf{X}$ and $\mathbf{E}$ denote the node feature matrix and edge matrix, respectively, they define a score-based model for each node and edge component: $s_{\theta}(\mathbf{X}_t, \mathbf{E}_t) \approx \nabla_{\mathbf{X}_t} \log p(\mathbf{X}_t, \mathbf{E}_t)$ and $s_{\phi}(\mathbf{X}_t, \mathbf{E}_t) \approx \nabla_{\mathbf{E}_t} \log p(\mathbf{X}_t, \mathbf{E}_t)$. Building on this framework, \citet{lee2023exploring} proposed a standard classifier-based diffusion guidance method for conditional molecular sampling in out-of-distribution settings. In our experiments, we use the same pretrained model and hyperparameters as \citet{lee2023exploring}.
Specifically, we model the node component using a Variance Preserving SDE (VPSDE) and the edge component using a Variance Exploding SDE (VESDE). In sampling, we adopt the predictor-corrector sampling framework, with the reverse SDE as the predictor and annealed Langevin dynamics as the corrector. As reported in \citet{jo2022score} (Table 12), the pretrained model tends to generate molecules with very low validity when using either the predictor or corrector framework alone.

\subsection{Regressor pretraining on clean data}
%
We pre-train our molecular property predictors on clean (i.e., noise-free) molecular data of ZINC250k, where the target property is defined as the product of the normalized scores: $\hat{\textbf{SA}} \times \hat{\textbf{DS}}$. Since most training molecules satisfy the $\textbf{QED}$ hit condition, we thus ignore this target to simplify our multi-objective optimization task. Our regressor architecture is similar to the one from \citet{lee2023exploring} with an additional graph convolution layer. We set the learning rate to $0.01$, the number of epochs to $10$, the AdamW optimizer \cite{loshchilov2018decoupled}, and utilize the same architecture hyperparameters for all target proteins. 

\subsection{Hardware usage}
%
All experiments are conducted on a single NVIDIA Titan RTX GPU with 8 CPU cores, using a Slurm-managed high-performance computing (HPC) system.

