\section{Multipole moments in the Zipoy-Voorhees spacetime} \label{app:multipole_moments}
%-----------------------------------------------------------------%
The relativistic and coordinate-invariant definitions of multipole moments in general relativity have been proposed by Geroch~\cite{Geroch:1970cd}, Hansen~\cite{Hansen:1974zz}, Thorne~\cite{Thorne:1980ru}, and Beig and Simon~\cite{Beig:1981}. Algorithms to calculate the multipole moments have been developed, for example, by Fodor, Hoenselaers, and Perj\'{e}s~\cite{Fodor:1989}. In this appendix, we present the calculation of the multipole moments in the ZV spacetime using a method proposed by Hoenselaers~\cite{Hoenselaers:1986gcr} and summarized more practically by Quevedo~\cite{Quevedo:1989rfm}.

Let us start by considering the Ernst potentials~\cite{Ernst:1967by}, $E$ and $\xi$, in the ZV spacetime:
\begin{align}
    E = \mathrm{e}^{2\Phi} = \left( \frac{x-1}{x+1} \right)^\gamma, \quad \xi = \frac{1-E}{1+E},
\end{align}
where we have used the prolate spheroidal coordinates. Introducing the inverse Weyl coordinate $\tilde{z}$ as
\begin{align}
    \tilde{z} = \frac{1}{z} = \frac{1}{l x y},
\end{align}
the Ernst potentials are  rewritten as
\begin{align}
    E(\tilde{z},y) = \left( \frac{1-l y \tilde{z}}{1+l y \tilde{z}} \right)^\gamma, \quad \xi(\tilde{z},y) = \frac{1-E(\tilde{z},y)}{1+E(\tilde{z},y)}. \label{Ernst_potentials}
\end{align}

Hoenselaers showed that, particularly in the static case, the mass multipole moments $M_n$ can be calculated by
\begin{align}
    M_n = m_n + d_n \quad (n=0,1,2,\ldots), \label{eq:multipole_cal}
\end{align}
where the first term $m_n$ can be obtained
\begin{align}
    m_n = \left. -\frac{h_{n+1}}{(n+1)!} \right|_{y=1, \tilde{z}=0}, \label{eq:m_n}
\end{align}
with the simple recurrence formula for $h_n$:
\begin{align}
    h_1 = \frac{1}{2 E} \dv{E}{\tilde{z}}, \quad h_n = \dv{h_{n-1}}{\tilde{z}} + 2 \xi h_1 h_{n-1} \ (\text{for} \ n \geq 2), \label{recurrence_formula}
\end{align}
while the second term $d_n$ in Eq.~\eqref{eq:multipole_cal} is determined by comparing Eq.~\eqref{eq:multipole_cal} with the original Geroch-Hansen definition (see also~\cite{Fodor:1989}). It can be written in terms of $m_n$, for example
\begin{align}
    d_0 &= d_1 = d_2 = d_3 = 0, \quad d_4 = -\frac{1}{7} A_{2,0} m_0, \quad d_5 = -\frac{1}{21} A_{2,0} m_1 - \frac{1}{3} A_{3,0} m_0, \label{eq:def_d_1} \\[8pt]
    d_6 &= \frac{1}{33} A_{2,0} m_0^{3} - \frac{5}{231} A_{2,0} m_2 - \frac{4}{33} A_{3,0} m_1 - \frac{8}{33} A_{3,1} m_0 - \frac{6}{11} A_{4,0} m_0, \label{eq:def_d_2}
\end{align}
where we have introduced the convenient notation
\begin{align}
    A_{i,j} := m_i m_j - m_{i-1} m_{j+1}.
\end{align}

Substituting Ernst potentials $E$ and $\xi$ \eqref{Ernst_potentials} into Eq.~\eqref{recurrence_formula}, we can determine $h_n$. Then, using the obtained $h_n$ and Eq.~\eqref{eq:m_n}, $m_n$ up to $n=6$ can be obtained as follows:
\begin{align}
    m_0 &= l \gamma, \quad m_2 = \frac{l^3}{3} \gamma \left( 1-\gamma^2 \right), \quad
    m_4 = \frac{l^5}{15} \gamma \left( 3-5 \gamma^2 + 2 \gamma^4 \right), \\[8pt]
    m_6 &= \frac{l^7}{315} \gamma \left( 45 -98 \gamma^2 +70 \gamma^4 -17 \gamma^6 \right), \quad m_1=m_3=m_5=0.
\end{align}
Finally, using the obtained $m_n$ and Eqs.~\eqref{eq:multipole_cal},~\eqref{eq:def_d_1}, and~\eqref{eq:def_d_2}, we can get the multipole moments in the ZV spacetime up to $n=6$ (see e.g.~\cite{Herrera:2004fg}):
\begin{subequations}
\begin{align}
    M_0 &= l \gamma, \label{eq:multipole_moment_m0} \\[8pt]
    M_2 &= \frac{l^3}{3} \gamma \left(1-\gamma^2\right), \\[8pt]
    M_4 &= \frac{l^5}{5} \gamma (1-\gamma^2) \left(1-\frac{19}{21} \gamma^2 \right), \\[8pt]
    M_6 &= \frac{l^7}{7}\gamma (1-\gamma^2) \left( 1 - \frac{292}{165} \gamma^2 + \frac{389}{495} \gamma^4 \right), \label{eq:multipole_moment_m6} \\[8pt]
    M_1&=M_3=M_5=0.
\end{align} \label{eq:multipole_moment}
\end{subequations}
Introducing the ADM mass $M=l \gamma$, we can rewrite Eqs.~\eqref{eq:multipole_moment_m0}-\eqref{eq:multipole_moment_m6} as
\begin{subequations}
\begin{align}
    M_0 &= M, \label{ZV_monopole} \\[8pt]
    M_2 &= -\frac{M^3}{3} \left( 1 - \frac{1}{\gamma^2} \right), \label{ZV_quadrupole} \\[8pt]
    M_4 &= \frac{M^5}{5} \left( 1 - \frac{1}{\gamma^2} \right) \left( \frac{19}{21} - \frac{1}{\gamma^2}  \right), \\[8pt]
    M_6 &= -\frac{M^7}{7} \left( 1 - \frac{1}{\gamma^2} \right) \left( \frac{389}{495} - \frac{292}{165} \frac{1}{\gamma^2} + \frac{1}{\gamma^4}  \right).
\end{align}
\end{subequations}
For the Schwarzschild case $\gamma=1$, all multipole moments except the monopole moment obviously vanish. Note that taking the CC limit $\gamma \rightarrow \infty$, they reproduce the multipole moments in the CC spacetime (see e.g.~\cite{Herrera:2004fg}):
\begin{align}
    M_0 &= M, \quad M_2 = -\frac{1}{3} M^3, \quad M_4 = \frac{19}{105} M^5 , \quad M_6 = -\frac{389}{3465} M^7.
\end{align}

