 \section{Appendix}\label{secAppendix}

\subsection{Squared Hamiltonian}\label{sec:squared}

In our previous works \cite{Naumis2021, Naumis2022, Naumis2023,NN2024,Navarro-Labastida_2025}, we demonstrated that squaring the Hamiltonian $\mathcal{H}$ allows us to simplify it into a $2 \times 2$ matrix that we call the squared Hamiltonian  $H^{2}$,
\begin{equation}\label{eq:H2}
\begin{split}
&H^{2}=\\
&\begin{pmatrix} -\nabla^{2}+\alpha^{2}(\bm{A}^{2}+\Delta)&  \alpha (-2i\bm{A}\cdot\nabla +\bm{B}) \\
 \alpha (-2i\bm{A}^{*}\cdot\nabla +\bm{B}^{*}) & -\nabla^{2}+\alpha^{2}(\bm{A}^{2}-\Delta) 
  \end{pmatrix} 
  \end{split} 
  \end{equation}
where we defined, 
\begin{equation}
 \begin{split}
\bm{A}&=\sum_{\nu=1}^{3}e^{-i\bm{q}_{\nu}\cdot\bm{r}}\bm{q}_{\nu}^{\perp}.\\
  \end{split} 
\end{equation}
$\bm{A}$ is a pseudo-magnetic vector potential with $C_3$ symmetry and $\bm{A}^{2}=|\bm{A}|^{2}$.  The squared norm of the coupling potential is an effective intralayer confinement potential,
\begin{equation}
\begin{split}
|U(\pm\bm{r})|^{2} &= \bm{A}^{2}\mp \Delta
\end{split}
\end{equation}
where the confinement potential $|U(\pm\bm{r})|^{2}$ is separated into its purely symmetric $\bm{A}^2(\bm{r})$ and anti-symmetric $\Delta(\bm{r})$ parts defined as, 

\begin{equation}
\begin{split}
\bm{A}^2(\bm{r})= 3-\sum_{\nu=1}^{3}\cos{(\bm{b}_{\nu}\cdot\bm{r})}\\
\Delta(\bm{r})=\sqrt{3}\sum_{\nu}(-1)^{\nu}\sin{(\bm{b}_{\nu}\cdot\bm{r})}
\label{eq:potentials_s_anti}
\end{split}
\end{equation}
where,
\begin{equation}
    \Delta(\bm{r})=i[A_x,A_y].
\end{equation}
$A_x$ and $A_y$ are the non-Abelian components of the $SU(2)$ pseudo-magnetic vector potential (See Appendix A). It is important to remark that the pseudo-magnetic vector potential satisfies the relation $\gradient\cdot\bm{A}=0$, and thus is a Coulomb gauge invariant field and $\gradient\times\bm{A}=\bm{B}$ (layer 1) and $\gradient\times\bm{A}^{*}=\bm{B}^{*}$  (layer 2).
The magnetic field is given by,
\begin{equation}
    \bm{B}=-i \sum_{\nu=1}^{3}e^{-i\bm{q}_{\nu}\cdot\bm{r}}\bm{e}_z
\end{equation}
where we have used the identity $\bm{e}_z=\bm{q}_{\nu}\times\bm{q}^{\perp}_{\nu}$ and $\bm{e}_z$ is a unit vector in the direction perpendicular to the graphene's plane. The squaring of the chiral TBG model is akin to a supersymmetric transformation \cite{DikiMatsumoto2023, Hatsugai2020, TomonariMizoguchi2022, Yoshida2021,2023Mizoguchi}.\\


\subsection{Quantum Metric: Marzari-Vanderbilt} \label{Sec: Marzari-Vanderbilt}

For clarity, in this appendix we drop any band indexes attached to the wavefunctions, later on they will be restored. Based on the infinitesimal Bures distance \cite{2024Abdiel},
\begin{equation}
\begin{split}\label{eq:bures}
D^{2}_{12}=1-|\langle\partial_{\mu}\Psi(\bm{k})|\Psi(\bm{k}+d\bm{k})\rangle|^{2}
\end{split}
\end{equation}
and using the Taylor expansion in the infinitesimal wavefunction,

\begin{equation}
\begin{split}\label{eq:taylor}
|\Psi(\bm{k}+d\bm{k})\rangle &\approx |\Psi(\bm{k}))\rangle+ \sum_{\alpha}|\partial_{\alpha}\Psi(\bm{k})\rangle d\bm{k}_{\alpha}\\
&+ \frac{1}{2}\sum_{\alpha,\beta}|\partial_{\beta}\partial_{\alpha}\Psi(\bm{k})\rangle d\bm{k}_{\alpha}d\bm{k}_{\beta}
\end{split}
\end{equation}
introducing Eq. (\ref{eq:taylor}) into Eq. (\ref{eq:bures}) and keeping terms up to the second order, it follows that,

\begin{equation}
\begin{split}\label{eq:Bure_metric}
D^{2}_{\bm{k},\bm{k}+d\bm{k}}=\sum_{\alpha,\beta}g_{\alpha,\beta}(\bm{k})d\bm{k}_{\alpha}d\bm{k}_{\beta}
\end{split}
\end{equation}
where we have the quantum metric tensor, also called the Fubini-Study metric \cite{2024Abdiel}, 
\begin{equation}
\begin{split}\label{eq:fubini-study}
g_{\alpha,\beta}(\bm{k})&=Re(\langle\partial_{\alpha}\Psi(\bm{k})|\partial_{\beta}\Psi(\bm{k})\rangle\\
&-\langle\partial_{\alpha}\Psi(\bm{k})|\Psi(\bm{k})\rangle\langle\Psi(\bm{k})|\partial_{\beta}\Psi(\bm{k})\rangle)
\end{split}
\end{equation}
By using the projector
\begin{equation}
\begin{split}\label{eq:Qmu}
Q_{\bm{k}}=1-|\Psi(\bm{k})\rangle\langle\Psi(\bm{k})|
\end{split}
\end{equation}

the quantum geometric tensor is re-expressed as, 
\begin{equation}
\begin{split}\label{eq:gmunu}
\bm{g}_{\alpha,\beta}(\bm{k})=Re(\langle\partial_{\alpha}\Psi(\bm{k})|Q_{\bm{k}}|\partial_{\beta}\Psi(\bm{k})\rangle)
\end{split}
\end{equation}
where $\partial_{\alpha}=\partial/\partial_{\bm{k}_{\alpha}}$.

In calculating the matrix tensor, we take the difference between one wavefunction and its neighbors, through the projection operator $Q_{\bm{k}}=1-|\Psi(\bm{k})\rangle\langle\Psi(\bm{k})|$, this difference is projected into the orthogonal subspace of $|\Psi(\bm{k})\rangle$. Then the sum of the trace of the metric tensor measures the intrinsic homogeneity of the underlying Hilbert space and the trace of the metric tensor at each value of $\bm{k}$ measures the degree of mismatch between the neighboring Bloch subspaces $\bm{k}$ and $\bm{k} + \bm{q}$, for $\bm{q}$ a small change in momentum $\bm{k}$, i.e., $\bm{q}=\Delta \bm{k}\rightarrow0$.

