	\\
	&\quad - \frac{1}{|\Theta|} \ a(V,N) \int_{\Theta} u_0(\vartheta')\vartheta'd\vartheta'\cdot(\frac{ \gamma_1}{K_N}\nabla N+\frac{\gamma_2}{K_V}\nabla V \big)\bigg].\label{3}
