\end{equation}
which means $u_0$ depends on the constant speed $s$.
\\ Now let us consider equation \eqref{3}. Using \eqref{u0} we get
\begin{align}\label{epsilon1-eqn-simplified}
	\nabla_x \cdot (\vartheta u_0)&= \eta_0(x)\bigg[\frac{1}{|\Theta|} U_1(t,x)-u_1(t,x,\vartheta)+a(V,N)\big(\frac{ \gamma_1}{K_N}  \vartheta \cdot \nabla N+\frac{\gamma_2}{K_V}  \vartheta \cdot \nabla V\big) u_0\bigg]
\end{align}
and therefore, as e.g. in \cite{engwer2015glioma,painter2013mathematical} we have the compact Hilbert-Schmidt operator
\begin{equation*}
	\begin{aligned}
		\mathcal{L}_u[\eta_0(x)]u_1&=-\eta_0(x)u_1+\frac{1}{|\Theta|}\eta_0(x)U_1\\
		&=\nabla_x \cdot (\vartheta u_0)-a(V,N)\big(\frac{ \gamma_1}{K_N}  \vartheta \cdot \nabla N+\frac{\gamma_2}{K_V}\vartheta \cdot \nabla V\big) u_0\
	\end{aligned}
\end{equation*}
defined on the $L^2$ space. We
can therefore calculate its pseudo-inverse to get an expression for $u_1$ :
\begin{equation}\label{5buruli2} u_1=-\frac{1}{\eta_0(x)}\nabla_x\cdot (\vartheta u_0)+a(V,N)(\frac{ \gamma_1}{K_N}  \vartheta \cdot \nabla N+\frac{\gamma_2}{K_V}\vartheta \cdot\nabla V)u_0\end{equation} 

\noindent Again by using \eqref{5buruli2} in \eqref{epsilon1-eqn-simplified}, we get
\begin{equation}\label{u1}
	U_1=0.
\end{equation}
Integrating \eqref{4} with respect to $\vartheta$, we get the macroscopic equation for bacteria as:
%$$ \begin{array}{lll}\partial_t u_0&+&\nabla_x\int_{\theta}(\vartheta u_1)d\vartheta= 
	%\\
	%& &
	%\\
	%& & \left[\begin{array}{lll} \eta_0(x)a(v,n)(\gamma_1\partial_t n+\gamma_2\partial_t v)\left[u_0-s_n^{\sigma}\frac{1}{s_n^{\sigma}}u_0\right]
	%\\
	%+\frac{\eta_0(x)}{2}\left[a^2(v,n)\vartheta^2((\gamma_1\nabla n)^2+(\gamma_2\nabla v)^2)u_0(\vartheta')\left(1-s_n^{\sigma}\frac{1}{s_n^{\sigma}}\right)d\vartheta'\right]
	%\\
	%+\eta_0(x)a(v,n)\left[\vartheta (\gamma_1\nabla n+\gamma_2\nabla v)u_1 d\vartheta(1-s_n^{\sigma}\frac{1}{s_n^{\sigma}}\right]
	%\\
	%+\eta_0(x)\left[-u_2(t,x)+u_2(t,x)s_n^{\sigma}\frac{1}{s_n^{\sigma}}\right]+\mu_u(u_0,v,n)u_0.\end{array}\right]\end{array}$$

	%Hence we get the macroscopic equation for M. Ulcerans as
	\begin{equation}\label{6}\partial_t U_0+\int_{\Theta}\nabla_x\cdot(\vartheta u_1)d\vartheta=\mu_u(U_0,V,N) U_0.\end{equation}
	To compute the integral on left-hand side, by using \eqref{5buruli2} we have 
	\begin{equation}
\begin{aligned}
	\int_{\Theta}\nabla_x\cdot(\vartheta u_1)d\vartheta&=\int_{\Theta}\nabla_x \cdot  \left[ \vartheta \bigg(-\frac{1}{\eta_0(x)}\nabla_x \cdot (\vartheta u_0)+a(V,N )(\frac{ \gamma_1}{K_N} \vartheta \cdot \nabla N+\frac{\gamma_2}{K_V}\vartheta \cdot \nabla V )u_0\bigg)\right]d\vartheta\\[5pt]
	&=\nabla_x \cdot \big[ \int_{\Theta}-\frac{1}{\eta_0(x)}\vartheta \otimes \vartheta\nabla_x (\frac{1}{|\Theta|}U_0)d\vartheta\big]\\[5pt]
	&\quad + \nabla_x \cdot\big[ \frac{a(V,N) }{|\Theta|} \int_{\Theta} \vartheta\otimes \vartheta d\vartheta (\frac{ \gamma_1}{K_N}\nabla N+\frac{\gamma_2}{K_V} \nabla V ) U_0 \big]
	\\[5pt]
	&=-\nabla \cdot (\mathbb{D}_{u}\nabla U_0)+\nabla \cdot \big(\chi_a(V,N)(\frac{ \gamma_1}{K_N}\nabla N+\frac{\gamma_2}{K_V} \nabla V)U_0\big)
\end{aligned}
\end{equation}
where $\mathbb{D}_{u}:=\frac{s^2}{d\eta_0(x)}\mathbb{I}_d$, $\chi_a(V,N):=\frac{s^2 a(V,N)}{d}\mathbb{I}_d=a(V,N)\eta_0(x)\mathbb{D}_{u}.$ 
\\ \\
Therefore, the macroscopic equation for bacteria is obtained as 
\begin{equation}\label{13}
\partial_t U_0-\nabla\cdot (\mathbb{D}_{u}(x) \nabla U_0)+\nabla\cdot(\chi_a(V,N)(\frac{ \gamma_1}{K_N}\nabla N+\frac{\gamma_2}{K_V} \nabla V)U_0)
= \mu_u(U_0,V,N)U_0.
\end{equation} \normalsize \\ Here, we take the growth rate as $$\mu_u(U_0,V,N)=\alpha_u\frac{N}{K_N+N}\left(1-\frac{U_0}{K_U}-\frac{V}{K_V}-\frac{N}{K_N}\right),$$
where $\alpha_u>0$ is the proliferation rate of bacteria and $K_U >0$ is the carrying capacity for the bacteria. We consider a logistic growth slowed down by the competition for space between bacteria, normal tissue, and necrotic matter. There is also a growth enhancement factor that depends on necrotic matter for bacteria dynamics, as mentioned in \cite{palomino1998effect}.\\[-2ex]

\noindent
The above macroscopic equation for bacteria density is coupled with macroscopic equations describing the dynamics of mycolactone, normal tissue, and necrotic matter. Hence we get the following system:
\begin{equation}
	\label{14}
	\begin{aligned}
		\partial_t U&=\nabla \cdot (\mathbb{D}_{u}(x) \nabla U)-\nabla \cdot \big(\chi_a(V,N)(\frac{ \gamma_1}{K_N}\nabla N+\frac{\gamma_2}{K_V}\nabla V)U\big)  
		\\
		&\quad \quad  +\alpha_u\frac{N}{K_N+N}U\left(1-\frac{U}{K_U}-\frac{V}{K_V}-\frac{N}{K_N}\right) , \quad \quad   t>0, \ x \in  \Omega,
		\\
		\partial_t M &= D_m \Delta M+{\delta} \frac{U}{K_U+U}-\lambda M , \quad \quad   t>0, \ x \in  \Omega,
		\\
		\partial_t V &= -\beta_1 V \frac{M}{K_M} , \quad \quad   t>0, \ x \in  \Omega,
		\\
		\partial_t N &= \beta_2 \frac{V}{K_V} \frac{M}{K_M}-\gamma N,  \quad \quad   t>0, \ x \in  \Omega,
	\end{aligned}
\end{equation}
\\
where $D_m, \ \delta, \ K_M, \ \lambda, \  \beta_1 , \ \beta_2 , \ \gamma$ are positive constants, and $\Omega\subset \R^d$ is a bounded, sufficiently smooth domain.\\[-2ex]

\noindent
The evolution of mycolactone is governed by the second equation in the system (\ref{14}), where diffusion serves as the primary mechanism driving its spread. Bacteria release mycolactone, which diffuses into wounds and surrounding tissues, causing necrosis. Over time, mycolactone degrades, altering its concentration profile.
\\[-2ex]

\noindent
The third equation in (\ref{14}) describes the dynamics of normal tissue, capturing its necrotisation by the action of mycolactone on it. The fourth equation focuses on necrotic tissue, featuring its natural decay and the ongoing necrotisation of adjacent healthy tissue.
\\[-2ex]

\noindent The above parabolic upscaling was actually performed with $x\in \R^d$. Going down to $\Omega $ and obtaining no-flux boundary conditions can be done (at least informally) similarly to \cite{plaza}, yielding
\begin{equation}\label{*_}
	\left(\mathbb{D}_{u}(x) \nabla U+\chi_a(V,N)(\frac{ \gamma_1}{K_N}\nabla N+\frac{\gamma_2}{K_V} \nabla V)U\right)\cdot \nu=0, \quad \nabla M\cdot \nu=0.
\end{equation} 
For the initial conditions we take
\begin{equation}\label{*-*}
	U(0,x)=u_0, \ V(0,x)=v_0, \ N(0,x)=n_0, \ M(0,x)=m_0, \ x \in  \Omega.
\end{equation}
\noindent
The obtained PDE for bacteria dynamics features double haptotaxis and Fickian diffusion, with a space-dependent diffusion tensor $\mathbb D_u$, which is also present in the tactic sensitivity function $\chi_a$. It depends on the average cell speed (squared) and is inversely proportional to the space dimension and the turning rate. In \cite{conte2021mathematical,conte2023mathematical,corbin2021modeling,engwer2015glioma,engwer2016effective,kumar2021multiscale,mohanan2024mathematicalmodeltissueregeneration} the parabolic upscaling from KTEs led to myopic diffusion, with the corresponding tensor depending on the orientation distribution of tissue fibers. Here the simpler choice of the turning kernel leads to omission of the supplementary drift with velocity $\nabla \cdot \mathbb D_u$.

	\subsection{Approach via random position jumps}\label{subsec:PJA}

	\noindent
	In this subsection we deduce a continuous, macroscopic PDE for bacteria dynamics by an alternative approach, namely assuming that cells are particles jumping with certain probabilities between the sites of a lattice, as developed, e.g., in \cite{randomjumpKPH, randomjumpSAO}. We will use the notations $u,m,v,n$ for the (macroscopic) volume fractions of bacteria, mycolactone, normal and necrotic tissue, respectively. As the informal approach is rather standard, we only sketch the deduction in the 1D case, for convenience. \\[-2ex]

	\noindent
	Imagine a 1D lattice with nodes $x_i$ and a particle (bacterium)  jumping from one node to its neighbours or resting at its current position (node).  We are interested in $u_i(t)$, the probability of finding a particle at $x_i$ at time $t$. Let $h$ and $\Delta t$ denote the lengths of space and time steps, respectively. Let $T_i^{\pm}$ denote the probabilities of jumping to the right (+) or to the left (-), respectively. Then we have
	\\
	\begin{equation}\label{u_i}
		u_i(t+\Delta t) = \bigg(T_{i-1}^+ u_{i-1}(t) +T_{i+1}^- u_{i+1}(t)\bigg) \Delta t + \bigg(1-\Delta t (T_i^+ +T_i^-)\bigg) u_i (t).
	\end{equation}
	\noindent
	When deciding to move, a cell 'tests' its environment by comparing - via cell receptors- the amount of haptoattractants (normal tissue and necrotic matter) at its current and at neighboring locations. Therefore, the jump probability per unit time typically depends on the amount of necrotic matter and normal tissue, as well as on the cell density. Thus, we define $ T_i^{\pm}$ as:
	\begin{equation*}
		T_i^{\pm}(u,v,n):=\lambda \bigg({a}(u_{i},v_{i})+\kappa(u_{i},n_{i})(\tau(n_{i\pm1})-\tau(n_i)) \bigg),
	\end{equation*}
	\noindent
	where $v_i, \  n_i$ represent the probabilities of normal tissue and necrotic matter at a node $x_i$ at time $t,$ respectively. Define $\kappa(u_i,n_i)$ as 
	\begin{equation}\label{kappa}
		\kappa (u_{i},n_{i})= \frac{K_u K_n }{K_u K_n + u_{i}n_{i}}.
	\end{equation}
		\noindent
	The choice of $\kappa$ to be inversely proportional to cell-necrotic matter complexes is motivated by the fact that the increase of such bindings reduces the tendency of bacteria $u$ to migrate towards regions with higher necrotic matter density $n$.\\[-2ex] % Conversely, when the product of $u$ and $n$ decreases (indicating weaker binding), $\kappa$ increases, allowing for greater bacterial mobility towards areas with lower necrotic matter density.

	\noindent
	Now divide \eqref{u_i} by $\Delta t$ and informally pass to the limit for $\Delta t \rightarrow 0$
	\begin{equation*}
		\frac{\partial u_i}{\partial t}=T_{i-1}^+u_{i-1}+T_{i+1}^-u_{i+1}-(T_i^++T_i^-)u_i. 
	\end{equation*}
	\noindent
	With the Taylor expansions (for the simplification of notation we set ${T}_i:=T(u_i,v_i,n_i)$):
	\begin{equation*}
		\begin{aligned}
			{T}_{i+1}^ -u_{i+1}&={T}_i^-u_i+h\frac{\partial}{\partial x}({T}_i^-u_i)+\frac{h^2}{2}\frac{\partial^2}{\partial x^2}({T}_i^-u_i)+\frac{h^3}{3!}\frac{\partial^3}{\partial x^3}({T}_i^-u_i)+O(h^4)
			\\
			{T}_{i-1}^ + u_{i-1}&={T}_i^+u_i-h\frac{\partial}{\partial x}({T}_i^+u_i)+\frac{h^2}{2}\frac{\partial^2}{\partial x^2}({T}_i^+u_i)-\frac{h^3}{3!}\frac{\partial^3}{\partial x^3}({T}_i^+u_i)+O(h^4).
		\end{aligned}
	\end{equation*}
	\noindent
	Hence
	\begin{equation*}
		\begin{aligned}
			\frac{\partial u_i}{\partial t}=&{T}_i^+u_i-h\frac{\partial}{\partial x}({T}_i^+u_i)+\frac{h^2}{2}\frac{\partial^2}{\partial x^2}({T}_i^+u_i)-\frac{h^3}{3!}\frac{\partial^3}{\partial x^3}({T}_i^+u_i)
			\\
			&+{T}_i^-u_i+h\frac{\partial}{\partial x}({T}_i^-u_i)+\frac{h^2}{2}\frac{\partial^2}{\partial x^2}({T}_i^-u_i)+\frac{h^3}{3!}\frac{\partial^3}{\partial x^3}({T}_i^-u_i)
			\\
			&-(T_i^++T_i^-)u_i+O(h^4),
		\end{aligned}
	\end{equation*}
	from which follows
	\begin{equation*}
		\begin{aligned}
			\frac{\partial u_i}{\partial t}
			&=   h \frac{\partial}{\partial x} \big((T_i^- - T_i^+)u_i\big) + \frac{h^2}{2} \frac{\partial}{\partial {x^2}}\big((T_i^+ + T_i^-)u_i\big)+ O(h^3)\\
		%	&= \lambda \bigg(-h \frac{\partial}{\partial x} \big( \kappa (u_i,n_i) (\tau(n_{i+1})- \tau(n_{i-1}))u_i\big)  \\
		%	& \quad + \frac{h^2}{2} \frac{\partial}{\partial {x^2}}\big( 2 a (u_i, v_i)+ \kappa (u_i,n_i) (\tau(n_{i+1})+ \tau(n_{i-1}) - 2 \tau(n_i))u_i\big)\bigg)+ O(h^3)\\
		%	&= \lambda \bigg(-2 h^2 \frac{\partial}{\partial x} \big( \kappa (u_i,n_i) \frac{(\tau(n_{i+1})- \tau(n_{i-1}))}{2h}u_i\big) \\
		%	& \quad  + \frac{h^2}{2} \frac{\partial}{\partial {x^2}}\big( 2 a (u_i, v_i)u_i \big)+ \quad  \frac{h^4}{2}\frac{\partial}{\partial {x^2}}\big(\kappa (u_i,n_i) \frac{(\tau(n_{i+1})+ \tau(n_{i-1}) - 2 \tau(n_i))}{h^2}u_i\big)\bigg)+ O(h^3)\\
			&= \lambda \bigg(-2 h^2 \frac{\partial}{\partial x} \big( \kappa (u_i,n_i) \frac{(\tau(n_{i+1})- \tau(n_{i-1}))}{2h}u_i\big) +  \frac{h^2}{2} \frac{\partial}{\partial {x^2}}\big( 2 a (u_i, v_i)u_i \big)\bigg)+ O(h^3).
		\end{aligned}
	\end{equation*}

	\noindent
	Passing to the limit (again, informally) for $h\rightarrow 0$ with $2{\lambda}h^2\rightarrow D,$ %and identifying the variables $u_i, \ n_i, \ v_i$  continuous variables $u(x,t), \ n(x,t) \text{ and } v(x,t)$ respectively,
	we get
		$$\frac{\partial u}{\partial t}=\frac{D}{2}({a}(u,v)u)_{xx}-D(\kappa(u,n) u \tau'(n) n_x)_x,$$
where $u,v,n$ represent the continuous limits (which are supposed to exist) of $u_i,v_i,n_i$.\\[-2ex]

	\noindent The higher dimensional version of this equation reads 
	\begin{equation*}
		\partial_t u=D\nabla.\left(\frac{1}{2}\left({a}(u,v)+\frac{\partial{a}}{\partial u}u\right)\nabla u+\frac{1}{2}\frac{\partial{a}}{\partial v}u\nabla v-\kappa u\frac{d\tau}{dn}\nabla n\right).
	\end{equation*}  
	\noindent
%	To show the interaction of bacteria with the normal tissue, we take
 With the choice ${a}(u,v)=\frac{K_u K_v}{K_uK_v+uv}$, %. This is a choice similar to that of $\kappa(u,n)$, which depends on the binding of bacteria to normal tissue. Therefore, 
 we have 
	\begin{equation*}
		\frac{D}{2}\left({a}(u,v)+\frac{\partial{a}}{\partial u}u\right)\nabla u+\frac{D}{2}\frac{\partial{a}}{\partial v}u\nabla v=\frac{DK_u^2 K_v^2}{2(K_uK_v+uv)^2}\nabla u-\frac{D K_u K_vu^2}{2(K_uK_v+uv)^2}\nabla v.
	\end{equation*}
	\noindent
	To find the chemotactic sensitivity function $\tau(n),$ we follow the idea in \cite{randomjumpSAO} and use the receptor binding kinetics of bacteria to necrotic matter.  Thus, we take $R$ as the receptors on bacteria which are free, $R_0$ as the receptors occupied by $n$, and let $R_T$ be the total amount of receptors on bacteria, which is conserved. Let $R_T=R+R_0$ be a constant.
	\\[-2ex]

	\noindent
	Using simple mass action kinetics for the receptor binding 
	\begin{equation*}
		R+\frac{n}{K_n}\underset{k{-}}{\overset{k^{+}}{\rightleftharpoons }} R_0,
	\end{equation*}
 we obtain an ODE for the dynamics of occupied receptors :
	\begin{equation} \label{ode-reaction}
		\frac{dR_0}{dt}=k^+\frac{n}{K_n}R-k^-R_0,
	\end{equation}
	\noindent
	Since attachment/detachment of receptors is very fast, we assume it to quickly reach its equilibrium. The steady state of (\ref{ode-reaction}) is
	\begin{equation*}
		R_0^*=\frac{{K}R_T\frac{n}{K_n}}{1+{K}\frac{n}{K_n}},
	\end{equation*}where ${K}=\frac{k^+}{k^-}.$
		\noindent 
	If we consider $\tau(n)$ to be a chemical mechanism to measure the concentration of chemoattractant $n$, we could assume $\tau(n)$ to be proportional to the amount of receptors occupied by $n$, that is
	\begin{equation*}
		\tau(n)={b} R_0^*,
	\end{equation*}where ${b}$ is a positive constant. Hence
	\begin{equation*}
		D\kappa(u,n) u\frac{d\tau}{dn}\nabla n=\frac{D\kappa(u,n){b}\frac{K}{K_n}R_Tu}{(1+{K}\frac{n}{K_n})^2}\nabla n,
	\end{equation*}
	is obtained. 
	\\

	\noindent
	Assuming the attachment rate $k^+$ and the detachment rate $k^-$ of bacteria to the necrotic matter to be almost the same, we get ${K} \approx 1$ and let $K_1:=D{b} {K}R_T,$ and using  \eqref{kappa} we have
	\begin{equation*}
		D\kappa(u,n) u\frac{d\tau}{dn}\nabla n=\frac{K_1 K_u  u}{(1+\frac{n}{K_n})^2 (K_u K_n +un)}\nabla n. 
	\end{equation*}

	\noindent
	The system describing the dynamics of $u,n,v,m$ then reads:
	\begin{equation}
		\begin{aligned}\label{burulinonlinear}
			\partial_tu&=\nabla \cdot (D_u(u,v)\nabla u)-\nabla \cdot (\chi_1(u,v)u\nabla v)-\nabla \cdot          (\chi_2(u,n)u\nabla n)  \\& \qquad \qquad +\alpha \frac{ n}{K_n+n}u(1-\frac{u}{K_u}-\frac{v}{K_v}-\frac{n}{K_n}),  \quad \quad   t>0, \ x \in  \Omega,\\
			\partial _tm&=D_m\Delta m+\delta \frac{u}{K_u+u}-\lambda m,  \quad \quad   t>0, \ x \in  \Omega,\\
			\partial_tv&=-\beta _1 v \frac{m}{K_m} , \quad \quad   t>0, \ x \in  \Omega,\\
			\partial_tn&=\beta _2\frac{v}{K_v}\frac{m}{K_m} - \gamma n ,  \quad \quad   t>0, \ x \in  \Omega,
		\end{aligned}
	\end{equation}

	\noindent where $$D_u(u,v)=\frac{DK_u^2 K_v^2 }{2(K_uK_v+uv)^2}, \ \chi_1(u,v)=\frac{D K_u K_v u}{2(K_uK_v+uv)^2}, \ \chi_2(u,n)=\frac{K_1 K_u  }{(1+\frac{n}{K_n})^2 (K_u K_n +un)}.$$
	As before, $\Omega \subset \R^d$ is a bounded, smooth enough domain, and we consider no-flux boundary conditions
	\begin{equation}\label{5}
		(D_u(u,v)\nabla u-\chi_1(u,v) \nabla v-\chi_2(n)u \nabla n)\cdot \nu =0, \ \nabla m \cdot \nu=0 \quad   \quad \quad   t>0, \ x \in  \partial\Omega,
	\end{equation} where $\nu$ represents the outer unit normal vector to $\partial \Omega$. 
	\\[-2ex]

	\noindent
	For the initial conditions we take
	\begin{equation}\label{6}u(0,x)=u_0,\  v(0,x)=v_0, \ n(0,x)= n_0, \ m(0,x)=m_0 \quad \quad x \in \Omega .\end{equation}

\section{Existence of solutions}\label{sec:analysis}

\noindent
In this section we prove the global existence of solutions to the obtained macroscopic systems. We will begin with system \eqref{14}, \eqref{*_}, \eqref{*-*}; the proof for system \eqref{burulinonlinear}, \eqref{5}, \eqref{6} is very similar. \\[-2ex]

\noindent
Before performing the analysis, we nondimensionalise system \eqref{14}. Therefore, we take
\begin{equation}\label{dim-var}
	\tilde{u}=\frac{U}{K_U}, \ \tilde{v}=\frac{V}{K_V}, \ \tilde{n}=\frac{N}{K_N}, \ \tilde{m}=\frac{M}{K_M}, \ \tilde{x}={x}\sqrt{\frac{\alpha_u}{D_m}}, \ \tilde{t}=t \alpha_u,
\end{equation}
where $K_M$ is the maximum possible level of mycolactone. By using the transformations in \eqref{dim-var}, system \eqref{14} becomes
\begin{equation}\begin{aligned}
		\label{nondimsysburuli2}
		\tilde{u}_{\tilde{t}}&=\nabla \cdot \left({\tilde{\mathbb{D}_u}}\nabla \tilde{u}\right)-\nabla \cdot \left(\tilde{a}(\tilde{v}, \tilde{n}) \tilde{\mathbb{D}_u} \tilde{\gamma_1} \tilde{u}\nabla \tilde{n} \right)-\nabla \cdot \left(\tilde{a}(\tilde{v}, \tilde{n}) \tilde{\mathbb{D}_u} \tilde{\gamma_2}\tilde{u} \nabla \tilde{v}\right)\\
		&\quad \ + \frac{\tilde{n}}{1+\tilde{n}} \tilde{u} \left(1-\tilde{u}-\tilde{v}-\tilde{n}\right)
		\\
		\tilde{m}_{\tilde{t}}&=\Delta \tilde{m}+\frac{\tilde{\delta} \tilde{u}}{1+\tilde{u}}-\tilde{\lambda} \tilde{m}
		\\
		\tilde{v}_{\tilde{t}}&=-\tilde{\beta}_1\tilde{m}\tilde{v}
		\\
		\tilde{n}_{\tilde{t}}&=\tilde{\beta}_2\tilde{m}\tilde{v}-\tilde{\gamma}\tilde{n},
	\end{aligned}
\end{equation}
where 
\begin{align*} 
	&\widetilde{\mathbb{D}_u}=\frac{\mathbb{D}_{u}}{D_m},\qquad \tilde{\gamma_1}=\gamma_1 \eta_0 , \qquad \tilde{\gamma_2}=\gamma_2 \eta_0 ,  \qquad \tilde{\delta}=\frac{\delta}{ K_M \alpha_u}, \qquad \tilde{\beta}_1=\frac{{\beta}_1}{\alpha_u},\\ 
	&  \qquad \tilde{\beta_2}=\frac{\beta_2 }{K_N \alpha_u},  \qquad \tilde{\lambda}=\frac{\lambda  }{\alpha_u} \qquad \tilde{\gamma} = \frac{\gamma}{\alpha_u}, \qquad \tilde{a}(\tilde{v}, \tilde{n})=\frac{1}{(1+\tilde{n} +\tilde{v})^2}.
\end{align*}

\noindent To simplify the notation we omit all tildes in system \eqref{nondimsysburuli2} and continue with this system along with the initial conditions (\ref{*-*}) and boundary conditions (\ref{*_}). 
\\

\noindent \textbf{Assumption: (A1)}  Let $ \mathbb{D}_{u}\in \big(C^{2,\rho}(\Omega)\cap C(\bar{\Omega})\big)^{d \times d},$ where $\rho\in(0,1)$ and observe that there exists $\Lambda>0$ such that for any $\xi\in \mathbb{R}^d$ and $x\in \Omega;$ $$\xi^{t}\mathbb{D}_{u}(x)\xi\geq \Lambda|\xi|^2$$ is satisfied.


\subsection{Local existence of a solution to \eqref{14}}
The following result establishes the local existence of solutions to (\ref{nondimsysburuli2}). The proof is similar to that in \cite{TAOchemohapto}.
\begin{Lemma}\label{lemma1buruli2}
	Let $\Omega\subset \mathbb{R}^d$ $(d\geq 1)$ be a bounded domain with a smooth boundary. Suppose that $u_0\in W^{1,\infty}(\Omega), \ m_0, \ n_0, \ v_0 \in W^{2,\infty}(\Omega)$ satisfy the compatibility conditions on boundary and are non-negative. Let \textbf{(A1)} be satisfied. Then there exists a quadruple of non-negative functions $(u,m,v,n)$ $\in C^0([0,T_{\max}) \times\bar{\Omega} ) \cap C^{2,1}((0,T_{\max})\times{\Omega})$ 
	which	solve system \eqref{nondimsysburuli2} classically in $(0,T_{\max})\times\Omega$. Moreover, we have the following dichotomy:
	\begin{equation}
		\begin{aligned}\label{dichoburuli2} 
			&\text{either } T_{max}=\infty \  \text{or } \\
			&  \limsup_{t\nearrow T_{\max}}(||u(t)||_{L^{\infty}(\Omega)}+||m(t)||_{W^{1,\infty}(\Omega)}+||v(t)||_{W^{1,\infty}(\Omega)}+||n(t)||_{W^{1,\infty}(\Omega)})=\infty.
		\end{aligned}
	\end{equation}
\end{Lemma}
\begin{proof} 
	We define the following closed, bounded, and convex set: 
	\begin{equation*}
		Q:=\{\bar{u}\in L^{\infty}((0,T) \times {\Omega}):0\leq \bar{u}\leq ||u_0||_{L^{\infty}(\Omega)}+1 \text{  a.e in } \Omega \times (0,T) \}
	\end{equation*}
	with $T>0$ small, to be fixed below. We consider a fixed point problem with the operator $F$ defined on $Q$ such that $F({\bar{u}})=u$, where $u$ is the first component of the solution $(u,m,v,n)$ to the following system for $ x \in \Omega , \ t \in (0,T)$:

	\begin{equation}\label{15}
		\begin{aligned}
			{u}_{{t}}&=\nabla \cdot \left({{\mathbb{D}_u}}\nabla {u}\right)-\nabla \cdot \left({a}({v}, {n}) {\mathbb{D}_u} {\gamma_1} {u}\nabla {n} \right)-\nabla \cdot \left({a}({v}, {n}) {\mathbb{D}_u} {\gamma_2}{u} \nabla {v}\right)\\
			&\quad \ + \frac{{n}}{1+{n}} {u} \left(1-{\bar u}-{v}-{n}\right)
			\\[5pt]
			\partial_t m &= \Delta m+\delta \frac{\bar u}{1+\bar u}-\lambda m
			\\[5pt]
			\partial_t v &= -\beta_1 v m
			\\[5pt]
			\partial_t n &= \beta_2 v m-\gamma n \\[5pt]
			\big(\mathbb{D}_{u} &\nabla u-a(v,n)\mathbb{D}_{u}u( \gamma_1 \nabla n+\gamma_2 \nabla v) \big)\cdot \vartheta=0, \quad \nabla m\cdot \vartheta=0 \quad x \in \partial \Omega , \ t> 0 \\[5pt]
			u(0,x)&=u_0 (x), \ m(0,x)=m_0 (x),\ v(0,x)=v_0 (x), \ n(0,x)=n_0 (x), \quad x \in \Omega.
		\end{aligned}
	\end{equation} 
	For any $q> \frac{d+2}{2}$, by using Theorem A.1 in \cite{Giesselmann}, there exists a solution $m(t,x)$ such that 
	\begin{equation}
		\label{m-lq}||\nabla m||_{L^{q}((0,T) \times \Omega)}\leq \tilde{c_1},
	\end{equation} 
	where $\tilde{c_1}$ is a positive constant which depends on $||u_0||_{L^{\infty}(\Omega)},||m_0||_{W^{1,\infty}(\Omega)},||n_0||_{W^{1,\infty}(\Omega)} $, and  $||v_0||_{W^{1,\infty}(\Omega)}$. The following constants $\tilde{c_2}, c_3, c_4, c_5 ,..$ also depend on the above values. \\

	\noindent	By solving the ODE for $v$ we get
	\begin{equation}
		\label{17buruli2}
		v(t,x)=v_0(x)\exp\left(-\beta_1\int_0^t m(s,x) ds \right),  \quad \quad t \in (0,T), \ x \in \Omega.  
	\end{equation} 

	\noindent From \eqref{m-lq} and \eqref{17buruli2}, we get
	\begin{equation}
		\label{v-lq}||\nabla v||_{L^{q}((0,T) \times \Omega)}\leq \tilde{c_2}.
	\end{equation} 
	\noindent Using the variation of constants formula for the fourth equation of system \eqref{nondimsysburuli2}, we obtain the following representation:
	\begin{equation}\label{18buruli2}
		n(t,x)=e^{-\gamma t} n_0(x)+\beta_2\int_0^t m(s,x)v(s,x) e^{-\gamma(t-s)}ds, \quad \quad t \in (0,T), \ x \in \Omega.
	\end{equation} 
	\noindent Using the previous estimates \eqref{m-lq} and \eqref{v-lq}, we have
	\begin{equation}\label{n-lq}
		||\nabla n||_{L^{q}((0,T) \times \Omega)}\leq c_3.
	\end{equation}

	\noindent Hence, we can rewrite the first equation in system  \eqref{nondimsysburuli2} as
	\begin{equation*}
		\partial_t u=\nabla \cdot (\mathbb{D}_{u}(x) \nabla u - g(t,x)u) +\frac{n}{n+1}u\left(1-\bar u-v-n\right)  
	\end{equation*}
	where $ ||g||_{L^{q}((0,T) \times \Omega)}\leq c_4$. Using the parabolic theory(Thm V.2.1 and V.1.1 from \cite{LAD}), 
	$||u||_{L^{\infty}((0,T) \times \Omega)}\leq c_5$ and we get $c_6$ such that $||u||_{C^{\beta, \frac{\beta}{2}}((0,T) \times \Omega)}\leq c_6$  for some $\beta >0$.  Hence $||u||_{L^{\infty}((0,T) \times \Omega)}\leq ||u_0||_{L^{\infty}(\Omega)} + c_7 T^{\frac{\beta}{2}}$ for some $T<1$ such that $ c_7 T^{\frac{\beta}{2}} <1$. 
	\\

	\noindent
	Now, consider the fixed point problem $F(\bar{u})=u$. By using the above, we have $F(Q)\subset Q.$ Since $F$ is continuous and $\overline{F(Q)}$ is a compact subset in $L^{\infty}((0,T) \times \Omega),$ by applying Schauders's fixed point theorem we have that there exists at least one fixed point $u\in Q.$ Hence by parabolic regularity theory $(u,v,n,m)$ is obtained as the classical solution of system \eqref{nondimsysburuli2} in $C^0([0,T) \times \bar{\Omega})\cap C^{2,1}((0,T)\times {\Omega}).$ By applying the maximum principle in \cite{protter2012maximum}, we get the non-negativity of $u$. Using Theorem A.3 in \cite{lenz} we get the non-negativity of $m$. By using the non-negativity of $m$, the assumption on $v_0,$ and \eqref{17buruli2}, the non-negativity of $v$ is obtained. By using the positivity of $\gamma$, the assumption on $n_0$, \eqref{18buruli2}, and by the non-negativity of $m \text{ and } v$ we get the nonnegativity of $n$.
	\\

	\noindent Define\begin{equation}\label{Aburuli2}
		A :=||u(0)||_{L^{\infty}(\Omega)}+||m(0)||_{W^{1,\infty}(\Omega)}+||v(0)||_{W^{1,\infty}(\Omega)}+||n(0)||_{W^{1,\infty}(\Omega)}.
	\end{equation}
	and let 
	$$T_{max}= \sup{\{T \in (0,\infty ] \ : \ \text{there exists a solution in } C^0([0,T_{max}) \times \bar{\Omega}))\cap C^{2,1}((0,T_{\max})\times {\Omega})\}}$$ be the maximum existence time. Let $T_{max} < \infty$ and
	$$\limsup_{t\nearrow T_{\max}}(||u(t)||_{L^{\infty}(\Omega)}+||m(t)||_{W^{1,\infty}(\Omega)}+||v(t)||_{W^{1,\infty}(\Omega)}+||n(t)||_{W^{1,\infty}(\Omega)})<\infty.$$
	Hence there exists $A'>0$ such that 
	$$||u(t)||_{L^{\infty}(\Omega)}+||m(t)||_{W^{1,\infty}(\Omega)}+||v(t)||_{W^{1,\infty}(\Omega)}+||n(t)||_{W^{1,\infty}(\Omega)} < A' \quad \text{for all } t < T_{max}.$$ 
	Next we choose $T_1$ sufficiently small such that the above procedure works in $[0,T_1]$ after replacing $A$ (defined in (\ref{Aburuli2}))
	by $A'$. Define $T_2 = T_{max} -\frac{ T_1}{2}$. As $T_1$ depends only on $A'$, we may choose $u(T_2,.), m(T_2,.),v(T_2,.) ,n(T_2,.)$ as new initial values. Hence by the above procedure, we obtain a solution in $[T_2, T_{max} + \frac{T_1}{2}]$. This contradicts the maximality of $T_{max}$. Hence (\ref{dichoburuli2}) holds.

\end{proof}	

\subsection{Boundedness of the solution components for \eqref{14}, global existence}
\noindent To prove the global existence of solutions we will begin by proving the boundedness of functions $u, \ m, \ v, \text{ and } n$ satisfying (\ref{nondimsysburuli2}), (\ref{*-*}), and (\ref{*_}). We follow the proof in \cite{kumar2021multiscale}.
\begin{Remark}
	The boundedness of the solution components is independent of the local existence of the solution.   However, for convenience, the same maximal time $T_{max}$ from the local existence proof is often used in the boundedness proof. This allows for consistency in the analysis while treating the existence and boundedness as separate properties.
\end{Remark}

\begin{Lemma}\label{lem1buruli2}
	There exists $C_m>0$ such that

	\begin{equation*}
		\begin{aligned}
			||m||_{L^{\infty}([0,T_{\max})\times\Omega)}&\leq ||m_0||_{L^{\infty}(\Omega)}+\frac{\delta}{\lambda}\\ 
			||\nabla m||_{L^{\infty}([0,T_{\max})\times\Omega)}&\leq C_m(||\nabla m_0||_{L^{\infty}(\Omega)}+1),
		\end{aligned}
	\end{equation*}  


\end{Lemma}
\begin{proof}
	\noindent 
	Let $pm^{p-1}$ be a test function for the $m$-equation of system \eqref{nondimsysburuli2} for $p>1$. Integrating over $\Omega,$  we have for any $\epsilon\in(0,1)$

	\begin{equation*}
		\begin{aligned}
			\frac{d}{dt}\int_{\Omega} m^p&=- p(p-1)  \int_{\Omega} m^{p-2}|\nabla m|^2+p\delta\int_{\Omega}m^{p-1}\frac{u }{1+u}-\lambda p \int_{\Omega} m^p
			\\ &= -\frac{4(p-1)}{p} \int_{\Omega}|\nabla m^{p/2}|^2+p\delta\int_{\Omega}m^{p-1}\frac{u}{1+u}-\lambda p \int_{\Omega} m^p
			\\ &\leq -\frac{4(p-1)}{p}  \int_{\Omega}|\nabla m^{p/2}|^2+p\delta\int_{\Omega}|m|^{p-1}-\epsilon\lambda p \int_{\Omega} m^p.
		\end{aligned}
	\end{equation*}

	\noindent For some $A>0$ and $\psi\in(0,1)$, we have

	\begin{equation*}
		\begin{aligned}
			p\delta\int_{\Omega}|m|^{p-1}&=p\delta\int_{ \{x\in\Omega \ : \ |m(x)|\leq A\}}|m|^{p-1}+p\delta\int_{\{x\in\Omega \ : \ |m(x)|> A\}}|m|^{p-1}
			\\
			&\leq p\delta A^{p-1}|\Omega|+p\delta\psi\int_{\Omega}|m|^{p-1}.
		\end{aligned}
	\end{equation*}

	\noindent	If we choose $A:=\frac{\delta(1-\psi)^{\frac{1}{p-1}}}{\lambda(1-\epsilon)},$ then we get
	\begin{equation}\label{16}
		\frac{d}{dt}\int_{\Omega} m^p+\epsilon\lambda p\int_{\Omega} m^p\leq \frac{p\delta^p|\Omega|}{(1-\epsilon)^{p-1}\lambda^{p-1}}.
	\end{equation} 
	Multiplying both sides of \eqref{16} with $e^{\epsilon\lambda p t}$ and integrating both sides from $0$ to $t$ for any $t\in[0,T_{\max})$, we obtain
	$$\int_{\Omega}m^p\leq \int_{\Omega}m_0^p+\frac{\delta^p|\Omega|}{\epsilon\lambda^{p}(1-\epsilon)^{p-1}}.$$
	Additionally,
	\begin{equation*}
		\begin{aligned}
			||m(t)||_{L^{\infty}(\Omega)}&=\lim_{p\rightarrow \infty}\left(\int_{\Omega}m^p(t)\right)^{\frac{1}{ p}}
			\\
			&\leq \lim_{p\rightarrow \infty} \left(\int_{\Omega}m_0^p+\frac{\delta^p|\Omega|}{\epsilon\lambda^{p}(1-\epsilon)^{p-1}}\right)^{\frac{1}{ p}}\\
			&\leq||m_0||_{L^{\infty}(\Omega)}+\lim_{p\rightarrow \infty}\frac{\delta |\Omega|^{\frac{1}{p}}}{\lambda \epsilon^{\frac{1}{ p}}(1-\epsilon)^{\frac{p-1}{ p}} }.
			\\
			&\leq||m_0||_{L^{\infty}(\Omega)}+\frac{\delta}{\lambda}.
		\end{aligned}
	\end{equation*} 

	\noindent	Because of the arbitrariness of $\epsilon\in(0,1),$ we get the desired result.
	By using the second equation of system \eqref{nondimsysburuli2}, we have for all $t\in(0,T_{\max})$
	$$m(t)= e^{ t \Delta} m_0+\int_0^t e^{ (t-s)\Delta}\big(\delta \frac{u}{1+u} - \lambda m\big) ds,$$ where $e^{ t \Delta}$ denotes the Neumann heat semigroup. By using the above estimate along with Lemma 1.3 (ii) and 1.3 (iii) from \cite{winkler}, we obtain for all $t \in (0,T_{max})$
	\begin{equation*}
		\begin{aligned}
			||\nabla m(t)||_{L^{\infty}(\Omega)}&\leq ||\nabla e^{ t \Delta} m_0||_{L^{\infty}(\Omega)}+\int_0^t ||\nabla e^{ (t-s)\Delta}\big(\frac{\delta u}{1+u} - \lambda m\big)||_{L^{\infty}(\Omega)}  ds
			\\
			&\leq k_1 e^{- \lambda_1 t } ||\nabla m_0||_{L^{\infty}(\Omega)}+k_2\int_0^t  e^{- \lambda_1(t-s)}(1+(t-s)^{\frac{-1}{2}}) || \frac{ \delta u}{1+u} - \lambda m||_{L^{\infty}(\Omega)} ds
			\\
			&\leq k_1 e^{- \lambda_1 t } ||\nabla m_0||_{L^{\infty}(\Omega)}+k_2\int_0^t  e^{- \lambda_1(t-s)}(1+(t-s)^{\frac{-1}{2}}) ( \delta + \lambda ||m||_{L^{\infty}(\Omega)}) ds
			\\
			&\leq C_m (||\nabla m_0||_{L^{\infty}(\Omega)}+1),
		\end{aligned}
	\end{equation*} 
	\normalsize where $ \lambda_1>0$ denotes the first non-zero eigenvalue of $-\Delta$ in $\Omega\subset \mathbb{R}^d$ under Neumann boundary conditions. 
	\\
\end{proof}
\begin{Remark}\label{rem1buruli2}
	By using \eqref{17buruli2}, non negativity of $m$, the assumption on $v_0$ and Lemma \ref{lemma1buruli2}, we can conclude that there exist constants $C_1, c_1> 0$ such that $||v||_{L^{\infty}([0,T_{\max})\times\Omega)}\leq C_1.$ By using \eqref{17buruli2} and Lemma \ref{lem1buruli2}, we also get 
	$$||\nabla v||_{L^{\infty}([0,T_{\max})\times\Omega)}\leq c_1.$$
\end{Remark}
\begin{Remark}
	\label{rem2buruli2}
	\noindent	By using  \eqref{18buruli2}, the positivity of $\gamma$, the assumption on $n_0$, Lemma \ref{lem1buruli2}, and Remark \ref{rem1buruli2}, there exist constants $C_2, c_2> 0$ such that $||n||_{L^{\infty}([0,T_{\max})\times\Omega)}\leq C_2$. Using \eqref{18buruli2}, Lemma \ref{lem1buruli2}, and Remark \ref{rem1buruli2}, we also get $$||\nabla n||_{L^{\infty}([0,T_{\max})\times\Omega)}\leq c_2.$$
\end{Remark}

\begin{Lemma}\label{lem2buruli2}
	Let \textbf{(A1)} be satisfied. Then for any $p>1,$  there exists $C>0$ such that for $t\in(0,T_{\max}),$ we have
	$$||u(t)||_{L^{p}(\Omega)}\leq C.$$ 
\end{Lemma}
\begin{proof}
	Let $pu^{p-1}$ be a test function for the first equation of system \eqref{nondimsysburuli2}. Then integrating over $\Omega$, using the no flux boundary conditions of the system and Young's inequality, and denoting $||\mathbb{D}_{u}||_{L^{\infty}(\Omega)}:=D_0$, we have
	\begin{equation*}
		\begin{aligned}
			\frac{d}{dt}\int_{\Omega}u^p=&-\frac{4(p-1)}{p}\int_{\Omega}(\nabla u^{\frac{p}{2}})^\top\mathbb{D}_{u}(x)\nabla u^{\frac{p}{2}}
			+(p-1)\int_{\Omega}(\nabla u^{{p}})^{\top} a(v,n)\mathbb{D}_{u}(x)(\gamma_1\nabla n+\gamma_2\nabla v)
			\\
			&+\int_{\Omega} p\frac{n}{n+1}u^p\left(1-u-v-n\right)
			\\ 
			\leq& -\frac{4(p-1)\Lambda}{p}\int_{\Omega} |\nabla u^{\frac{p}{2}}|^2+ \frac{4(p-1)\Lambda}{p}\int_{\Omega} |\nabla u^{\frac{p}{2}}|^2+\tilde{C}\int_{\Omega}  u^p
			+ p \int_{\Omega}  u^p,
			\\ 
			\leq& (\tilde{C}+ p)\int_{\Omega}u^p,
		\end{aligned}
	\end{equation*} where 
	\begin{equation*}
		\begin{aligned}
			\tilde{C}&=\frac{(p-1)p}{4\Lambda} D_0^2 (\gamma_1 ||\nabla n||_{L^{\infty}}+ \gamma_2 ||\nabla v||_{L^{\infty}})^2,
		\end{aligned}
	\end{equation*}

	\noindent By Gronwall's inequality, we obtain
	$$\int_{\Omega}u^p\leq \exp(t( \tilde{C}+p)) \int_{\Omega} u_0^p .$$
	Thus, we get the desired result
	\begin{equation}
		||u(t)||_{L^p(\Omega)} \leq C(p,T_{max}, ||u_0||_{L^p(\Omega)}).
	\end{equation}
\end{proof}
\begin{Remark}\label{rem3}
	By the usual Moser iteration process as in \cite{MARINO2019154}, we can prove that there exists $\tilde{C_1}(T_{max})>0$ such that
	$$||u(t)||_{L^\infty (\Omega)} \leq \tilde{C_1} \quad \text{for all } t \in (0,T_{max}). $$
\end{Remark}	



\begin{Theorem}\label{thm2}
	Under the assumptions of Lemma \ref{lemma1buruli2}, system \eqref{nondimsysburuli2} has a non-negative classical solution $(u,v,n,m)$ which is global in time.
\end{Theorem}
\begin{proof}
	This is now an immediate consequence of the previous results.
\end{proof}

\subsection{Global existence of solutions to \eqref{burulinonlinear}}

\noindent
The global existence of solutions to \eqref{burulinonlinear} follows the same lines. The fixed-point mapping $\phi $ is defined on the same set $Q$ as above: let $ A= ||u_0||_{L^{\infty}({\Omega})}$. For $\bar{u} \in Q$, let $\phi(\bar{u}) \equiv u$ denote the first component of the solution of the following system for $ x \in \Omega, \ {t}  \in (0,T)$:

\begin{equation}\label{15}
	\begin{aligned}
		\partial_t u &=\nabla \cdot ( {D_u} (\bar{u},v)\nabla u)-\nabla \cdot \left( {\chi_1 }(\bar{u},v))u\nabla v\right)-\nabla \cdot \left( {\chi_2}(\bar{u},n)u \nabla {n}\right) \\
		& \quad \quad \quad +  u{f}(\bar{u},v,n)
		\\
		\partial_t m &= D_m \Delta m+\delta \frac{\bar{u}}{K_u + \bar{u}}-\lambda m
		\\
		\partial_t v &= -\beta_1 v m
		\\
		\partial_t n &= \beta_2 v m-\gamma n \\
	\end{aligned}
\end{equation} 
\noindent
with boundary conditions
\begin{equation*}
	\bigg( {D_u} (\bar{u},v)\nabla u-{\chi_1 }(\bar{u},v))\nabla v- {\chi_2}(\bar{u},n)\nabla {n}  \bigg)\cdot \nu =0, \quad \nabla m\cdot \nu=0 \quad \ t> 0 ,\  x \in \partial \Omega , 
\end{equation*}
\noindent
and initial conditions
\begin{equation*}
	u(0,x)=u_0 (x), \ m(0,x)=m_0 (x),\ v(0,x)=v_0 (x), \ n(0,x)=n_0 (x), \quad x \in \Omega,
\end{equation*}
where $u_0, \ m_0$ are non negative and $v_0 ,\ n_0 >0.$ Then Schauder's fixed point theorem and standard parabolic regularity show  the local  existence of a solution in $C^0([0, T) \times \bar{\Omega})\cap C^{2,1}((0,T)\times {\Omega}).$ Analogous estimates as above ensure the boundedness of such solution, while a dichotomy analogous to that in Lemma \ref{lemma1buruli2} leads to the global existence. The solution-dependent motility coefficients $D_u,\ \chi_1,\ \chi _2$ are no particular challenge, since they are well-behaved in terms of boundedness and non-degeneracy. For details of this proof we refer to \cite{diss-shimi}.

\section{Numerical simulations}\label{sec:simulations}

\noindent
In this section we perform numerical simulations of the macroscopic systems for Buruli ulcer spread obtained in Section \ref{sec:models}. We employ the finite difference method (FDM) to discretize the equations. The diffusion terms are treated with the standard central difference scheme, while for the taxis terms we use a first-order upwind discretisation. For the time derivatives an implicit-explicit (IMEX) scheme is used, thereby treating the diffusion parts implicitly and discretizing the taxis and source terms with an explicit Euler method.\\[-2ex]

\noindent
In order to conduct simulations of the models, a set of realistic parameters is required. To establish an estimated range for these parameters, we consulted several relevant studies in the literature.  %\cite{Roberts2019, doi:10.1128/jb.06112-11, Barber2013, Shi2016, King2003, alghamdi2024combinedexperimentalmathematicalstudy,McGann2009, Licata2016}.
