\noindent The following is a straightforward computation, included here for completeness. 
\begin{claim}\label{claim:transform-normal}
    Let $x \sim N(\mu, C)$. Then $Px \sim N(P\mu, PCP^T - P \mu \mu^T P^T)$.
\end{claim}
\begin{proof} 
Since $Px$ is a linear transformation of a Gaussian random variable, it is also a Gaussian random variable. Linearity implies that the mean of $Px$ is equal to $P\mu$.
Observe
\begin{align*}
Cov(Px) &=  \E{(Px-P\mu)(Px-P\mu)^T}\\
    &= \E{Pxx^TP^T} - \E{P\mu x^TP^T}-\E{Px\mu^TP^T}+\E{P\mu \mu^TP^T}\\
    &= PCP^T - P\mu\mu^T P^T.
\end{align*}
\end{proof}


\begin{lemma}\label{lem:gauge-claim-25}(Claim 25 of \cite{posfai2024gauge}.) Let $V_1$ and $V_2$ be complementary subspaces of a vector space $V$. Let $P_1$ be the projection into  $V_1 $ along $V_2$, and $P_2$ be the projection into $V_2$ along $V_1$. Let $\Lambda$ be a symmetric positive definite matrix acting on $V$. Then the following are equivalent:
\begin{enumerate}
    \item $V_1$ and $V_2$ are $\Lambda$-orthogonal, i.e. $v_1^T \Lambda v_2=0$ for all $v_1 \in V_1$ and $v_2 \in V_2$.
    \item For any fixed $v_1 \in V_1$, $\argmin_{v_2 \in V_2} (v_1+v_2)^T \Lambda (v_1 + v_2) = 0$.
    \item $\Lambda = P_1^T \Lambda P_1 + P_2^T \Lambda P_2$.
\end{enumerate}
\end{lemma}


Next we prove \Cref{lem:form-of-Lambda}, which gives another equivalent condition for $\Lambda$ orthogonality.

\begin{proof}(of \Cref{lem:form-of-Lambda}).
Assume $\Lambda$ orthogonalizes $V_1$ and $V_2$. Since $\Lambda$ is positive-definite, we can write $\Lambda = Z^T Z$ where $Z$ is invertible. Moreover, since $\Lambda$ is orthogonalizing \Cref{lem:gauge-claim-25} implies that 

$$\Lambda = P_1^T\Lambda P_1 + P_2^T \Lambda P_2 = (ZP_1)^TZP_1 + (ZP_2)^TZP_2,$$ where $P_1$ and $P_2$ are the projection matrices into $V_1$ and $V_2$ along $V_2$ and $V_1$ respectively. It remains to show that the null space of $ZP_1$ is  $V_2$ and the null space of $ZP_2$ is $V_1$. Indeed, note that since $Z$ is invertible, if $ZP_1x =0$, then $P_1x=0$, meaning $x$ is in the null space of $P_1$, which is equal to $V_2$. The argument that $V_1$ is the null space of $ZP_2$ is analogous. 

Next assume that $\Lambda = A^TA + B^TB$ where $\nullspace(A) = V_2$ and $\nullspace(B)= V_1$. First we show that $\Lambda$ is positive-definite. Let $v = v_1 +v_2$ where $v_1 \in V_1$ and $v_2 \in V_2$. Note 

$$v^T \Lambda v= v_1^TA^TAv_1 + v_2^TB^TBv_2 = \|Av_1\|_2^2 + \|Bv_2\|_2^2$$
is zero if and only if $v_1 =0$ and $v_2 =0$. 
Next we apply Condition 1 of \Cref{lem:gauge-claim-25} to establish  that $\Lambda$ orthogonalizes $V_1$ and $V_2$. 
Let $v_1 \in V_1$ and $v_2 \in V_2$.  Observe

$$v_1^T(A^TA+B^TB) v_2 = v_1^TA^T(Av_2) +(v_1^TB^T)Bv_2 =0.$$ 
\end{proof}


\begin{lemma}\label{lem:vc-inverse}
  If $K$ has the form  $K_{x,y} = \sum_{k=0}^\ell \lambda_k \mathcal{K}_k(d(x,y))$, then 

$$K^{-1}_{x,y} = \sum_{k=0}^\ell \lambda_k^{-1} \mathcal{K}_k(d(x,y)).$$
\end{lemma}

\begin{proof}
    This results simply follows from the fact that $K_{x,y} = \sum_{k=0}^\ell \lambda_k \mathcal{K}_k(d(x,y))$ provides an eigendecomposition of the matrix $K$, see \cite{zhou2022higher}. 
\end{proof}



The following identity is a generalization of equation (22) in  \cite{neidhart2013exact}.

\begin{lemma}\label{lem:nice-identity} Let $j \in [\ell-d]$. Then

$$\alpha^{-j}\sum_{k=0}^j { \ell -k \choose j-k}  \mathcal{K}_k(d) =  { \ell -d \choose j}.$$
\end{lemma}


\begin{proof}
   We will show the equivalent statement
\begin{equation}\label{eq:both-coeffs}
    \sum_{0 \leq i\leq k \leq j} { \ell -k \choose j-k} {d \choose i} {\ell-d \choose k-i}\alpha^j (\alpha-1)^{k-i} (-1)^{i}= {\ell-d\choose j} \alpha^{2j}
\end{equation}
by showing that each side of the \Cref{eq:both-coeffs} is equal to the coefficient of $z^j$ in the polynomial $(\alpha^2z+1)^{\ell-d}$. To see the righthand side, imagine expanding $(\alpha^2z+1)^{\ell-d}$ into $2^{\ell-d}$ terms. Each degree $j$ term has coefficient $\alpha^{2j}$ and there are ${\ell-d \choose j}$ such terms. To see the lefthand side, note that

$$(\alpha^2z+1)^{\ell-d}=(\alpha z + \alpha(\alpha-1)z + 1)^{\ell-d} (\alpha z-\alpha z+1)^d.$$ 
Imagine expanding this polynomial into $3^{\ell}$ terms. We consider the possible coefficients for a degree $j$ term in this expansion and compute how many such terms yield this coefficient. Imagine a degree $j$ term that is the product of $j-k$ copies of $\alpha z$, $k-i$ copies of $\alpha(\alpha-1)z$ and $i$ copies of $(-\alpha z)$. 
There are 

$${\ell-k \choose j-k} {\ell-d \choose k-i} {d \choose i}$$ such terms, each with a coefficient of 

$$ (\alpha )^{j-k} (\alpha(\alpha-1))^{k-i} (-\alpha )^i = \alpha^j(\alpha-1)^{k-i}(-1)^i.$$
Thus, the lefthand side of \Cref{eq:both-coeffs} also counts the coefficient of the degree $j$ term in the polynomial $(\alpha^2z +1)^{\ell-d}.$
\end{proof}

