\subsection{Building regularizers for geometric decay, Connectedness, and Jenga kernels}

In this section, we discuss three subclasses of product kernels and compute $\Phi^TK^{-1}\Phi$ for each class. 
\subsubsection{Definitions of geometric decay, Connectedness, and Jenga kernels}\label{sec:defn-jenga}
We will consider the following three subclasses of product kernels. The most simple subclass are geometric decay kernels, where the covariance decays exponentially with Hamming distance. These isotropic kernels are also a special case of VC kernels corresponding to hyperparameters $\lambda_k$ that decay exponentially with the order $k$ \cite{zhou2022higher, neidhart2013exact}.

\begin{definition}
    A geometric decay kernel has the following form: 
    $$K_{x,y}= \beta^{d(x,y)}$$ where $\beta\in (0,1)$.
\end{definition}

Next we consider Connectedness kernels, which are a generalization of the geometric decay kernel that can express that making changes at different positions results in different effects on predictability. The covariation between a pair is the product of site specific factors $z^p$ for all positions $p$ where they differ. In the bi-allelic case ($\alpha = 2)$ when $z^p \in (0,1)$ this prior on function space is equivalent to the Connectedness model proposed by \cite{reddy2021global}.
\begin{definition}
    A Connectedness kernel has the form 

    $$K_{x,y} = \prod_{p: x_p \not =y_p} z^p$$
    where each factor satisfies $\frac{-1}{\alpha-1}< z^p <1 $. 
\end{definition}
\noindent The constraints ensure that $K$ is positive-definite, see \cite{zhou2024tbd}.


Finally, we consider Jenga kernels, a generalization of Connectedness kernels that allows different allele-position (character-position) combinations to affect predictability differently. We assign each character-position a factor $z^p_c$; the covariance between a pair of sequences is the product of the factors over the positions where the sequences differ.
\begin{definition}
A Jenga kernel has the form

$$K_{x,y} = \prod_{p: x_p \not = y_p} s_p  z^p_{x_p} z^p_{y_p}$$ where at each position $p$ either
\begin{enumerate}
    \item 
$s_p = 1$ and $z^p_c  \in (0,1)$ for each $c \in \mathcal{A}$, or 
\item $s_p = -1$ and $\sum_{c \in \mathcal{A}} \frac{\brac{z^p_c}^2}{1+ \brac{z^p_c}^2} \leq 1$.
\end{enumerate}
\end{definition}
\noindent The two conditions above correspond to  $z^p>0$ and $z^p \leq 0$ in the connectedness kernel, respectively, and the constraints ensure that $K$ is positive-definite, see \cite{zhou2024tbd}.


\subsubsection{\Cref{thm:phi-kinv-phi-product} applied to geometric decay, Connectedness, and Jenga kernels}\label{sec:jenga-cors}
The following corollaries of \Cref{thm:phi-kinv-phi-product} give the form of $\Phi^T K^{-1} \Phi$ for geometric decay, Connectedness, and Jenga kernels.
\begin{corollary}
\label{thm:phi-kinv-phi-jenga}
    Let $K$ be a Jenga kernel, $K_{x,y} = \prod_{p: x_p \not = y_p}s^p z^p_{x_p} z^p_{y_p}$,  then $(\Phi^T K^{-1} \Phi)_{(S,s),(T,t)} $ is as given in \Cref{thm:phi-kinv-phi-product}
with 

$$b^p_{c,c'} = \frac{\delta_{c=c'}}{1-s^p\brac{z^p_c}^2} + \frac{s^p\gamma^p z^p_c z^p_{c'}}{\brac{1-s^p\brac{z^p_c}^2}\brac{1-s^p\brac{z^p_{c'}}^2}}, \quad \quad \gamma^p = \frac{-1}{1+ s^p\sum_{c \in \mathcal{A}} \frac{\brac{z^p_c}^2}{1-s^p\brac{z^p_c}^2}}
$$
\end{corollary}


\begin{corollary}\label{cor:phi-kinv-phi-connectedness}
        Let $K$ be a connectedness kernel $K_{x,y} = \prod_{p:x_p \not = y_p} z^p$.  Then

    $$(\Phi^T K^{-1} \Phi)_{(S,s),(T,t)} = \prod_{p \in [\ell]} \frac{1}{1+(\alpha-1) z^p} \prod_{\substack{p \in S\cap T\\x_p = y_p}} \frac{1+ (\alpha-2)z^p}{1-z^p}\prod_{\substack{p \in S\cap T\\x_p \not= y_p}} \frac{-z^p}{1-z^p} \prod_{p \not \in S \cup T} \alpha.$$
\end{corollary}

 \begin{corollary}\label{cor:phi-kinv-phi-geometric}
    Suppose $K$ is a geometric decay kernel, $K_{x,y}= \beta^{d(x,y)}$ with $\beta\in (0,1)$. Then 

    $$ (\Phi^T K^{-1} \Phi)_{(S,s),(T,t)} =  \frac{\alpha^{L-|S\cup T|} }{(1+(\alpha-1)\beta)^\ell}  \bfrac{1+(\alpha -2) \beta}{1-\beta}^{|\{p \in S \cap T: s_p=t_p\}|}
\bfrac{-\beta}{1-\beta}^{|\{p \in S \cap T: s_p\not=t_p\}|}.$$ 

\end{corollary}

\Cref{thm:phi-kinv-phi-jenga} follows directly from \Cref{thm:phi-kinv-phi-product} and \Cref{lem:inverse-jenga-piece}, which gives the form of $\brac{K^p}^{-1}$ for a Jenga kernel. 
\begin{lemma}\label{lem:inverse-jenga-piece} Let $K$ be a matrix of the form 

$$K_{ij}= \begin{cases}
    1 & i = j\\
    sa_ia_j & i \not = j
\end{cases}$$
where $s \in \{-1,1\}$.
Then 

$$K^{-1}_{ij} =\frac{ \delta_{i=j}}{(1-sa_i^2)}+\frac{s\zeta a_ia_j}{(1-sa_i^2)(1-sa_j^2)} \quad \text{ for } \quad \zeta = \frac{-1}{1 + s\sum_{i} \frac{a_i^2}{(1-sa_i^2)}}.$$
\end{lemma}

\begin{proof}
The result follows directly from applying Sherman-Morrison formula (\Cref{lem:sherman}) with $A$ the diagonal matrix with $A_{ii} = 1-sa_i^2$ and $u=sv$ with $u_i = a_i$. 
%Note
%$$c= 1 + \sum_{i} \frac{a_i^2}{(1-a_i)^2}= 1+u^T A^{-1}u.$$
\end{proof}

\begin{lemma}\label{lem:sherman} (Sherman-Morrison formula) Let $A$ be an invertible matrix. Then

$$(A+uv^T)^{-1}=A^{-1} - \frac{A^{-1} uv^T A^{-1}}{1+v^TA^{-1}u}.$$
\end{lemma}

To arrive at the expression in \Cref{cor:phi-kinv-phi-connectedness}, we begin with \Cref{thm:phi-kinv-phi-jenga} and plug in $s^p=sgn(z^p)$ and $z^p_c = \sqrt{|z^p|}$ for all $c$. We obtain

$$b^p_{x_p,y_p} = 
\begin{cases}
    \frac{1 + (\alpha-2) z^p}{(1-z^p)(1+(\alpha-1)z^p)} & x_p = y_p\\
    \frac{- z^p}{(1-z^p)(1+(\alpha-1)z^p)} & x_p \not = y_p
\end{cases}$$

$$\sum_{c \in \mathcal{A}} b^p_{c,c'} = \frac{1 + (\alpha-2)z^p - (\alpha-1)z^p}{(1-z^p )(1+(\alpha-1)z^p)} = \frac{1}{ 1+(\alpha-1)z^p}$$

$$\sum_{c,c'} b^p_{c,c'} = \frac{\alpha(1 + (\alpha-2)z^p) - \alpha(\alpha-1)z^p}{(1-z^p )(1+(\alpha-1)z^p)} = \frac{\alpha}{ 1+(\alpha-1)z^p}$$

To arrive at the expression in \Cref{cor:phi-kinv-phi-geometric}, we plug  $z^p =\beta$ for all $p$ in to \Cref{cor:phi-kinv-phi-connectedness}.






\subsection{Proofs of \Cref{thm:gen-kernel-trick} and \Cref{thm:kernel-trick}}\label{sec:pf-of-6-7}
We now prove \Cref{thm:gen-kernel-trick}.
\begin{proof}(\Cref{thm:gen-kernel-trick})
(a) The results follows by taking $M=\bar{P}$ and applying \Cref{thm:trans-kernel-trick}.
(b) Recall the posterior distribution under the weight space Gaussian prior, $w \sim N(w^{MAP},C_w)$, where 

$$w^{MAP} = \sigma^{-1} \brac{\sigma^2 \Phi_X^T\Phi_X + W^{-1}}^{-1} \Phi^T_X y \quad \text{ and } \quad C_w =\brac{\sigma^2 \Phi_X^T\Phi_X + W^{-1}}^{-1}.
$$
\Cref{claim:transform-normal} implies $\bar{\theta} = P \sigma^{-1} C_w \Phi^T_X y$ and 

\begin{align}
R
    = PC_wP^T - Pw^{MAP}\brac{w^{MAP}}^T P^T
    = PC_wP^T - P\brac{\sigma^{-1} C_w \Phi^T_X y }\brac{\sigma^{-1} C_w \Phi^T_X y }^T P^T %\label{eq:w}
\end{align}

(c) By \Cref{claim:transform-normal}, %\Cref{eq:f,eq:w}, 
it suffices to show that if $K= \Phi W \Phi^T$, then $\bar{P} f^{MAP} = P w^{MAP}$ and $\bar{P}C_f\bar{P}^T=PC_wP^T$.
Note  $P=\bar{P} \Phi$ and $f^{MAP} = \Phi w^{MAP}$ (\Cref{lem:gp-equiv-coeff-func}). It follows that $\bar{P} f^{MAP} = \bar{P} \Phi w^{MAP}  = P w^{MAP}$. 

Next we apply the matrix inversion formula (\Cref{claim:mat-inv-formula}) with $W= \sigma^2 I$, $U = \Phi_X^T$, $V^T = \Phi_X$ and $Z= W^{-1}$ to show that $\bar{P}C_f\bar{P}^T=PC_wP^T$. Observe

$$C_w =\brac{\sigma^2 \Phi_X^T\Phi_X + W^{-1}}^{-1} = W -W \Phi_X^T \brac{\sigma^{-2} I + \Phi_X W \Phi_X^T}^{-1} \Phi_XW = W -W \Phi_X^T Q \Phi_XW.$$
Also note that 

$$PWP^T = \bar{P} \Phi W \Phi^T \bar{P}^T = \bar{P} K \bar{P}^T, \quad PW\Phi^T_X = \bar{P} \Phi W \Phi^T_X = \bar{P} K_{*,X}, \quad \text{ and } \quad \Phi_X W P^T = K_{*,X} \bar{P}^T.$$
We obtain

$$PC_wP^T = PWP^T -PW \Phi_X^T Q \Phi_XWP^T = \bar{P}K \bar{P}^T - \bar{P} K_{*,X}Q K_{*,X} \bar{P}^T=\bar{P}C_f\bar{P}^T,$$
as desired.
\end{proof}


\begin{proof}(of \Cref{thm:kernel-trick}.) %We apply \Cref{thm:trans-kernel-trick}.
Recall 

$$P^{\lambda, \pi}_{(S,s),([\ell],t)} = 
\prod_{p \in S}\brac{\delta_{s_p = t_p} -\pi^p_{t_p} \eta}  \prod_{p \not \in S}\pi^p_{t_p} \eta.
$$
We apply \Cref{thm:trans-kernel-trick}b with $M= \bar{P}$ and 

$$m^{(S,s),p}_c =
\begin{cases}
    \delta_{s_p=c} -\pi^p_c\eta &p\in S\\
    \pi^p_c\eta &p\not\in S.
\end{cases}$$
   The result follows directly from the following computations:
    \begin{align*}
        \brac{\bar{P}K}_{(S,s),y}
        &= \prod_{p \in S} \brac{\brac{1- \pi^p_{s_p}\eta} a_{y_p,s_p}^p - \sum_{c \not = s_p}  \pi^p_{c}\eta a_{y_p,c}^p }   \prod_{p \not \in S} \brac{\sum_{c \in \mathcal{A}} \pi^p_{c}\eta a_{y_p,c}^p}\\
        &= \prod_{p \in S} \brac{a_{y_p,s_p}^p - \zeta^p_{y_p}}\prod_{p \not \in S}\zeta^p_{y_p}
    \end{align*}
    and
    \begin{align*}
        \brac{\bar{P}K\bar{P}^T}_{(S,s),(T,t)}
        &= \brac{\prod_{p \in S\cap T} \sum_{c,c' \in \mathcal{A}}\brac{\delta_{s_p=c}- \pi^p_c \eta}\brac{\delta_{t_p=c'}- \pi^p_{c'} \eta}}
       \brac{ \prod_{p \not \in S \cap T} \sum_{c,c' \in \mathcal{A}} \pi^p_c \eta \pi^p_{c'} \eta}\\
       &         \brac{ \prod_{p \in S \setminus T} \sum_{c,c' \in \mathcal{A}} \brac{\delta_{s_p=c}- \pi^p_c \eta} \pi^p_{c'} \eta}
          \brac{\prod_{p \in T \setminus S} \sum_{c,c' \in \mathcal{A}} \pi^p_c \eta \brac{\delta_{t_p=c'}- \pi^p_{c'} \eta}}\\
          &= \prod_{p \in S \cap T} \brac{\bar{\zeta}^p- \zeta^p_{s_p} - \zeta^p_{t_p} + a^p_{s_p,t_p}   }\prod_{p \in S \setminus T} \brac{ \zeta^p_{s_p} - \bar{\zeta}^p }\prod_{p \in T\setminus S} \brac{ \zeta^p_{t_p} - \bar{\zeta}^p } \prod_{p \not \in S \cup T} \bar{\zeta}^p.
    \end{align*}


    \end{proof}

\subsection{Variance component kernels that cannot be induced by order-dependent diagonal regularizers}\label{sec:cannot-achieve}
Every sequence of positive $\lambda_k$ defines a valid variance component (VC) kernel. Here we show that not all VC kernels can be induced by some order-dependent digaongal regularizer. \Cref{thm:prior-from-diag-reg} establishes that priors induced by order-dependent diagonal regularizers have dimension-normalized $k^{th}$ order variance given by 

$$\lambda_k = \sum_{j=k}^\ell \frac{1}{\alpha^j a_j}   {\ell-k \choose j-k}.$$ Note that such $\lambda_k$'s decrease with $k$, meaning that any sequence of non-decreasing $\lambda_k$'s cannot be induced by an order-dependent diagonal regularizer. Moreover, it is not the case that any VC prior defined by decreasing $\lambda_k$ is induced by an order-dependent diagonal regularizer. 
Indeed note that 

$$\lambda_{\ell-1} = \frac{1}{\alpha^{\ell-1} a_{\ell-1}}+\frac{1}{\alpha^\ell a_\ell}$$
and for $k\leq \ell-1$, 

$$\lambda_k \geq \frac{\ell-k}{\alpha^{\ell-1} a_{\ell-1}} + \frac{1}{\alpha^\ell a_\ell} \geq \lambda_{\ell-1} + \frac{\ell-k-1}{\alpha^{\ell-1} a_{\ell-1}}.$$
This restriction that $\lambda_k$ cannot be arbitrarily close to $\lambda_{\ell-1}$ for order-dependent diagonal regularizers implies that not all VC priors with decreasing $\lambda_k$ can be induced by an order-dependent diagonal regularizer. 


\subsection{Function space priors induced by diagonal regularizers for alternative bi-allelic  weight spaces}\label{sec:diag-two}

Finally, we describe the function space priors induced by diagonal regularizers for different weight spaces in the bi-allelic case $(\alpha = 2)$. When $\alpha = 2$, there are natural bases to use for regularized regression that are interpretable and not overparameterized \cite{weinberger1991fourier,poelwijk2016context}: the Walsh-Hadamard basis  (WH) and the wild-type basis (WT). Both have one basis element associated with each subset of positions $S \subseteq [\ell]$, but the meaning of the weight of each basis element is interpreted differently.

\paragraph{Walsh-Hadamard basis.} We encode the alleles as $\{-1, +1\}$ and write a function $f$ in terms of $2^\ell$ weights $w_S$ as 

$$ \quad f = \sum_S w_S \prod_{p \in S} x_p = Hw \quad \text{ where } \quad H_{x,S} = \prod_{p \in S} x_p.$$ 

\paragraph{Wild-type basis.} We encode the wild-type allele as $0$ and the mutant allele as $1$. We write a function $f$ in terms of $2^\ell$ weights $w_S$ as 

$$f=\sum_S w_S \prod_{p \in S} \delta_{x_p=1}= Tw \quad \text{ where } \quad T_{x,S} = \prod_{p \in S}\delta_{x_p=1}. $$

We apply the framework established in \Cref{subsec:equiv} to describe how regularized regression in these $\alpha^\ell=2^\ell$-dimensional weight spaces induce function space priors. Here $H$ or $T$ will play the role of $\Phi$.  We show that any diagonal regularizers with the WT basis induces a heterosketdastic prior, whereas any diagonal regularizer with the WH basis induces a homoskedastic prior. Moreover, we describe how a subset of connectedness kernel can be induced with diagonal regularizers with the WH basis.  

\begin{theorem}\label{thm:2-allele}
    Let $\Lambda$ be diagonal regularizer indexed by subsets of positions,

$$\Lambda_{S,S} = \prod_{p \in S} \rho_p$$
where $\rho_p >0$. Let $f^{MAP}(K, \sigma^2)$ be the MAP estimate for the Gaussian process $y = f_X +\ve$ where $f \sim N(0,K)$ and $\ve \sim N(0, \sigma^2 I)$. 
\begin{enumerate}
    \item When used with the WH basis, the regularizer $\Lambda$ induces the function space prior 

    $$K^H_{x,y}=\brac{ \prod_p \brac{1+ \rho_p^{-1}}} \prod_{p:x_p \not = y_p} \frac{1-\rho_p^{-1}}{1+\rho_p^{-1}},$$ meaning 

    $$Hw^{OPT}(\Lambda, \sigma^2) = f^{MAP}(K^H, \sigma^2)$$ where 

    $$w^{OPT}(\Lambda, \sigma^2) = \argmin_{w \in \R^{2^\ell}} \| y-H_Xw\|_2^2 + \sigma^2 w^T \Lambda w.$$
    \item When used with the WT basis, the regularizer $\Lambda$ induces the function space prior 

    $$K^{(T)}_{x,y}=\prod_{\substack{p \in S:\\ x_p = y_p = 1}} (1+\rho_p^{-1}),$$ meaning 

    $$Tw^{OPT}(\Lambda, \sigma^2) = f^{MAP}(K^{(T)}, \sigma^2)$$ where 

    $$w^{OPT}(\Lambda, \sigma^2) = \argmin_{w \in \R^{2^\ell}} \| y-T_Xw\|_2^2 + \sigma^2 w^T \Lambda w.$$
\end{enumerate}
\end{theorem}

Whereas $K^H$ is a homoskedastic prior, $K^{(T)}$ is heteroskedastic; the variance of the wild-type sequence is one and the variance of the other sequences depends on the extent to which they differ from the wild-type (sequences that are more different from the wild-type tend to have higher variances). We can induce a connectedness prior with $0<z^p<1$ through regularized regression in the WH basis by choosing $\rho_p = (1+z^p)/(1-z_p)$ and rescaling by $1/ \prod_p (1+ \rho_p^{-1})$.
%$z^p = \frac{1-\rho_p^{-1}}{1+\rho_p^{-1}}$.


\begin{proof} (of \Cref{thm:2-allele}).
Taking $\Phi$ to be $H$ or $T$, we apply \Cref{lem:gp-map-equiv,lem:gp-equiv-coeff-func} to conclude that the regularizer $\Lambda$ induces the kernels $H\Lambda^{-1} H^T$ and $T\Lambda^{-1} T^T$ on function space for the WH and WT bases respectively. 
    Observe
    \begin{align*}
    (H\Lambda^{-1}H^T)_{x,y}&= \sum_S \Lambda^{-1}_S \prod_{p \in S} x_p y_p\\
    &=\sum_S \brac{ \prod_{p \in S} \rho_p^{-1} } \brac{\prod_{\substack{p \in S\\x_p \not = y_p}}(-1)}\\
    &= \prod_{p: x_p = y_p} (1+\rho_p^{-1})\prod_{p: x_p \not = y_p} (1- \rho_p^{-1})\\
    &= \brac{ \prod_p \brac{1+ \rho_p^{-1}}} \prod_{p:x_p \not = y_p} \frac{1-\rho_p^{-1}}{1+\rho_p^{-1}}.
    \end{align*}

Similarly
    \begin{align*}
    (T\Lambda^{-1}T^T)_{x,y}= \sum_S \Lambda^{-1}_S \prod_{p \in S} \delta_{x_p=1}\delta_{y_p=1}
    =\sum_S \brac{ \prod_{\substack{p \in S:\\ x_p = y_p = 1}} \rho_p^{-1} } 
    = \prod_{\substack{p \in S:\\ x_p = y_p = 1}} (1+\rho_p^{-1}).
    \end{align*}
\end{proof}


