\begin{definition}[$\C$-chronological and $\C$-causal curves]
Let $M$ be a smooth connected manifold endowed with a cone structure $\C$. A piecewise $C^1$ curve in $M$ is \emph{$\C$-chronological} (respectively \emph{$\C$-causal}) if its velocity vectors are all $\C$-timelike (respectively non-$\C$-spacelike). In both cases we say that it is \emph{future directed} (respectively \emph{past directed}) if all its velocity vectors are future directed (respectively past directed). 
\end{definition}

\begin{definition}[$\C$-future and $\C$-past of a point, $\C$-diamond]
Let $p$ be a point of a smooth connected manifold manifold $M$ endowed with a cone structure $\C$. The \emph{$\C$-future of $p$} (respectively the \emph{$\C$-past of $p$}) is the subset $I^+(p)$ (respectively $I^-(p)$) of $M$ formed by the points which are end-points of future directed (respectively past directed) $\C$-chronological curves starting at $p$ .

Replacing the $\C$-chronological curves by $\C$-causal curves, we obtain the definition of the \emph{$\C$-causal future} $J^+(p)$ (respectively \emph{$\C$-causal past} $J^-(p)$) of $p$. 

For two points $p,q \in M$ the (possibly empty) set $I^+(p) \cap I^-(q)$ is called a \emph{$\C$-diamond}, and the set $J^+(p) \cap J^-(q)$ is called a \emph{$\C$-causal diamond}.
\end{definition}

\begin{definition}[Global hyperbolicity and Cauchy surface]
\label{def Cauchy surface}
A convex cone structure $\C$ on a smooth connected manifold $M$ is \emph{globally hyperbolic} if there exists a $C^1$ embedded hypersurface $S$ which is:
\begin{itemize}
\item \emph{$\C$-spacelike}, that is every tangent hyperplane $\mathrm{T}_p S \subseteq \mathrm{T}_p M$ is $\C$-spacelikea,
\item a \emph{Cauchy surface}, namely every inextensible $\C$-causal curve intersects $S$ at exactly one point.
\end{itemize}
\end{definition}

The following results for Lorentzian spacetimes are due to Geroch in \cite{Geroch_70}. As their proofs only rely on topological and differential arguments, and not on the Lorentzian metric or shape of the cones in the tangent space, these results still hold for smooth manifolds with a proper convex cone structure \cite{Minguzzi_19}.

\begin{proposition}
\label{prop Geroch Cauchy surfaces}
Let $M$ be a smooth connected manifold admitting a globally hyperbolic convex cone structure $\C$ with a Cauchy surface $S$. All the Cauchy surfaces of $M$ for the cone structure $\C$ are homeomorphic and $M$ is homeomorphic to $S \times \R$.
\end{proposition}
\begin{proof}
In order to be able to replicate the proof in {\cite[Property 7]{Geroch_70}}, one just needs to produce a non-vanishing $\C$-causal vector field on $M$. For that fix any Riemannian metric $g$ on $M$ and take $X(p) \in \mathrm{T}_pM$ to be the barycentre with respect to $\vol_{g_p}$ of the intersection $\C_p \cap B_{g_p}$, where $ B_{g_p}$ is the unit ball of $(\mathrm{T}_pM,g_p)$. The vector field $X$ is $\C$-causal because of the convexity of the cone distribution $C$, and non-vanishing because of its properness.
Let $\phi^t_X$ be the flow associated with $X$, up to rescaling $X$ we can assume that it is always defined for all $t \in \R$. Every curve $\bp{\phi^t_X(p)}_{t \in \R}$ is an inextensible $\C$-causal curve and thus intersects $S$. Hence the wanted homeomorphism is provided by 
\begin{equation*}
 \function{\Phi}{S \times \R}{M}{(p,t)}{\phi^t_X(p)}. \qedhere
\end{equation*} 
\end{proof}

\begin{theorem}[{\cite[Theorem 2.45]{Minguzzi_19}}]
A smooth connected manifold $M$ with a convex cone structure $\C$ is globally hyperbolic if and only if it admits no closed causal curve and all the $\C$-causal diamonds are compact.
\end{theorem}



\subsection{Affine spacetimes}
\label{subsec affine spacetimes}

Given any open proper convex cone $\C$ in $\A^{d+1}$, the affine space of dimension $d+1$ can be endowed with the \emph{parallel convex cone structure} induced by $\C$. Namely, taking $X_0$ to be the vertex of $\C$, we can see $\C_{X_0} = \C $ as an open proper convex cone in $\V^{d+1}=\mathrm{T}_{X_0} \A^{d+1}$ with vertex at the origin. Then any cone $\C_X$ is defined as the parallel transports of $\C_{X_0}$ from $\mathrm{T}_{X_0} \A^{d+1}$ to $\mathrm{T}_{X} \A^{d+1}$ by the flat affine connection $D$ on $\A^{d+1}$. We shall introduce affine spacetimes as manifolds with a cone structure which are locally modelled on $\bp{\A^{d+1},\C}$.

\begin{definition}[Affine spacetime]
An $\emph{affine spacetime}$ $(M,\C)$ is a connected equiaffine manifold $M$ endowed with a convex cone structure $\C$ parallel for the flat affine connection induced by the equiaffine structure of $M$ .
\end{definition}


\begin{definition}[Maximality of a globally hyperbolic affine spacetime]
\label{def Maximal}
A globally hyperbolic affine spacetime $(M,\C)$ is said to be 
\begin{itemize}
\item \emph{Cauchy-compact globally hyperbolic} if it admits a compact Cauchy surface,
\item \emph{maximal} if, for every globally hyperbolic affine spacetime $(M',\C')$ and any embedding $i:M~\lhook\joinrel\longrightarrow~M'$ preserving the equiaffine structure, the cone structure, and mapping any Cauchy surface of $M$ to a Cauchy surface of $M'$, $i$ is necessarily surjective.
\end{itemize}
\end{definition}

\begin{definition}[Convexity of a Cauchy surface of an affine spacetime]
\label{def Convex Cauchy surface}
A Cauchy surface $S$ of a globally hyperbolic affine spacetime $(M,\C)$ is said to be \emph{convex} if in any local affine chart, the $\C$-spacelike surface $S$ can locally be parametrised as a the graph of convex function, and any $\C$-causal vector on $S$ points toward the convex side. 

It is said to be \emph{locally uniformly convex} if moreover those graphs are graphs of $C^2$ functions with positive definite Hessian matrix. 
\end{definition}


\begin{definition}[Isomorphism of affine spacetimes]
\label{def isomorphism of affine spacetimes}
An \emph{isomorphism of affine spacetimes} between two $(d+1)$-dimensional affine spacetimes $(M,\C)$ and $(M',\C')$ is a diffeomorphism 
\begin{equation*}
\varphi: M~\longrightarrow~M'
\end{equation*}
such that
\begin{itemize}
\item $\varphi$ preserves the equiaffine structure, i.e. on each chart of the equiaffine structure of $M$ the corestriction of $\varphi$ to a chart of the equiaffine structure of $M'$ is the restriction of an element of $\SA \bp{\A^{d+1}}$,
\item $\varphi$ sends the cone distribution $\C$ to $\C'$, i.e. for all $x$ in $M$,
\begin{equation*}
\dif_x \varphi ( \C_x) = \C'_{\varphi(x)}.
\end{equation*}
\end{itemize}
\end{definition}

\begin{remark}
Imposing a parallel cone structure is a natural choice generalising the Lorentzian case, where the distribution of isotropic cones in the tangent bundle is parallel for the Levi-Civita connexion of the metric.
\end{remark}

\section{Backgrounds}
\label{sec Backgrounds}

Now, let us recall a few results from two classical theories which will prove useful for our work.

\subsection{Background on affine differential geometry and affine spheres}

This subsection is composed of a few results and definitions concerning \emph{affine differential geometry} and \emph{affine spheres}. For a more complete and deeper overview on those notions we refer the reader to \cite{Nomizu_Sassaki_95,Loftin_10,LSZH_15}.

Affine differential geometry studies smooth hypersurfaces $\Sigma$ embedded in $\A^{d+1}$ through the following method. The datum of a transverse vector field $N: \Sigma~\longrightarrow~\V^{d+1}$ allows one to decompose the tangent space at each point $p \in \Sigma$ as the direct sum 
\begin{equation*}
\mathrm{T}_p\A^{d+1} = \mathrm{T}_p\Sigma \oplus \bigl\langle N(p)\bigr\rangle.
\end{equation*}
Using that decomposition, one can define \emph{affine invariants} of $(\Sigma,N)$:
\begin{itemize}
\item the \emph{induced affine connection} $\nabla$ and the \emph{induced affine fundamental form} or \emph{Blaschke fundamental form} $h \in \Gamma(\mathrm{T}^*\Sigma \otimes \mathrm{T}^*\Sigma)$, determined by
\begin{equation*}
D_X Y =\nabla_X Y + h(X,Y) N,
\end{equation*}
\item the \emph{affine shape operator} $S \in \Gamma(\mathrm{T}^*\Sigma \otimes \mathrm{T}\Sigma)$ and the \emph{transversal connection form} $\tau \in \Gamma(\mathrm{T}^*\Sigma)$, determined by 
\begin{equation*}
D_X N =S(X) + \tau(X) N,
\end{equation*}
\item the \emph{affine Gauss-Kronecker curvature} $\phi \in C^\infty(\Sigma,\R)$, defined by
\begin{equation*}
\phi = \det S,
\end{equation*}
\item the \emph{induced volume form $\nu \in \Gamma\bp{\bigwedge^{d+1}\mathrm{T}^*\Sigma}$}, defined by 
\begin{equation*}
\nu(X_1, \dots, X_d) = \det(X_1, \dots, X_d,N),
\end{equation*}
\item in the case where the Blaschke fundamental form $h$ is non degenerate, the \emph{volume form $\dif \, \vol_h \in \Gamma\bp{\bigwedge^{d+1}\mathrm{T}^*\Sigma}$ induced by} $h$ on $\Sigma$.
\end{itemize}
Given an open set $U \subseteq \R^d$, a smooth immersion $f: U~\longrightarrow~\A^{d+1}$ and a smooth map $N: U~\longrightarrow~\V^{d+1}$ transversal to $f$, the above invariants can all directly be defined on $U$ by pullback. In order to lighten them, all the following definitions and propositions will be stated for smooth hypersurfaces, but once again they can be extended to smoothly immersed hypersurfaces.

\begin{definition}[Equiaffine and normal affine fields]
A transverse vector field $N$ on $\Sigma$ a smooth hypersurface in $\A^{d+1}$ is said to be \emph{equiaffine} if the transversal connection form $\tau$ vanishes. An equiaffine vector field is said to be an \emph{affine normal field} if moreover $\nu = \dif \, \vol_h$. 
\end{definition}

\begin{proposition}
\label{prop facts about aff diff geo}
Let $\Sigma$ be a smooth hypersurface in $\A^{d+1}$. Here are some fundamental facts from the theory of affine differential geometry.
\begin{itemize}
\item The rank and signature of the affine fundamental form $h$ only depend on $\Sigma$ and not on the choice of the transverse vector field $N$. Thus $\Sigma$ is said to be \emph{non-degenerate} if $h$ is, in that case $h$ is a genuine pseudo-Riemannian metric. 
\item If $\Sigma$ is locally convex, it is non-degenerate if and only if it is \emph{locally uniformly convex}, meaning that $\Sigma$ can locally be parametrized as the graph of a map with positive definite Hessian matrix. Then $h$ is a Riemannian metric if and only if the transverse vector field $N$ is pointing towards the convex side.
\item Any non-degenerate hypersurface admits a unique (up to sign) affine normal.
\end{itemize}
\end{proposition}

\begin{definition}[Affine conormal field]
\label{def conormal}
Let $\Sigma$ be a smooth hypersurface in $\A^{d+1}$ with an affine normal field $N$. Its \emph{affine conormal field} $N^*:\Sigma
~\longrightarrow~\bp{\V^{d+1}}^*$ is the field defined in the following way: for all $p\in \Sigma$, $l=N^*(p)$ is the unique linear form such that 
\begin{equation*}
l\bp{N(p)} = 1 \quad \textup{and} \quad \ker l = \mathrm{T}_p \Sigma. 
\end{equation*}
\end{definition}

\begin{definition}[Blaschke metric]
\label{def Blaschke metric}
Let $\Sigma$ be a smooth locally uniformly convex hypersurface in $\A^{d+1}$. The Riemannian metric $h$ given by the unique affine normal pointing towards the convex side of $\Sigma$ is called the \emph{affine metric} or \emph{Blaschke metric}.
\end{definition}

\begin{definition}[Affine sphere]
A non-degenerate hypersurface $\Sigma$ is called an \emph{affine sphere} if its shape operator with respect to an affine normal field is of the form $S = \lambda \, \Id$, where $\lambda$ is a real constant. It is called \emph{proper} if $\lambda \neq 0$ and \emph{improper} if $\lambda = 0$. If $\Sigma$ is locally convex, then it is called \emph{hyperbolic} if for the affine normal pointing towards the convex side $\lambda > 0$ and \emph{elliptic} if for that normal $\lambda < 0$.
\end{definition}
It can be shown that being a proper affine sphere with shape operator $\lambda \, \Id$ is a condition equivalent to the existence of a point $o \in \A^{d+1}$, called the \emph{centre of the affine sphere}, such that $N(p) = \lambda \, \overrightarrow{op}$ is an affine normal field.

\begin{theorem}[Cheng--Yau \cite{Cheng_Yau_77,Gigena_81,Cheng_Yau_86}]
\label{theo Cheng--Yau V1}
For any open proper convex cone $\C \subseteq \A^{d+1}$, there exists
a unique complete hyperbolic affine sphere $\S \subset \C$ centred at the vertex of $\C$, asymptotic to $\partial \C$ with affine shape operator the identity.
\end{theorem}
Here, \emph{proper} again means that the cone is non-empty and with closure containing no entire line. The hypersurface is \emph{complete} in the sense that the Riemannian metric on it induced by the ambient Euclidean metric is complete\footnote{In the case of an hyperbolic affine sphere, it is equivalent to completeness of the Blaschke metric \cite[Theorem 3.54]{LSZH_15}, but in a more general setting it is important to keep in mind the differences between the distinct kinds of completeness. A whole discussion on that subject can be found in \cite[Section 3.4]{LSZH_15}.}, and it is \emph{asymptotic to $\partial \C$} in the sense that the distance from $X \in \Sigma$ to $\partial \C$ with respect to an ambient Euclidean metric tends to $0$ as $X$ goes to infinity in $\A^{d+1}$. 

\begin{proposition}[{\cite[Proposition 1]{Gigena_81}}]
\label{prop dual of an affine sphere is affine sphere} Let $\Sigma \subset \R^{d+1}$ be a proper affine sphere. The image of the conormal map $N^*$ (Definition~\ref{def conormal}) on $\Sigma$ is a proper affine sphere in $\bp{\V^{d+1}}^*$ (seen as an affine space) centred at the origin. We shall call it the \emph{affine sphere dual to $\Sigma$}. 

If $\Sigma$ is locally convex, then $N^*(\Sigma)$ is of the same type (elliptic or hyperbolic) as $\Sigma$. 
\end{proposition}

\subsection{Background on convex analysis and Legendre--Fenchel transform}

Here are a few useful notions and results from \emph{convex analysis}, we refer the reader to the classic literature \cite{Rockafellar_97} for a richer view of the basis of the theory.

\begin{definition}[Legendre--Fenchel transform]
\label{def Legendre--Fenchel transform}
The \emph{Legendre--Fenchel transform} or \emph{Legendre--Fenchel conjugate} of a lower semi-continuous function $s: \R^d~\longrightarrow~\R \cup \{+\infty\}$ is the function $s^*:\bp{\R^d}^*~\longrightarrow~\R \cup \{+\infty\}$ defined by 
\begin{equation*}
s^*(l) = \sup_{x \in \R^d}\bp{l(x) - s(x)}.
\end{equation*}
Equivalently, using the usual scalar product $\cdot$ on $\R^d$ to identify $\bp{\R^d}^*$ to $\R^d$, it is defined on $\R^d$ by 
\begin{equation*}
s^*(y) = \sup_{x \in \R^d}\bp{x \cdot y - s(x)}.
\end{equation*}
\end{definition}

The Legendre--Fenchel transform is a standard and fundamental object in analysis. It can easily be shown that:
\begin{itemize}
\item it is order reversing, in the sense that if $s \leq f$ then $f^* \leq s^*$,
\item if $c$ is a constant function $(s + c)^* = s^*-c$ ,
\item the Legendre--Fenchel transform of a function is lower semi-continuous and convex,
\item the \emph{biconjugate} $s^{**}$ of a function is its convex hull, that is the pointwise largest lower semi-continuous convex function bounded above by $s$. Hence if $s$ is convex and lower semi-continuous then $s^{**}=s$, and for any function $s$ (not necessarily convex) there are no new higher conjugates after the biconjugate as $s^{***}=s^*$.
\end{itemize}

The \emph{domain} of a convex lower semi-continuous function $s: \R^d~\longrightarrow~\R \cup \{+\infty\}$ is the convex domain \begin{equation*}
\dom(s) \coloneqq \left\lbrace x \in \R^d \st s(x) < +\infty \right\rbrace.
\end{equation*}

\begin{proposition}
\label{prop conjugate are Lipschitz}
If $s$ is a lower semi-continuous convex function on $\R^d$ with non-empty domain $\mathrm{dom}(s)$ included in the Euclidean ball $B_{\mathrm{Euc}}(0,r)$, then $s^*$ has finite values and is $r$-Lipschitz on the whole $\R^d$. 
\end{proposition}
Thus, if $U$ is a bounded open convex subset of $\R^d$ one can define the conjugate of a continuous convex function $s:U~\longrightarrow~\R$ by taking the conjugate of the unique lower semi-continuous function restricting to $s$ on $U$, taking value $+\infty$ on $\R^d \setminus\bar{U}$ and values in $\R \cup \{+\infty\}$ on $\partial U$. Then $s^*$ has finite values on all $\bp{\R^d}^*$ and $(s^{**})_{\vert U} = s$.

\begin{proposition}
\label{prop uniform convergence of conjugates}
Let $U$ be a bounded open convex subset of $\R^d$. A sequence $s_n$ of convex functions $U~\longrightarrow~\R$ uniformly converges to some convex function $s: U~\longrightarrow~\R$ if and only if $f_n=s_n^*: \R^{d}~\longrightarrow~\R$ uniformly converges to some convex function $f:\R^{d}~\longrightarrow~\R$ . 
\end{proposition}
\begin{proof}
For $s$ a finite valued convex function on $U$ with conjugate $f$, as $(s^{**})_{\vert U}=s$ and $(s_n^{**})_{\vert U}=s_n$, using the order reversing property of the the Legendre--Fenchel transform we get the equivalence
\begin{equation*}
s_n-\varepsilon \leq s \leq s_n+ \varepsilon \iff f_n-\varepsilon \leq f \leq f_n+ \varepsilon. \qedhere
\end{equation*}
\end{proof}

\begin{definition}[Subgradient and subdifferential]
\label{def subgrad subdif}
Let $s: \R^d~\longrightarrow~\R \cup \{+\infty\}$ be a lower semi-continuous convex function and $x_0 \in \R^d$, a linear form $l \in \bp{\R^d}^*$ is a \emph{subgradient} of $s$ at $x_0$ if for all $x\in \R^d$
\begin{equation*}
s(x_0) + l(x-x_0) \leq s(x).
\end{equation*}
From now on, we shall use the usual scalar product $\cdot$ on $\R^d$ to identify $(\R^d)^*$ to $\R^d$, a subgradient of $s$ at $x_0$ can then be seen as a vector $y\in \R^d$ such that for all $x\in \R^d$ 
\begin{equation*}
s(x_0) + (x-x_0) \cdot y \leq s(x).
\end{equation*}
The set of all subgradients of $s$ at $x_0$ is a convex set of $\R^d$ called the \emph{subdifferential} of $s$ at $x_0$ and is denoted by $\partial s(x_0)$. If $x_0$ is in the interior of $\dom(s)$ its subdifferential is non-empty.
\end{definition}

One can easily see that in the most general case
\begin{equation*}
\partial s_1(x) +\partial s_2(x) \subseteq \partial (s_1+s_2)(x).
\end{equation*}
In some cases, that even becomes an equality.

\begin{theorem}[{\cite[Theorem 23.8]{Rockafellar_97}}]
\label{theo equality of sum of differentials}
Let $s_1,s_2: \R^d~\longrightarrow~\R \cup \{+\infty\}$ be lower semi-continuous convex functions such that $\dom(s_1) \cap \dom(s_2)$ has non-empty interior, then for all $x \in \R^d$,
\begin{equation*}
\partial s_1(x) +\partial s_2(x) = \partial (s_1+s_2)(x)
\end{equation*}
\end{theorem}


\begin{proposition}[Fenchel Inequality]
\label{prop equality for subgradients}
Let $s$ be a lower semi-continuous convex function $s$ on $\R^d$ and $x,y \in \R^d$. The following, known as the \emph{Fenchel inequality}, holds:
\begin{equation}
\label{eq Fenchel Inequality}
x \cdot y \leq s(x) + s^*(y).
\end{equation} 
Moreover the following conditions are equivalent:
\begin{enumerate}[label=(\roman*)]
\item the equality is achieved,
\item $y\in \partial s(x)$,
\item $x\in \partial s^*(y)$. 
\end{enumerate}
\end{proposition}

\begin{proposition}[{\cite[Theorems 25.1 and 25.5]{Rockafellar_97}}]
\label{prop C1 convex function}
Let $s: \R^d~\longrightarrow~\R\cup\{+\infty\}$ be a lower semi-continuous convex function. It is differentiable at a point $x \in \dom (s)$ if and only if its subdifferential $\partial s(x)$ is a singleton. In that case $\partial s(x) = \left\lbrace \grad s(x) \right\rbrace$ where $\grad$ is the gradient for the usual scalar product $\cdot$ on $\R^d$ that we used for duality.

A lower semi-continuous convex function $s: \R^d~\longrightarrow~\R \cup \{+\infty\}$ is $C^1$ on a non-empty open set $U \subseteq \dom(s)$ if and only if at every point of $U$ its subdifferential is a singleton. 
\end{proposition}

\begin{proposition}
\label{prop strictly convex gives C1 conjugate}
Let $U$ be a bounded open subset of $\R^d$ and $s: U~\longrightarrow~\R$ a convex function. The Legendre--Fenchel transform $f = s^*: \R^n~\longrightarrow~\R$ is a $C^1$ function if and only if $s$ is strictly convex.
\end{proposition}
\begin{proof}
\textbullet\ Assume that $s$ is strictly convex. Let $y \in \R^d$, for all $x \in \partial f(y)$, using Proposition~\ref{prop equality for subgradients} we have 
\begin{equation*}
s(x) = x \cdot y-f(y).
\end{equation*}
Hence, if $x, x' \in \partial f(y)$, for all $t \in [0,1]$ we have $(1-t) x+t x' \in \partial f(y)$ and 
\begin{equation*}
s\bp{(1 - t) x + t x'}=(1 - t) x \cdot y + t x' \cdot y- f(y) = (1 - t) s(x)+t s(x'),
\end{equation*}
but as $s$ is strictly convex that means that $x = x'$ and hence $\partial f(y) = \{x\}$ so $f$ is $C^1$ by Proposition~\ref{prop C1 convex function}.

\textbullet\ Assume that $s$ is not strictly convex. Let $x,x'$ be two distinct point of $U$ such that for all $t \in [0,1]$
\begin{equation*}
s\bp{(1 - t) x + t x'} = (1 - t) s(x)+t s(x').
\end{equation*}
Let $y\in \partial s\vp{\frac{x+x'}{2}}$ be a subgradient of $s$ at $\frac{x+x'}{2}$. We claim that $y$ is then also a subgradient of $s$ at $x$ and $x'$, meaning by Proposition~\ref{prop equality for subgradients} that $\left\lbrace x,x'\right\rbrace \subset \partial s^*(y)$ and thus that $ s^*(y)$ is not a singleton and $f=s^*$ is not $C^1$, by Proposition~\ref{prop C1 convex function}. Let us prove our claim, using the definition of a subgradient (Definition~\ref{def subgrad subdif}) we get that $y\in \partial s \vp{\frac{x+x'}{2}}$ satisfies 
\begin{equation*}
s \vp{\frac{x+x'}{2}} + \frac{x-x'}{2} \cdot y \leq s(x) \quad \textup{and} \quad s \vp{\frac{x'+x}{2}} + \frac{x'-x}{2} \cdot y \leq s(x').
\end{equation*}
The sum of these inequalities is $ 2 s \vp{\frac{x+x'}{2}} \leq s(x)+s(x')$, which happens to be an equality, thus both those inequalities must be equalities, so that 
\begin{equation*}
s \vp{\frac{x+x'}{2}} + \frac{x-x'}{2} \cdot y = s(x) \quad \textup{and} \quad s \vp{\frac{x'+x}{2}} + \frac{x'-x}{2} \cdot y = s(x').
\end{equation*}
Using Proposition~\ref{prop equality for subgradients} we have 
\begin{equation*}
s(x)= s\vp{\frac{x+x'}{2}} + \frac{x-x'}{2} \cdot y = s^*(y) + \frac{x+x'}{2} \cdot y + \frac{x-x'}{2} \cdot y = s^*(y) + x \cdot y,
\end{equation*}
meaning that $y \in \partial s(x)$. Similarly we have $y \in \partial s(x')$.
\end{proof}

\section{\texorpdfstring{$\C$-convex domains in the affine spacetime $\bp{\A^{d+1},\C}$}{C-convex domains in the affine spacetime (A,C) }}
\label{sec About C-convex domains}

This section is devoted to generalisations of notions and tools from convex geometry in the Minkowski space to the model affine spacetimes $\bp{\A^{d+1},\C}$ (introduced in subsection~\ref{subsec affine spacetimes}).


In this whole section, we let $\C$ be an open proper convex cone in an affine space of dimension $d+1$, that is a non-empty open convex cone with closure containing no entire line. We choose the vertex of the cone as our base point, so that our affine space is identified with $\R^{d+1}$ through a parametrisation such that 
\begin{equation}
\label{eq expression of C}
\C = \left\lbrace t (x,1) \st x \in \Omega, t>0 \right\rbrace,
\end{equation}
where $\Omega$ is a bounded open convex domain of $\R^d$ containing $0$. We are thus working inside the affine spacetime $\bp{\R^{d+1},\C}$, where the cone distribution is given at any point $X \in \R^{d+1}$ by $\C_X = \C \subset \R^{d+1} = \mathrm{T}_X\R^{d+1}$.

In an attempt to keep a coherent and consistent notation that allows the reader to easily identify in which spaces each element lies, we shall use the following notations:
\begin{itemize}
\item an element of $\R^d$ will be denoted by $x$ and an element of $\R^{d+1}$ by $X$,
\item when using the usual scalar product on $\R^d$ and $\R^{d+1}$ for duality identifications, dual elements will be denoted by $y \in \R^d = \bp{\R^d}^*$ and $Y \in \R^{d+1} = \bp{\R^{d+1}}^*$.
\end{itemize}

\subsection{\texorpdfstring{$\C$-convex and $\C$-regular domains}{C-convex and C-regular domains}}

Following the work of Nie and Seppi \cite{Nie_Seppi_22}, we generalise standard notions from Lorentzian Minkowski geometry to the affine spacetime $\bp{\R^{d+1},\C}$.

\begin{definition}[Supporting hyperplane and Gauss map]
Let $K$ a convex domain of $\R^{d+1}$ (it is thus open). 

An affine hyperplane $H$ is said to be a \emph{supporting hyperplane of $K$} if $H \cap K = \emptyset$ and there is a point $X \in H \cap \partial K$.

The \emph{Gauss map} of $K$ is a set-valued map which maps each point $X$ of $\partial K$ to the set of linear hyperplanes directing a supporting hyperplane of $K$ at $X$.
\end{definition}

Let $K$ be an open convex domain which is defined as an intersection of the future sides of $\C$-spacelike hyperplanes of $\R^{d+1}$. Note that it may have $\C$-null supporting hyperplanes (for instance, that is the case of the cone $\C$). We will denote by $\partial_{sp} K$ the part of the boundary $\partial K$ of $K$ which admits $\C$-spacelike supporting hyperplanes (Definition~\ref{def C-sp C-n hyperplanes}). 

\begin{definition}[$\C$-convex and $\C$-regular domains]
\label{def C-convex and C-regular domains}

A \emph{$\C$-convex domain} is a convex domain $K \subset \R^{d+1}$ which is an intersection of the future sides of $\C$-spacelike hyperplanes of $\R^{d+1}$ and such that the restriction of its Gauss map to $\partial_{sp} K$ is surjective onto $\mathcal{H}_{sp}(\C)$ (Definition~\ref{def C-sp C-n hyperplanes}). 

A $\C$-convex domain $K$ is called \emph{$\C$-spacelike} if all its supporting hyperplanes are spacelike, i.e. if it satisfies $\partial K = \partial_{sp}K$.

A $\C$-convex domain $K$ is called $C^2_+$ if its spacelike boundary $\partial_{sp}K$ is a $C^2$ hypersurface and the restriction of its Gauss map to $\partial_{sp} K$ is a $C^1$ diffeomorphism (for the differentiable structure of the Grassmannian $\mathrm{Gr}_d\bp{\R^{d+1}}$, which is the space of linear hyperplanes of $\R^{d+1})$. 

A \emph{$\C$-regular domain} is a $\C$-convex domain which can be expressed as the intersection of the future sides of only $\C$-null hyperplanes. 
\end{definition}

\begin{remark}
A trivial example of a $\C$-regular domain is the cone $\C$ itself: it is the intersection of the future sides of all its $\C$-null supporting hyperplanes. Its spacelike boundary is its vertex: $\partial_{sp} \C = \left\lbrace 0 \right\rbrace$.
\end{remark}

\subsection{Support functions and affine sphere}
\label{subsec support functions and affine sphere}
We shall now use the convex geometry tools developed in \cite{Fillastre_Veronelli_16, Bonsante_Fillastre_17, Barbot_Fillastre_20, Nie_Seppi_22} in this more general setting. We set $\C^*$ to be the \emph{polar cone} to $\C$ defined as the open proper convex cone 
\begin{equation*}
\C^* \coloneqq \mathrm{int} \left\lbrace l \in \bp{\R^{d+1}}^* \st l(X) \leq 0, \forall X \in \C\right\rbrace.
\end{equation*}
Equivalently,
\begin{equation*}
 \C^* = \left\lbrace l \in \bp{\R^{d+1}}^* \st l(X)<0, \forall X \in \overline{\C} \setminus \{0\} \right\rbrace.
\end{equation*}
For $K$ a $\C$-convex domain of $\R^{d+1}$, we set its \emph{total support function} $\tilde{s}_K$ (only denoted by $\tilde{s}$ when there is no possible confusion) to be the function
\begin{equation*}
\function{\widetilde{s}_K}{\C^*}{\R}{l}{\sup \left\lbrace l(X) \st X \in K\right\rbrace},
\end{equation*}
which is well-defined (the supremum is always finite) by definition of $\C$-convex domains (Definition~\ref{def C-convex and C-regular domains}. It is also clearly sublinear and $1$-homogeneous, hence convex.

From now on, using the usual scalar product $\cdot$ on $\R^{d+1}$, we identify $\bp{\R^{d+1}}^*$ to $\R^{d+1}$. Using identity \eqref{eq expression of C}, that allows us to see $\C^*$ as
$\C^* = \left\lbrace t(y,-1) \st y \in \Omega^*, t>0 \right\rbrace$ where $\Omega^*$ is the bounded open convex domain of $\R^d$ containing $0$ defined by
\begin{equation*}
\Omega^* = \left\lbrace y \in \R^d \st x \cdot y < 1 , \forall x \in \overline{\Omega} \right\rbrace.
\end{equation*}
We define $s_K:\Omega^*~\longrightarrow~\R$, the \emph{$\Omega^*$-support function} of a $\C$-convex domain $K$ by $s_K (y)=\tilde{s}_K(y,-1)$. The total support function is $1$-homogeneous so that for all $Y = (y,-\mu)$ in $\C^*$,
\begin{equation*}
\tilde{s}_K(Y)=\tilde{s}_K(y,-\mu)=\mu \, s_K\vp{\frac{y}{\mu}}.
\end{equation*}
As a total support function $\tilde{s}$ can fully be reconstructed from an $\Omega^*$-support function $s$, we shall mostly use the $\Omega^*$-support functions of $\C$-convex domains. In order to lighten notations we shall simply write that $s$ is the \emph{support function of $K$}. 

\begin{proposition}
\label{prop K is epigraph}
Let $K$ be a $\C$-convex domain of $\R^{d+1}$ with support function $s$. The hypersurface $\partial K \subset \R^{d+1}=\R^d \times \R$ is the graph of $f=s^*$ the Legendre--Fenchel transform of $s$ (Definition~\ref{def Legendre--Fenchel transform}). 
\begin{equation*}
\partial K = \graph(f) \coloneqq \left\lbrace \bp{x,f(x)} \st x \in \R^{d} \right\rbrace.
\end{equation*}
The domain $K$ is then its epigraph: 
\begin{equation*}
K = \epi(f) \coloneqq \left\lbrace (x,\lambda)\in \R^d \times \R \st \lambda > f(x) \right\rbrace.
\end{equation*}
\end{proposition}
\begin{proof}
For $y\in \Omega^*$,
\begin{equation*}
s(y)=\tilde{s}(y,-1)= \sup_{(x,\lambda)\in K} (x,\lambda)\cdot(y,-1)= \sup_{(x,\lambda)\in K} (x\cdot y - \lambda).
\end{equation*}
Since the supporting half-spaces of $K$ are $\C$-spacelike and hence not vertical in our coordinates (as $0\in \Omega^*$, we have $(0,\cdots,0,1)\in \C$), one can see $\partial K$ as a graph: $\partial K = \graph(f)$ for some convex function $f:\R^d~\longrightarrow~\R$. Hence the previous equation becomes
\begin{equation*}
s(y)= \sup_{x\in \R^d} \bp{x\cdot y - f(x)} = f^*(y),
\end{equation*}
and as $f$ is convex that means that $f=f^{**}=s^*$, $\partial K = \graph(f) = \graph(s^*)$, and $K=\epi(f)$.
\end{proof}
Conversely, it is clear that any convex function $s:\Omega^*~\longrightarrow~\R$ gives a $\C$-convex domain, denoted by $K(s)$, by taking the epigraph of its Legendre--Fenchel transform $f=s^*$, which is finite over the whole $\R^d$ by Proposition~\ref{prop conjugate are Lipschitz}. 

This \emph{tube domain} $\Omega^*\times \R$, in which the graphs of support function live, generalises the setting of \emph{co-Minkowski geometry} \cite{Fillastre_Seppi_19,Barbot_Fillastre_20}, also known as \emph{‘‘half-pipe'' geometry} \cite{Danciger_13}. The duality with that tube domain was already used and studied in the work of Choi \cite{Choi_17,Choi_25}, Nie and Seppi \cite{Nie_Seppi_22,Nie_Seppi_23}, or Bobb and Farre \cite{Bobb_Farre_24}.

\begin{figure}[ht]
\centering
\includegraphics{Duality_on_convex.pdf}
\caption{Convex duality in dimension $d+1 =2$.}
\label{Duality figure}
\end{figure}

Figure~\ref{Duality figure} illustrates that duality between $\C$-convex domains and convex graphs in the tube domain $\Omega^*\times \R$. It shows points 
\begin{equation*}
 X_0 = \bp{x_0,s^*(x_0)} \in \R^{d+1} \quad \textup{and} \quad Y_0 = \bp{y_0,s(y_0)} \in \Omega^*\times \R,
\end{equation*}
with $x_0 \in \partial s(y_0)$. Proposition~\ref{prop equality for subgradients} implies that the hyperplanes 
\begin{equation*}
 H_{Y_0} = \left\lbrace \bp{x,\lambda} \in \R^{d+1} \st x\cdot y_0 -\lambda = s(y_0)\right\rbrace \quad \textup{and} \quad H_{X_0} = \left\lbrace\bp{y,\nu} \in \Omega^*\times \R \st x_0 \cdot y - \nu = s^*(x_0) \right\rbrace,
\end{equation*}
are supporting hyperplanes of respectively $\graph(s^*)$ and $\graph(s)$.


In that setting, Theorem~\ref{theo Cheng--Yau V1} can now be more precisely stated.

\begin{theorem}[Cheng--Yau, \cite{Cheng_Yau_77,Gigena_81,Cheng_Yau_86}]
\label{theo Cheng--Yau V2}
Let $\C$ be open proper convex cone in the affine space $\A^{d+1}$, there is a unique complete hyperbolic affine sphere $\S \subset \C$ asymptotic to $\partial \C$ with shape operator the identity. Parametrising $\A^{d+1}$ as $\R^{d+1}$ so that $\C = \left\lbrace t (x,1) \st x \in \Omega, t>0 \right\rbrace$ with $\Omega$ a bounded convex domain containing $0$, $\S$ is the graph of the Legendre--Fenchel transform of the unique convex function $\omega_\C$ satisfying the Monge--Ampère equation 
\begin{equation*}
\begin{cases}
\det \Hess \omega= (-\omega)^{-d-2} \textup{ in } \Omega^*,\\
\omega_{\vert \partial\Omega^*} =0.
\end {cases}
\end{equation*}
Moreover, $\omega_\C$ satisfies $\lim_{y \to y_0} \left\vert \grad \omega_\C(y) \right\vert = +\infty$ for all $y_0 \in \partial \Omega^*$.

Then, $\S^*$ the affine sphere polar to $\S$ (the opposite of the dual affine sphere from Proposition~\ref{prop dual of an affine sphere is affine sphere}) is the unique complete hyperbolic affine sphere with shape operator the identity and asymptotic to $\partial \C^*$. It is given by the image of $-N^*_{\S}$, the opposite of the conormal map on the affine sphere (Definition~\ref{def conormal}): 
\begin{equation*}
\Sigma_{(\C^*)} = \S^* = \left\lbrace -\frac{1}{\omega_\C(y)} (y,-1) \st y \in \Omega^*\right\rbrace.
\end{equation*} 
\end{theorem}

\begin{figure}[ht]
\centering
\includegraphics{Cheng--Yau_affine_sphere.pdf}
\caption{The affine sphere given by the theorem of Cheng and Yau.}
\label{Affine sphere figure}
\end{figure}

\begin{corollary}
\label{cor affine sphere invariance}
Let $\C$ be open proper convex cone in the affine space $\A^{d+1}$. The affine sphere $\S=\graph(\omega_\C^*)$ from Theorem~\ref{theo Cheng--Yau V2} is preserved by $\mathrm{Aut}_{\SA}(\C)$, the subgroup of elements of $\SA\bp{\A^{d+1}}$ preserving the cone $\C$.
\end{corollary}
\begin{proof}
The action of an element $A \in \mathrm{Aut}_{\SA}(\C)$ on $\A^{d+1}$ preserves the cone $\C$ and the volume, so it necessarily preserves the unique affine sphere $\S$ given by Theorem~\ref{theo Cheng--Yau V2}.
\end{proof}

\begin{remark}[The Minkowski case]
\label{rem the Minkowski case}
In the case where $\Omega$ is the Euclidean unit ball $\mathbb{B}^d$ in $\R^d$, then $\C$ is the Minkowski future light cone given by the inequalities $x_1^2 + \dots + x_d^2 - x_{d+1}^2 < 0$ and $x_{d+1}>0$, and $\Omega^* = \mathbb{B}^d$ is the unit ball given by $y_1^2 + \dots + y_d^2 < 1$. The support function of the affine sphere is $\omega_\C (y) = -\sqrt{1 - y_1^2 - \dots - y_d^2}$ and the affine sphere $\S$ is the hyperboloid $\mathbb{H}^d \subset \R^{d+1}$ given by the equation $x_1^2 + \dots + x_d^2 - x_{d+1}^2 = -1$ and $x_{d+1}>0$. The polar affine sphere $\S^*$ is also a hyperboloid given by the equation $y_1^2 + \dots + y_d^2 - y_{d+1}^2 = -1$ and $y_{d+1}<0$.
\end{remark}

We define $\overline{s}:\S^*~\longrightarrow~\R$, the $\S^*$-support function of a $\C$-convex domain $K$, by $\overline{s} = \tilde{s}_{\vert \S}$. 
Let us introduce the radial identification on the dual affine spheres:
\begin{equation*}
\function{R^*}{\S^*}{\Omega^*}{(y,\mu)}{-\frac{y}{\mu}} \quad \textup{with inverse} \quad \function{\bp{R^*}^{-1}}{\Omega^*}{\S^*}{y}{ -\frac{1}{\omega_\C(y)} (y,-1)}.
\end{equation*}
Notice that because $\tilde{s}$ is 1-homogeneous and because of the expression of $\S^*$ given by Theorem~\ref{theo Cheng--Yau V2}, it also satisfies $ \overline{s}=-\frac{s}{\omega_\C}\circ R^*$. Thus the affine sphere $\S$ has the constant function $-1$ for $\S^*$-support function.

\subsection{Gauss map}

Notice that this duality setting gives a smooth diffeomorphism between $\Omega^*$ and $\mathcal{H}_{sp}(\C)$, and a homeomorphism between $\partial \Omega^*$ and $\mathcal{H}_n(\C)$; by $y \mapsto \left\lbrace X \in \R^{d+1} \st X \cdot (y,-1) =0 \right\rbrace$.

Let $K$ be a $\C$-convex domain with support function $s$. Using those identifications, we now see the restriction to $\partial_{sp} K$ of the Gauss map as a set-valued map with values in $\Omega^*$. It can be expressed as 
\begin{equation}
\label{eq gauss map def}
\function{\G_{K}}{\partial_{sp} K}{\mathcal{B}(\Omega^*)}{X}{\partial s^*\bp{\pi(X)}},
\end{equation}
where $\mathcal{B}(\Omega^*)$ is the Borel algebra of $\Omega^*$, and $\pi$ is the projection $\function{\pi}{\R^{d+1}}{\R^{d}}{X=(x,\lambda)}{x}$. 

If $s$ is strictly convex, and thus $s^*$ is $C^1$ by Proposition~\ref{prop strictly convex gives C1 conjugate}, one can even express it as a true map
\begin{equation*}
\label{eq expression of the Gauss map}
\function{\G_{K}}{\partial_{sp} K}{\Omega^*}{X}{\grad s^*\bp{\pi(X)}}.
\end{equation*}

Using the Fenchel inequality (Proposition~\ref{prop equality for subgradients}), we get that $\G_K$ is invertible if and only if $s$ has a gradient at each point of $\Omega^*$, in that case $s$ is $C^1$ (Proposition~\ref{prop C1 convex function}) and the inverse of the Gauss map is expressed as 
\begin{equation}
\label{eq expression of the inverse of the Gauss map}
\function{\G_{K}^{-1}}{\Omega^*}{\partial_{sp} K}{y}{\bp{\grad s(y) , \grad s(y) \cdot y -s (y)}},
\end{equation}
giving a parametrisation of $\partial_{sp}K$ by $\Omega^*$. Then the global inversion theorem gives the following proposition.

\begin{proposition}
\label{prop C2+ support function has positive Hessian}
A $\C$-convex domain is $C^2_+$ (Definition~\ref{def C-convex and C-regular domains}) if and only if its support function is $C^2$ with positive definite Hessian everywhere. We shall call such functions \emph{$C^2_+$ support functions}. 
\end{proposition}

\begin{remark}
\label{rem smooth diffeos}
Notice that the Gauss map of the affine sphere gives a favourite smooth diffeomorphism
\begin{equation*}
\G_{\S}: \S~\longrightarrow~\Omega^*.
\end{equation*}
Moreover the radial identifications in $\R^{d+1}$ and $\bp{\R^{d+1}}^*$ give two favourite smooth diffeomorphisms
\begin{equation*}
R: \S~\longrightarrow~\Omega \quad \textup{and} \quad R^*: \S^*~\longrightarrow~\Omega^*.
\end{equation*}
Thus the followings are all smoothly diffeomorphic 
\begin{equation*}
\Omega \approx \Omega^* \approx \S \approx \S^*.
\end{equation*}
Using $N^*_{\S}$ the affine conormal map on the affine sphere (Definition~\ref{def conormal}), everything can be summarised through the following commutative diagram.

\begin{equation*}
\begin{tikzcd}[column sep = large, row sep = large]
& \Omega^* \\
\S \arrow[ur, "\G_{\S}"] \arrow[rr, "- N^*_{\S}"] \arrow[dr, swap, "R"] && \S^*\arrow[ul, swap, "R^*"] \arrow[dl, "\G_{\S^*}"] \\
& \Omega
\end{tikzcd}
\end{equation*}

\end{remark}

\subsection{\texorpdfstring{Boundary functions, $g$-convex domains and Cauchy developments of $\C$-spacelike surfaces}{Boundary functions, g-convex domainsand Cauchy developments of C-spacelike surfaces}}
\label{subsec Boundary functions and g-convex domains}

As every convex function $s: \Omega^*~\longrightarrow~\R$, i.e. every support function of a $\C$-convex domain, extends uniquely to a convex lower semi-continuous function $s:\overline{\Omega^*}\longrightarrow \R \cup \{+\infty\}$ (using an abusive notation), let us introduce the following objects.


\begin{definition}[$\Omega^*$-boundary function and $g$-convex domain]
\label{def boundary function and g-convex domain}
A function $g:\partial \Omega^*\longrightarrow \R \cup \{+\infty\}$ is an \emph{$\Omega^*$-boundary function} if there exist a convex function $s: \Omega^* \longrightarrow\R$ extending lower semi-continuously to $g$ on the boundary $\partial \Omega^*$. A convex domain $K$, with support function $s_K : \Omega^*~ \longrightarrow~\R\cup\{+\infty\}$ extending lower semi-continuously to $g$ is then called a \emph{$g$-convex domain}.
\end{definition}

\begin{remark}
A $g$-convex domain is not necessarily $\C$-convex, as its support function might take infinite values inside the domain $\Omega^*$. Nevertheless, if $g$ is finitely valued, then every $g$-convex domain is a $\C$-convex domain.
\end{remark}

\begin{definition}[Convex envelope of an $\Omega^*$-boundary function]
\label{def convex envelope}
Let $g:\partial \Omega^*\longrightarrow \R \cup \{+\infty\}$ be an $\Omega^*$-boundary function. The \emph{convex envelope} of $g$ is the pointwise largest convex lower semi-continuous function $s_g : \overline{\Omega^*}\longrightarrow \R \cup \{+\infty\}$ with boundary values on $\partial \Omega^*$ given by $g$. It can be expressed in the following way: for all $y \in \overline{\Omega^*}$,
\begin{equation*}
s_g (y)= \sup \left\lbrace a(y) \st a \textup{ is affine and } a\leq g \textup{ on }\partial \Omega^*\right\rbrace.
\end{equation*}
\end{definition}

Because of the order reversing property of the Legendre--Fenchel  transform, the fact that the convex envelope of an $\Omega^*$-boundary function is the largest support function of a $g$-convex domain clearly implies the following.

\begin{proposition}
\label{prop Dg is maximal}
Let $g:\partial \Omega^*\longrightarrow \R \cup \{+\infty\}$ be an $\Omega^*$-boundary function and consider its convex envelope $s_g : \overline{\Omega^*}\longrightarrow \R \cup \{+\infty\}$. 
\begin{itemize}
 \item If $g$ (and thus $s_g$) is not constant and equal to $+\infty$, by Proposition~\ref{prop conjugate are Lipschitz}, the Legendre--Fenchel  transform $s_g^*:\R^{d}\longrightarrow~\R$ is finite. Then, the convex domain $D_g$ with support function $s_g$, i.e. the epigraph of $s_g^*$, is the maximal $g$-convex domain for inclusion, in the sense that every $g$-convex domain is included in $D_g$.
 \item If $g \equiv +\infty$, then the $g$-convex $D_g\coloneqq\R^{d+1}$, i.e. the epigraph of $s_g^* \equiv -\infty$, is the maximal $g$-convex domain for inclusion.
\end{itemize}

\begin{remark}
Again, the maximal $g$-convex domain $D_g$ is not necessarily $\C$-convex. Nevertheless, if $g$ is finitely valued, then $D_g$ is actually a $\C$-convex domain.
\end{remark}

\end{proposition} 

\begin{proposition}
\label{prop Dg as intersection}
Let $g:\partial \Omega^*~\longrightarrow ~\R~\cup~\{+\infty\}$ be an $\Omega^*$-boundary function. The maximal $g$-convex domain $D_g$, given by Proposition~\ref{prop Dg is maximal}, is $\C$-regular (Definition~\ref{def C-convex and C-regular domains}). It is the intersection of the $\C$-future of the family of $\C$-null affine hyperplanes given by $g: \partial \Omega^*~\longrightarrow~\R~\cup~\{+\infty\}$, that is
\begin{equation*}
D_g = \bigcap_{y \in \partial \Omega^*} \left\lbrace X \in \R^{d+1} \st X \cdot (y,-1) < g(y) \right\rbrace.
\end{equation*}
\end{proposition}
\begin{proof}
Let us set
\begin{equation*}
K_g \coloneqq \bigcap_{y \in \partial \Omega^*} \left\lbrace X \in \R^{d+1} \st X \cdot (y,-1) < g(y) \right\rbrace.
\end{equation*}
If $X \in K_g$, its future $I^+(X) =X +\C$ is a $\C$-regular domain with the affine function $a_X(y) = X \cdot (y,-1)$ as $\C$-support function. By definition of $K_g$, it satisfies $a_X < g $ on $\partial \Omega^*$. Conversely, any affine function $a$ on $\R^d$ can be expressed by $a(y) = X_a \cdot (y,-1)$ where $X_a \in \R^{d+1}$, and then $a < g $ on $\partial \Omega^*$ implies that $X_a\in K_g$. Thus, the support function of $K_g$ is the convex envelope of $g$ (Definition~\ref{def convex envelope}), meaning that $D_g = K_g$ is $\C$-regular, with the desired expression.
\end{proof}

Let us now highlight how maximal $g$-convex domains given by Proposition~\ref{prop Dg is maximal}, which at first seem to be objects purely related to convex geometry, actually have nice causality properties in the affine spacetime $(\R^{d+1},\C)$.

\begin{definition}[Cauchy development]
\label{def Cauchy dev}
The \emph{Cauchy development} of a $\C$-spacelike $C^1$ hypersurface $S$ in $\bp{\R^{d+1}, \C}$ is the set of points $X$ of $\R^{d+1}$ such that all inextensible $\C$-causal curves through $X$ meet $S$. We shall denote it by $D(S)$.
\end{definition}

\begin{proposition}
\label{prop maximal g domain = Cauchy development}
Let $K$ be a $\C$-spacelike $\C$-convex domain (Definition~\ref{def C-convex and C-regular domains}) with $C^1$ boundary and support function $s_K: \Omega~\longrightarrow~\R$ extending lower semi-continuously to an $\Omega^*$-boundary function $g:\partial \Omega^*~\longrightarrow ~\R\cup\{+\infty\}$. Its boundary $\partial K = \partial_{sp} K$ has Cauchy development $D\bp{\partial K}$ equal to the maximal $g$-convex domain $D_g$.
\end{proposition}

\begin{proof}
By hypothesis, the boundary $\partial K=\partial_{sp} K$ is the entire graph of the convex function $s_K^*:\R^{d}~\longrightarrow~\R$.

\textbullet\ First let us show that $D(\partial K)\subseteq D_g$. Let $X=(x,\lambda) \in D(\partial K)$, its future $I^+(X) =X +\C$ is the $\C$-regular domain having the affine function $a_X(y) = x \cdot y - \lambda$ as its support function. As $X$ is in the Cauchy development of $\partial K$, every $\C$-null line through $X$ intersects $\partial K$. Thus every $\C$-null hyperplane through $X$ intersects $\partial K$. 

As $K$ is $g$-convex, it is contained in the maximal $g$-convex domain $D_g$, and thus every $\C$-null hyperplane through $X$ also intersects $D_g$. By Proposition~\ref{prop Dg as intersection}, $D_g$ is the following intersection of $\C$-future sides of $\C$-null hyperplane,
\begin{equation*}
D_g = \bigcap_{y \in \partial \Omega^*} \left\lbrace X \in \R^{d+1} \st X \cdot (y,-1) < g(y) \right\rbrace,
\end{equation*}
Thus, every $\C$-null hyperplane through $X$ directed by a $y \in \partial \Omega^*$ is in the future of the following hyperplane:
\begin{equation*}
 \left\lbrace X \in \R^{d+1} \st X \cdot (y,-1) = g(y) \right\rbrace.
\end{equation*}
Using the support function $a_X$, that means that for all $y \in \partial \Omega^*$, $a_X(y)<g(y)$ (see Figure~\ref{proof Cauchy dev figure}).

As $a_X$ is affine, by definition of $s_g$, the convex envelope of $g$ (Definition~\ref{def convex envelope}), that implies that $a_X < s_g$ on $\Omega^*$, i.e. $X \in D_g$.

\textbullet\ Now, let us show the reverse inclusion $D_g \subseteq D(\partial K)$. Let $X \in D_g$, its support function $a_X$ satisfies that for all $y \in \partial \Omega^*$, $a_X(y)<g(y)$. As $s_K$, the support function of $K$, continuously extends to $g$ on $\partial \Omega^*$, we claim that implies that every $\C$-causal line through $X$ intersects $\partial K$ (see Figure~\ref{proof Cauchy dev figure}). Then, the graph $\partial K = \graph(s_K^*)$ separates $J^+(X) \cup J^-(X) = \bp{X + \overline{\C}} \cup \bp{X - \overline{\C}}$ in two distinct connected components, ensuring that every inextensible causal curves through $X$ meet $\partial K$. That is precisely $X \in D(\partial K)$.

Now, let us prove our claim. Let $L$ be a $\C$-causal line through $X$, it is directed by a vector $V=(x',1) \in \overline{\Omega}\times\left\lbrace1\right\rbrace$ and expressed as
\begin{equation*}
 L = \left\lbrace X_t \coloneqq X + tV \st t \in \R \right\rbrace.
\end{equation*}
The $\C$-convex domain $K$ has a horizontal supporting hyperplane, thus for $t$ small enough we have that $X_t \notin K$. Hence, in order to prove that $L$ intersects $\partial K$, we just have to show that for $t$ large enough we have $X_t \in K$. As the convex $K$ can be expressed as 
\begin{align*}
 K = \epi(s_K^*) = \bigcap_{y \in \Omega^*} \left\lbrace X \in \R^{d+1} \st X \cdot (y,-1) < s_K(y) \right\rbrace,
\end{align*}
we shall prove that for $t$ large enough, we have that for all $y\in \Omega^*$,
\begin{equation*}
 X_t\cdot (y,-1) = a_X(y) + t(x'\cdot y-1) < s_K(y). 
\end{equation*}
Notice that because $s_K$ extends continuously to $g >a_X$ on $\partial \Omega^*$, the subset $A \coloneqq \left\lbrace y \in \Omega^* \st a_X(y)\geq s_K(y)\right\rbrace$ is a compact subset of the convex domain $\Omega^*$. If $A$ is empty we have $a_X < s_K$ on $\Omega^*$ and thus $X=X_0 \in K$. Otherwise, as $A$ is compact and non-empty, we can set $m \coloneqq \min \left\lbrace x' \cdot y -1 \st y \in A \subset \Omega^* \right\rbrace < 0$ (by definition of $\Omega^*)$ and $M \coloneqq \min \left\lbrace s_K(y) - a_X(y) \st y \in A \right\rbrace \in \R$. For $t >0$ and such that $M+tm < 0$, we have that for all $y \in \Omega^*$, if $y \in A$, then 
\begin{equation*}
X_t\cdot (y,-1) = a_X(y) + t(x'\cdot y-1)\leq s_K(y) + M+ tm < s_K(y),
\end{equation*}
otherwise $y \notin A$, and then
\begin{equation*}
X_t\cdot (y,-1) = a_X(y) + t(x'\cdot y-1)\leq a_X(y) < s_K(y),
\end{equation*}
concluding the proof.
\end{proof}

