\centering
\includegraphics{Normal_projection.pdf}
\caption{Normal projection onto the spacelike boundary of a $\C$-convex.}
\label{Normal projection figure}
\end{figure}

\begin{definition}[Normal projection, cosmological time and projecting normal]
\label{def normal projection, cosmological time and projecting normal}
Let $K$ be a $\C$-convex domain. In the decomposition of some element $X \in K$ from Proposition~\ref{prop decomposition},
\begin{itemize}
\item we shall denote $P\in \partial_{sp} K$ by $P_K(X)$ and call it the \emph{normal projection} of $X$ onto $\partial_{sp}K$,
\item we shall denote $t\in \R_+^*$ by $\mathcal{T}_K(X)$ and call it the \emph{cosmological time of $K$} at $X$, 
\item we shall denote $y\in\Omega^*$ by $y_K(X)$ and call it the \emph{projecting normal} from $X$ to $\partial_{sp}K$.
\end{itemize}
\end{definition}

\begin{proposition}
\label{prop TK, PK and yK are continuous}
Let $K$ be a $\C$-convex domain with support function $s$. The cosmological time $\mathcal{T}_K: K~\longrightarrow~\R^*_+$, normal projection $P_K: K~\longrightarrow~\partial_{sp}K$ and projecting normal $y_K: K~\longrightarrow~\Omega^*$ are all continuous.
\end{proposition}
\begin{proof}
\textbullet\ First let us prove that the cosmological time is continuous. The closed epigraph of a continuous function $f: \R^d~\longrightarrow~\R$ is the closed set
\begin{equation*}
\overline{\epi}(f) \coloneqq \left\lbrace (x,\lambda) \in \R^d \times \R \st \lambda \geq f(x) \right\rbrace.
\end{equation*}
For all $I = ]a,b[\subset \R_+^*$, as the functions $(s+a\omega)^*$ and $(s+b\omega)^*$ are continuous, we have that
\begin{equation*}
\mathcal{T}_K^{-1} (I) = \bigcup_{t \in I}\partial K(s + t\omega) = \epi(s+a\omega)^* \setminus \overline{\epi} (s+b\omega)^*
\end{equation*}
is open, so $\mathcal{T}_K$ is continuous.

\textbullet\ Now let us prove that $y_K$ is continuous. Let $X_n$ be a sequence of points of $K$ converging to $X$. We have that $y_K(X_n) =\grad \bp{s+\mathcal{T}_K(X_n)\omega}^*\bp{\pi (X)}$. As $\mathcal{T}_K(X_n)$ converges to $\mathcal{T}_K(X)$, by continuity of $\mathcal{T}_K$, we have that $(s+\mathcal{T}_K(X_n)\omega)^*$ converges pointwise to $(s+\mathcal{T}_K(X)\omega)^*$ and thus using \cite[Theorem 24.5]{Rockafellar_97} we have that $y_K(X_n)$ converges to $y_K(X)=\grad \bp{s+\mathcal{T}_K(X)\omega}^*\bp{\pi (X)}$. 

\textbullet\ Finally, as $P_K = \Id_K - \mathcal{T}_K \times (\G_{\Sigma}^{-1} \circ y_K)$, the continuities of $\mathcal{T}_K$, $\G_{\Sigma}^{-1}$ and $y_K$ imply the continuity of $P_K$. 
\end{proof}

We shall denote the level sets of the cosmological time by 
\begin{equation*}
S_K^t \coloneqq \mathcal{T}_K^{-1}(t) = \partial K (s+t\omega) = \partial_{sp} K(s+t\omega) = \graph(s+t\omega)^*.
\end{equation*}

