\begin{proposition}
\label{prop TK is C1}
Let $K$ be a $\C$-convex domain with support function $s$. The cosmological time $\mathcal{T}_K$ on $K$ is $C^1$ and its gradient at any point $X \in K$ is expressed as 
\begin{equation*}
\grad \mathcal{T}_K (X) = \frac{\bp{y_K(X),-1}}{\omega\bp{y_K(X)}},
\end{equation*}
where $y_K(X)$ is the projecting normal from $X$ to $\partial_{sp}K$.
\end{proposition}
\begin{proof}
Let $X \in K$. In order to lighten the notation, we denote by $P \coloneqq P_K(X) \in \partial_{sp}K$ the normal projection of $X$ onto $\partial_{sp}K$, by $y \coloneqq y_K(X)$ the projecting normal and $N = \G_{\Sigma}^{-1}(y)$. The cone $I^+(P) = P + \C$, is foliated by its intersections with:
\begin{itemize}
\item[-] the level surfaces of the cosmological time $\bp{S^t_K}_{t>0}$,
\item[-] the hyperplanes directed by $y$, i.e. $(P + t \, H_y)_{t>0}$, where $H_y = \left\lbrace V \in \C \st V \cdot (y,-1) = \omega(y) \right\rbrace$,
\item[-] the $\C$-spacelike hypersufaces $\bp{P + t \, \Sigma}_{t>0}$.
\end{itemize}
For any vector $V \in \C$, we set $g(V) \coloneqq \mathcal{T}_K(P+V)$, it is the unique $t>0$ such that $P+V \in S^t_K$. Similarly we define $f(V)$ to be the unique $t>0$ such that $V \in t H_y$, it can explicitly be expressed as
\begin{equation*}
\function{f}{\C}{\R}{V}{\frac{V \cdot (y,-1)}{\omega(y)}}
\end{equation*}
and we set $h(V)$ to be the unique $t>0$ such that $V \in t \Sigma$. 

Inspired by the proof of Bonsante \cite[Proposition 4.3]{Bonsante_05} in the Lorentzian case, we claim that those satisfy the hypothesis of the following fact: 

 Let $U$ be an non-empty open subset of $\R^{d+1}$ and $f,g,h: U~\longrightarrow~\R$ be maps such that:
\begin{itemize}
\item $f \leq g \leq h$,
\item $f$ and $h$ are $C^1$,
\item there exist a point $X_0 \in U$ such that $f(X_0)=g(X_0)=h(X_0)$ and $\dif_{X_0} f = \dif_{X_0} h$.
\end{itemize}
Then $g$ is differentiable at $X$ and $\dif_{X_0} f = \dif_{X_0} g = \dif_{X_0} h$.

Let us prove our claim.

\begin{itemize}
\item Notice that for all $t>0$, $S^t_K = \graph(s+t \omega)^*$ and $P + t \,\Sigma = \graph(a_p+t \omega)^*$, where $a_P(y) = P\cdot (y,-1)$ is the support function of the future cone $I^+(P) = P + \C$. Notice that because $P \in \partial K(s)$, we have $a_P \leq s$ and thus, using the order reversing property of the Legendre--Fenchel transform, $(s+t \omega)^* \leq (a_p+t \omega)^*$ are convex maps with graphs having the common supporting hyperplane $P+t \, H_y$ at $P + t N$ (see Figure~\ref{fig f<g<h}). Hence, by definition of $f,g$ and $h$, we have $f \leq g \leq h$.
\item Because of the smoothness of hyperplanes and affine spheres, the maps $f$ and $g$ are clearly $1$-homogeneous smooth maps. 
\item Finally for all $t>0$, $f(tN)=g(tN)=h(tN)=t$ and 
\begin{equation}
\label{eq Grad expression}
\grad f (tN) = \grad h(tN) = \frac{(y,-1)}{\omega(y)}.
\end{equation}
\end{itemize}

Thus, for all $t>0$, $g$ is differentiable at $tN$ with gradient expressed by equation \eqref{eq Grad expression}. Hence as for all $V \in \C$, $\mathcal{T}_K(P+V)=g(V)$ and $X = P + \mathcal{T}_K(X) N$, $\mathcal{T}_K$ is differentiable at $X$ and its gradient at any point $X \in K$ is expressed as 
\begin{equation*}
\grad \mathcal{T}_K (X) = \frac{(y ,-1)}{\omega(y)} = \frac{\bp{y_K(X),-1}}{\omega\bp{y_K(X)}}.
\end{equation*}
Then the continuity of the projecting normal $y_K$ (Proposition~\ref{prop TK, PK and yK are continuous}) gives that the cosmological time $\mathcal{T}_K$ is $C^1$.
\end{proof}

