\begin{proposition}
\label{prop level set of cosmo time is Cauchy surf}
Let $K$ be a $\C$-convex domain with support function $s$. Every level set of the cosmological time $\mathcal{T}_K$ on $K$ is a convex Cauchy surface of the affine spacetime $(K,\C)$. 
\end{proposition}
\begin{proof}
Every level set $\left\lbrace \mathcal{T}_K =t \right\rbrace$ is the boundary of the $\C$-spacelike domain $K(s+t\omega)$. Because of condition~\ref{cdt 0 on dOmega} from Definition~\ref{def gauge support function}, the lower semi-continuous convex extensions (maybe with value in $\R \cup \left\lbrace+\infty\right\rbrace$) of $s$ and $s+t\omega$ on $\overline{\Omega^*}$ are equal on $\partial \Omega^*$. Then, the proof that $\partial K(s+t\omega)$ is a Cauchy surface of $(K,\C)$ the same as the one of Proposition~\ref{prop maximal domain = Cauchy development}. The convexity of the Cauchy surface $\partial K(s+t\omega)$, in the sense of Definition~\ref{def Convex Cauchy surface}, is clear.
\end{proof}

\subsection{\texorpdfstring{Length of causal curves in the affine spacetime $\bp{\A^{d+1},\C}$}{Length of causal curves in the affine spacetime (A,C) }}
\label{subseclength of causal curves}

This subsection discusses the cosmological time through the framework of pseudo-Finsler geometry described in \cite{Papadopoulos_Yamada_19, Buro_23} and based on the work of Busemann \cite{Busemann_67}. In that context we proceed to give a geometric interpretation of cosmological time, justifying its name \cite{Andersson_Galloway_Howard_98}.


In the model affine spacetime $\bp{\A^{d+1},\C}$, using our fixed gauge support functions $\omega$ satisfying properties~\ref{cdt C2+},~\ref{cdt 0 on dOmega} and~\ref{cdt empty subdif on dOmega}, from Definition~\ref{def gauge support function}, one can define a \emph{pseudo-Finsler} norm of a $\C$-timelike vector as the \emph{gauge} of $\Sigma$: a vector $V \in \C \subset \R^{d+1} = \mathrm{T}_X \A^{d+1}$ has norm $\lambda >0$ if and only if $V \in \lambda \Sigma$. As $\Sigma$ is asymptotic to $\C$, the norm of a $\C$-null vector is set to $0$, so that the norm is continuous on $\overline{\C}$.

\begin{remark}
Here \(K(\omega)\), the $\C$-convex domain bounded by $\Sigma$, is an example of a Valinor convex domain introduced by Buro in order to introduce pseudo-Finsler metrics on manifolds \cite[Section 3.2]{Buro_23}.
\end{remark}


Because $\Sigma = \graph(\omega^*)\subseteq \C$ is the graph of a strictly convex $C^1$ function asymptotic to $\partial\C$, we can parametrise $\Sigma$ radially, i.e. set $w: \Omega~\longrightarrow~\R$ to be the convex function such that 
\begin{equation*}
\Sigma = \left\lbrace -\frac{1}{w(x)}(x,1) \st x \in \Omega \right\rbrace.
\end{equation*}
Then a simple computation shows that the pseudo-Finsler norm of vectors $V = (v,\nu) \in \C \subset \R^d \times \R $ is expressed as the positive 1-homogeneous function
\begin{equation*}
F(V) \coloneqq -\nu \, w\vp{\frac{v}{\nu}}.
\end{equation*}

\begin{remark} 
When using $\omega =\omega_\C$ the support function of the Cheng--Yau affine sphere $\S$ given by Theorem~\ref{theo Cheng--Yau V2}, notice that Remark~\ref{rem the Minkowski case} implies that in the Minkowski case it precisely coincides with the Lorentzian norm of a causal vector. In the general case, using Gigena's work \cite{Gigena_81,Loftin_10}, we have that the radial parametrisation of an hyperbolic affine sphere is
\begin{equation*}
\S = \left\lbrace -\frac{1}{w_\C(x)}(x,1) \st x \in \Omega \right\rbrace,
\end{equation*}
where $w_\C = \omega_{(\C^*)}$ is the unique solution to the Monge--Ampère equation 
\begin{equation*}
\begin{cases}
\det \Hess w= (-w)^{-d-2} \textup{ in } \Omega,\\
w_{\vert \partial\Omega} =0.
\end {cases}
\end{equation*} 
\end{remark}

\begin{definition}[Length of a $\C$-causal curve and $\C$-distance]
The \emph{length of a $\C$-causal curve} $\gamma: I~\longrightarrow~\R^{d+1}$ is defined as 
\begin{equation*}
l_F(\gamma) \coloneqq \int_I F\bp{\gamma'(t)} \dif t \geq 0.
\end{equation*}
The homogeneity of the function $F$ ensures that it does not depend on the parametrisation of the path $\gamma$. 

Given $X_0 \in \R^{d+1}$ and $X_1 \in J^+(X_0) = X_0 + \C$, the \emph{$\C$-distance between $X_0$ and $X_1$} is 
\begin{equation*}
\rho(X_0,X_1) \coloneqq \sup \left\lbrace l_F(\gamma) \st \gamma \textup{ is a future directed $\C$-causal curve from $X_0$ to $X_1$} \right\rbrace.
\end{equation*}
\end{definition}

\begin{proposition}
Let $X_0 \in \R^{d+1}$ and $X_1 \in J^+(X_0) = X_0 + \C$. The $\C$-distance between $X_0$ and $X_1$ is attained for the straight line from $X_0$ to $X_1$, i.e. 
\begin{equation*}
\rho(X_0,X_1) = F(X_1 - X_0).
\end{equation*}
\end{proposition}
\begin{proof}
Let $\gamma: \left[0,1\right]~\longrightarrow~\R^{d+1}$ be a future directed $\C$-causal curve from $\gamma(0) = X_0$ to $\gamma(1) = X_1$. We decompose it as $\gamma(t)=\bp{x(t),\lambda(t)}$, then up to reparametrisation we can assume that $\lambda(t) = (1-t)\lambda_0 + t \lambda_1$. Then 
\begin{equation*}
l_F(\gamma) = \int_{0}^{1} F\bp{\gamma'(t)} \dif t = -\int_{0}^{1} \lambda'(t) w \vp{\frac{x'(t)}{\lambda'(t)}} \dif t = -(\lambda_1 - \lambda_0) \int_{0}^{1} w \vp{\frac{x'(t)}{\lambda_1 - \lambda_0}}\dif t.
\end{equation*}
As $w$ is convex, the Jensen inequality gives
\begin{equation*}
\int_{0}^{1} w \vp{\frac{x'(t)}{\lambda_1 - \lambda_0}}\dif t \geq w \vp{\int_{0}^{1} \frac{x'(t)}{\lambda_1 - \lambda_0}\dif t} = w \vp{\frac{x_1 - x_0}{\lambda_1 - \lambda_0}}.
\end{equation*}
Because the path is future directed, $\lambda_1 - \lambda_0 \geq 0$, and thus
\begin{equation*}
l_F(\gamma) \leq -(\lambda_1 - \lambda_0) w\vp{\frac{x_1 - x_0}{\lambda_1 - \lambda_0}} = F(X_1 - X_0),
\end{equation*}
where $F(X_1 - X_0)$ the length of the straight line from $X_0$ to $X_1$. 
\end{proof}

\begin{proposition}[Time inequality]
\label{prop time inequality}
If $X_1,X_2,X_3 \in \R^{d+1}$ are causally ordered, i.e. such that $X_2 \in J^+(X_1)$ and $X_3 \in J^+(X_2) \subseteq J^+(X_3)$, we have the \emph{time inequality}
\begin{equation*}
\rho(X_1,X_2) + \rho(X_2,X_3) \leq \rho(X_1,X_3).
\end{equation*}
\end{proposition}
\begin{proof}
Set $X_i = (x_i, \lambda_i)$, for all $i \in \left\lbrace 1,2,3 \right\rbrace$ As $w$ is convex we have 
\begin{equation*}
\frac{\lambda_2 - \lambda_1}{\lambda_3 - \lambda_1} w\vp{\frac{x_2 - x_1}{\lambda_2 - \lambda_1}} + \frac{\lambda_3 - \lambda_2}{\lambda_3 - \lambda_1} w\vp{\frac{x_3 - x_2}{\lambda_3 - \lambda_2}} \geq w \vp{\frac{x_3 - x_1}{\lambda_3 - \lambda_1}}.
\end{equation*}
Multiplying by $-(\lambda_3 - \lambda_1) \leq 0$, we get the wanted result.
\end{proof}


\begin{remark}
This time inequality is one of the axioms describing a \emph{timelike space} in the sense of Busemann \cite{Busemann_67}. One can easily check that a $\C$-convex domains endowed with the causal structure induced by $\C$ and the time function $\rho$ satisfies all the other axioms.
\end{remark}

\begin{proposition}
\label{prop cosmological time and length causal curve}
Let $K$ a $\C$-convex domain. The cosmological time defined in Definition~\ref{def normal projection, cosmological time and projecting normal} satisfies
\begin{align*}
\mathcal{T}_K(X) & = \sup \left\lbrace \rho(X_0,X) \st X_0 \in J^-(X) \cap \partial_{sp}K \right\rbrace,\\
& = \sup \left\lbrace l_F(\gamma) \st \gamma \textup{ is a future directed $\C$-causal curve from a point of $\partial_{sp}K$ to $X$} \right\rbrace.
\end{align*}
\end{proposition}
\begin{proof}
First, notice that $T \coloneqq \mathcal{T}_K(X) = F\bp{X - P} = \rho\bp{P,X}$ where $P \coloneqq P_K(X) \in J^-(X) \cap \partial_{sp}K$ is the normal projection of $X$ onto $\partial_{sp}K$. Then notice that $X - T \, \Sigma$ and $\partial_{sp}K$ touch at $P$ and have a common $\C$-spacelike hyperplane directed by $y \coloneqq y_K(X)$ the projecting normal from $X$ to $\partial_{sp}K$. Then, using the foliation of $(X - \C)$ by the $-\C$-convex hypersurfaces $\bp{X - t \, \Sigma}_{t>0}$, as $K$ is $\C$-convex, it is clear that any element $X_0 \in (X - \C) \cap \partial_{sp}K$ belongs to some $X - T_0 \cdot \Sigma$ with $T_0 \leq \mathcal{T}_K(X)$, i.e. $\rho(X_0,X) \leq \mathcal{T}_K(X)$ with equality for $X_0 = P$ (see Figure~\ref{fig proof length}). 
\end{proof}

