\begin{remark}
This new characterisation of cosmological time highlights its similarity with the Lorentzian one \cite{Andersson_Galloway_Howard_98}. When using $\omega =\omega_\C$, the support function of the Cheng--Yau affine sphere given by Theorem~\ref{theo Cheng--Yau V2}, as our gauge support function, Remark~\ref{rem the Minkowski case} implies that in the Minkowski case it precisely coincides with the Lorentzian cosmological time. 
\end{remark}

\begin{proposition}
\label{prop TK is concave}
Let $K$ be a $\C$-convex domain. The cosmological time $\mathcal{T}_K$ on $K$ is concave.
\end{proposition}

\begin{proof}
Let $X_1,X_2 \in K$ be two points, we denote by $P_i \coloneqq P_K(X_i) \in \partial_{sp}K$ their normal projections. Then we have for $i \in \{1,2\}$,
\begin{equation*}
\mathcal{T}_K(X_i) = \rho(P_i, X_i) = F(X_i - P_i).
\end{equation*}
Starting from
\begin{align*}
\frac{\mathcal{T}_K(X_1) + \mathcal{T}_K(X_2)}{2} & = \frac{F(X_1 - P_1) + F(X_2 -P_2)}{2}, \\
& = \frac{F(X_1 - P_1) + F\bp{(X_1 + X_2 - P_2)-X_1}}{2}, \\
& = \frac{\rho(P_1, X_1) + \rho(X_1,X_1 + X_2 - P_2)}{2},
\end{align*}
and using the time inequality (Proposition~\ref{prop time inequality}),
\begin{equation*}
\rho(P_1,X_1) + \rho(X_1,X_1 + X_2 - P_2) \leq \rho(P_1,X_1 + X_2 - P_2) = \rho(P_1 + P_2 ,X_1 + X_2),
\end{equation*}
we get 
\begin{equation*}
\frac{\mathcal{T}_K(X_1) + \mathcal{T}_K(X_2)}{2} \leq \frac{\rho(P_1 + P_2 ,X_1 + X_2)}{2} = \rho\vp{\frac{P_1 + P_2}{2} ,\frac{X_1 + X_2}{2}}. 
\end{equation*}
As $K$ is convex and $P_1,P_2 \in \partial_{sp}K$, we have that $\frac{1}{2}(P_1 + P_2) \in \overline{K}$ and thus, by Proposition~\ref{prop cosmological time and length causal curve},
\begin{equation*}
\frac{\mathcal{T}_K(X_1) + \mathcal{T}_K(X_2)}{2} \leq \rho\vp{\frac{P_1 + P_2}{2} ,\frac{X_1 + X_2}{2}} \leq \mathcal{T}_K \vp{\frac{X_1 + X_2}{2}} \qedhere
\end{equation*}
\end{proof}

\subsection{Invariance of the cosmological time given by the Cheng--Yau affine spheres}
\label{subsec Invariance of the cosmological time given by the CHeng--Yau affine spheres}

In this subsection we use the support function $\omega_\C$ of $\S$, the Cheng--Yau affine sphere given by Theorem~\ref{theo Cheng--Yau V2}, as our gauge support function in order to prove Theorem~\ref{Theorem Intro cosmological time}. 

Remember that the affine sphere $\S=\graph(\omega_\C^*)$ is preserved by $\mathrm{Aut}_{\SL}(\C)$, the subgroup of elements of $\SL\bp{\R^{d+1}}$ preserving the cone $\C$ (Corollary~\ref{cor affine sphere invariance}). That implies that the cosmological time induced by the Gauge support function $\omega_\C$ satisfy the following invariance property.

\begin{proposition}
\label{prop cosmological time equivariance}
Let $K$ be a $\C$-convex domain and $\mathcal{T}_K$, $P_K$ and $y_K$ be be the cosmological time, normal projection and projecting normal on $K$ (Definition~\ref{def normal projection, cosmological time and projecting normal}) induced by the gauge support function $\omega_\C$, the support function of $\S$ the Cheng--Yau affine sphere (Theorem~\ref{theo Cheng--Yau V2}). If $K$ is preserved by an affine transformation $(\gamma,\tau) \in \SL\bp{\R^{d+1}}\ltimes\R^{d+1}$, then $\gamma \in \mathrm{Aut}_{\SL}(\C)$, the subgroup of elements of $\SL\bp{\R^{d+1}}$ preserving $\C$, and for all $X$ in $K$ we have the following
\begin{align*}
& \mathcal{T}_K(\gamma X + \tau) = \mathcal{T}_K(X), \\
& P_K(\gamma X + \tau) = \gamma P_K(X) + \tau,\\
& y_K(\gamma X + \tau) = \gamma *y_K(X),
\end{align*}
where the projective dual action of an element $\gamma \in \mathrm{Aut}_{\SL}(\C)$ on $\Omega^*$, denoted by $*$, is described at the beginning of Section~\ref{sec Affine deformations of divisible convex cones}.
\end{proposition}
\begin{proof}
Let $(\gamma,\tau) \in \SL\bp{\R^{d+1}}\ltimes\R^{d+1}$ be an affine transformation preserving the $\C$-convex domain $K$. As $(\gamma,\tau)$ preserves $K$, its linear part $\gamma$ preserves its set of supporting hyperplane. By definition of a $\C$-convex domain (Definition~\ref{def C-convex and C-regular domains}), that implies that the dual action of $\gamma$ preserves the cone $\C^*$ and hence, by duality, that $\gamma$ preserves $\C$, i.e. $\gamma \in \mathrm{Aut}_{\SL}(\C)$.

Let $X \in K$. Acting by $(\gamma,\tau)$ on the equality
\begin{equation*}
X = P_K(X) + \mathcal{T}_K(X) \cdot \G_{\S}^{-1}\bp{y_K(X)}
\end{equation*}
that defines the cosmological time, normal projection and projecting normal of $X$ (Definition~\ref{def normal projection, cosmological time and projecting normal}), we get 
\begin{equation*}
\gamma X + \tau = \bp{\gamma P_K(X) + \tau} + \mathcal{T}_K(X) \cdot \gamma \, \G_{\S}^{-1}\bp{y_K(X)}.
\end{equation*}
As the affine sphere $\S$ is invariant under the action of $\mathrm{Aut}_{\SL}(\C)$ (Corollary~\ref{cor affine sphere invariance}), its Gauss map is clearly $\mathrm{Aut}_{\SL}(\C)$-equivariant, and so is its inverse. Thus, 
using that equivariance of $\G_{\S}^{-1}$, the previous equality becomes
\begin{equation}
\label{eq projection equation composed by gamma}
\gamma X + \tau = \bp{\gamma P_K(X) + \tau} + \mathcal{T}_K(X) \cdot \G_{\S}^{-1}\bp{\gamma *y_K(X)}.
\end{equation}
As $K$ is preserved by the affine transformation $(\gamma,\tau)$ and $\gamma \in \mathrm{Aut}_{\SL}(\C)$, its $\C$-spacelike boundary $\partial_{sp}K$ is also preserved by $(\gamma,\tau)$. Thus, $\gamma P_K(X) + \tau \in \partial_{sp}K$ and $\gamma * y_K(X)$ directs a supporting hyperplane to $K$ at that point. Hence, equality \eqref{eq projection equation composed by gamma} characterises the cosmological time, normal projection and projecting normal of $\gamma X + \tau$ (Definition~\ref{def normal projection, cosmological time and projecting normal}), giving the desired expressions.
\end{proof}

We can now prove the following theorem, implying Theorem~\ref{Theorem Intro cosmological time}.

\begin{theorem}
Let $K$ be a $\C$-convex domain. The cosmological time $\mathcal{T}_K: K~\longrightarrow~\R^*_+$, induced by the gauge support function $\omega_\C$, the support function of $\S$ the Cheng--Yau affine sphere given by Theorem~\ref{theo Cheng--Yau V2}, is a $C^1$ function whose level sets are $C^1$ convex Cauchy surfaces of $(K,\C)$ foliating $K$.
Moreover, $\mathcal{T}_K$ is invariant by any transformation of $\SA\bp{\R^{d+1}}$ preserving $K$.
\end{theorem}
\begin{proof}
This is just a consequence of Lemma~\ref{lem C1 foliation of K} and Propositions~\ref{prop TK is C1}, \ref{prop level set of cosmo time is Cauchy surf}, \ref{prop TK is concave} and \ref{prop cosmological time equivariance}.
\end{proof}


\section{Quotient of the maximal domain}
\label{sec Quotient of the maximal domain}

In this section, we first study the action of $\Gamma_\tau$, an affine deformation of a group $\Gamma$ dividing an open proper convex cone $\C$, on the maximal $\tau$-convex domain $D_\tau$ from Theorem~\ref{Theorem Intro domain} constructed in Section~\ref{sec Affine deformations of divisible convex cones}. We then focus on the affine spacetime $\bp{D_\tau / \Gamma_\tau, \C}$, using the cosmological time we introduced in the previous section. That allows us to produce proofs for point~\ref{theo11} and the GHCC part of point~\ref{theo12} of Theorem~\ref{Theorem Intro domain}.

We shall use the cosmological time functions introduced in Section~\ref{sec Cosmological time on C-convex domains} and given by setting $\omega = \omega_\C$ the support function of the Cheng--Yau affine sphere given by Theorem~\ref{theo Cheng--Yau V2}.

\subsection{\texorpdfstring{Action of $\Gamma_\tau$ on $D_\tau$}{Action of Gamma-tau on D-tau}}
\label{subsec Action on the maximal domain}
In this subsection we shall prove point~\ref{theo11} from Theorem~\ref{Theorem Intro domain}.
We come back to the case where $\C$ happens to be divisible by a torsion-free discrete subgroup $\Gamma < \SL\bp{\R^{d+1}}$. Set $\Gamma_\tau$ to be some affine deformation of $\Gamma$, we can use the tools introduced in subsection~\ref{subsec Normal projection, cosmological time and foliation of C-convex domains} on the maximal $\tau$-convex domain $D_\tau$ constructed in Section~\ref{sec Affine deformations of divisible convex cones}.

In order to lighten notations, the normal projection onto the initial singularity $\partial_{sp}D_\tau$ will simply be denoted by $P_\tau$, similarly the cosmological time on $D_\tau$ will be denoted by $\mathcal{T}_\tau$, its $t$-level hypersurface by $S_\tau^t$, and the projecting normal by $y_\tau$.


\begin{proposition}
\label{prop tau cosmological time equivariance}
On $D_\tau$ the maximal $\tau$-convex domain:
\begin{itemize}
\item the cosmological time $\mathcal{T}_\tau: D_\tau~\longrightarrow~\R_+^*$ is $\Gamma_\tau$-invariant, 
\item the normal projection $P_\tau: D_\tau~\longrightarrow~\partial_{sp} D_\tau$ is $\Gamma_\tau$-equivariant,
\item the projecting normal $y_\tau: D_\tau~\longrightarrow~\Omega^*$ is equivariant with respect to the action of $\Gamma_\tau$ on $D_\tau$ and the action of $\Gamma$ on $\Omega^*$.
\end{itemize}
\end{proposition}
\begin{proof}
For all $X \in D_\tau$ and $(\gamma,\tau_\gamma) \in \Gamma_\tau$, by Proposition~\ref{prop cosmological time equivariance}, 
\begin{align*}
& \mathcal{T}_\tau(\gamma X + \tau_\gamma) = \mathcal{T}_\tau(X), \\
& P_\tau(\gamma X + \tau_\gamma) = \gamma P_\tau(X) + \tau_\gamma,\\
& y_\tau(\gamma X + \tau_\gamma) = \gamma *y_\tau(X). \qedhere
\end{align*}
\end{proof}

\begin{proposition}
\label{prop cosmological foliation of Dtau}
The maximal $\tau$-convex domain $D_\tau$ is foliated by the level hypersurfaces of its cosmological time, which are the spacelike $C^1$ embedded $\Gamma_\tau$-invariant hypersurfaces $\{\partial K(s_\tau + t \omega_\C)\}_{t>0}$.
\end{proposition}
\begin{proof}
The foliation is simply a consequence of Lemma~\ref{lem C1 foliation of K}, the $\tau$-invariance comes from the equivariance of $\mathcal{T}_\tau$ (Proposition~\ref{prop tau cosmological time equivariance}) or equivalently from the $\tau$-equivariance of any function $s_\tau + t \omega_\C$ with $t>0$.
\end{proof}

\begin{proposition}
\label{prop projection Ptau}
The projection $\Pi_\tau$ defined by 
\begin{equation*}
\function{\Pi_\tau}{D_\tau}{\partial K(s_\tau + \omega_\C) = S_\tau^1}{X}{P_{\tau}(X) + \G_{\S}^{-1}\bp{y_{\tau}(X)}}
\end{equation*}
is continuous and $\Gamma_\tau$-equivariant, in the sense that for all $(\gamma, \tau_\gamma) \in \Gamma_\tau$,
\begin{equation*}
\Pi_\tau(\gamma X + \tau_\gamma) =\gamma \Pi_\tau(X) + \tau_\gamma.
\end{equation*} 
\end{proposition}
\begin{proof}
The continuity and equivariance are just consequences of, respectively, Propositions~\ref{prop TK, PK and yK are continuous} and~\ref{prop tau cosmological time equivariance}.
\end{proof}

\begin{corollary}
\label{cor definition of Theta}
There is a homeomorphism
\begin{equation*}
\function{\Theta}{D_\tau}{S_\tau^1 \times \R_+^*}{X}{\bp{\Pi_\tau(X),\mathcal{T}_{\tau}(X)}}
\end{equation*}
satisfying that for all $(\gamma,\tau_\gamma) \in \Gamma_\tau$
\begin{equation}
\label{prop property of Theta}
\Theta(\gamma X + \tau_\gamma) = \bp{\gamma \Pi_\tau(X) + \tau_\gamma,\mathcal{T}_{\tau}(X)}.
\end{equation}
\end{corollary}
\begin{proof}
The continuity of $\Theta$ and condition \eqref{prop property of Theta} are consequences of Proposition~\ref{prop projection Ptau}. To see that $\Theta$ is a homeomorphism just notice that its inverse map is explicitly expressed as
\begin{equation*}
\Theta^{-1}=\namelessfunction{S_\tau^1 \times \R_+^*}{D_\tau}{(X,t)}{ P_{\tau}(X) + t \, \G_{\S}^{-1}\bp{y_{\tau}(X)}}
\end{equation*}
which is continuous by Proposition~\ref{prop TK, PK and yK are continuous}.
\end{proof}

\begin{proposition}
\label{prop action is properly discontinuous}
The action of $\Gamma_\tau$ on $D_\tau$ is free and properly discontinuous and there is a homeomorphism
\begin{equation*}
D_\tau /\Gamma_\tau \simeq S_\tau^1 /\Gamma_\tau \times \R.
\end{equation*}
\end{proposition}
\begin{proof}
Using the homeomorphism $\Theta$ from Corollary~\ref{cor definition of Theta} this is just a consequence of the free and properly discontinuous action of $\Gamma_\tau$ on the $C^1$ hypersurface $S_\tau^1 = \partial K(s_\tau + \omega_\C)$ proved in Proposition~\ref{prop free and properly discontinuous action on C1 tau-invariant hypersurfaces}.
\end{proof}

\begin{lemma}
\label{lem concrete homeomorphism between Cauchy surfaces}
If $K$ is a spacelike $\tau$-convex domain ($\partial K =\partial_{sp}K$) in $\bp{\R^{d+1},\C}$, then $\partial K$ is a Cauchy surface of $\bp{D_\tau,\C}$. Moreover it is $\Gamma_\tau$-equivariantly homeomorphic to $S_\tau^1$.
\end{lemma}
\begin{proof}
The fact that $\partial K$ is a Cauchy surface of $D_\tau$ is Corollary~\ref{cor C2+ implies Cauchy surface}. An explicit $\Gamma_\tau$-equivariant homeomorphism between $\partial K$ and $S_\tau^1$ is given by the restriction $\Pi_{\tau\vert \partial K}$ of the projection from Proposition~\ref{prop projection Ptau}.
\end{proof}

\begin{remark}
In Lemma~\ref{lem concrete homeomorphism between Cauchy surfaces}, the fact that $\partial K$ is $\Gamma_\tau$-equivariantly homeomorphic to $S_\tau^1$ can also be seen as a direct consequence of Proposition~\ref{prop Geroch Cauchy surfaces} on the quotient affine spacetime $\bp{D_\tau / \Gamma_\tau,\C}$ (which will be the focus of subsection~\ref{subsec Spacetime structure of the quotient}). 
\end{remark}


\begin{theorem}[Theorem~\ref{Theorem Intro domain}~\ref{theo11}]
\label{the action is properly discontinuous + homeo}
The action of $\Gamma_\tau$ on $D_\tau$ is free and properly discontinuous and there is a homeomorphism
\begin{equation*}
D_\tau /\Gamma_\tau \simeq \Omega /\Gamma \times \R.
\end{equation*}
\end{theorem}
\begin{proof}
By Proposition~\ref{prop exists tau-support function extending to boundary}, there exist a $C^2_+$ $\tau$-convex $K$ with $\partial K = \partial_{sp}K$. Then the Gauss map $\G_K$ on $K$ gives a diffeomorphism $\partial K /\Gamma_\tau \approx \Omega^*/\Gamma$. Propositions~\ref{prop dual convex is divisible} and~\ref{prop action is properly discontinuous}, and Lemma~\ref{lem concrete homeomorphism between Cauchy surfaces} then conclude the proof.
\end{proof}

\subsection{Spacetime structure of the quotient}
\label{subsec Spacetime structure of the quotient}

In this subsection, we prove the GHCC part of point~\ref{theo12} (we shall treat maximality in subsection~\ref{subsec Maximality of the quotient spacetimes}) from Theorem~\ref{Theorem Intro domain}.

As $\Gamma$, the linear part of $\Gamma_\tau$, preserves the cone $\C$, the parallel proper convex cone structure of $\bp{D_\tau,\C}$ descends to the equiaffine manifold $D_\tau / \Gamma_\tau$, endowing it with an affine spacetime structure. 

Proposition~\ref{prop tau cosmological time equivariance} indicates that the cosmological time, normal projection and projecting normal descends to maps $\mathcal{T}_\tau: D_\tau / \Gamma_\tau~\longrightarrow~\R_+^*$, $P_\tau: D_\tau / \Gamma_\tau~\longrightarrow~\partial_{sp}D_\tau / \Gamma_\tau$, and $y_\tau: D_\tau / \Gamma_\tau~\longrightarrow~\Omega^*/\Gamma$ (that we abusively denoted in the same way).

\begin{theorem} [Theorem~\ref{Theorem Intro domain}, GHCC part of~\ref{theo12}]
The affine spacetime $\bp{D_\tau / \Gamma_\tau,\C}$ is a globally hyperbolic spacetimes admitting a locally uniformly convex (Definition~\ref{def Convex Cauchy surface}) and compact Cauchy surface.
\end{theorem}
\begin{proof}
In the proof of Proposition~\ref{prop exists tau-support function extending to boundary}, we have shown that there exists a $C^2_+$ $\tau$-convex domain $K$ with $\partial K = \partial_{sp}K$. The $C^2_+$ nature of $K$ implies that $\partial K / \Gamma_\tau$ is a spacelike locally uniformly convex hypersurface in $\bp{D_\tau / \Gamma_\tau,\C}$. It is also compact as the Gauss map $\G_K$ descends to a diffeomorphism from $\partial K / \Gamma_\tau$ to $\Omega^* / \Gamma$ which is compact by Proposition~\ref{prop dual convex is divisible}. Finally, Corollary~\ref{cor C2+ implies Cauchy surface} descends to the quotient and implies that $\partial K / \Gamma_\tau$ is a Cauchy surface of $\bp{D_\tau / \Gamma_\tau,\C}$.
\end{proof}

\begin{theorem}
The affine spacetime $\bp{D_\tau / \Gamma_\tau,\C}$ is foliated by the level hypersurfaces of its cosmological time, which are $\C$-spacelike and $C^1$ embedded convex Cauchy surfaces.
\end{theorem}
\begin{proof}
The fact that level hypersurfaces of the cosmological time are a $C^1$ foliation is just a quotiented version of Proposition~\ref{prop cosmological foliation of Dtau}. Those are quotients of $\C$-spacelike convex hypersurfaces, and thus, by Corollary~\ref{cor C2+ implies Cauchy surface}, are convex Cauchy surfaces of $\bp{D_\tau / \Gamma_\tau,\C}$.
\end{proof}


\begin{remark}
\label{rem even dimension}
Remembering the discussion in subsection~\ref{subsec The two maximal domains}, we can consider the two GHCC affine spacetimes $\bp{D_{\tau}^{\C} / \Gamma_\tau , \C}$ and $\bp{D_{\tau}^{-\C} / \Gamma_\tau , -\C}$. In general, they have no reason to be isomorphic affine spacetimes. In the case where $d+1$ is even and $\tau = 0 $, they actually are: indeed $-\Id \in \SL \bp{\R^{d+1}}$ and we have (see subsection~\ref{subsec The two maximal domains}) that $D^{\C}_0 = - D^{-\C}_{0}$.

In the case of flat Lorentzian spacetimes \cite{Mess_07,Bonsante_05}, $-\Id$ never belongs to $\SO_0(d,1) \subset \SL\bp{\R^{d+1}}$, moreover one can arbitrarily fix a time orientation on the common ambient Minkowski space containing all the maximal domains (the cone $\C$ does not vary) in order to have a favourite choice between the two spacetimes given by the two quotients of those maximal domains.
\end{remark}

\section{Correspondence between affine deformations of dividing groups and affine spacetimes}
\label{sec Correspondence between affine deformations of dividing groups and affine spacetimes}

This section is devoted to the proofs of the remaining maximality part of Theorem~\ref{Theorem Intro domain}~\ref{theo12} and of Theorem~\ref{Theorem Intro dev}, through the study of the developing maps of \emph{Globally Hyperbolic affine spacetimes admitting a locally uniformly Convex and Compact Cauchy surface} (GHCC affine spacetimes).

\subsection{Restriction of a developing map to a compact locally uniformly convex Cauchy surface}

In this subsection, we study the restriction of developing maps of GHCC affine spacetimes to a compact locally uniformly convex Cauchy surface. 

Let $(M,\C^M)$ be a GHCC affine spacetime. Using the equiaffine structure of $M$, we choose a pair $(\dev,\rho)$ of developing and holonomy maps (see subsection~\ref{subsec Equiaffine manifolds}). The developing map $ \dev: \widetilde{M}~\longrightarrow~\A^{d+1}$, 
is then a local diffeomorphism and it is $\rho$-equivariant, that is for all $p \in \widetilde{M}$ and $\gamma \in \pi_1 M$, 
\begin{equation*}
\dev(\gamma \cdot p)=\rho(\gamma) \cdot \dev(p).
\end{equation*}

The cone structure $\C^M$ on $M$ lifts to a cone structure $\C^{\widetilde{M}}$ on $\widetilde{M}$ which is parallel for the flat connection induced by the equiaffine structure of $\widetilde{M}$. Thus, we can set $\C \subset \V^{d+1}$ to be the proper open convex cone such that in each tangent space $\mathrm{T}_{\dev(p)}\A^{d+1} = \V^{d+1},$ we have 
\begin{equation*}
\C = \dif_{p} \dev\bp{\C^{\widetilde{M}}_p},
\end{equation*}
from now on we shall abusively write that this cone is defined as $\C \coloneqq \dif \, \dev\bp{\C^M}$.

Let $S$ be a compact locally uniformly convex Cauchy surface of $M$. Remember that Proposition~\ref{prop Geroch Cauchy surfaces} implies that $\pi_1 M = \pi_1S$ and that $\widetilde{S}$, the preimage of $S$ in the universal covering $\widetilde{M}~\longrightarrow~M$, is a universal cover of $S$.

By definition of a locally uniformly convex Cauchy surface (Definition~\ref{def Convex Cauchy surface}), the developing map $\dev$ induces a $\C$-spacelike locally uniformly convex immersion $\dev_{\vert \widetilde{S}}: \widetilde{S}~\longrightarrow~\A^{d+1}$, namely $\dev_{\vert \widetilde{S}}$ is locally a diffeomorphism onto a $\C$-spacelike graph of a uniformly convex $C^2$ map. We can thus consider the Blaschke metric $h$ on $\widetilde{S}$ induced by that immersion (Definition~\ref{def Blaschke metric}). We can also fix any Euclidean metric $g_{euc}$ on $\A^{d+1}$ and consider its pullback by the restriction $\dev_{\vert\widetilde{S}}$, denoted by $\dev_{\vert\widetilde{S}}^*g_{euc}$.

As the immersion $\dev_{\vert \widetilde{S}}: \widetilde{S}~\longrightarrow~\A^{d+1}$ is $\rho$-equivariant and $\rho$ takes values in $\SA\bp{\A^{d+1}}$, the Blaschke metric $h$ on $\widetilde{S}$ is preserved by $\pi_1S$ and descends to a Riemannian metric $\bar{h}$ on $S = \widetilde{S}/\pi_1 S$. The Riemannian manifold $(S,\bar{h})$ is closed and thus complete, so $\bp{\widetilde{S},h}$ is also complete. We are thus in the setting of the following theorem of Trudinger and Wang \cite[Theorem A]{Trudinger_Wang_02}.

\begin{theorem}[Trudinger--Wang \cite{Trudinger_Wang_02}]
\label{theo Trudinger--Wang}
Let $i: M~\longrightarrow~\A^{d+1}$ be a locally uniformly convex immersed hypersurface, namely the map $i$ is locally a diffeomorphism onto a graph (in some well chosen affine coordinates) of a uniformly convex $C^2$ function. Let $h$ be the Blaschke metric on $M$ induced by that immersion and $g_{euc}$ be a Euclidean metric on $\A^{d+1}$. If the Riemannian manifold $(M,h)$ is complete, then $(M, i^*g_{euc})$ is also complete.
\end{theorem}

We can also parametrise $\A^{d+1}$ as $\R^{d+1}$ so that we have 
\begin{equation*}
\C = \left\lbrace t (x,1) \st x \in \Omega, t>0 \right\rbrace,
\end{equation*}
where $\Omega$ is a bounded open convex domain of $\R^d$ containing $0$. In that setting, the following lemma holds.

\begin{lemma}
\label{lem projection is bilipschitz}
Let $\C \subset \V^{d+1}$ be an open proper convex cone and $g_{euc}$ a Euclidean metric on $\A^{d+1}$. Parametrise $\A^{d+1}$ as $\R^{d+1}$ such that $\C = \left\lbrace t (x,1) \st x \in \Omega, t>0 \right\rbrace$ where $\Omega$ is a bounded open convex domain of $\R^d$ containing $0$, and let $\pi: \R^{d+1}~\longrightarrow~\R^d$ be the projection onto the first $d$ coordinates. If $i: M~\longrightarrow~\A^{d+1}$ is a $\C$-spacelike immersed hypersurface, then the map $\pi\circ i: \bp{M,i^*g_{euc}}~\longrightarrow~\bp{\R^d, g_{euc\vert\R^d}}$ is bi-Lipschitz.
\end{lemma}
\begin{proof}
As $\Omega$ is a bounded open convex domain containing $0$, we can set
\begin{equation*}
M \coloneqq \sup\left\lbrace g_{euc\vert\R^d}(x,x) \mid x \in \Omega\right\rbrace >0.
\end{equation*}
For every $\C$-spacelike vector $V \in \R^{d+1}$, we then have 
\begin{equation*}
g_{euc\vert\R^d}\bp{\pi(V),\pi(V)} \leq g_{euc}\bp{V,V} \leq \vp{1+\frac{1}{M}}g_{euc\vert\R^d}\bp{\pi(V),\pi(V)}.
\end{equation*}
Applying that inequality to vectors $V$ tangent to the immersed hypersurface $i: M~\longrightarrow~\A^{d+1}$ we get the lemma.
\end{proof}

We can now prove the following. 

\begin{proposition}
\label{prop devS is diffeo}
Let $(\dev,\rho)$ be a pair of developing and holonomy maps of a GHCC affine spacetime $(M,\C^M)$ and parametrise $\A^{d+1}$ as $\R^{d+1}$ so that the open proper convex cone $\C \coloneqq \dif \, \dev \bp{\C^M}$ is expressed as $\C = \left\lbrace t (x,1) \st x \in \Omega, t>0 \right\rbrace$, where $\Omega$ is a bounded open convex domain of $\R^d$ containing $0$. If $S$ is a compact locally uniformly convex Cauchy surface of $(M,\C^M)$, the developing map $\dev$ on $\widetilde{M}$ embeds its universal cover $\widetilde{S} \subset \widetilde{M}$ into $\R^{d+1}$ as the graph of a $\C$-spacelike and locally uniformly convex function $f: \R^d~\longrightarrow~\R$.
\end{proposition}
\begin{proof}
Using the definition of a locally uniformly convex Cauchy surface (Definition~\ref{def Convex Cauchy surface}) and our well chosen parametrisation of $\A^{d+1}$, we already know that the image of $\dev_{\vert\widetilde{S}}$ is locally the graph of a $\C$-spacelike and locally uniformly convex function of the first $d$ coordinates. By Lemma~\ref{lem projection is bilipschitz}, $\pi \circ \dev_{\vert\widetilde{S}}$ is injective, thus all those local graphs agree with each other. That means that $\dev\bp{\widetilde{S}}$ is the graph of a $\C$-spacelike locally uniformly convex function $f:U~\longrightarrow~\R$ on some open subset $U \subseteq\R^d$.

Now, let us show that $U$ is the whole $\R^d$. Remember that the Blaschke metric $h$ on $\widetilde{S}$ given by the immersion $\dev_{\vert\widetilde{S}}:\widetilde{S}~\longrightarrow~\R^{d+1}$ descends to the closed manifold $S = \widetilde{S}/\pi_1S$, so that $\bp{\widetilde{S},h}$ is complete. By Theorem~\ref{theo Trudinger--Wang}, $\bp{\widetilde{S},\dev_{\vert\widetilde{S}}^*g_{euc}}$ is also complete. As bi-Lipschitz maps preserve completeness, Lemma~\ref{lem projection is bilipschitz} implies that $\bp{U = \pi \circ \dev \bp{\widetilde{S}},g_{euc\vert\R^d}}$ is complete, so that $U$ is the whole $\R^d$.

Finally, let us prove that $\dev_{\vert\widetilde{S}}:\widetilde{S}~\longrightarrow~\R^{d+1}$ is an embedding. By Lemma~\ref{lem projection is bilipschitz}, $\pi \circ \dev_{\vert\widetilde{S}}$ is injective on $\widetilde{S}$, thus $\dev$ is also injective on $\widetilde{S}$. As $\bp{\widetilde{S},\dev_{\vert\widetilde{S}}^*g_{euc}}$ is complete, the Hopf--Rinow Theorem implies that $\dev_{\vert\widetilde{S}}$ is proper. Thus $\dev_{\vert\widetilde{S}}$ is a proper injective immersion, that is $\dev_{\vert\widetilde{S}}$ is an embedding.
\end{proof}

As we parametrised $\A^{d+1}$ as $\R^{d+1}$, we can also see $\SA\bp{\A^{d+1}}$ as $\SA\bp{\R^{d+1}} = \SL\bp{\R^{d+1}} \ltimes \R^{d+1}$. Consider the linear part of the representation $\rho: \pi_1S~\longrightarrow~\SA\bp{\R^{d+1}}$, it is a representation $\rho_{lin}: \pi_1S~\longrightarrow~\SL\bp{\R^{d+1}}$. Then the following holds.

\begin{proposition}
\label{prop Gauss on S is equivariant diffeo}
In setting of Proposition~\ref{prop devS is diffeo}, let $\G: \dev\bp{\widetilde{S}}~\longrightarrow~\Omega^*$ be the Gauss map of the $\C$-spacelike hypersurface $\graph(f) = \dev\bp{\widetilde{S}}$. The map $\phi \coloneqq \G \circ \dev: \widetilde{S}~\longrightarrow~\Omega^*$ is a diffeomorphism onto its image $\Theta^*\coloneqq \G \circ \dev\bp{\widetilde{S}}$, which is an open convex subset of $\Omega^*$ preserved by the dual projective action (described at the beginning of Section~\ref{sec Affine deformations of divisible convex cones}) of $\rho_{lin}(\pi_1S)$, the linear part of $\rho$ on $\Omega^* \simeq\P\bp{\C^*}$ .
Moreover, it is $\rho_{lin}$-equivariant, that is for all $p \in \widetilde{S}$ and $\gamma \in \pi_1 S$, 
\begin{equation*}
\phi(\gamma \cdot p)=\rho_{lin}(\gamma) * \phi(p).
\end{equation*}

\end{proposition}
\begin{proof}
As $\graph(f)$ is a $\C$-spacelike locally uniformly convex hypersurface, the Gauss map $\G$ is defined as 
\begin{equation*}
\function{\G}{\graph(f)}{\Omega^*}{\bp{x,f(x)}}{\grad f (x)}
\end{equation*}
and is a $C^1$ diffeomorphism onto its image $\Theta^*$ which is an open subset of $\Omega^*$. This subset $\Theta$ is the interior of the support of the convex function $f^*$, the Legendre--Fenchel transform of $f$, and thus it is convex.

By Proposition~\ref{prop devS is diffeo}, the restriction $\dev_{\vert\widetilde{S}}$ is a diffeomorphism onto $\graph(f)$ so that $\phi = \G \circ \dev$ is a diffeomorphism onto $\Theta^*$.

As $\widetilde{S}$ is preserved by $\pi_1S=\pi_1M$ and $\dev$ is $\rho$-equivariant, $\dev\bp{\widetilde{S}}=\graph(f)$ is preserved by $\rho(\pi_1S)$. Using the equivariance of the Gauss map $\G$, we get that $\Theta^* = \G \circ \dev\bp{\widetilde{S}}$ is preserved by $\rho_{lin}(\pi_1S)$ and that $\phi = \G \circ \dev$ is $\rho_{lin}$-equivariant.
\end{proof}

\begin{corollary}
\label{cor rholin injective}
Let $\rho :\pi_1M~\longrightarrow~\SL\bp{\R^{d+1}}\ltimes\R^{d+1}$ be a holonomy map of a GHCC affine spacetime $\bp{M,\C^M}$. The linear part of $\rho$ is an injective representation $\rho_{lin}: \pi_1M~\longrightarrow~\SL\bp{\R^{d+1}}$. That means, by Remark~\ref{rem necessary condition for affine deformation}, that $\rho(\pi_1M)$ is an affine deformation of its linear part $\rho_{lin}(\pi_1S)$.
\end{corollary}
\begin{proof}
As $S$ is a closed manifold, the action of $\pi_1S$ on $\widetilde{S}$ is free, and thus using the $\rho_{lin}$-equivariance of the diffeomorphism $\phi$ between $\widetilde{S}$ and $\Theta^*$ (Proposition~\ref{prop Gauss on S is equivariant diffeo}), $\rho_{lin}$ must be injective.
\end{proof}

\begin{corollary}
\label{cor theta divisible}
In the setting of Proposition~\ref{prop Gauss on S is equivariant diffeo}, the subgroup $\rho_{lin}(\pi_1S) < \SL\bp{\R^{d+1}}$ is discrete and the open convex domain $\Theta^*$, seen as a projective convex domain inside $\Omega^* \simeq\P\bp{\C^*}$, is divisible by the dual projective action of $\rho_{lin}(\pi_1S) $.
\end{corollary}
\begin{proof}
As $S$ is a closed manifold, the action of $\pi_1S$ on $\widetilde{S}$ is free and properly discontinuous, and thus using the $\rho_{lin}$-equivariance of the diffeomorphism $\phi$ between $\widetilde{S}$ and $\Theta^*$ (Proposition~\ref{prop Gauss on S is equivariant diffeo}), we get that the dual projective action of $\rho_{lin}(\pi_1S) $ on $\Theta^*$ is free and properly discontinuous so $\rho_{lin}(\pi_1S) $ is discrete. Moreover we also have that the quotients $S=\widetilde{S}/\pi_1S$ and $\Theta^*/\rho_{lin}(\pi_1S)$ are diffeomorphic. As $S$ is compact, that means that $\Theta^*$ is divisible by $\rho_{lin}(\pi_1S) $.
\end{proof}

Corollary~\ref{cor theta divisible} indicates that we are in a setting where we can apply Lemma~\ref{lem inclusion and divisibility} to $\Theta^*\subseteq \Omega^*$. That implies that $\Theta^*=\Omega^*$, i.e. that the Gauss map $\G$ in Proposition~\ref{prop Gauss on S is equivariant diffeo} is surjective. Thus the epigraph of $f$ is a $\rho(\pi_1M)$-invariant $\C$-convex domain (Definition~\ref{def C-convex and C-regular domains}). As $\rho_{lin}(\pi_1M) = \rho_{lin}(\pi_1S)$ divides $\C^*$, the cone over $\Omega^*$, by Proposition~\ref{prop dual convex is divisible}, it also divides $\C$. To summarise, we have the following. 

\begin{proposition}
\label{prop dev embeds u.l.c. Cauchy surface}
Let $(\dev,\rho)$ be pair of developing and holonomy maps of a GHCC affine spacetime $(M,\C^M)$. Parametrise $\A^{d+1}$ as $\R^{d+1}$ and consider the proper convex cone $\C \coloneqq \dif \, \dev \bp{\C^M} \subset \R^{d+1}$. The holonomy map $\rho$ is injective and its image is an affine deformation of its linear part $\Gamma\coloneqq \rho_{lin}(\pi_1M)$, which divides the cone $\C$. Introducing $\tau: \Gamma~\longrightarrow~\R^{d+1}$ the cocycle such that $\rho(\pi_1M) = \Gamma_\tau$, if $S$ is a compact locally uniformly convex Cauchy surface of $(M,\C^M)$, the developing map $\dev$ embeds $\widetilde{S}$ in $\R^{d+1}$ as the boundary of a $\C$-spacelike and $C^2_+$ $\tau$-convex domain.
\end{proposition}

\subsection{ Properties of developing maps on GHCC affine spacetimes}
\label{subsec Properties of developing maps on a GHCC affine spacetime}

In this subsection, we extend the results in Proposition~\ref{prop dev embeds u.l.c. Cauchy surface} to properties on developing maps of GHCC affine spacetimes, in order to prove Theorem~\ref{theo GHCC embedding}, which is a classification theorem for GHCC implying Theorem~\ref{Theorem Intro dev}.

\begin{proposition}
\label{prop dev(M) included in Dtau}
Let $(\dev,\rho)$ be pair of developing and holonomy maps of a GHCC affine spacetime $(M,\C^M)$, parametrise $\A^{d+1}$ as $\R^{d+1}$, consider the proper convex cone $\C \coloneqq \dif \, \dev \bp{\C^M} \subset \R^{d+1}$ and, by Proposition~\ref{prop dev embeds u.l.c. Cauchy surface}, introduce $\tau$ a cocycle such that $\rho(\pi_1M) = \Gamma_\tau$ is an affine deformation of the subgroup $\Gamma \coloneqq \rho_{lin}(\pi_1M)$ dividing $\C$. The image $\dev\bp{\widetilde{M}}$ is contained in the maximal $\tau$-convex domain $D_\tau$ of $\bp{\R^{d+1},\C}$.
\end{proposition}
\begin{proof}
Let us set $S$ to be compact locally uniformly convex Cauchy surface of $M$.

First notice that, using Proposition~\ref{prop maximal domain = Cauchy development} and Proposition~\ref{prop dev embeds u.l.c. Cauchy surface}, we have $D\bp{\dev\bp{\widetilde{S}}} = D_\tau$.

Now, let $X =\dev(p) \in \dev\bp{\widetilde{M}}$ and $X(t)$ be an inextensible $\C$-causal curve in $\R^{d+1}$ parametrised by $t \in (-\infty,+\infty)$ and such that $X(0)=X$. As $\dev$ is a local diffeomorphism around $p$, we have that locally around $t=0$ the path $X(t)$ lifts to a causal curve $p(t)$ in $\widetilde{M}$ such that $\dev\bp{p(t)}=X(t)$. 

Let $t^- \in \R_{-}^* \cup \{-\infty\}$ and $t^+ \in \R_{+}^* \cup \{+\infty\}$ be such that $(t^-,t^+)$ is the maximal interval on which the developing map lifts $X(t)$ to a causal curve $p(t)$. By definition of $t^-$ and $t^+$, $\left\lbrace p(t) \st t \in (t^-,t^+) \right\rbrace$ is an inextensible causal curve in $\widetilde{M}$, thus there exist a unique $t_s \in (t^-,t^+)$ such that $p(t_s)$ belongs to the Cauchy surface $\widetilde{S}$. Then, $\dev\bp{p(t_s)}=X(t_s) \in \dev\bp{\widetilde{S}}$.

Thus, any inextensible $\C$-causal curve going through $X = \dev(p)$ intersects $\dev\bp{\widetilde{S}}$, meaning precisely that $\dev(p) \in D\bp{\dev\bp{\widetilde{S}}} = D_\tau$.
\end{proof}


\begin{proposition}
\label{prop dev is injective}
A developing map $\dev: \widetilde{M}~\longrightarrow~\A^{d+1}$ on a GHCC affine spacetime $(M,\C^M)$ is necessarily injective.
\end{proposition}
\begin{proof}
Let us work in the setting of Proposition~\ref{prop dev(M) included in Dtau} and prove it by contradiction. Assume there are $p \neq q \in \widetilde{M}$ such that $\dev(p)=\dev(q)=X \in D_\tau$ (by Proposition~\ref{prop dev(M) included in Dtau}). Let $X(t)$ be an inextensible $\C$-causal curve with $X(0) = X$. As $X \in D_\tau = D \bp{\dev\bp{\widetilde{S}}}$, there is a unique $t_s \in \R$ such that $X(t_s) \in \dev\bp{\widetilde{S}}$. Following what was done in the proof of Proposition~\ref{prop dev(M) included in Dtau}, there are real numbers $t^-<\min(0,t_s)$ and $t^+>\max(0,t_s)$ such that for all $t \in (t^-, t^+)$,
\begin{equation*}
X(t)= \dev\bp{p(t)} = \dev\bp{q(t)},
\end{equation*}
where $p(t),q(t)$ are causal curves in $\widetilde{M}$ and $p(t_s),q(t_s) \in \widetilde{S}$. As 
\begin{equation*}
X(t_s)=\dev\bp{p(t_s) } = \dev\bp{q(t_s) },
\end{equation*}
using the injectivity of the developing map on $\widetilde{S}$ (Proposition~\ref{prop dev embeds u.l.c. Cauchy surface}), one gets that $p(t_s)=q(t_s)$ (thus $t_s\neq 0$).

If $t_s<0$, let $T = \max \left\lbrace t \in [t_s,0] \st p(t)=q(t)\right\rbrace$ which is well-defined because of the continuity of $p(t)$ and $q(t)$ and that $p(t_s)=q(t_s)$. By assumption $p(0) \neq q(0)$ and thus $t_s \leq T<0$. Then for all $\varepsilon >0$ such that $T< T + \varepsilon < 0$, we have 
\begin{equation*}
p(T +\varepsilon) \neq q(T+ \varepsilon) \quad \textup{and} \quad X(T+\varepsilon) = \dev\bp{p(T + \varepsilon) } = \dev\bp{q(T + \varepsilon) } ,
\end{equation*} 
which contradicts the fact that $\dev$ is a local diffeomorphism at $p(T)=q(T)$ (see Figure~\ref{fig Developing}).

The case where $t_s>0$ can be treated in a similar way.
\end{proof}

