\centering
\includegraphics{Developing_figure.pdf}
\caption{Illustration of the situation in the proof of Proposition~\ref{prop dev is injective}.}
\label{fig Developing}
\end{figure}

\begin{theorem}
\label{theo GHCC embedding}
Let $(M,\C^M)$ be a GHCC affine spacetime. Any pair $\bp{\dev,\rho}$ of a developing map
\begin{equation*}
\dev: \widetilde{M}~\longrightarrow~\R^{d+1},
\end{equation*}
and a holonomy map 
\begin{equation*}
\rho: \pi_1M~\longrightarrow~\SA\bp{\R^{d+1}},
\end{equation*}
given by its equiaffine structure satisfies the following:
\begin{itemize}
\item the holonomy map $\rho$ is a group isomorphism onto its image $ \rho(\pi_1M)$ which is an affine deformation $\Gamma_\tau$ of a subgroup $\Gamma < \SL\bp{\R^{d+1}}$ dividing the cone $\C \coloneqq \dif \, \dev(\C^M)$, 
\item the developing map $\dev$ is an isomorphism of affine spacetimes onto its image which is included in $(D_\tau,\C)$, where $D_\tau $, the domain associated with $\Gamma_\tau \coloneqq \rho(\pi_1M)$ and $\C$, is given by Theorem~\ref{Theorem Intro domain},

\item the developing map $\dev$ descends to an embedding $(M,\C^M)~\lhook\joinrel\longrightarrow~\bp{D_{\tau} / \Gamma_\tau, \C}$ preserving the equiaffine and cone structures, and mapping any locally uniformly convex and compact Cauchy surface of $(M,\C^M)$ to a locally uniformly convex and compact Cauchy surface of $\bp{D_{\tau} / \Gamma_\tau, \C}$.
\end{itemize}
\end{theorem}
\begin{proof}
The first point is a consequence of Proposition~\ref{prop dev embeds u.l.c. Cauchy surface} and the second one of Propositions~\ref{prop dev(M) included in Dtau} and~\ref{prop dev is injective}. Finally, using those two first points and the equivariance of the developing map we get the third one.
\end{proof}

In Theorem~\ref{theo GHCC embedding}, if moreover $(M,\C^M)$ is a MGHCC, then the definition of \emph{maximality of globally hyperbolic affine spacetimes} (Definition~\ref{def Maximal}) implies that the embedding $(M,\C^M)~\lhook\joinrel\longrightarrow~\bp{D_{\tau} / \Gamma_\tau, \C}$ given by the developing map must be surjective, proving Theorem~\ref{Theorem Intro dev}.

\subsection{\texorpdfstring{Maximality of the quotient spacetimes $D_\tau / \Gamma_\tau$}{Maximality of the quotient spacetimes D-tau / Gamma-tau}}
\label{subsec Maximality of the quotient spacetimes}

In this subsection, we use the preceding work in order to prove the maximality of spacetimes built with Theorem~\ref{Theorem Intro domain}.

Let $\Gamma_\tau < \SL \bp{\R^{d+1}} \ltimes \R^{d+1}$ be an affine deformation of a group $\Gamma < \SL \bp{\R^{d+1}}$ dividing an open proper convex cone $\C$. We consider the associated spacetimes $\bp{D_{\tau}^{\C} / \Gamma_\tau , \C}$ given by Theorem~\ref{Theorem Intro domain}. In Section~\ref{sec Quotient of the maximal domain} we have proved that it is a GHCC affine spacetime. Using the results from subsection~\ref{subsec Properties of developing maps on a GHCC affine spacetime} we have the following.

\begin{theorem}[Theorem~\ref{Theorem Intro domain}~\ref{theo12}]
\label{theo maximality of spacetime}
Let $\Gamma_\tau < \SL \bp{\R^{d+1}} \ltimes \R^{d+1}$ is an affine deformation of a group $\Gamma < \SL \bp{\R^{d+1}}$ dividing an open proper convex cone $\C$. The GHCC affine spacetime $\bp{D_{\tau} / \Gamma_\tau, \C}$ is a maximal globally hyperbolic spacetime.
\end{theorem}

\begin{proof} 
Let $i: \bp{D_{\tau}/ \Gamma_\tau, \C}~\lhook\joinrel\longrightarrow~(M',\C')$ be an embedding preserving the equiaffine and cone structures, and mapping a locally uniformly convex compact Cauchy surface $S$ of $D_{\tau} / \Gamma_\tau$ to a Cauchy surface $S'$ of $M'$.

First, notice that, because $i$ preserves the equiaffine structure, $S'$ is also a locally uniformly convex Cauchy surface and thus $(M',\C')$ is also a GHCC affine spacetime. It lifts to an embedding $\widetilde{i}: \bp{D_{\tau}, \C}~\lhook\joinrel\longrightarrow~\bp{\widetilde{M'},\C'}$ also preserving the equiaffine and cone structures, and mapping a locally uniformly convex Cauchy surface $\widetilde{S}$ of $D_{\tau}$ to a locally uniformly convex Cauchy surface $\widetilde{S'}$ of $\widetilde{M'}$. We want to show that $i$ is surjective.

Now, let $(\dev, \rho)$ be a couple of developing and holonomy maps for the the GHCC affine spacetime $(M',\C')$. Theorem~\ref{theo GHCC embedding} states that, $\rho(\pi_1 M')$ is an affine deformation $\Gamma''_{\tau''}$ of its linear part $\Gamma'' < \SL\bp{\R^{d+1}}$, which divides a proper convex cone $\C''$. It also states that the developing map $\dev$ on $\bp{\widetilde{M'},\C'}$ embeds it into $\bp{D''_{\tau''}/ \Gamma''_{\tau''}, \C''}$.

Consider the following embedding $\widetilde{j} = \dev \circ \widetilde{i}: (D_{\tau},\C)~\lhook\joinrel\longrightarrow~(D_{\tau''},C'')$, which descends to an embedding $j: \bp{D_{\tau}/ \Gamma_\tau, \C}~\lhook\joinrel\longrightarrow~\bp{D_{\tau''}/ \Gamma_{\tau''}, \C''}$. It preserves the equiaffine structure between two convex domains of $\R^{d+1}$ so it is of the form $\widetilde{j}: X~\longmapsto~AX$, where $A \in \SL\bp{\R^{d+1}}$. Thus, up to post-composing we can assume that $\widetilde{j}$ is a restriction of the identity. 

As the embedding $\widetilde{j}$ is a restriction of the identity, we clearly have $D_\tau \subseteq D_{\tau''}$. Moreover as $\widetilde{j}$ preserves the cone structure, we also have $\C= \C''$. 

Using the immersion $i : \bp{D_{\tau}/ \Gamma_\tau, \C}~\lhook\joinrel\longrightarrow~(M',\C') $ one can see $\pi_1\bp{D_{\tau}/ \Gamma_\tau}\simeq \Gamma_\tau$ as included in $\pi_1M'$. Actually, as $S$ is a Cauchy surface of $M$ and $S'=i(S)$ is a Cauchy surface of $M'$, by Proposition~\ref{prop Geroch Cauchy surfaces}, we have an identification
\begin{equation*}
 \Gamma_\tau \simeq \pi_1\bp{D_{\tau}/ \Gamma_\tau} \simeq \pi_1S \overset{i}{\simeq}\pi_1 S'\simeq \pi_1M'.
\end{equation*}
Then, using that identification, the embedding $\widetilde{j} = \dev \circ \widetilde{i}$ is $\rho$-equivariant in the sense that for all $(\gamma,\tau_\gamma) \in \Gamma_\tau \simeq \pi_1M'$ and $X\in D_\tau$, we have 
\begin{equation*}
\widetilde{j} (\gamma X + \tau_\gamma) = \rho(\gamma,\tau_\gamma) \cdot \widetilde{X},
\end{equation*}
where $\rho(\gamma,\tau_\gamma)\in \SA\bp{\R^d}$. As $\widetilde{j}$ is a restriction of the identity and $D_\tau$ is open, we get that the affine transformations $(\gamma,\tau_\gamma)$ and $\rho(\gamma,\tau_\gamma)$ are equal. Thus $\Gamma''_{\tau''} = \rho(\pi_1M')=\Gamma_\tau$.

Finally, that implies that $\widetilde{j} = \Id_{\vert D_{\tau}}$ is surjective. Hence, as $\widetilde{j} = \dev \circ \widetilde{i}$ and $\dev$ is a diffeomorphism onto its image, $\widetilde{i}$ is also surjective and so is $i$.
\end{proof}

\begin{remark}
Let $(M,\C)$ be a MGHCC affine spacetime, like in subsection~\ref{subseclength of causal curves}, using affine spheres in the tangent spaces of $M$, one can again define a norm $F$ on $\C$-null and $\C$-timelike vectors, a length $l_F$ of $\C$-causal curve and a $\C$-distance $\rho$ satisfying the time inequality. Theorem~\ref{Theorem Intro dev} implies that again this norm endows $(M, \C)$ with a timelike space structure in the sense of Busemann \cite{Busemann_67}, and that the cosmological time on $(M,\C)$ satisfies 
\begin{align*}
\mathcal{T}(p) & = \sup \left\lbrace \rho(q,p) \st q \in J^-(p) \right\rbrace, \\
& = \sup \left\lbrace l_F(\gamma) \st \gamma \textup{ is a future directed $\C$-causal curve from a point of $J^-(p)$ to $p$} \right\rbrace.
\end{align*}
\end{remark}

\appendix

\section{Examples of dividing groups admitting affine deformations}
\label{sec Examples of affine deformations}

This appendix is devoted to the construction of examples proving the following proposition.

\begin{proposition}
In any dimension $d \geq 2$, there exists a discrete subgroup $\Gamma < \SL\bp{\R^{d+1}}$ dividing a proper convex cone $\C \subset \R^{d+1}$ over a proper convex domain $\Omega \subset\P\bp{\R^{d+1}}$ which is not projectively equivalent to an ellipse (giving the Klein ball model of the hyperbolic space).
\end{proposition}

\subsection*{Bending of holonomy groups}

An amalgamated product $\Gamma = \Gamma'*_\Lambda \Gamma'' < \SL\bp{\R^{d+1}}$ can be algebraically deformed through the following general procedure called \emph{bending} and deeply studied by Johnson and Millson \cite{Johnson_Millson_87}. Let $\bp{A_s}_{s\in\R}$ be a continuous path of elements of $\SL\bp{\R^{d+1}}$ such that $A_0$ is the identity and every $A_s$ commutes with all the elements of $\Lambda$. Then the bending procedure consists in continuously deforming $\Gamma$ by looking at the family $\Gamma_s = \Gamma'*_\Lambda \bp{A_s\Gamma''A_s^{-1}}$.

\subsection*{Bulging the holonomy groups of hyperbolic manifolds}

Let $\Gamma_0 < \SO_0(d,1)$ be the holonomy group of a closed hyperbolic $d$-dimensional manifold $M = \mathbb{B}^d/\Gamma_0$ (using the Klein ball projective model of the hyperbolic space) containing a totally geodesic embedded compact connected hypersurface $N$ separating $M$ into two connected components: $M \setminus N = M' \sqcup M''$. We shall deform $\Gamma_0$ through a particular bending procedure called \emph{bulging} (following the nomenclature in \cite{Blayac_Viaggi_24}).

Using the inclusion $i:\pi_1 N \hookrightarrow \pi_1 M$ and taking the image by the holonomy of $\pi_1 N$ we get a subgroup $\Lambda < \Gamma_0$ preserving a hyperplane $H$ intersecting the Minkowski light cone $\C_0$. Then $H \cap \bp{\mathbb{B}^d \times \{1\}}$ is a connected preimage of $N$ by the projection $\mathbb{B}^d \times \{1\}~\longrightarrow~M= \mathbb{B}^d/\Gamma_0$ and a universal cover over $N$. For $k \in \{1,2\}$, using the inclusion $i^{(k)}:\pi_1 M^{(k)} \hookrightarrow \pi_1 M$ and setting $\Gamma_0^{(k)}$ to be the holonomy of $\pi_1 M^{(k)}$, by the Seifert--van Kampen Theorem we can see the holonomy group of $M$ as the amalgamated product $\Gamma_0 = \Gamma_0' *_\Lambda \Gamma_0''$.

Let $X \in \R^{d,1}=\R^{d+1}$ be a unit Minkowski spacelike vector orthogonal to the hyperplane $H$. For later constructions, it is worth noting that $X$ is a common eigenvector, with associated eigenvalue $1$, of all elements of $\Lambda$. For $s \in \R$, let $A_s \in \SL\bp{\R^{d+1}}$ be the element that restricts to the homothety $e^s I_n$ on $H$ and sends $X$ to $e^{-d s}X$ (in a well-chosen basis it has form $\mathrm{Diag}(e^s,\dots,e^s,e^{-ds})$ and thus its determinant is indeed $1$). As $A_s \gamma A_s^{-1} = \gamma$, for all $\gamma \in \Lambda$, we can continuously deform $\Gamma_0$ by bulging by considering $\Gamma_s \coloneqq \Gamma_0' *_\Lambda \bp{A_s \Gamma_0'' A_s^{-1}} < \SL\bp{\R^{d+1}}$. Then, by the work of Koszul \cite{Koszul_70} and Benoist \cite{Benoist_05}, each group $\Gamma_s$ happens to also divide an open proper convex cone $C_s$, which is not affinely equivalent to the Minkowski light cone if $s\neq 0$ \cite[Section 8.2]{Benoist_08}. 

\subsection*{Bending to get affine deformations of groups obtained by bulging}

Let us now prove that such a group $\Gamma \coloneqq\Gamma_{s_0}$ (we fix $s_0$ for the rest of this section) obtained by bulging admits a non-trivial cocycle $\tau \in \mathrm{H}^1\bp{\Gamma, \R^{d+1}}$, i.e. that $\Gamma$ admits a non-trivial affine deformation $\Gamma_\tau < \SL\bp{\R^{d+1}}\ltimes \R^{d+1}$. We shall proceed by seeing $\SL\bp{\R^{d+1}}$ as included in $\SL\bp{\R^{d+1}}\ltimes \R^{d+1}$ in order to bend the amalgamated product $\Gamma = \Gamma'*_\Lambda \Gamma''$ (where $\Gamma'=\Gamma_0'$ and $\Gamma''= A_s \Gamma_0'' A_s^{-1})$. 

Remembering that there is $X \in \R^{d+1}$, a common eigenvector, with associated eigenvalue $1$, of all elements of $\Lambda$, we set for all $s \in \R$, $B_s = (I,sX) \in \SL\bp{\R^{d+1}}\ltimes \R^{d+1}$, where $I$ is the identity in $\SL\bp{\R^{d+1}}$. Then notice that for all $\gamma \in \Gamma$ and $s \in \R$,
\begin{equation}
\label{eq linear part of bending}
B_s(\gamma,0)B_s^{-1} = \bp{\gamma, s(X - \gamma X)}.
\end{equation}
If moreover $\gamma \in \Lambda$, as $X$ is an eigenvector of $\gamma$ with associated eigenvalue $1$, it becomes 
\begin{equation*}
B_s(\gamma,0)B_s^{-1} = (\gamma, 0).
\end{equation*}
Thus, we can consider the bending of $\Gamma = \Gamma_{\tau=0} < \SL\bp{\R^{d+1}}\ltimes \R^{d+1}$ by the family $(B_s)_{s \in \R}$. We get a family of groups $G_s = \Gamma' *_\Lambda \bp{ B_s \Gamma'' B_{s}^{-1}}$ in $\SL\bp{\R^{d+1}}\ltimes \R^{d+1}$. Equality \eqref{eq linear part of bending} implies that we have actually built a family of affine deformations $\bp{\Gamma_{\tau_s}}_{s \in \R}$ of $\Gamma$. 

To conclude, let us prove that for $s \neq 0$, such a deformation is non-trivial. It suffices to prove it for $s=1$. In order to lighten expressions we shall denote $\tau_1$ by $\tau$. By contradiction, assume that $\tau$ is a coboundary, that is that we can set $V \in \R^{d+1}$ such that for all $\gamma \in \Gamma$, $\tau(\gamma) = (I - \gamma)V$. For all $\gamma' \in \Gamma'$, we have 
\begin{equation*}
\tau(\gamma') = (I - \gamma')V = 0,
\end{equation*}
thus $V$ is either $0$ or an eigenvector of all $\gamma' \in \Gamma'$ with associated eigenvalue $1$.

As $\Lambda$ is conjugate to a subgroup of the form
\begin{equation*}
\vp{\begin{array}{c|c}
G & 0 \\
\hline 0 & 1 
\end{array}} < \SL\bp{\R^{d+1}}
\end{equation*}
where $G < \SO(d-1,1)$ is the holonomy group of a closed hyperbolic $(d-1)$-dimensional manifold $N$, its only common eigenvector is $X$. Thus, $V$ is necessarily in the span of $X$. 

We claim that for all $\gamma \in \Gamma \setminus \Lambda$, $X$ is not an eigenvector of $\gamma$ with associated eigenvalue $1$. Then, for $\gamma' \in \Gamma' \setminus \Lambda$, as $X$ is not a an eigenvector with associated eigenvalue $1$ of $\gamma'$, if $V \neq 0$, then
\begin{equation*}
\tau(\gamma') = (I - \gamma')V \neq 0,
\end{equation*}
so necessarily $V=0$. But then for $\gamma'' \in \Gamma'' \setminus \Lambda$, as $X$ is not a an eigenvector with associated eigenvalue $1$ of $\gamma''$,
\begin{equation*}
\tau(\gamma'') = (I - \gamma'')X \neq 0,
\end{equation*}
and thus $V \neq 0$. That is a contradiction.

Now let us prove our claim. Let $\gamma \in \Gamma \setminus \Lambda$, if $X$ was an eigenvector of $\gamma$ with associated eigenvalue $1$ we would have that $\gamma$ preserves the hyperplane $H$, thus any straight path from a point $P \in \C \cap H$ to $\gamma P$ would descends to a loop in $N$ with holonomy $\gamma$, which is not in $\Lambda$, the image of $\pi_1 N$ by the holonomy .

\section{The projective approach to affine deformations}
\label{sec Projective approach}
This appendix offers a more projective approach to affine deformations in order to link the work of this article to the notion of convex cocompact representation \cite{DGK_17} .

Let $\Gamma$ be a torsion-free discrete subgroup of $\SL \bp{\R^{d+1}}$ dividing an open proper convex cone $\C$ in $\R^{d+1}$. Seeing the affine space $\R^{d+1}$ as an affine chart of the $(d+1)$-dimensional real projective space $\P\bp{\R^{d+2}}$:
\begin{equation*}
\namelessembedding{\R^{d+1}}{\P\bp{\R^{d+2}}}{X}{(X:1)},
\end{equation*}
we can see $\SA \bp{\R^{d+1}} = \SL\bp{\R^{d+1}} \ltimes \R^{d+1}$ as a Lie subgroup of $\PGL\bp{\R^{d+2}}$:
\begin{equation*}
\namelessembedding{\SL\bp{\R^{d+1}} \ltimes \R^{d+1}}{\PGL\bp{\R^{d+2}}}{ (\gamma,\tau)}{\left[\begin{matrix} \gamma & \tau \\ 0 & 1 \end{matrix}\right]}.
\end{equation*}
As $\Gamma$ divides the cone $\C = \left\lbrace t(x,1) \st x \in \Omega, t>0 \right\rbrace$, the domain $\Omega_\P$ defined by
\begin{equation*}
\Omega_\P \coloneqq \left\lbrace (x:1:0) \st x \in \Omega \right\rbrace \subseteq \P\bp{\R^{d+2}}
\end{equation*}
is preserved by $\Gamma$ seen a subgroup of $\PGL\bp{\R^{d+2}}$. Let $\C_\P$ be the cone over $\Omega_\P$ with vertex at $[e_{d+2}] = (0:\dots:0:1)\in \P\bp{\R^{d+2}}$, i.e.
\begin{equation*}
\C_\P \coloneqq \Omega_\P \cup \left\lbrace (tx:t:1) \st x \in \Omega,t \neq 0 \right\rbrace = \Omega_\P \cup \left\lbrace (X:1) \st X \in \C \right\rbrace.
\end{equation*}
Then $\C_\P$ is also preserved by $\Gamma$ and moreover, noticing that 
\begin{equation*}
\C_\P = \left\lbrace (x:1:\lambda) \st x \in \Omega,\lambda \in \R \right\rbrace,
\end{equation*}
we easily see that $\C_\P$ is convex and homeomorphic to $\Omega \times \R$. Its polar cone in the dual projective space $\P\bp{\R^{d+2}}^*$, identified with $\P\bp{\R^{d+2}}$ using the usual scalar product on $\R^{d+2}$, is homeomorphic to $\Omega^* \times \R$ and can be expressed as 
\begin{equation}
\label{eq projective polar cone as a pipe}
\C_\P^* = \left\lbrace (y:-1:\mu) \st y \in \Omega^*,\mu \in \R \right\rbrace.
\end{equation}
Let $\Gamma_\tau$ be an affine deformation of $\Gamma$. An element $ (\gamma, \tau_\gamma) \in \Gamma_\tau$ acts:
\begin{itemize}
\item on $\P\bp{\R^{d+2}}$ by 
\begin{equation*}
(\gamma, \tau_\gamma) \cdot (X:1) = (\gamma X + \tau_\gamma: 1) \quad \textup{and} \quad (\gamma, \tau_\gamma) \cdot (X:0) = (\gamma X:0),
\end{equation*}
\item on $\P\bp{\R^{d+2}}^*$ by 
\begin{equation*}
(\gamma, \tau_\gamma) \star (Y:1) = (\gamma \star Y: 1 + \tau_{\gamma^{-1}} \cdot Y) \quad \textup{and} \quad (\gamma, \tau_\gamma) \star (Y:0) = (\gamma \star Y:0),
\end{equation*}
where $\gamma \star Y = \gamma^{\top}Y$. That dual action comes from the action of $\SA^* \bp{\A^{d+1}}$, the group of \emph{coaffine transformations} \cite{Bobb_Farre_24} seen as a subgroup of $\PGL^*\bp{\R^{d+1}}$:
\begin{equation*}
\namelessembedding{\SL^*\bp{\R^{d+1}} \ltimes \bp{\R^{d+1}}^*}{\PGL^*\bp{\R^{d+2}}}{(\eta,\theta)}{\left[\begin{matrix} \eta & 0 \\ \theta & 1 \end{matrix}\right]},
\end{equation*} 
in which $\Gamma_\tau$ is seen as
\begin{equation*}
\left\lbrace \left[\begin{matrix} \gamma^{-\top} & 0 \\ \bp{\tau_{\gamma^{-1}}}^\top & 1 \end{matrix}\right] \in \PGL^*\bp{\R^{d+1}} \st \gamma \in \Gamma \right\rbrace.
\end{equation*}
\end{itemize}
If $s$ is the support function of a $\tau$-convex domain, using the identification \eqref{eq projective polar cone as a pipe}, we can see its graph as embedded in $\P\bp{\R^{d+2}}^*$:
\begin{equation*}
\graph_\P(s) \coloneqq \left\lbrace \bp{y:-1:-s(y)} \st y \in \Omega^*\right\rbrace = \left\lbrace \bp{Y:-\tilde{s}(Y)} \st Y \in \C^*\right\rbrace
\end{equation*}
Then the $\tau$-equivariance \eqref{eq action on C* support function} of $s$ precisely tells that $\graph_\P(s)$ is $\Gamma_\tau$-invariant. The existence of the unique boundary function $g_\tau: \partial \Omega^*~\longrightarrow~\R$ (Proposition~\ref{prop existence of boundary function gtau}) thus tells us that there exist a $\Gamma_\tau$-invariant limit set $\Lambda_\tau \subset \partial \C_\P^*$ defined by
\begin{equation*}
\Lambda_{\tau}^* \coloneqq \graph_\P(g_\tau) \coloneqq \left\lbrace \bp{y:-1:-g_\tau(y)} \st y \in \Omega^*\right\rbrace.
\end{equation*} 

\begin{definition} [{\cite[Definition 1.1]{DGK_17}}]
Let $G < \PGL\bp{\R^{d+2}}$ be an infinite discrete subgroup.
\begin{itemize}
\item Let $W$ be a $G$-invariant properly convex open subset of $\P\bp{\R^{d+2}}$. The action of $G$ on $W$ is \emph{strongly convex cocompact} if $W$ is strictly convex with $C^1$ boundary and that for some $p \in W$, the convex hull in $W$ of the \emph{orbital limit set} $\overline{\Gamma_\tau \cdot p}\cap \partial W$ is non-empty
and has compact quotient by $G$.
\item The group $G$ is \emph{strongly convex cocompact in $\P \bp{\R^{d+2}}$} if it admits a strongly convex cocompact action on some properly convex open subset $W$ of $\P\bp{\R^{d+2}}$.
\end{itemize}
\end{definition}

\begin{proposition}
When $\Gamma$ is hyperbolic, $\Gamma_\tau$ is strongly convex cocompact in $\P \bp{\R^{d+2}}^*$, and $\Lambda_{\tau}^*$ is its orbital limit set.
\end{proposition}

\begin{remark}
\label{rem hyperbolic group gives C1 domain}
By the work of Benoist \cite[Theorem 1.1]{Benoist_04}, if $\Gamma$ is hyperbolic, then the domain $\Omega^*$ is strictly convex and $\partial \Omega^*$ is $C^1$.
\end{remark}

\begin{proof}
For the fact that $\Gamma_\tau$ is strongly convex cocompact, one way to proceed is to realise that $\Gamma_\tau \simeq \Gamma$ is hyperbolic and show that the action of $\Gamma_\tau$ is projective-Anosov, as in \cite[Lemma 3.6]{Bobb_Farre_24}, and then use Theorem 1.4 from \cite{DGK_17}. In fact, we can explicitly build a $C^1$ strictly convex $\Gamma_\tau$-invariant domain of $\P \bp{\R^{d+2}}^*$ on which the action of $\Gamma_\tau$ is strongly convex cocompact. In Proposition~\ref{prop exists tau-support function extending to boundary} we proved the existence of $s_-$ and $s_+$, two smooth $\tau$-equivariant function on $\Omega^*$ which are respectively locally uniformly convex and locally uniformly concave satisfying that for all $y \in \partial \Omega^*$,
\begin{equation}
\label{eq gradient of s+_}
\left\vert \grad s_\pm(y')\right\vert \xrightarrow[y' \to y]{} +\infty.
\end{equation}
Consider the following convex domain in $\P \bp{\R^{d+2}}^*$:
\begin{equation*}
W^* \coloneqq \left\lbrace \bp{y:-1:-\mu} \st y \in \Omega^*, s_-(y) < \mu < s_+(y)\right\rbrace \subset \C_\P^*.
\end{equation*}
We claim that the dual action of $\Gamma_\tau$ on $W^*$ is strongly convex cocompact.

We decompose the boundary of $W^*$ as 
\begin{equation*}
\partial W^* = \graph_\P(s_-) \cup \Lambda_{\tau}^* \cup \graph_\P(s_-).
\end{equation*}
The strict convexity of $\Omega^*$ and the respective strict convexity and concavity of $s_-$ and $s_+$ tells us that there is no line segment in $\partial W^*$, i.e. that $W^*$ is strictly convex. 

By Proposition~\ref{prop C1 convex function}, in order to prove that $\partial W^*$ is $C^1$, we only have to prove that at each point of its boundary $W^*$ admits only one supporting hyperplane. Using the smoothness of $s_-$ and $s_+$, that is clear for points in $ \graph_\P(s_+) \cup \graph_\P(s_-)$. Let $P = \bp{y:-1:-g_\tau(y)}$ be a point of $\Lambda_{\tau}^* \subset \partial W^*$, then condition \eqref{eq gradient of s+_} implies that any supporting hyperplane to $W^*$ at $P$ is a supporting hyperplane (at $P$) to the convex domain $\C^*_\P = \left\lbrace (y:-1:\mu) \st y \in \Omega^*,\mu \in \R \right\rbrace$ which has $C^1$ boundary because of Remark~\ref{rem hyperbolic group gives C1 domain}, and is thus unique. Hence, we have that $\partial W^*$ is $C^1$.

Let $P = \bp{y:-1:-\mu}$ be a point of $W^*$. Using the well-known dynamic of the action of $\Gamma$ on $\Omega^*$ \cite[Proposition 5.1]{Benoist_04} and the fact that any $\tau$-invariant function extends continuously to $g_\tau$, we get that the proximal limit set of the action of $\Gamma_\tau$ on $W^*$ is $\overline{\Gamma_\tau \cdot P}\cap \partial W^* = \Lambda_{\tau}^*$.

Finally, taking barycentres of its two boundary graphs, one can easily foliate $\mathrm{CH}_\P^*(\tau)$ the convex hull of $\Lambda_\tau^*$ by $\Gamma_\tau$-invariant graphs. That means that it is cocompact for the action of $\Gamma_\tau$: it is the universal cover of the convex core $\mathrm{CC}^*_\P(\tau) \coloneqq \mathrm{CH}^*_\P(\tau) / \Gamma_\tau \simeq \Omega^* / \Gamma \times [0,1]$.
\end{proof}


\begin{remark}
Notice that when $\Gamma$ is not hyperbolic, we still have a limit set $\Lambda_\tau^*$, but it does not come from a projective-Anosov property: there is no limit map $\partial \Gamma_\tau~\longrightarrow~\Lambda_\tau^*$.
\end{remark}


