\section{Fast iterative algorithm for solving nonlinear least-squares problems with a nonlinear  constraint}\label{sec:Fast_iterative_algorithm}


The optimization problem we derived in \cref{full_dis_sol} is a constrained least-squares problem with two nonlinear terms. First, the vector function $ \mathbf{b}_k(\boldsymbol{\eta}) $ within the objective function introduces nonlinearity. Second, the energy constraint is quadratic in nature with a scalar nonlinear function $ \mathcal{N}_{F}(\boldsymbol{\eta}) $. 
In this section, we propose a fast iteration algorithm to enhance computational efficiency and convergence speed. 
This  algorithm uses the Newton method with successive linearization to cope with the nonlinear components and the quadratic constraint.

Our algorithm is based on the combination of Generalized Singular Value Decomposition (GSVD) and the Lagrange multiplier method with linearization. 
Due to the nonlinearity of both the problem and its constraint, we employ an alternating iteration method.

Firstly, we compute the GSVD of matrices $A, B$ in \cref{full_dis_sol} as
\begin{equation}\label{GSVD}
    \begin{aligned}
    A=UCH^{T},\quad B=VSH^{T},
    \end{aligned}
\end{equation}
where $C = \text{diag}(c_1, \ldots, c_{n_Z})$, $S = \text{diag}(s_1, \ldots, s_{n_Z})$ with nonnegative entries,  $U, V$ are unitary matrices, and $H$ is invertible.

%\blue{(The Lagrangian function for \cref{full_dis_sol} is differentiated with respect to $\eta$ and $\lambda$ respectively)}

Secondly, linearization is applied to \(\mathbf{b}_k(\boldsymbol{\eta})\) and \(\mathcal{N}_{F}(\boldsymbol{\eta})\), followed by the method of Lagrange multipliers to solve \cref{full_dis_sol}, yielding:
\begin{eqnarray}
  C^T\big(  C H^T \boldsymbol{\eta} - U^T\mathbf{b}_k(\boldsymbol{\eta}^{j-1}) \big) + \lambda S^T\big(S H^T \boldsymbol{\eta} - V^T\mathbf{d} \big) &=& 0,
  \label{LM1}\\
  \big\| S H^T \boldsymbol{\eta} - V^T\mathbf{d} \big\|^2 + \mathcal{N}_{F}(\boldsymbol{\eta}^{j-1})  &=& 0.
  \label{LM2}
\end{eqnarray}
%The first equation \eqref{LM1} is a diagonal system. 
Let $\boldsymbol{\zeta} = H^T \boldsymbol{\eta},$
then  \cref{LM1} becomes  a diagonal system:
\begin{equation}
(C^T C + \lambda S^T S) \boldsymbol{\zeta} = C^T U^T\mathbf{b}_k(\boldsymbol{\eta}^{j-1}) + \lambda S^T V^T \mathbf{d}.
\end{equation}
It allows us to express the  $\boldsymbol\zeta$ explicitly in terms of $\lambda$. 

From $t^{k-1}$ to $t^k$,  we consider an alternating iteration on RBF coefficients and Lagrange multiplier $(\boldsymbol\eta^{j}, \lambda_j)\in \mathbb{R}^{n_Z}\times\mathbb{R}$ at some iterative step $j\geq 1$ with some initial values $(\boldsymbol\eta^{0}, \lambda_0)$ based on the solution at $t^{k-1}$.
We define the iterative solution as 
\begin{equation}\label{eta^j}
  \boldsymbol{\eta}^{j}(\lambda) = H^{-T} (C^TC + \lambda S^TS)^{-1} \big(C^TU^T\mathbf{b}_k(\boldsymbol{\eta}^{j-1})+ \lambda S^TV^T \mathbf{d}\big).
\end{equation}
We can now put \cref{eta^j} into the EC
 \eqref{LM2} to express it as
 a function of $\lambda$:
\begin{equation}\label{Ce}
    \mathcal{C}_E( \lambda ) := \big\| S H^T \boldsymbol{\eta}^j(\lambda) - V^T\mathbf{d} \big\|^2 + \mathcal{N}_{F}(\boldsymbol{\eta}^{j-1}).
\end{equation}
It is analogous to a previously proposed solver for least-squares optimization problems with quadratic inequality constraint \cite{Li+Ling-CollMethCaucProb:19}.
The standard method of  Lagrange multipliers requires $\lambda_j$ to be the root of $\mathcal{C}_E( \lambda_j ) = 0$. 

Thirdly, we propose to apply the Newton method and define
\begin{equation}\label{lam_j}
  \lambda_j := \lambda_{j-1} - \frac{\mathcal{C}_E( \lambda_{j-1} )}{\mathcal{C}_E^{'}( \lambda_{j-1} )}.
\end{equation} 
The iteration alternates between: 

(a) \textbf{RBF coefficient update:} For a fixed \(\lambda_{j-1}\), compute \(\boldsymbol{\eta}^{j}\) via \cref{eta^j}.

(b) \textbf{Multiplier update:} For a fixed \(\boldsymbol{\eta}^{j-1}\) within \(\mathcal{C}_E(\lambda)\), compute the new \(\lambda_j\) via \cref{lam_j}.


We iterate until $|\mathcal{C}_E( \lambda_J )| < \text{tol}$ at some iterative step $J$, for some tolerance $\text{tol}$, and the RBF coefficient vector is $\boldsymbol{\alpha}^{k} = \boldsymbol{\eta}^{J}(\lambda_J)$. We summarize the process of updating from $\boldsymbol{\alpha}^{k-1}$ to $\boldsymbol{\alpha}^{k}$ for $k\geq 1$ in  Algorithm \ref{alg:update_alpha}.


\begin{algorithm}[H]
\caption{The Newton method with successive linearization}
\label{alg:update_alpha}
\begin{algorithmic}[0]
\STATE{Step 1} 
\STATE{\qquad\textbf{Initialization:}} 
\STATE{\hspace*{3em}\customitem {Initial solution and Lagrange multiplier: \((\boldsymbol{\eta}^{0}, \lambda_0) = (\boldsymbol{\alpha}^{k-1}, 0)\),}}
\STATE{\hspace*{3em}\customitem{Tolerance for stopping criterion: \text{tol},}}
\STATE{\hspace*{3em}\customitem{Maximum number of iterations: $j_{\text{max}}$.}}
\STATE{Step 2} 
\STATE{\qquad Compute the GSVD  of matrices $A$ and $B$ as in \cref{GSVD}.}
\STATE{\qquad Compute the 
$\boldsymbol{\eta}^{0}(\lambda_0)$ in \cref{eta^j} and
constraint error
$\mathcal{C}_E^{}(\lambda_0)$ in \cref{Ce}.}
\STATE{Step 3} 
\STATE{\qquad $j=0$.}

\qquad\algorithmicwhile { ($j \leq j_{\text{max}}  \text{ and }  |\mathcal{C}_E(\lambda_{j})|> \text{tol}$)}
\STATE{\hspace*{3em} Let $j=j+1$.}
\STATE{ \hspace*{3em} Evaluate  $\lambda_j$ by  \cref{lam_j}.}
\STATE{\hspace*{3em} Compute the 
constraint error
$\mathcal{C}_E^{}(\lambda_j)$ via \cref{Ce} and $\mathcal{C}_E^{'}(\lambda_{j})$.}
\STATE{ \hspace*{3em} Update $\boldsymbol{\eta}^{j}(\lambda_j)$ in \cref{eta^j},
$\boldsymbol b_k(\boldsymbol{\eta}^{j})$, and $\mathcal{N}_F(\boldsymbol{\eta}^{j})$.}

\qquad\algorithmicend
\STATE{Step 4} 
\STATE{\qquad Compute $\boldsymbol\alpha^{k} := \boldsymbol{\eta}^{j}(\lambda_j)$.}
%\ENDWHILE
\end{algorithmic}
\end{algorithm}

\textbf{Remark:}
The solvability, stability, and convergence of Kansa methods can be guaranteed by satisfying certain denseness requirements \cite{chen2022oversampling, cheung2018h, ling2006results, ling2008stable, schaback2016all}. Among them, the least-squares Kansa method has demonstrated remarkable success in solving a wide range of PDEs \cite{Li+Ling-CollMethCaucProb:19,chen2023kernel,chen2020extrinsic,li2019discrete}, showcasing its significant potential for further applications.
However, the theoretical analysis of the least-squares Kansa method with an $F$-dependent energy constraint is currently insufficient. 
A major challenge we face is determining a RBF approximation that satisfies the energy constraint, i.e., $E_w$ in \cref{approx E} equals $E_0$.



\section{Numerical experiments}\label{sec:Numerical experiments}
In this section, we demonstrate the accuracy and efficiency of Algorithm \ref{alg:update_alpha} using numerical experiments. 
All methods are defined as follows:
\begin{itemize}
    \item\textbf{EC-LS Kansa-CN}: 
    The energy-conserving least-squares Kansa method with CN scheme for solving \cref{full_dis_sol}.
    \item\textbf{EC-LS Kansa-CNAB}: 
    The energy-conserving least-squares Kansa method with CNAB scheme for solving \cref{full_dis_sol}.
    \item\textbf{MGAVF} \cite{sun2022kernel}: A meshless Galerkin method with the AVF  time integrator.
\end{itemize}
The same definitions apply to \textbf{LS Kansa-CN} and \textbf{LS Kansa-CNAB} without EC.
All least-squares Kansa methods utilize a boundary scaling factor of $\theta = 1.5$ in \cref{unconstrained_LS_Kansa_solution}  
while consistently employing the Whittle-Matérn-Sobolev kernels in \cref{Whittle-Matern-def} with various smoothness orders $m$ and shape parameters $\epsilon$. 
The following four kinds of Hamiltonian equations are considered in numerical tests.
%\vspace{1.5mm}
\begin{enumerate}[label=\textbf{PDE 1.}, labelindent=2em, leftmargin=*, align=left]
\item  The 2D linear wave equation is described by 
\begin{subequations}
\begin{align*}
	&\ddot u(\boldsymbol{x},t)-\Delta u(\boldsymbol{x},t) = 0, 
\hphantom{aaaaaaaaaaaa}
    (\boldsymbol{x},t)\in \left( 0,1\right)^2\times\left(0,100\right],
    \\
    & u(\boldsymbol{x},t) = 1,
    \hphantom{aaaaaaaaaaaaaaaaaaaaaaaaa}(\boldsymbol{x},t)\in\Gamma\times\left(0,100\right],
    \\
    &u(\boldsymbol{x},0) = 1, \quad \dot u(\boldsymbol{x},0) =\sqrt{2}\pi \sin(\pi x) \sin(\pi y), 
    \hphantom{aaaaaaaaii}
    x\in \Omega.
\end{align*}
\end{subequations} 
\end{enumerate}
The exact solution is given by
\[u^*(\boldsymbol{x}, t) = \sin(\sqrt{2}\pi t) \sin(\pi x) \sin(\pi y)+1.\]


\begin{enumerate}[label=\textbf{PDE 2.}, labelindent=2em, leftmargin=*, align=left]
    \item The 1D sine-Gordon equation  is expressed as follows: 
\begin{subequations}
\begin{align*}
&\ddot{u}(x,t) - \Delta u(x,t) + \sin(u) = 0,
\hphantom{aa}
(x,t)\in\left(-20,20\right) \times( 0,15],
    \\
    & u_x(\pm 20, t) = 0, 
\hphantom{aaaaaaaaaaaaaaaaaaaaai}(x,t)\in\Gamma\times\left(0,15\right].
\end{align*}
\end{subequations}
\end{enumerate}
The initial conditions can be derived from the exact solution:
\[
u^{*}(x,t)= 4\tan^{-1}
\left(\dfrac{1}{\zeta}\sinh( \dfrac{\zeta t}{\sqrt{1-\zeta^{2}}})/\cosh( \dfrac{x}{\sqrt{1-\zeta^{2}}})\right)
,\zeta\in(0,1).
\]
As $\zeta\rightarrow 1$, the solution gets steeper. 
Here, we set $\zeta=0.9$.



\begin{enumerate}[label=\textbf{PDE 3.}, labelindent=2em, leftmargin=*, align=left]
    \item  The 2D Klein-Gordon equation is specified by:
\begin{subequations}
\begin{align*}
	&\ddot{u}(\boldsymbol{x}, t) - \Delta u(\boldsymbol{x}, t) + u^3 = 0, 
\hphantom{a}\\&\hphantom{aaaaaaaaaaaaaaaaai}
    (\boldsymbol x,t)\in\left\lbrace (x,y)|x^2+y^2 < 10^2\right\rbrace   \times( 0,7],
    \\
    &  u(\boldsymbol{x}, t) = 0,
    \hphantom{aaaaaaaaaaaaaaaaaaaaaaaaii}
    (\boldsymbol x,t) \in \Gamma\times( 0,7],
    \\
    &u(\boldsymbol{x},0) = 2 \mathrm{sech}(\mathrm{cosh}{(x^2 + y^2)}),\quad \dot{u}(\boldsymbol{x},0) = 0, \hphantom{aaaaaa}\boldsymbol x\in\Omega.
\end{align*}
\end{subequations}
\end{enumerate}
It describes the propagation process of an isolated wave.

\begin{enumerate}[label=\textbf{PDE 4.}, labelindent=2em, leftmargin=*, align=left]
    \item The 2D Klein-Gordon equation  is presented as:
\begin{subequations}
\begin{align*}
	&\ddot{u}(\boldsymbol{x}, t) - \Delta u(\boldsymbol{x}, t) + u^5 = 0,
\hphantom{aaaaa}
    (\boldsymbol x,t)\in (-10,10)^2\times(0,20],
    \\
    &  \dfrac{\partial u}{\partial \vec{n}}(\boldsymbol{x},t) = 0, \hphantom{aaaaaaaaaaaaaaaaaaaaaaai}\:
(\boldsymbol{x},t)\in\Gamma\times(0,20],
    \\
    &u(\boldsymbol{x},0) = 0.5 \mathrm{sech}(\cosh(x)) +  0.5 \mathrm{sech}(\cosh(y)),\\
    &\dot{u}(\boldsymbol{x},0) = 0,\hphantom{aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaai}\boldsymbol{x} \in \Omega.
\end{align*}
\end{subequations}
\end{enumerate}

To measure the error at
 time $t^k$ and compute the convergence order, we use some sets   $\mathcal{X}$ of quasi-uniform and sufficiently dense sets  of evaluation points to define the relative $L^2$ errors between numerical solution $u_{Z, ECLS}^k$ and the exact solution $u$ by
\[
\|u(\cdot, t^k) -  u_{Z, ECLS}^{k}\|_{L^2(\Omega)} \approx \left(\frac{\sum_{x \in \mathcal{X}} \omega_x |u(x, t^k) -  u_{Z, ECLS}^{k}(x)|^2}{\sum_{x \in \mathcal{X}} \omega_x |u^k(x)|^2}\right)^{1/2}.
\]
 Additionally, the relative energy error is computed as follows:
\[
\mathcal{E}_{\text{energy}} = \big|E_w( \boldsymbol{\alpha}^k ) - E_0\big|/\big|E_0\big|,
\]
where energy is discretized at the point set \( P \) of size $n_P$, with quadrature weights computed via the trapezoidal rule.


\textbf{Remark:} 
Since $u^k_Z\big|_P = \Phi(P,Z)\,\boldsymbol{\alpha}^k$, according to \cref{rbf exp},
the energy computed from the original variables \((u^k_Z,v^k_Z)\) coincides with that computed from the RBF coefficients in \cref{approx E}.
Similarly, the relative energy errors computed from either formulation are identical.
As demonstrated in Table \ref{tab:example1_pde1_tolerance_comparison}, the numerical differences between the two approaches are negligible.
