\appendix
\section{Collection of formulas}\label{sec:appendix}
This appendix contains formulas for  implementing the least-squares Kansa methods with the CN and CNAB time-stepping method.
Let $u^0=I_Z \psi_0$ and $v^0=I_Z \psi_1$ be the RBF interpolants of the initial conditions within the working trial space. 

\subsection{Semi-discrete solution in \cref{both eq}}\label{sec:appendix A1}
The formulas for semi-discrete solution $u^k$ in \cref{both eq} are as follows:

\begin{align}
    \tag{Initialization}\label{Init}
    \small{
    u^{1} = \frac{\tau^2}{4} \Delta u^{1} + \left(\frac{\tau^2}{4} \Delta + I\right) u^0 + \tau v^0 - \frac{\tau^2}{2} F'\left(\frac{1}{2}u^{1} + \frac{1}{2} u^0\right), \nonumber
    }
\end{align}

\begin{itemize}
    \item\textbf{CN}: 
    \begin{small}
    \begin{align}
        u^k =& \frac{\tau^2}{4} \Delta u^k + \left(\frac{\tau^2}{2} \Delta + 2I\right) u^{k-1} + \left(\frac{\tau^2}{4} \Delta - I\right) u^{k-2} \nonumber \\
        & - \frac{\tau^2}{2} F'\left(\frac{1}{2}u^k + \frac{1}{2}u^{k-1}\right) - \frac{\tau^2}{2} F'\left(\frac{1}{2}u^{k-1} + \frac{1}{2}u^{k-2}\right),  
