\subsection{Fully discretized energy in \cref{approx E}}\label{sec:appendix A3}
As for discretizing  \cref{semi energy}, we employ a sufficiently dense set \( P = \{p_1, \dots, p_{n_P}\} \subset \overline{\Omega} \) of quadrature points associated with some quadrature weights \( w_j \).
For any two functions  $f$, $g\in L^2(\Omega)$, their  $L^2$ inner product can be approximated by

\begin{equation}\label{quadrature formula}
\big\langle f, g \big\rangle_{L^2(\Omega)} := \int_\Omega fg \, dx \approx \sum\limits_{j=1}^{n_P} w_j f(p_j) g(p_j) = f(P)^T W g(P),
\end{equation}
where \( W = \text{diag}(w_1, \ldots, w_{n_P}) \) is the \( n_P \times n_P \) diagonal matrix. 

Since \(v^k\) is a linear function of \(u^k\), \((v^k)^2\) can be expressed as a quadratic function of \(u^k\), including interactions with other \(u^j\) for \(j < k\).
Using the quadrature formula \cref{quadrature formula},
the first two terms in the energy in \cref{semi energy}, when fully discretized, are a quadratic function in \( \boldsymbol{\alpha}^k \), whose quadratic form matrix is the  weighted sum of the following two Gram matrices:
\begin{align}
    G_{\Phi}\:\:\: & := 
     \big[\Phi(P, Z)\big]^T W \big[\Phi(P, Z)\big],
     \label{Gram0}\\
    G_{\nabla \Phi} & := 
    \sum_{\substack{\lvert \xi \rvert = 1, \xi \in \mathbb{N}_{0}^{d}}} \big\{ [D^{\xi} \Phi](P, Z) \big\}^T W \big\{ [D^{\xi} \Phi](P, Z) \big\},  
    \label{Gram1}
\end{align}
where \(D^{\xi}\) represents the mixed partial derivatives of function \(\Phi\) according to the multi-index \(\xi\), and
\begin{align*}
[G_{\Phi}]_{ij}\:\:\:&\approx
    {\big\langle \Phi(\cdot, z_i), \Phi(\cdot, z_j) \big\rangle}_{L^2(\Omega)},\\
[G_{\nabla\Phi}]_{ij}&\approx 
     \sum_{\substack{\lvert \xi \rvert = 1, \xi \in \mathbb{N}_{0}^{d}}} {\left\langle D^{\xi} \Phi(\cdot, z_i), D^{\xi} \Phi(\cdot, z_j) \right\rangle}_{L^2(\Omega)}.
\end{align*}
An important fact is the symmetric positive definite (SPD) nature of this quadratic form because Eqs.\eqref{Gram0} and \eqref{Gram1} are SPD.

Along with integrals for lower-order terms and the \( F \)-related final term, we can express the fully discretized energy in terms of RBF coefficients as 
\begin{equation*}
E_w( \boldsymbol{\alpha}^k ) =\mathcal{Q}(\boldsymbol{\alpha}^k) +\mathcal{N}(\boldsymbol{\alpha}^k),
\end{equation*}
where
\begin{align}
\mathcal{Q}(\boldsymbol{\alpha}^k) = &(\boldsymbol\alpha^{k})^{T}\small{\Big(\dfrac{2}{\tau^2} G_{\Phi} + \dfrac{1}{2}G_{\nabla\Phi}\Big)}\boldsymbol\alpha^{k}+
\dfrac{2}{\tau}(\mathbf{d}^{k-1}_{P})^T W [\Phi(P,Z)]\boldsymbol\alpha^{k} + \dfrac{1}{2}
(\mathbf{d}^{k-1}_{P})^T W 
\mathbf{d}^{k-1}_{P}, \label{E_w:Q} \\
\mathcal{N}(\boldsymbol{\alpha}^k) =& \boldsymbol 1_{n_{P}}^{T} W \Big[F\left(\Phi(P,Z) \boldsymbol\alpha^{k}\right)\Big]. \label{E_w:N}
\end{align}







The components $\mathbf{d}^{k-1}_{P}$ of  \( E_w( \boldsymbol{\alpha}^k ) \)  that are independent of the unknown coefficients \(\boldsymbol{\alpha}^k \) are as follows:
\begin{align}
    \tag{Initialization}
    \begin{small}
    \mathbf{d}^{0}_{P} =\Big\{ - \dfrac{2}{\tau}u^0-v^0\Big\}\Big\vert_P,  \qquad\qquad\qquad\qquad\qquad\qquad\qquad\nonumber
    \end{small}
\end{align}

\begin{itemize}
    \item\textbf{CN}:
    \begin{small}
    \begin{align}
    \mathbf{d}^{k-1}_{P} &= -
    \left(\dfrac{\tau }{4} \Delta\Phi(P, Z)+\dfrac{3}{\tau}\Phi(P, Z)\right) \boldsymbol{\alpha}^{k-1}  + \left( - \dfrac{\tau }{4}\Delta\Phi(P, Z)+\dfrac{1}{\tau}\Phi(P, Z)\right) \boldsymbol{\alpha}^{k-2}\nonumber \\
        &\quad+\dfrac{\tau}{2}
 F^{'}\left(\dfrac{1}{2}\Phi(P,Z)\left(\boldsymbol{\alpha}^{k-1} + \boldsymbol{\alpha}^{k-2}\right) \right), 
\nonumber \quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\:(k \geq 2) 
\end{align}
\end{small}
%
\item\textbf{CNAB}: 
\begin{small}
\begin{align}
    \mathbf{d}^{k-1}_{P} &=- \dfrac{4}{\tau} \Phi(P, Z)\boldsymbol{\alpha}^{k-1} +\dfrac{2}{\tau} \Phi(P, Z)\boldsymbol{\alpha}^{k-2} + v^{k-2}\vert_P, \:\:\quad\quad\quad\quad\quad\quad \quad\quad\:\,\,(k = 2)  
\nonumber
\\
    \mathbf{d}^{k-1}_{P} &=-
    \left( \dfrac{\tau }{4} \Delta\Phi(P, Z)+\dfrac{3}{\tau}\Phi(P, Z)\right) \boldsymbol{\alpha}^{k-1}  + \left( - \dfrac{\tau }{4}\Delta\Phi(P,Z)+\dfrac{1}{\tau}\Phi(P,Z)\right) \boldsymbol{\alpha}^{k-2} \nonumber \\
        &\quad+\dfrac{\tau}{2}
 F^{'}\left(\dfrac{1}{2}\Phi(P,Z)\left(3\boldsymbol{\alpha}^{k-2} - \boldsymbol{\alpha}^{k-3}\right)\right).  \quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\:\:\:\:\quad ( k \geq 3)
\nonumber
\end{align}
\end{small}
\end{itemize}
Additionally, we can analytically compute the initial energy by the initial condition $E_0 := E[\psi_0, \psi_1](0)$ or approximate the initial energy using the RBF interpolants to the initial conditions, i.e., $E_0 \approx E[I_Z\psi_0, I_Z\psi_1](0)$.


