\section{Equivalence of Left and Right IEKF}
\label{sec:equivalence}
In this section, we present our main claim that the L-IEKF and R-IEKF always yield equivalent estimates of the state at each filter step.

\subsection{Definition of equivalence}
\label{sub:definition}
The equivalence of the L-IEKF and R-IEKF is defined based on the underlying distribution of the state estimate represented by the concentrated Gaussians.

\begin{lemma}\label{lemma:cgd_equiv}
    Consider a L-CGD $\GP^\tL_{\hat{X}_\tL}(\mu_\tL, \Sigma_\tL)$ and a R-CGD $\GP^\tR_{\hat{X}_\tR}(\mu_\tR, \Sigma_\tR)$ defined by \eqref{eq:L_CGD} and \eqref{eq:R_CGD} respectively. 
    The two distributions are equivalent (as functions on $\grpG$) if 
    \begin{align}
        \mu_\tR &= \Ad_{\hat{X}_\tL} \mu_\tL, &
        \hat{X}_\tR &= \hat{X}_\tL, &
        \Sigma_\tR &= \Ad_{\hat{X}_\tL}^\vee \Sigma_\tL {\Ad_{\hat{X}_\tL}^\vee}^\top.
\label{eq:left_right_correspondence_condition}
    \end{align}
\end{lemma}

\begin{proof}
    We prove this lemma by showing that the log likelihood of left and right distributions is the same under the conditions of the lemma, that is,
    \begin{align*}
        \Lyap_\tL(\mu_\tL, \hat{X}_\tL, \Sigma_\tL)
        &= \Lyap_\tR(\mu_\tR, \hat{X}_\tR, \Sigma_\tR).
    \end{align*}
    This is shown by straightforward computation.
    \begin{align*}
        \Lyap_\tR&(\mu_\tR, \hat{X}_\tR, \Sigma_\tR)\\
        &= \frac{1}{2} \vert \log(X \hat{X}_\tR^{-1}) - \mu_\tR \vert_{\Sigma_\tR^{-1}}^2 \\
        &= \frac{1}{2} \vert \log(X \hat{X}_\tL^{-1}) - \Ad_{\hat{X}_\tL} \mu_\tL \vert_{(\Ad_{\hat{X}_\tL}^\vee \Sigma_\tL {\Ad_{\hat{X}_\tL}^\vee}^\top)^{-1}}^2 \\
        &= \frac{1}{2} \vert  \Ad_{\hat{X}_\tL} \log(\hat{X}_\tL^{-1} X) - \Ad_{\hat{X}_\tL} \mu_\tL \vert_{(\Ad_{\hat{X}_\tL}^\vee \Sigma_\tL {\Ad_{\hat{X}_\tL}^\vee}^\top)^{-1}}^2  \\
        &= \frac{1}{2} \vert  \log(\hat{X}_\tL^{-1} X) -  \mu_\tL \vert_{\Sigma_\tL^{-1}}^2 \\
        &= \Lyap_\tL(\mu_\tL, \hat{X}_\tL, \Sigma_\tL),
    \end{align*}
    for any $X_\tL = X_\tR \in \grpG$.
\end{proof}

Concretely, this lemma shows that the L-IEKF and R-IEKF, which use left and right concentrated Gaussians for state representation respectively, have the exact same log likelihood function when the states correspond according to the condition \eqref{eq:left_right_correspondence_condition}.
This leads to the following definition of equivalence between the L-IEKF and R-IEKF.
\begin{definition}\label{def:equivalent}
Let $(\mu_\tL, \hat{X}_\tL, \Sigma_\tL)$ and $(\mu_\tR, \hat{X}_\tR, \Sigma_\tR)$ denote the states of the L-IEKF and R-IEKF, respectively.
We say the L-IEKF and R-IEKF states are \emph{equivalent} if \eqref{eq:left_right_correspondence_condition} holds. 
\end{definition}


\subsection{Equivalence of filter steps}
\label{sub:equivalence}
In this section, we first present the main theorem, which shows that the evolution of the left and right filter estimates matches, and hence the likelihood functions are equivalent.
Its proof relies on the lemmas that are proven later in the section. 
Note that we will re-introduce the time index $t_k, t_{k+1}$ when necessary to clarify the time evolution of the filter propagation.

\begin{theorem}\label{thm:IEKF_equivalence}
Let $(\mu_\tL, \hat{X}_\tL, \Sigma_\tL)$ and $(\mu_\tR, \hat{X}_\tR, \Sigma_\tR)$ denote the states of the L-IEKF and R-IEKF, respectively.
Assume that the measurements $y_k$ admit left-invariance (Section~\ref{sub:invariant_measurement}). 
If the initial conditions of the states are equivalent (at a time $t_0$), 
\begin{align}
\mu_\tR(t_0) & = 0 = \Ad_{X_\tL(t_0)} \mu_\tL(t_0) \notag \\ 
\hat{X}_\tR(t_0)  & = \hat{X}_\tL(t_0) \notag \\
\Sigma_\tR (t_0) & = \Ad_{X_\tL(t_0)}^\vee\Sigma_\tL(t_0) {\Ad_{X_\tL(t_0)}^\vee}^\top, \notag 
\end{align}
with $\mu_\tL(t_0) = \mu_\tR(t_0) = 0$, then the states are equivalent for all time $t \geq t_0$.
\end{theorem}


\begin{proof}
Lemma \ref{lem:prediction_equivalence} proves that if the initial state of the L-IEKF and R-IEKF
\[
(\mu_\tL, \hat{X}_\tL, \Sigma_\tL) = (\mu_\tL(t_k), \hat{X}_\tL(t_k), \Sigma_\tL(t_k)) \] and \[ 
(\mu_\tR, \hat{X}_\tR, \Sigma_\tR) = (\mu_\tR(t_k), \hat{X}_\tR(t_k), \Sigma_\tR(t_k)) 
\]
are equivalent, then the filter state after propagation
$(\mu_\tL^-,\allowbreak \hat{X}_\tL^-, \Sigma_\tL^-)$ and $(\mu_\tR^-, \hat{X}_\tR^-, \Sigma_\tR^-)$
are equivalent.

Lemma \ref{lem:measurement_equivalence_right} proves that if 
$(\mu_\tL^-, \hat{X}_\tL^-,\allowbreak \Sigma_\tL^-)$ and $(\mu_\tR^-, \hat{X}_\tR^-,\allowbreak \Sigma_\tR^-)$  are equivalent then the filter states after the measurement update
$(\mu_\tL^+, \hat{X}_\tL^-, \Sigma_\tL^+)$ and $(\mu_\tR^+, \hat{X}_\tR^-, \Sigma_\tR^+)$  are equivalent. 

Lemma \ref{lem:reset_equivalence} proves that if $(\mu_\tL^+, \hat{X}_\tL^-, \Sigma_\tL^+)$ and $(\mu_\tR^+, \hat{X}_\tR^-,\allowbreak \Sigma_\tR^+)$  are equivalent 
then the filter states after the reset step
\[
(\mu_\tL(t_{k+1}), \hat{X}_\tL(t_{k+1}), \Sigma_\tL(t_{k+1})) = (\mu_\tL, \hat{X}_\tL, \Sigma_\tL)\]
and
\[(\mu_\tR(t_{k+1}), \hat{X}_\tR(t_{k+1}), \Sigma_\tR(t_{k+1}))  = (\mu_\tR, \hat{X}_\tR, \Sigma_\tR)
\]
are equivalent. 

By induction, this completes the proof.
\end{proof}
\begin{remark}
    We only present the technical results with left-invariant measurements since this matches the setup in the INS problem. 
    However, the equivalence holds for any type of measurements, and it is straightforward to extend the proof to the case of right-invariant measurements or general measurements.
    We omit the detailed proofs for other types of measurements.
    A similar analysis has recently been performed in \cite{maurerEquivalenceLeftRightInvariant2025} for the case of general measurement update.
\end{remark}

\begin{lemma}[Predict step equivalence]\label{lem:prediction_equivalence}
    Let $(\mu_\tL, \hat{X}_\tR, \Sigma_\tL)$ and $(\mu_\tR, \hat{X}_\tR, \Sigma_\tR)$ be the states of the L-IEKF and R-IEKF, respectively, with $\mu_\tL = \mu_\tR = 0$.
    Suppose that the L-IEKF and R-IEKF states are equivalent (Def.~\ref{def:equivalent}) at a time $t_0$.
    Then the L-IEKF and R-IEKF states remain equivalent for as long as the prediction dynamics are applied.
\end{lemma}

\begin{proof}
    This is shown by applying the uniqueness of smooth ODE solutions. 
    Let $P := \Ad_{\hat{X}_\tL} \Sigma_\tL \Ad_{\hat{X}_\tL}^\top$ 
    where $(0,X_\tL,\Sigma_\tL)$ is the solution of the left-invariant prediction dynamics. 
    Then $P(t_0) = \Sigma_\tR(t_0)$ and the dynamics of $P$ are given by 
    \begin{align*}
        \dot{P}
        &= \ddt \Ad_{\hat{X}_\tL}^\vee \Sigma_\tL {\Ad_{\hat{X}_\tL}^\vee}^\top \\
        % ------------
        &= \Ad_{\hat{X}_\tL}^\vee (A_\tL \Sigma_\tL + \Sigma_\tL A_\tL^\top + B_\tL Q B_\tL^\top) {\Ad_{\hat{X}_\tL}^\vee}^\top
        \\&\hspace{1cm}
        + \Ad_{\hat{X}_\tL}^\vee \ad_{\Lambda(\hat{X}_\tL, v_m)}^\vee \Sigma_\tL {\Ad_{\hat{X}_\tL}^\vee}^\top
        \\&\hspace{1cm}
        + \Ad_{\hat{X}_\tL}^\vee \Sigma_\tL {\ad_{\Lambda(\hat{X}_\tL, v_m)}^\vee}^\top {\Ad_{\hat{X}_\tL}^\vee}^\top \\
        % ------------
        % &= \Ad_{\hat{X}_\tL} A_\tL \Ad_{\hat{X}_\tL}^{-1} \Ad_{\hat{X}_\tL} \Sigma_\tL \Ad_{\hat{X}_\tL}^\top + \Ad_{\hat{X}_\tL} \Sigma_\tL \Ad_{\hat{X}_\tL}^\top (\Ad_{\hat{X}_\tL} A_\tL \Ad_{\hat{X}_\tL}^{-1})^\top 
        % \\&\hspace{1cm}
        % + \Ad_{\hat{X}_\tL} B_\tL Q B_\tL^\top  \Ad_{\hat{X}_\tL}^\top
        % + \Ad_{\hat{X}_\tL} \ad_{\Lambda(\hat{X}_\tL, v_m)} \Ad_{\hat{X}_\tL}^{-1} \Ad_{\hat{X}_\tL} \Sigma_\tL \Ad_{\hat{X}_\tL}^\top
        % \\&\hspace{1cm}
        % + \Ad_{\hat{X}_\tL} \Sigma_\tL \Ad_{\hat{X}_\tL}^\top  (\Ad_{\hat{X}_\tL} \ad_{\Lambda(\hat{X}_\tL, v_m)} \Ad_{\hat{X}_\tL}^{-1})^\top \\
        % ------------
        &= (\Ad_{\hat{X}_\tL}^\vee A_\tL {\Ad_{\hat{X}_\tL}^\vee}^{-1} + \Ad_{\hat{X}_\tL}^\vee \ad_{\Lambda(\hat{X}_\tL, v_m)}^\vee {\Ad_{\hat{X}_\tL}^\vee}^{-1}) P 
        \\&\hspace{0.2cm}
        + P (\Ad_{\hat{X}_\tL}^\vee A_\tL {\Ad_{\hat{X}_\tL}^\vee}^{-1} + \Ad_{\hat{X}_\tL}^\vee \ad_{\Lambda(\hat{X}_\tL, v_m)}^\vee {\Ad_{\hat{X}_\tL}^\vee}^{-1})^\top
        \\&\hspace{0.2cm}
        + \Ad_{\hat{X}_\tL}^\vee B_\tL Q B_\tL^\top  {\Ad_{\hat{X}_\tL}^\vee}^\top.
    \end{align*}
    where $A_\tL$ and $B_\tL$ are the linearisation matrices given in Def.~\ref{def:left_prediction}. 
    Observe that
    \begin{align*}
        &\Ad_{\hat{X}_\tL}^\vee A_\tL {\Ad_{\hat{X}_\tL}^\vee}^{-1} + \Ad_{\hat{X}_\tL}^\vee \ad_{\Lambda(\hat{X}_\tL, v_m)}^\vee {\Ad_{\hat{X}_\tL}^\vee}^{-1} \\
        &= \Ad_{\hat{X}_\tL}^\vee (\tD_X|_{\hat{X}_\tL} \Lambda(X, v_m) \cdot\tD \tL_{\hat{X}_\tL}(I) \\
        & \qquad -\ad_{\Lambda(\hat{X}_\tL, v_m)}^\vee){\Ad_{\hat{X}_\tL}^\vee}^{-1} + \Ad_{\hat{X}_\tL}^\vee \ad_{\Lambda(\hat{X}_\tL, v_m)}^\vee {\Ad_{\hat{X}_\tL}^\vee}^{-1} \\
        &= \Ad_{\hat{X}_\tL}^\vee \tD_X|_{\hat{X}_\tL} \Lambda(X, v_m) \cdot \tD \tL_{\hat{X}_\tL}(I) {\Ad_{\hat{X}_\tL}^\vee}^{-1} \\
        &= \Ad_{\hat{X}_\tL}^\vee \tD_X|_{\hat{X}_\tL} \Lambda(X, v_m) \cdot \tD \tR_{\hat{X}_\tL}(I) \\
        &= A_\tR, 
    \end{align*}
    while 
    \[
    \Ad_{\hat{X}_\tL}^\vee B_\tL = \Ad_{\hat{X}_\tL}^\vee \Upsilon = B_\tR,
    \]
    and hence $(0,\hat{X}_\tL, P)$ obey the R-IEKF prediction dynamics.
    Uniqueness of ODE solutions implies that $\hat{X}_\tL = \hat{X}_\tR$ and $P(t) = \Sigma_\tR(t)$ for all time.
\end{proof}


\begin{remark}
    The result in Lemma~\ref{lem:prediction_equivalence} depends only on the algebraic structure of the EKF equations.  
    In particular, it does not require group-affine dynamics or any other additional properties of the system.
\end{remark}


The next result shows that the update step preserves the equivalence of the L-IEKF and R-IEKF solutions.

\begin{lemma}[Left-invariant measurement update equivalence]\label{lem:measurement_equivalence_right}
    Let $(\mu_\tL^-, \hat{X}_\tL^-, \Sigma_\tL^-)$ and $(\mu_\tR^-, \hat{X}_\tR^-, \Sigma_\tR^-)$ be the states of the L-IEKF and R-IEKF, respectively, with $\mu_\tL^-=\mu_\tR^- = 0$.
    Suppose that the states are equivalent (Def.~\ref{def:equivalent}) at the instant a left-invariant measurement $y$ is received.
    If the respective update steps are applied to both the L-IEKF and R-IEKF, then the posterior states $(\mu_\tL^+, \hat{X}_\tL^-, \Sigma_\tL^+)$ and $(\mu_\tR^+, \hat{X}_\tR^-, \Sigma_\tR^+)$ are equivalent as well.
\end{lemma}

\begin{proof}
    There is no update to the reference and $\hat{X}_\tL^- = \hat{X}_\tR^-$ remain fixed in the update step. 

    Recalling \eqref{eq:CL_left_y_L-IEKF} and \eqref{eq:CL_left_y_R-IEKF} then 
    $C_\tR = C_\tL \Ad_{{\hat{X}_\tR^-}^{-1}}^\vee$. 
    Similarly, from \eqref{eq:DL_left_y_L-IEKF} and \eqref{eq:DL_left_y_R-IEKF} then $D_\tL = D_\tR$.
    Thus one has 
    \begin{align*}
            S_\tR &= C_\tR \Sigma_\tR^- C_\tR^\top + D_\tR R D_\tR^\top\\
            & = C_\tL \Ad_{{\hat{X}_\tR^-}^{-1}}^\vee \Ad_{\hat{X}_\tL}^\vee \Sigma_\tL^- {\Ad_{\hat{X}_\tL^-}^\vee}^\top {\Ad_{{\hat{X}_\tR^-}^{-1}}^\vee}^\top C_\tL^\top \\
            & \hspace{5cm} + D_\tL R D_\tL^\top\\
        &=C_\tL \Sigma_\tL^- C_\tL^\top + D_\tL R D_\tL^\top = S_\tL.
    \end{align*}
    The updated offsets are related by
    \begin{align*}
        \mu_\tR^+
        &= K_\tR (\rho({\hat{X}_\tR^-}^{-1}, y) - \mr{y}) \\
        &= \Sigma_\tR^- C_\tR^\top S_\tR^{-1} (y - h(\hat{X}_\tR^-)) \\
        &= \Ad_{\hat{X}_\tL^-}^\vee \Sigma_\tL^- {\Ad_{\hat{X}_\tL^-}^\vee}^\top (C_\tL {\Ad_{\hat{X}_\tL^-}^\vee}^{-1})^\top S_\tL^{-1}\\
        &\hspace{5cm} \cdot(\rho({\hat{X}_\tR^-}^{-1}, y) - \mr{y}) \\
        &= \Ad_{\hat{X}_\tL^-}^\vee \Sigma_\tL^- C_\tL^\top S_\tL^{-1} (\rho({\hat{X}_\tR^-}^{-1}, y) - \mr{y}) \\
        &= \Ad_{\hat{X}_\tL^-}^\vee \mu_\tL^+.
    \end{align*}
    Finally, the updated covariances satisfy\small
    \begin{align*}
        \Sigma_\tR^+
        &= (I - K_\tR C_\tR) \Sigma_\tR^- = (I - \Sigma_\tR^- C_\tR^\top S_\tR^{-1} C_\tR) \Sigma_\tR^- \\
        &= (I - \Ad_{\hat{X}_\tL^-}^\vee \Sigma_\tL {\Ad_{\hat{X}_\tL^-}^\vee}^\top (C_\tL {\Ad_{{\hat{X}_\tL^-}}^\vee}^{-1})^\top S_\tL^{-1} C_\tL {\Ad_{\hat{X}_\tL^-}^\vee}^{-1})
        \\&\hspace{5cm} \cdot \Ad_{\hat{X}_\tL^-}^\vee \Sigma_\tL {\Ad_{\hat{X}_\tL^-}^\vee}^\top \\
        &= \Ad_{\hat{X}_\tL^-}^\vee (I - \Sigma_\tL^- {\Ad_{\hat{X}_\tL^-}^\vee}^\top (C_\tL {\Ad_{\hat{X}_\tL^-}^\vee}^{-1})^\top S_\tL^{-1} C_\tL)\Sigma_\tL^- {\Ad_{\hat{X}_\tL^-}^\vee}^\top \\
        &= \Ad_{\hat{X}_\tL^-}^\vee (I - \Sigma_\tL^- C_\tL^\top S_\tL^{-1} C_\tL)\Sigma_\tL^- {\Ad_{\hat{X}_\tL^-}^\vee}^\top \\
        &= \Ad_{\hat{X}_\tL^-}^\vee \Sigma_\tL^+ {\Ad_{\hat{X}_\tL^-}^\vee}^\top.
    \end{align*}\normalsize
    This completes the proof.
\end{proof}

The final result required is to prove equivalence under the reset step. 
\begin{lemma}[Reset step equivalence]\label{lem:reset_equivalence}
Let $(\mu_\tL^+, \hat{X}_\tL^-, \Sigma_\tL^+)$ and $(\mu_\tR^+, \hat{X}_\tR^-, \Sigma_\tR^+)$ be the states of the L-IEKF and R-IEKF, respectively, following an update step.
If the states are equivalent \eqref{eq:left_right_correspondence_condition} then after the respective reset steps are applied to both the L-IEKF and R-IEKF, the resulting states $(\mu_\tL, \hat{X}_\tL, \Sigma_\tL)$ and $(\mu_\tR, \hat{X}_\tR, \Sigma_\tR)$ are equivalent.
\end{lemma}
\begin{proof}
Consider the update of the reference states $\hat{X}_\tL^- = \hat{X}_\tL^+$ and $\hat{X}_\tR^- = \hat{X}_\tR^+$ since the update does not change the reference. 
Given \eqref{eq:left_right_correspondence_condition}, one has
\begin{align*}
    \hat{X}_\tR
    &= \expG(\mu_\tR^+) \hat{X}_\tR^-\\
    &= \expG(\Ad_{\hat{X}_\tL^-} \mu_\tL^+) \hat{X}_\tL^-
    = \hat{X}_\tL^- \expG(\mu_\tL^+)
    = \hat{X}_\tL.
\end{align*}

To prove the equivalence of the covariance matrices, we first analyse the relation between the linearisation matrices $J_\tL$ \eqref{eq:JL} and $J_\tR$ \eqref{eq:JR}
For any $\varepsilon \in \R^m$, one has\small
\begin{align*}
    J_\tR [\varepsilon]
    &= \ddz{s} \logGv(\expG(s\varepsilon^\wedge)\exp(-\mu_\tR^+)) \\
    &= \ddz{s} \logGv(\expG(s\varepsilon^\wedge)\exp(-\Ad_{\hat{X}_\tL^-} \mu_\tL^+)) \\
    &= \ddz{s} \logGv(\expG(s\varepsilon^\wedge)\hat{X}_\tL^- \exp(-\mu_\tL^+) {\hat{X}_\tL^-}^{-1}) \\
    % &= \ddz{s} \logGv(\hat{X}_\tL^- {\hat{X}_\tL^-}^{-1}\expG(s\varepsilon^\wedge)\hat{X}_\tL^- (\hat{X}_\tL^- \expG(\mu_\tL^+))^{-1}) \\
    &= \ddz{s} \logGv(\hat{X}_\tL^- \expG(\mu_\tL^+) \exp(-\mu_\tL^+) \\
    &\hspace{2cm} \expG(\Ad_{{\hat{X}_\tL^-}^{-1}}s\varepsilon^\wedge)(\hat{X}_\tL^- \expG(\mu_\tL^+))^{-1}) \\
    &= \ddz{s} \Ad_{\hat{X}_\tL^- \expG(\mu_\tL^+)}^\vee\\
    &\hspace{2cm} \logGv(\expG(-\mu_\tL^+) \expG(\Ad_{{\hat{X}_\tL^-}^{-1}}s\varepsilon^\wedge)) \\
    &= \Ad_{\hat{X}_\tL}^\vee\, J_\tL\, \Ad_{{\hat{X}_\tL^-}^{-1}}^\vee \varepsilon,
\end{align*}\normalsize
and hence $J_\tR = \Ad_{\hat{X}_\tL} J_\tL \Ad_{{\hat{X}_\tL^-}^{-1}}$.
Therefore, the reset covariance matrices are related by
\begin{align*}
    \Sigma_\tR
    &= J_\tR\, \Sigma_\tR^+\, J_\tR^\top \\
    &= \Ad_{\hat{X}_\tL}^\vee J_\tL {\Ad_{{\hat{X}_\tL^-}^{-1}}^\vee} \Ad_{\hat{X}_\tL^-}^\vee \Sigma_\tL^+ {\Ad_{\hat{X}_\tL^-}^\vee}^\top \\
    &\hspace{3cm}(\Ad_{\hat{X}_\tL}^\vee J_\tL \Ad_{{\hat{X}_\tL^-}^{-1}}^\vee)^\top \\
    &= \Ad_{\hat{X}_\tL}^\vee J_\tL \Sigma_\tL^+ J_\tL^\top {\Ad_{\hat{X}_\tL}^\vee}^\top \\
    &= \Ad_{\hat{X}_\tL}^\vee \Sigma_\tL^+ {\Ad_{\hat{X}_\tL}^\vee}^\top.
\end{align*}
This completes the proof.
\end{proof}

\begin{remark}
    Note that the reset step is critical in the whole equivalence proof, as the equivalence of the prediction step \ref{lem:prediction_equivalence} relies on the filter states being zero-mean concentrated Gaussians at the start of the prediction step.
\end{remark}


