\appendix
\section{Equivalence of the L-IEKF and R-IEKF for discrete-time systems}\label{app:discrete_equivalence}

In the main result (Sec.~\ref{sub:equivalence}), we proved that the prediction step of the L-IEKF and R-IEKF yields equivalent estimates for hybrid systems.
However, the equivalence no longer holds when the continuous-time filter dynamics are discretised and implemented on a digital computer.
In this section, we show that given a discrete-time system, the discrete L-IEKF and R-IEKF are equivalent as well. 
We will only consider the prediction step of the L-IEKF and R-IEKF, as the update and reset steps remain identical in the discrete-time case.

Consider a noise-free discrete-time system on a Lie group $\grpG$ given by
\begin{align*}
    X_{k+1} = F_v(X_k) = X_k \discreteLift{X_k, v_k},
\end{align*}
where $X_k\in\grpG$ is the true state at time step $k$, $F_v(X_k)$ is the discrete-time flow induced by the velocity $v_k\in\vecL$.
One may define the system evolution function with left trivialisation by $\discreteLift{X_k, v_k} = X_{k+1} X_k^{-1}\in\grpG$.
We make the assumption that the process noise is left-invariant and enters the system as a Gaussian process on the Lie algebra $\gothg$, i.e.
\begin{align}
    X_{k+1} = X_k \discreteLift{X_k, v_k} \expG(w_k^\wedge), \quad w_k \sim \GP(0, Q_k)
\label{eq:dynamicsDT}
\end{align}
where $Q_k$ is a positive-definite covariance matrix.
This follows the definition of the general dynamical system provided in \cite{barrauInvariantKalmanFiltering2018}.
To enhance readability and avoid excessive use of subscripts, we will drop the subscript $k, k+1$ and use the notation $X, X^-$ to align with the notation used in the main text.

\begin{remark} 
If one considers a pure left-invariant continuous-time system with noise \[\td {X} = X (\Lambda(v)\dt+\Upsilon[Q^{\frac{1}{2}}dw])\] then if the velocity $v = v_k$ is constant on short time intervals, the model can be integrated into an exact noisy discrete-time model on the Lie-group 
\begin{align}\label{eq:system_dt}    
X_{k+1} = X_{k} \expG(\Lambda(v_k) \delta t + w_k^\wedge), \quad w_k \sim \GP(0, \delta t \Upsilon Q \Upsilon^\top)
\end{align}
where the Gaussian process lives on the Lie-algebra $\gothg$. 
This construction differs from the general discrete-time model \eqref{eq:dynamicsDT} by the higher-order terms in the Baker–Campbell– Hausdorff (BCH) expansion. 
One may choose to keep the first commutator from the BCH expansion to obtain second-order accuracy in the noise model, however, the modelling choice does not affect the equivalence proof. 
\end{remark}

Given the discrete-time system \eqref{eq:dynamicsDT} and the pre-observer system 
\[
\hat{X}^- = \hat{X} \discreteLift{\hat{X}, v},
\]
the left-invariant error and its dynamics are given by
\begin{align*}
    E_{\tL}^- &= {\hat{X}^{-}_\tL}^{-1} X^-_\tL \\
    &= \discreteLift{\hat{X}_\tL, v}^{-1} E_{\tL} \discreteLift{\hat{X}_\tL E_{\tL}, v}\expG(w^\wedge).
\end{align*}
Similarly, one can define the right-invariant error and its dynamics
\begin{align*}
    E_{\tR}^- &= X^-_\tR {\hat{X}^{-}_\tR}^{-1} \\
    &= E_{\tR} \hat{X}_\tR \discreteLift{E_{\tR} \hat{X}_\tR, v}\expG(w^\wedge)\discreteLift{\hat{X}_\tR, v}^{-1}\hat{X}_\tR^{-1} .
\end{align*}


\begin{definition}[L-IEKF discrete-time prediction step]
    Let $(\mu_\tL, \hat{X}_\tL, \Sigma_\tL)$ denote the L-IEKF state with $\mu_\tL =0$ at time $t_k$.
    The discrete-time prediction step of the L-IEKF is given by
    \begin{align*}
        \mu_\tL^- &= 0,\\
        \hat{X}_\tL^- &= \hat{X}_\tL \discreteLift{\hat{X}_\tL, v}, \\
        \Sigma_\tL^- &= \mathbf{A}_\tL \Sigma_\tL \mathbf{A}_\tL^\top + \mathbf{B}_\tL Q \mathbf{B}_\tL^\top, 
    \end{align*}
    where $\mathbf{A}_\tL$ and $\mathbf{B}_\tL$ are the linearisation matrices defined by 
    \begin{align*}
        \mathbf{A}_\tL &:= \tD \tL_{{\discreteLift{\hat{X}_\tL, v}}^{-1}} \cdot \tD_X|_{\hat{X}_\tL} \discreteLift{X, v} \cdot \tD \tL_{\hat{X}_\tL} \\
    &\hspace{5cm}+ \Ad^\vee_{{\discreteLift{\hat{X}_\tL, v}}^{-1}}, \\
    \mathbf{B}_\tL &:= I. 
    \end{align*}

\end{definition}

\begin{definition}
    [R-IEKF discrete-time prediction step]
    Let $(\mu_\tR, \hat{X}_\tR, \Sigma_\tR)$ denote the R-IEKF state with $\mu_\tR =0$ at time $t_k$.
    The discrete-time prediction step of the R-IEKF is given by
    \begin{align*}
        \mu_\tR^- &= 0, \\
        \hat{X}_\tR^- &= \hat{X}_\tR \discreteLift{\hat{X}_\tR, v}, \\
        \Sigma_\tR^- &= \mathbf{A}_\tR \Sigma_\tR \mathbf{A}_\tR^\top + \mathbf{B}_\tR Q \mathbf{B}_\tR^\top,
    \end{align*}
    where $\mathbf{A}_\tR$ and $\mathbf{B}_\tR$ are the linearisation matrices defined by 
    \begin{align*}
        \mathbf{A}_\tR &:= \Ad^\vee_{\hat{X}_\tR} \cdot \tD \tR_{\discreteLift{\hat{X}_\tR, v}} \cdot \tD_X|_{\hat{X}_\tR} \discreteLift{X, v} \cdot \tD \tR_{\hat{X}_\tR} - I ,\\
        \mathbf{B}_\tR &:= \Ad^\vee_{\hat{X}_\tR^-}.
    \end{align*}
\end{definition}

\begin{lemma}(Discrete-time prediction step equivalence)
    The discrete-time prediction steps of the L-IEKF and R-IEKF are equivalent, i.e. 
    Let $(\mu_\tL, \hat{X}_\tL, \Sigma_\tL)$ and $(\mu_\tR, \hat{X}_\tR, \Sigma_\tR)$ be the states of the L-IEKF and R-IEKF, respectively, with $\mu_\tL = 0$ and $\mu_\tR = 0$.
    Suppose that the L-IEKF and R-IEKF states are equivalent (Def. \ref{def:equivalent}) before the prediction step, then the states after the prediction step remain equivalent.
\end{lemma}
\begin{proof}
    It is straightforward to see that the mean $\mu$ and the reference state $\hat{X}$ remain equivalent after the prediction step.
    To prove the equivalence of the covariance matrices, it suffices to show that 
    \begin{align}
        \mathbf{A}_\tR &= \Ad^\vee_{\hat{X}_\tL^-} \mathbf{A}_\tL {\Ad^\vee_{\hat{X}_\tL}}^{-1}, \label{eq:AR_AL_equivalence_DT}\\
        \mathbf{B}_\tR &= \Ad^\vee_{\hat{X}_\tL^-} \mathbf{B}_\tL. \label{eq:BR_BL_equivalence_DT}
    \end{align}
    To prove \eqref{eq:AR_AL_equivalence_DT}, one has
    \begin{align*}
        &\Ad^\vee_{\hat{X}_\tL^-} \mathbf{A}_\tL {\Ad^\vee_{\hat{X}_\tL}}^{-1}\\
        &=\Ad^\vee_{\hat{X}_\tL^-} \tD\tL_{{\discreteLift{\hat{X}_\tL, v}}^{-1}} \tD_X|_{\hat{X}_\tL} \discreteLift{X, v} \tD \tL_{\hat{X}_\tL}{\Ad^\vee_{\hat{X}_\tL}}^{-1} \\
        &\hspace{3.5cm}+ \Ad^\vee_{\hat{X}_\tL^-} \Ad^\vee_{{\discreteLift{\hat{X}_\tL, v}}^{-1}} {\Ad^\vee_{\hat{X}_\tL}}^{-1} \\
        &=\tD\tL_{\hat{X}_\tL^-}\tD\tR_{\hat{X}_\tL^-}\tD_X|_{\hat{X}_\tL} \discreteLift{X, v} \tD\tL_{\hat{X}_\tL} \tD\tR_{\hat{X}_\tL} \tD\tR_{\hat{X}_\tL} \\
        &\hspace{3.5cm}+ \Ad^\vee_{\hat{X}_\tL^-} \Ad^\vee_{{\discreteLift{\hat{X}_\tL, v}}^{-1}} {\Ad^\vee_{\hat{X}_\tL}}^{-1} \\
        &= \Ad_{\hat{X}_\tL}^\vee \tD\tR_{\discreteLift{\hat{X}_\tL, v}} \tD_X|_{\hat{X}_\tL} \discreteLift{X, v} \tD\tR_{\hat{X}_\tL} - I \\
        &= \mathbf{A}_\tR.
    \end{align*}
    The proof of condition \eqref{eq:BR_BL_equivalence_DT} follows directly from the definition of $\mathbf{B}_\tR$ and $\mathbf{B}_\tL$.
    This completes the proof of the lemma.
\end{proof}

