\begin{definition}\label{erf}
(Tensor Restricted isometry property (TRIP) \cite{FRW11,GLMNQ20}). Let $\mathcal{A}: \mathbb{R}^{n_{1}\times\cdots\times n_{d}} \rightarrow \mathbb{R}^m$ and
$\mathcal{A}_{l_i}:\mathbb{R}^{n_{1}\times\cdots\times n_{d}}\rightarrow \mathbb{R}^l$
be the two linear operators defined in the section \ref{PF}.
For a fixed tensor CP or Tucker decomposition and a relevant CP or Tucker rank $r$,
we say $\mathcal{A}$ and $\mathcal{A}_{l_i}$ meet the TRIP if there exist a tensor restricted isometry constant $\delta_r$ such that
\begin{equation}\label{costFunction1}
(1-\delta_{r})\|\mathcal{X}\|_{F}^{2}
\leq\frac{1}{m}\|\mathcal {A}(\mathcal{X})\|_{2}^{2}
\end{equation}
and
\begin{equation}\label{RIP2}
\frac{1}{l}\|\mathcal {A}_{l_{i}}(\mathcal{X})\|_{2}^{2}
\leq(1+\delta_{r})\|\mathcal{X}\|_{F}^{2},
\end{equation}
holds for all tensors $\mathcal{X}\in\mathbb{R}^{n_{1}\times\cdots\times n_{d}}$ of CP or Tucker rank at most $r$.
\end{definition}

\begin{lemma}\label{refZ18} \cite{Z18}
For a function $f$ with a Lipschitz continuous gradient over $\mathbb{R}^n$, the following relations holds:
$$(5)\Leftrightarrow(7)\Leftrightarrow(6)
\Leftrightarrow(0)\Leftrightarrow(1)\Leftrightarrow(2)
\Leftrightarrow(3)\Leftrightarrow(4).$$
If the function $f$ is convex, then all the conditions (0)-(7) are equivalent.
\begin{equation*}
\begin{aligned}
&(0)~\| \nabla f(x)-\nabla f(y)\| \leq L\|x-y\|,~\forall x,y.\\
&(1)~g(x)=\frac{L}{2}x^{T}x-f(x)~is~convex,~\forall x.\\
