&\mathbb{E}_i\|\mathcal{X}-\mathcal{Y}-\eta\mathcal {P}_{\Gamma}(\nabla f_i(\mathcal{X})-\nabla f_i(\mathcal{Y}))\|_{F}^{2}\\
&=\|\mathcal{X}-\mathcal{Y}\|_{F}^{2}
+\mathbb{E}_i\eta^2\|\mathcal {P}_{\Gamma}(\nabla f_i(\mathcal{X})-\nabla f_i(\mathcal{Y}))\|_{F}^{2}
-2\eta\mathbb{E}_i\langle \mathcal{X}-\mathcal{Y},\mathcal{P}_{\Gamma}(\nabla f_i(\mathcal{X})-\nabla f_i(\mathcal{Y}))\rangle\\
\end{aligned}
\end{equation*}
For the latter two parts, we have
\begin{equation*}
\begin{aligned}
&\mathbb{E}_i\eta^2\|\mathcal {P}_{\Gamma}(\nabla f_i(\mathcal{X})-\nabla f_i(\mathcal{Y}))\|_{F}^{2}
-2\eta\mathbb{E}_i\langle \mathcal{X}-\mathcal{Y},\mathcal{P}_{\Gamma}(\nabla f_i(\mathcal{X})-\nabla f_i(\mathcal{Y}))\rangle\\
&\leq\eta^{2}\delta_{r}^+\mathbb{E}_i
\langle \mathcal{X}-\mathcal{Y},\nabla f_i(\mathcal{X})-\nabla f_i(\mathcal{Y}) \rangle
-2\eta \mathbb{E}_i \langle \mathcal{X}-\mathcal{Y},\mathcal {P}_{\Gamma}(\nabla f_i(\mathcal{X})-\nabla f_i(\mathcal{Y})\rangle\\
&=(\eta^{2}\delta_{r}^+
-2\eta)\mathbb{E}_i\langle \mathcal{X}-\mathcal{Y},\nabla f_i(\mathcal{X})-\nabla f_i(\mathcal{Y})\rangle\\
&=-(2\eta- \eta^{2}\delta_{r}^+)
\langle \mathcal{X}-\mathcal{Y},\nabla F(\mathcal{X})-\nabla F(\mathcal{Y})\rangle\\
&\leq-\delta_{r}^-(2\eta-\eta^{2}\delta_{r}^+)
\|\mathcal{X}-\mathcal{Y}\|_{F}^{2}\\
\end{aligned}
\end{equation*}
Here the first inequality is derived from (\ref{leee}). The second equality follows from $\mathbb{E}_i\nabla f_i(\mathcal{X})=\nabla F(\mathcal{X})$.
The last inequality is deduced from (\ref{lla}). And then we get
\begin{equation*}
\begin{aligned}
&\mathbb{E}_i\|\mathcal{X}-\mathcal{Y}-\eta\mathcal {P}_{\Gamma}(\nabla f_i(\mathcal{X})-\nabla f_i(\mathcal{Y}))\|_{F}^{2}
=\rho_{r}^2
\|\mathcal{X}-\mathcal{Y}\|_{F}^{2}\\
\end{aligned}
\end{equation*}
with $\rho_{r}^2=1+\eta^{2}\delta_{r}^+\delta_{r}^--2\eta\delta_{r}^-$. Finally, the desired result for \ref{eeeee} follows by using Jensen inequality $(\mathbb{E}Z)^{2}\leq\mathbb{E}(Z)^{2}$.
\end{proof}

\begin{theorem}
Assume that the operators $\mathcal{A}:\mathbb{R}^{n_1\times n_2\times\cdots \times n_d}\rightarrow \mathbb{R}^m$ and $\mathcal{A}_{l_i}:\mathbb{R}^{n_1\times n_2\times\cdots \times n_d}\rightarrow \mathbb{R}^l$
used in generating the linear measurements satisfy the TRIP defined in {\em Definition \ref{erf}} with $\delta_{3r}\leq\frac{1}{71}$.
And the rank-$r$ approximation operator $\mathcal{H}_r(\cdot)$ satisfies (\ref{ass}) for all $t=0,1\ldots,n-1$ with some $\theta\in[1,\infty)$.
Denote $\mathcal{X}^{\ast}$ and $\mathcal{X}_{0}$ as the optimal solution of (\ref{l0formulation}) and the initial tensor, respectively.
Then at the $t$-th iteration in Algorithm 1, TSVRG converges linearly in expectation:
\begin{equation*}
\begin{aligned}
\mathbb{E}_{l_t}\|\mathcal{X}_{t+1}-\mathcal{X}^{\ast}\|_{F}
\leq\kappa\|\mathcal{X}_{0}-\mathcal{X}^{\ast}\|_{F}\\
\end{aligned}
\end{equation*}
and the step size satisfies
\begin{equation*}
\begin{aligned}
\frac{3\delta_{3r}^- -\omega}{3\delta_{3r}^+\delta_{3r}^-}<
\eta
<\frac{3\delta_{3r}^- +\omega}{3\delta_{3r}^+\delta_{3r}^-},
\end{aligned}
\end{equation*}
where $\kappa=\frac{-3\theta^{n+1}+\theta^{n}+2\theta}{1-\theta}<1$ and $\omega=\sqrt{71\delta_{3r}^{2}-72\delta_{3r}+1}.$ And $\theta=2\rho_{3r}=2\sqrt{1+\eta^{2}\delta_{3r}^+\delta_{3r}^--2\eta\delta_{3r}^-}$, $\delta_{3r}^-=2(1-\delta_{3r})$, $\delta_{3r}^+=2(1+\delta_{3r})$.
\end{theorem}




\begin{proof}
Observe that Eckart–Young theorem ensures that $\mathcal{X}_{t+1}$ is the tensor of rank $r$ closest to $\tilde{\mathcal{X}}_{t}$ with respect to the Frobenius norm, we know $\|\mathcal{X}_{t+1}-\tilde{\mathcal{X}}_{t}\|_{F}^{2}
\leq\|\mathcal{X}^{\ast}-\tilde{\mathcal{X}}_{t}\|_{F}^{2}$. It can be inferred that
\begin{equation*}
\begin{aligned}
\|\mathcal{X}_{t+1}-\mathcal{X}^{\ast}\|_{F}^{2}
&=\|\mathcal{X}_{t+1}-\mathcal{X}^{\ast}
+\mathcal{X}^{\ast}-\tilde{\mathcal{X}}_{t}\|_{F}^{2}
-\|\mathcal{X}^{\ast}-\tilde{\mathcal{X}}_{t}\|_{F}^{2}-
2\langle\mathcal{X}_{t+1}-\mathcal{X}^{\ast},
\mathcal{X}^{\ast}-\tilde{\mathcal{X}}_{t}\rangle\\
&=\|\mathcal{X}_{t+1}-\tilde{\mathcal{X}}_{t}\|_{F}^{2}
-\|\mathcal{X}^{\ast}-\tilde{\mathcal{X}}_{t}\|_{F}^{2}-2\langle \mathcal{X}_{t+1}-\mathcal{X}^{\ast},
\mathcal{X}^{\ast}-\tilde{\mathcal{X}}_{t}\rangle\\
&\leq2\langle \mathcal{X}_{t+1}-\mathcal{X}^{\ast},\tilde{\mathcal{X}}_{t}-\mathcal{X}^{\ast}\rangle\\
&=2\left\langle \mathcal{X}_{t+1}-\mathcal{X}^{\ast},\mathcal{X}_{t}-\eta(\nabla f_{l_t}(\mathcal{X}_{t})-\nabla f_{l_t}(\widetilde{\mathcal{X}}_{k})+g_{k})-\mathcal{X}^{\ast}\right\rangle\\
&=2\left\langle  \mathcal{X}_{t+1}-\mathcal{X}^{\ast},\mathcal{X}_{t}-\mathcal{X}^{\ast}-\eta(\nabla f_{l_t}(\mathcal{X}_{t})-\nabla f_{l_t}(\mathcal{X}^{\ast}))\right\rangle\\
&-2\left\langle \mathcal{X}_{t+1}-\mathcal{X}^{\ast},
\widetilde{\mathcal{X}}_{k}-\mathcal{X}^{\ast}-\eta(\nabla f_{l_t}(\widetilde{\mathcal{X}}_{k})-\nabla f_{l_t}(\mathcal{X}^{\ast}))\right\rangle\\
&+2\left\langle \mathcal{X}_{t+1}-\mathcal{X}^{\ast},
\widetilde{\mathcal{X}}_{k}-\mathcal{X}^{\ast}-\eta(\nabla F(\widetilde{\mathcal{X}}_{k})-\nabla F(\mathcal{X}^{\ast}))\right\rangle.\\
\end{aligned}
\end{equation*}
Where the fourth equality is deduced from $g_{k}=\nabla F(\widetilde{\mathcal{X}}_{k})$ and $\nabla F(\mathcal{X}^{\ast})=0$.
Let $\Gamma_{t}$ represent the subspace spanned by $\mathcal{X}_{t+1}$, $\mathcal{X}_{t}$ and $\mathcal{X}^{\ast}$ and $\Gamma_{t}' $ represent the subspace spanned by $\mathcal{X}_{t+1}$, $\widetilde{\mathcal{X}}_{k}$ and $\mathcal{X}^{\ast}$.
$\mathcal {P}_{\Gamma_{t}}:\mathbb{R}^{n_{1}\times n_{2}\times \cdots \times n_{d}} \rightarrow \Gamma_{t}$ is defined as the orthogonal projection onto $\Gamma_{t}$.
Clearly, $\mathcal {P}_{\Gamma_{t}}(\mathcal{X}_{t+1})=\mathcal{X}_{t+1}$, $\mathcal {P}_{\Gamma_{t}}(\mathcal{X}_{t})=\mathcal{X}_{t}$, $\mathcal {P}_{\Gamma_{t}}(\mathcal{X}^{\ast})=\mathcal{X}^{\ast}$, $\mathcal {P}_{\Gamma_{t}'}(\mathcal{X}_{t+1})=\mathcal{X}_{t+1}$, $\mathcal {P}_{\Gamma_{t}' }(\widetilde{\mathcal{X}}_{k})=\widetilde{\mathcal{X}}_{k}$ and $\mathcal {P}_{\Gamma_{t}'}(\mathcal{X}^{\ast})=\mathcal{X}^{\ast}$.
The rank of any tensor in $\Gamma_{t}$ and $\Gamma_{t}' $ is at most $3r$. As a result, we get
\begin{equation*}
\begin{aligned}
\|\mathcal{X}_{t+1}-\mathcal{X}^{\ast}\|_{F}^{2}
&\leq2\left\langle  \mathcal{X}_{t+1}-\mathcal{X}^{\ast},\mathcal{X}_{t}-
\mathcal{X}^{\ast}-\eta\mathcal {P}_{\Gamma_{t}}(\nabla f_{l_t}(\mathcal{X}_{t})-\nabla f_{l_t}(\mathcal{X}^{\ast}))\right\rangle\\
&-2\left\langle  \mathcal{X}_{t+1}-\mathcal{X}^{\ast},\widetilde{\mathcal{X}}_{k}-
\mathcal{X}^{\ast}-\eta\mathcal {P}_{\Gamma_{t}'}(\nabla f_{l_t}(\widetilde{\mathcal{X}}_{k})-\nabla f_{l_t}(\mathcal{X}^{\ast}))\right\rangle\\
&+2\left\langle  \mathcal{X}_{t+1}-\mathcal{X}^{\ast},\widetilde{\mathcal{X}}_{k}-
\mathcal{X}^{\ast}-\eta\mathcal {P}_{\Gamma_{t}'}(\nabla F(\widetilde{\mathcal{X}}_{k})-\nabla F(\mathcal{X}^{\ast}))\right\rangle\\
&\leq2\|\mathcal{X}_{t+1}-\mathcal{X}^{\ast}\|_{F}(\|\mathcal{X}_{t}
-\mathcal{X}^{\ast}-\eta{P}_{\Gamma_{t}}(\nabla f_{l_t}(\mathcal{X}_{t})-\nabla f_{l_t}(\mathcal{X}^{\ast}))\|_{F}\\
&+\|\widetilde{\mathcal{X}}_{k}-\mathcal{X}^{\ast}-\eta{P}_{\Gamma_{t}'}(\nabla f_{l_t}(\widetilde{\mathcal{X}}_{k})-\nabla f_{l_t}(\mathcal{X}^{\ast}))\|_{F}\\
&+\|\widetilde{\mathcal{X}}_{k}-\mathcal{X}^{\ast}-\eta{P}_{\Gamma_{t}'}(\nabla F(\widetilde{\mathcal{X}}_{k})-\nabla F(\mathcal{X}^{\ast}))\|_{F}).\\
\end{aligned}
\end{equation*}
The following inequality yield by eliminating $\|\mathcal{X}_{t+1}-\mathcal{X}^{\ast}\|_{F}$ of the above inequality
\begin{equation}\label{equation11}
\begin{aligned}
\|\mathcal{X}_{t+1}-\mathcal{X}^{\ast}\|_{F}
&\leq2(\|\mathcal{X}_{t}-\mathcal{X}^{\ast}-\eta{P}_{\Gamma_{t}}(\nabla f_{l_t}(\mathcal{X}_{t})-\nabla f_{l_t}(\mathcal{X}^{\ast}))\|_{F}\\
&+\|\widetilde{\mathcal{X}}_{k}-\mathcal{X}^{\ast}-\eta{P}_{\Gamma_{t}'}(\nabla f_{l_t}(\widetilde{\mathcal{X}}_{k})-\nabla f_{l_t}(\mathcal{X}^{\ast}))\|_{F}\\
&+\|\widetilde{\mathcal{X}}_{k}-\mathcal{X}^{\ast}-\eta{P}_{\Gamma_{t}'}(\nabla F(\widetilde{\mathcal{X}}_{k})-\nabla F(\mathcal{X}^{\ast}))\|_{F}).\\
\end{aligned}
\end{equation}

As given $\eta
<\frac{3\delta_{3r}^- +\omega}{3\delta_{3r}^+\delta_{3r}^-}
<\frac{1}{1+\delta_{3r}}$,
note that $l_t$ determines the solution $\mathcal{X}_{t+1}$. We take the expectation on both sides of (\ref{equation11}) to get
\begin{equation*}
\begin{aligned}
\mathbb{E}_{l_t}\|\mathcal{X}_{t+1}-\mathcal{X}^{\ast}\|_{F}
&\leq2(\mathbb{E}_{l_t}\|\mathcal{X}_{t}-
\mathcal{X}^{\ast}-\eta{P}_{\Gamma_{t}}(\nabla f_{l_t}(\mathcal{X}_{t})-\nabla f_{l_t}(\mathcal{X}^{\ast}))\|_{F}\\
&+\mathbb{E}_{l_t}\|\widetilde{\mathcal{X}}_{k}-
\mathcal{X}^{\ast}-\eta{P}_{\Gamma_{t}'}(\nabla f_{l_t}(\widetilde{\mathcal{X}}_{k})-\nabla f_{l_t}(\mathcal{X}^{\ast}))\|_{F}\\
&+\mathbb{E}_{l_t}\|\widetilde{\mathcal{X}}_{k}-
\mathcal{X}^{\ast}-\eta{P}_{\Gamma_{t}'}(\nabla F(\widetilde{\mathcal{X}}_{k})-\nabla F(\mathcal{X}^{\ast}))\|_{F})\\
&\leq2(\rho_{3r}
\|\mathcal{X}_{t}-\mathcal{X}^{\ast}\|_{F} +\rho_{3r}
\|\widetilde{\mathcal{X}}_{k}-\mathcal{X}^{\ast}\|_{F} +\rho_{3r}
\|\widetilde{\mathcal{X}}_{k}-
\mathcal{X}^{\ast}\|_{F})\\
&=2\rho_{3r}\|\mathcal{X}_{t}-\mathcal{X}^{\ast}\|_{F}+4\rho_{3r}
\|\widetilde{\mathcal{X}}_{k}-\mathcal{X}^{\ast}\|_{F}\\
&\overset{\theta=2\rho_{3r}}{=}
\theta\|\mathcal{X}_{t}-\mathcal{X}^{\ast}\|_{F}+2\theta
\|\widetilde{\mathcal{X}}_{k}-\mathcal{X}^{\ast}\|_{F},
\end{aligned}
\end{equation*}
where $\omega=\sqrt{71\delta_{3r}^{2}-72\delta_{3r}+1}$, $\rho_{3r}=\sqrt{1+\eta^{2}\delta_{3r}^+\delta_{3r}^--2\eta\delta_{3r}^-}$, $\delta_{3r}^-=2(1-\delta_{3r})$, $\delta_{3r}^+=2(1+\delta_{3r})$.
And the second inequality is derived from (\ref{rtr}) and (\ref{eeeee}) in Lemma 4.3.
By recursively using the above inequality over $t$, and noting that $\widetilde{\mathcal{X}}_{k}=\mathcal{X}_{0}$ and $\mathcal{X}_{t+1}=\mathcal{X}_{n}$, we can deduce
\begin{equation*}
\begin{aligned}
\mathbb{E}_{l_t}\|{\mathcal{X}}_{t+1}-\mathcal{X}^{\ast}\|_{F}
&=\mathbb{E}_{l_t}\|\mathcal{X}_{n}-\mathcal{X}^{\ast}\|_{F}\\
&\leq \theta\|\mathcal{X}_{t}-\mathcal{X}^{\ast}\|_{F}+2\theta
\|\mathcal{X}_{0}-\mathcal{X}^{\ast}\|_{F}\\
&\leq
\theta(\|\mathcal{X}_{t-1}-\mathcal{X}^{\ast}\|_{F}+
2\theta\|\mathcal{X}_{0}-\mathcal{X}^{\ast}\|_{F})
+2\theta\|\mathcal{X}_{0}-\mathcal{X}^{\ast}\|_{F}\\
&\leq\cdots\\
&\leq \theta^{n}\|\mathcal{X}_{0}-\mathcal{X}^{\ast}\|_{F}
+2(\theta^{n}+\theta^{n-1}\cdots+\theta)\|\mathcal{X}_{0}-\mathcal{X}^{\ast}\|_{F}\\
&=(\theta^{n}+2(\theta^{n}+\theta^{n-1}\cdots+\theta))\|\mathcal{X}_{0}-\mathcal{X}^{\ast}\|_{F}\\
&= \frac{-3\theta^{n+1}+\theta^{n}+2\theta}{1-\theta}\|
\mathcal{X}_{0}-\mathcal{X}^{\ast}\|_{F}\\
&\leq \|\mathcal{X}_{0}-\mathcal{X}^{\ast}\|_{F}.
\end{aligned}
\end{equation*}
The last inequality follows from $\kappa=\frac{-3\theta^{n+1}+\theta^{n}+2\theta}{1-\theta}<1$, since $\delta_{3r}<\frac{1}{71}$ and $$\frac{3\delta_{3r}^- -\omega}{3\delta_{3r}^+\delta_{3r}^-}<
\eta
<\frac{3\delta_{3r}^- +\omega}{3\delta_{3r}^+\delta_{3r}^-},$$
 where $\omega=\sqrt{71\delta_{3r}^{2}-72\delta_{3r}+1}$.
 Obviously, the linear convergence of TSVRG method for tensor recovery issue with CP or Tucker rank constraint follows immediately.
\end{proof}
\fi
Now, we have completed the convergence proof of the Tensor SVRG algorithm.
As we all know, numerous practical applications are closely related to tensors.
In the next section, we focus on two types of tensor data, that are selected for clarity of presentation, and with the aim of confirming our theoretical results.
Specifically, we will examine tensors derived from synthetic data and video data.
The following numerical experiments are designed to demonstrate that TSVRG can indeed be effectively utilized in tensor recovery problem.

\section{Numerical experiments}
The tensor recovery is commonly regarded as a classic rank minimization problem, where the core challenge lies in effectively recovering an approximate form of the original tensor with as low rank as possible from partially observed data.
In this section, we present some numerical experiments to demonstrate the performance of TSVRG method for tensor recovery task with CP or Tucker rank constraint.
All experiments adopt third-order tensor data (i.e., $d=3$), including synthetic and real data.
For comparisons of comprehensiveness and completion, we first contrast recovery performance based on CP rank restraint of tensor with TIHT \cite{GLMNQ21}.
Then we contrast recovery performance based on Tucker rank restraint of tensor with TIHT and StoIHT \cite{GLMNQ20}.
In these methods, TIHT is based on GD, and StoIHT or TSVRG is based on SGD. And TSVRG is designed to reduce the variance generated in SGD process, while helps to converge faster than standard SGD.
The red, green and blue lines in figures of numerical results represent TIHT, StoTIHT and TSVRG method, respectively.
In all the existing methods, numerical results will verify that TSVRG performs the best with CP rank constraint or low Tucker constraint both synthetic and real data.
In addition, we employ Barzilai-Borwein (BB) \cite{BB88,TMDQ16} technique for automatic determination of step sizes $\eta$.
And the $k$-th iteration, we adopt $\eta_{k}=\|\widetilde{\mathcal{X}}_{k}-\widetilde{\mathcal{X}}_{k-1}\|_{F}^{2}
/\langle\widetilde{\mathcal{X}}_{k}-\widetilde{\mathcal{X}}_{k-1},g_{k}-g_{k-1}\rangle$.
All the methods are executed on desktop of Window 11 and Matlab (R2023a) with Intel(R) Core(TM) i7-10700 CPU at 2.90 GHz  and 64 GB RAM.


In terms of parameter setting, we establish the maximum number of iterations K =500 both synthetic data and real data for all methods.
Algorithm 1 will stop if $\text{RSE}\leq10^{-3}$, which signifies that the algorithm has converged; or it will stop if the number of iterations reached K.
We randomly select $30\%, 50\%, 70\%, 90\%$ entries of each tensor as missing data,
and employ the abbreviation “SR" to signify Sample Ratio.



At the same time, we select the data (synthetic and video data) and other parameters (such as CP or Tucker rank $r$,  corresponding sample ratio SR and so on) of the compared algorithms according to guidance provided in the source papers.
We assess the performance of tensor recovery using two common criteria.
Namely the Relative Square Error (RSE) and the Peak Signal-to-Noise Ratio (PSNR), it can be defined by
\begin{equation*}
\begin{aligned}
\text{RSE}:=\frac{\|\mathcal{X}^{\ast}-\mathcal{X}\|_F}{\|\mathcal{X}\|_F},
~~~~~\text{PSNR}:=10log_{10}(\frac{\|\mathcal{X}\|^2_\infty}{\frac{1}{i_1 i_2 \cdots  i_d}\|\mathcal{X}^{\ast}-\mathcal{X}\|^2_F}).
\end{aligned}
\end{equation*}
Where $\mathcal{X}^{\ast}$ represents the recovered tensor based on a few entries from the (ground truth) $\mathcal{X}$.
In each figure of numerical experiment, we also observe varying levels of of what is referred to as the “convergence horizon”.
In other words, convergence horizon is the RSE values after the algorithm has reached a relative and stable state in operation process.
It reflects that the precision level (corresponds to the effect of tensor recovery problem) of the algorithm can achieve after a certain number of iterations.
A smaller RSE value indicates a better recovery effect.
Another metric for assessing the recovery effect is PSNR. It is a commonly used image quality assessment indicator that measures the similarity between the recovered image and the original image. A higher PSNR value indicates better visual recovery quality (higher resolution) of the image.
We repeat each run 5 times and report the average results.
We also show the execution time of the each algorithm in real data, in seconds.
For the sake of simplicity in presentation, we have rounded the running time and the PSNR to two decimal places.



\subsection{Performance comparison with CP rank restraint}
In this subsection, we demonstrate the effectiveness of tensor recovery comparing with TIHT in synthetic and real data under CP rank restraint. 

\subsubsection{Virtual}
Firstly, for verification of real data, we produce $n_{1}\times n_{2}\times n_{3}$ tensors of CP rank $r$, whose elements adhere to the the Gaussian distributions.
The positions of observed entries over $n_{1}\times n_{2}\times n_{3}$ are randomly and uniformly selected.
And we set the size of tensor to be $n_{1}=n_{2}=n_{3}=10$, the different sample ratio SR = $\{30\%, 50\%, 70\%, 90\%\}$ and CP rank $r$ from 2 to 5 for demonstrating the performance comparing with TIHT for tensor recovery.
Figure 1 presents outcomes that illustrate the RSE of different ranks as well as different sample ratio.
In our first experiment, we report the results of RSE of TIHT and TSVRG method
versus varying CP rank $r$ with SR=0.5 in the left of Figure 1.
To further validate the effectiveness of TSVRG, we adopt CP rank $r=2$ and different sampling ratio, and show the recovery ability by RSE of TIHT and TSVRG method versus different sampling ratio in the right of Figure 1.
The difference in initial values arises from the random picking of the observed location.
And we can find the similar phenomena in the later experiments.


As shown on the left in Figure 1, as expected, both TIHT and TSVRG method demonstrate that the lower CP rank display more rapid convergence tendency.
However, this does not imply a slower tendency of convergence for tensors with larger CP rank. For example, convergence rate of $r=5$ is more effective than one of $r=4$ in terms of TSVRG method.
The same performance appears in TIHT (convergence rate of $r=5$ is better than one of $r=3$ and 4).
In addition, the convergence rate of the two methods indicates that TSVRG outperforms TIHT under the same rank conditions.
The last and most important, the convergence horizon and the convergence rate of TSVRG are superior to those of TIHT in all the demonstrated ranks.


And then, we observe in the Figure 1 on the right, again as predicted, that lager sample ratio enjoy quicker convergence tendency.
As shown, the convergence horizon of TSVRG exhibits a higher level of performance compared to  one of TIHT in all values of the varing sampling ratio.
And the convergence rate of TSVRG demonstrates outperforms than one of TIHT under each different sample ratio.
Furthermore, about the convergence rate, TSVRG in every sampling ratio outshines TIHT in SR=$30\%, 50\%, 70\%$, but TIHT in SR=$90\%$ is higher than TSVRG in SR=$30\%, 50\%$.
On the whole, the recovery performance of TSVRG is better than that of TIHT in synthetic data under CP rank restraint.







\subsubsection{Image}








\subsubsection{Video}

Next, in order to verify the recovery effectiveness of the TSVRG algorithm in real data under CP rank restraint.
We select the real tensor data (Candle video) using the original paper.
For sake of computation, we use smaller image that the size of the Candle video is $30\times30\times10$. Where the 10 images are a part of of larger image.
The position of observed entries are produced randomly, and the CP rank and SR is 15 and 0.8, respectively.
Here, Both the PSNR and RSE are employed for the comparison.
As shown on top left in Figure 2, the quantitative comparisons show that TSVRG can provide faster convergence rate and lower convergence horizon than ones of TIHT.
In addition, We discover that the proposed TSVRG algorithm escapes from local minima 3 times within 100 iterations, which also validates the theoretical advantage of SVRG over GD or SGD in numerical experiments.
We also show the 150th iteration that the execution time of TIHT and TSVRG is 304.05s and 161.30s; PSVR of TIHT and TSVRG is 25.70dB and 28.76dB. %16.
That is to say, as shown, the recovered first frame in 150 iterations by TSVRG has of visualization higher quality in comparison with TIHT.
The experimental results verify that our method is still comparable to TIHT with respect to synthetic and real data under CP rank restraint.








Now that we have completed the effectiveness validation of our proposed TSVRG method under CP rank restraint, we will proceed to continue with the performance verification of TSVRG under Tucker rank restraint for tensor recovery.



\subsection{Performance comparison with Tucker rank restraint}
In this subsection, we show the efficacy of tensor recovery when compared to TIHT and StoTIHT in synthetic and real data under Tucker rank restraint.


\subsubsection{Virtual}


Likely, first for verification of real data,
we produce $n_{1}\times n_{2}\times n_{3}$ tensors of Tucker rank $r$.
And its entries always keep to the the Gaussian distributions.
The positions of observed entries over $n_{1}\times n_{2}\times n_{3}$ are also randomly and uniformly selected.
We investigate the size of tensor to be $n_{1}=n_{2}=5,~n_{3}=6$, the four sample ratio SR=$\{30\%, 50\%, 70\%, 90\%\}$ and four different Tucker rank $r=(1,1,2;1,2,2;2,2,2;2,2,3)$
to validate the effectiveness of tensor recovery by comparing TSVRG with TIHT and StoTIHT.
As shown in Figure 3, we illustrate the RSE versus different Tucker ranks with SR = 0.5 on the left, and different sample ratio with Tucker rank $r=(1,2,2)$ on the right for three tensor recovery methods.


In the first experiment on the left of the Figure 3, on the whole, the outcomes show that convergence rate of TSVRG are superior to those of TIHT and StoTIHT.
Except for convergence rate of TIHT with Tucker rank $r=(1,1,2)$ is better than one of TSVRG with $r=(1,2,2)$ and $r=(2,2,3)$.
In addition, the convergence rate and the convergence horizon of the three methods indicate that TSVRG outperforms TIHT and StoTIHT under the same Tucker rank conditions.
We observe similar trend in the Figure on the right that larger sample ratio will generate quicker convergence rate.
At the same time, the convergence rate TSVRG exhibits a higher level performance compared to  one of TIHT and StoTIHT under each same sampling ratio.
Overall, the convergence rate of our TSVRG method is evidently superior to those of TIHT and StoTIHT; and the convergence horizonin of TSVRG is slightly better than other two method.
So, TSVRG holds obvious advantageous in comparison with other two algorithms in synthetic data under Tucker rank restraint.



