            \SetKwFunction{GC}{GetConflicts}
            \SetKwFunction{FG}{Fits}
            \SetKwInOut{Input}{input}
            \SetKwInOut{Output}{output}
            \SetKwData{R}{run}
            \SetKwData{BF}{buff}
            \SetKwData{C}{conf}
            \Fn{\FF{$B$}} {
                \tcp{A sorted set of buffers.}
                \Input{$B = \{~b~|~b=(h,t_s,t_e)~\}$}
                \tcp{A valid offset-buffer mapping.}
