                \BlankLine
                $O\leftarrow$ \texttt{HashMap.new();}\\
                \tcp{Each .pop() spawns a ``buff''.}
                \While{$B$\texttt{.pop()}}{
                    \tcp{For traversing the address space.}
                    \R $\leftarrow$ \texttt{0;}\\
                    \tcp{Scan placed, conflicting buffers}
                    \tcp{in ascending offset order.}
                    \For{\C in \GC{$O$\texttt{, \BF}}}{
                        \tcp{\C.offset - \R $\geq$ \BF.size}
                        \uIf{\FG{\BF, \R, \C}}{
                            \texttt{break;}
                        } \Else {
                            \tcp{\C.offset + \C.size}
                            \R $\leftarrow$ \GNA{\C}\texttt{;}
                        }
