Let $R$ be a ring.
For $\pppp\in\spec(R)$, we denote by $\kappa(\pppp)$ the quotient field
$R_\pppp/\pppp R_\pppp$ of $R/\pppp$.
For an ideal $I$ of $R$, we denote by $\min(I)$ the set of minimal over primes of $I$.
For a ring $R$ and a matrix $M$ with entries in $R$, we denote by $I_t(M)$ the ideal
of $R$ generated by $t$-minors of $M$.

An $\NNN$-graded ring $R=\bigoplus_{n\in\NNN}R_n$ is said to be an $\NNN$-graded
$\KKK$-algebra if $R_0=\KKK$.
An $\NNN$-graded $\KKK$-algebra $R=\bigoplus_{n\in\NNN}R_n$ is said to be standard 
graded if $R=\KKK[R_1]$.
For an $\NNN$-graded ring $R$, a greded $R$-module $M$ and $m\in\ZZZ$, we denote
by $M_{\geq m}$ the graded $R$-submodule $\bigoplus_{n\geq m}M_n$ of $M$.
When $R$ is a \cm\ local ring with a canonical module or an $\NNN$-graded algebra
over a field, we denote by $\omega_R$ the (graded) canonical module of $R$.
If $R$ is an $\NNN$-graded algebra and $\omega_R$ is the canonical module of $R$,
$-\min\{m:(\omega_R)_m\neq 0\}$ is called the $a$-invariant of $R$ and denoted
by $a(R)$.
See \cite{gw}.
For $\NNN$-graded $\KKK$-algebras $R^{(1)}$, \ldots,  $R^{(m)}$, we denote by
$R^{(1)}\#\cdots\#R^{(m)}$ the Segre product 
$\bigoplus_{n\in\NNN}R^{(1)}_n\otimes\cdots\otimes R^{(m)}_n$ of $R^{(1)}$, \ldots, $R^{(m)}$.

Let $R=\bigoplus_{n\in\NNN}R_n$ be a standard graded $\KKK$-algebra,
where $\KKK$ is a field.
We say that $R$ is level if the graded canonical module $\omega_R$ is generated in one degree.
If $\hom_R(\omega_R, R)$ (whice is a graded module. See \cite{gw}.) is generated in one degree,
we say that $R$ is anticanonical level.
Level and anticanonical level properties are independent,
see \cite{pag, mfiber, mchain}.
We denote $\hom_R(\omega_R, R)$ by $\omega_R^{-1}$.

Now we recall the following.

\begin{definition}
\rm
Let $R$ be a ring and $M$ an $R$-module.
We define the trace of $M$ denoted by $\trace_R(M)$ by
$$
\trace_R(M)\define\sum_{\varphi\in\hom_R(M,R)}\varphi(M).
$$
If $R$ is clear from context, we omit the subscript $R$ and denote $\trace(M)$.
\end{definition}
%
It follows from the definition, the following.

\begin{lemma}
\mylabel{lem:tr basic}
Let $R$ be a ring and $M$ an $R$-module.
Then $\trace_R(M)$ is the image of the canonical map
$$
\hom_R(M, R)\otimes M\to R, \quad f\otimes m\mapsto f(m).
$$
In particular, if $M$ is a finitely generated $R$-module and $S$ is a flat $R$-algebra,
then $\trace_S(M\otimes S)=\trace_R(M)S$ and therefore for $\pppp\in\spec(R)$,
$\trace_{R_\pppp}(M_\pppp)=\trace_R(M)_\pppp$.
\end{lemma}
%
Flat extension part of this lemma is shown in \cite[Lemma 1.5 (iii)]{hhs}.
Further, if $I$ is an ideal of $R$ and contains an $R$-regular element $b$, then
$\hom_R(I, R)\cong \{x\in (1/b)R : xI\subset R\}\subset Q(R)$,
where $Q(R)$ is the total quotient ring of $R$,
 and therefore, 
$\trace_R(I)=I\{x\in (1/b)R : xI\subset R\}$.
%In particular, if $R$ is a domain then $\trace_R(I)=I(R:_{Q(R)}I)$.
See the proof of \cite[Lemma 1.1]{hhs}.

Let $R$ be a normal domain.
For divisorial fractionary ideal $I$ of $R$ and $n\in\ZZZ$, we denote by
$I^{(n)}$ the $n$-th power of $I$ in $\Div(R)$.
Note that if $I$ is a height 1 prime ideal of $R$ and $n>0$, then
$I^{(n)}$ coincide with the $n$-the symbolic power of $I$.
Further, 
by the argument in the previous paragraph,
$\trace_R(I)=II^{(-1)}$ for any divisorial fractionary ideal $I$.

Next we state a tool to compute the trace of a canonical module which is a
generalization of \cite[Corollary 3.2]{hhs}.
A homomorphism $\varphi\colon F\to G$ of finitely generated free modules over a
ring can be expressed by a matrix by fixing bases of $F$ and $G$.
Let $M$ be such a matrix and $t$ a positive integer with $t\leq\min\{\rank F, \rank G\}$.
Then the ideal $I_t(M)$ is independent of the choice of bases of $F$ and $G$.
We denote this ideal by $I_t(\varphi)$.

\begin{lemma}%[{cf.\ \cite[Corollary 3.2]{hhs}}]
\mylabel{lem:hhs 3.2}
Let $S$ be a \gor\ local ring ($\NNN$-graded ring over a field), $J$ a (homogeneous) ideal of $S$ 
such that $R=S/J$ is a \cm\ ring.
Suppose that there exists a finite (graded) $S$-free resolution
$$
0\to F_h\stackrel{\varphi_h}{\to} \cdots\stackrel{\varphi_1}{\to} F_0\to R\to 0
$$
of $R$ with $h=\dim S-\dim R$.
Let $G$ be a free $R$-module and
$\psi\colon G\to F_h\otimes R$ a (graded) $R$-homomorphism with
$$
G\stackrel{\psi}{\to} F_h\otimes R\stackrel{\varphi_h\otimes 1}{\to}F_{h-1}\otimes R
$$
is exact.
Then $\trace_R(\omega_R)=I_1(\psi)$.
\end{lemma}
%
\begin{proof}
Since $\omega_R=\ext_S^h(R,\omega_S)=\ext_S^h(R,S)$,
we see that $\omega_R\cong\coker((\varphi_h\otimes 1)^\ast)$.
Therefore, by \cite[Proposition 3.1]{hhs}, we see the result.
\end{proof}

