%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Now we state the characterization of CTR property of $G(X;\gamma)$.

\begin{thm}
\mylabel{thm:schubert}
With the above notation, $G(X;\gamma)$ is CTR if and only if $\kappa-\kappa'\leq 1$.
\end{thm}
%
\begin{proof}
By Fact \ref{fact:bv 812}, $G(X;\gamma)$ is \gor\ if and only if $\kappa-\kappa'=0$.
Therefore, we may assume that $\kappa-\kappa'\geq 1$.

Set $J_i=J(x;\zeta_i)$ for $0\leq i\leq t$.
Then by \cite[Corollary 9.18]{bv}, we see that
$J_i^{(\ell)}=J_i^\ell$ for any positive integer $\ell$ and $0\leq i\leq t$.
Set also $\aaaa=\bigcap_{i=0}^t J_i^{\kappa_i}$.
Then by Fact \ref{fact:bv 812}, we see that $\aaaa$ is a canonical module of $G(X;\gamma)$ up to
shift of degree and $\trace(\aaaa)=\aaaa \aaaa^{(-1)}$ is the trace of the graded canonical module
of $G(X;\gamma)$.
(In fact, $\aaaa$ is the graded canonical module of $G(X;\gamma)$ by \cite[Proposition 3.7]{fm},
but we do not use this fact.)

First we consider the case where $\kappa-\kappa'=1$.
Set
\begin{eqnarray*}
I_1&=&\{i: 0\leq i\leq t, \kappa_i=\kappa\} \quad\mbox{and}\\
I_2&=&\{i: 0\leq i\leq t, \kappa_i=\kappa'\}.
\end{eqnarray*}
Then $I_1\cup I_2=\{0,1,\ldots, t\}$.
Since 
$\aaaa=\bigcap_{i=0}^t J_i^{\kappa_i}$ and $\Omega_i$ is straightening closed for any $i$
by \cite[Lemma 9.1]{bv},
$\aaaa$ is generated by
$\{\xi_1\cdots\xi_\kappa : \xi_1, \ldots, \xi_\kappa\in\Omega_i$ for $i\in I_1$ and
$\xi_1, \ldots, \xi_{\kappa-1}\in\Omega_i$ for $i\in I_2\}$
as an ideal of $G(X;\gamma)$ by Lemma \ref{lem:str cl ideal}.
Since $\bigcap_{i=0}^t\Omega_i=\{\gamma\}$, we see that
$\aaaa=\gamma^{\kappa-1}(\bigcap_{i\in I_1}J_i)$.
Note that $\bigcap_{i\in I_1}J_i$ is an ideal of $G(X;\gamma)$ generated by $\bigcap_{i\in I_1}\Omega_i$.

On the other hand, since $\aaaa^{(-1)}=\bigcap_{i=0}^t J_i^{(-\kappa_i)}$ and
$\gamma G(X;\gamma)=\bigcap_{i=0}^t J_i$,
we see that $\gamma^\kappa\aaaa^{(-1)}=\bigcap_{i=0}^t J_i^{(\kappa-\kappa_i)}=\bigcap_{i\in I_2}J_i$.
Therefore, $\gamma^\kappa\aaaa^{(-1)}$ is generated by $\bigcap_{i\in I_2}\Omega_i$ as an ideal of 
$\Gamma(m\times n;\gamma)$.
Therefore,
$$
\gamma^\kappa\trace(\aaaa)=\aaaa(\gamma^\kappa\aaaa^{(-1)})
=(\gamma^{\kappa-1}(\bigcap_{i\in I_1}J_i))(\bigcap_{i\in I_2} J_i)
$$
and we see that 
$$
\gamma\trace(\aaaa)=(\bigcap_{i\in I_1}J_i)(\bigcap_{i\in I_2} J_i).
$$
Thus, $\gamma\trace(\aaaa)$ is generated by $\{\xi\xi' : \xi\in\bigcap_{i\in I_1}\Omega_i, 
\xi'\in\bigcap_{i\in I_2}\Omega_i\}$.

Consider the standard representation of $\xi\xi'$ for arbitrary $\xi\in\bigcap_{i\in I_1}\Omega_i$ and
$\xi'\in\bigcap_{i\in I_2}\Omega_i$.
First note that $\xi\sqcap\xi'\in\bigcap_{i=0}^t\Omega_i=\{\gamma\}$ since $\Omega_i$ is a poset ideal
for any $i$.
Thus, $\xi\sqcap\xi'=\gamma$.
Suppose that
$$
\xi\xi'=\sum_{\ell} c_\ell\alpha_\ell\beta_\ell
$$
is the standard representation of $\xi\xi'$ in $G(X;\gamma)$.
Then, since $\xi\sqcap\xi'=\gamma\leq\alpha_\ell\leq\xi$, $\xi'$, 
$\alpha_\ell=\gamma$ for any $\ell$.
Moreover, since
$$
\cdeg_j\gamma+\cdeg_j\beta_\ell=\cdeg_j\xi+\cdeg_j\xi'=\cdeg_j\xi\sqcap\xi'+\cdeg_j\xi\sqcup\xi'
$$
for any $j$, we see that $\beta_\ell=\xi\sqcup\xi'$ for any $\ell$.
Therefore, the standard representation of $\xi\xi'$ is of the following form.
$$
\xi\xi'=c\gamma(\xi\sqcup\xi'), \quad c\in\KKK, c\neq0.
$$
(In fact, $c=1$, but we do not use this fact.)

Now consider $\xi\sqcup\xi'$.
Set $k(0)=0$ and
$$
\sigma_i\define[\beta_0, \ldots, \beta_{i-2}, a_{k(i-1)+1},  \ldots, a_{k(i)-1},
a_{k(i)+1}, \ldots, a_{k(i+1)}, a_{k(i+1)}+1, \beta_{i+1},  \ldots, \beta_{t+1}]
$$
for $1\leq i\leq t$ as in \cite[(6.8)]{bv},
$$
\Theta_i\define\Gamma(m\times n;\gamma)\setminus\Gamma(m\times n;\sigma_i)
$$
and $J(x;\sigma_i)=\Theta_i G(X;\gamma)$ for $1\leq i\leq t$.
Then $G(X;\gamma)/J(x;\sigma_i)\cong G(X;\sigma_i)$  is an integral domain and therefore $J(x;\sigma_i)$
is a prime ideal of $G(X;\gamma)$ for $1\leq i\leq t$.
Note that
$$
\Theta_i=\{[b_1, \ldots, b_m]\in\Gamma(m\times n;\gamma) : b_{k(i)}<a_{k(i)+1}\}
$$
for $1\leq i\leq t$.
Further, it is easily verified that $\zeta_{i-1}$, $\zeta_i\leq \sigma_i$ and therefore
$\Omega_{i-1}$, $\Omega_i\subset\Theta_i$ for $1\leq i\leq t$.

Set
$$
I'\define \{i : i\in I_1, i-1\in I_2\}\quad\mbox{and}\quad
I''\define\{i : i\in I_2, i-1\in I_1\}.
$$
Since $\xi\in\bigcap_{i\in I_1}\Omega_i$ and $\xi'\in\bigcap_{i\in I_2}\Omega_i$,
we see that $\xi\in\bigcap_{i\in I'\cup I''}\Theta_i$ and $\xi'\in\bigcap_{i\in I'\cup I''}\Theta_i$.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\iffalse
Since $I'\subset I_1$ and $I''\subset I_2$, we see that
$$
\xi, \xi'\in\bigcap_{i\in I'\cup I''}\Theta_i.
$$
\fi
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
On the other hand, since 
$$
\Theta_i=\{[b_1, \ldots, b_m]\in\Gamma(m\times n;\gamma) : b_{k(i)}<a_{k(i)+1}\},
$$
we see that $\xi\sqcup\xi'\in\bigcap_{i\in I'\cup I''}\Theta_i$.
Thus, $\xi\sqcup\xi'\in \bigcap_{i\in I'\cup I''}J(x;\sigma_i)$.
Since $\xi$ (resp.\ $\xi'$) is an arbitrary element of $\bigcap_{i\in I_1}\Omega_i$
(resp.\ $\bigcap_{i\in I_2}\Omega_i$), we see that 
$$
\gamma\trace(\aaaa)\subset\gamma(\bigcap_{i\in I'\cup I''}J(x;\sigma_i)).
$$
Thus, $\trace(\aaaa)\subset\bigcap_{i\in I'\cup I''}J(x;\sigma_i)$.

Now consider the reverse inclusion.
It is enough to show that for any $\beta\in\bigcap_{i\in I'\cup I''}\Theta_i$, it holds that 
$\gamma\beta\in\gamma\trace(\aaaa)$.
Set $\beta=[b_1,\ldots, b_m]$.
Set also $k(0)=0$,
\begin{eqnarray*}
H_1&=&\{j\in\ZZZ: \exists i\in I_1; k(i)<j\leq k(i+1)\},\\ 
H_2&=&\{j\in\ZZZ: \exists i\in I_2; k(i)<j\leq k(i+1)\},\mbox{ and }\\
H_3&=&\{k(t+1)+1, \ldots, m\}.
\end{eqnarray*}
Note that $H_3=\emptyset $ if and only if $a_m<n$ and $a_j=b_j$ for $j\in H_3$.
We define integers $c_1$, \ldots, $c_m$ and $c'_1, \ldots, c'_m$ by
$$
c_j=
\left\{
\begin{array}{ll}
a_j,\quad \mbox{ if $j\in H_1\cup H_3$},\\
b_j,\quad \mbox{ if $j\in H_2$},
\end{array}
\right.
\qquad
c'_j=
\left\{
\begin{array}{ll}
a_j,\quad \mbox{ if $j\in H_2\cup H_3$},\\
b_j,\quad \mbox{ if $j\in H_1$}.
\end{array}
\right.
$$
Here we show the following key fact.

\begin{claim}
\mylabel{claim:in gamma}
It holds that $c_1<\cdots<c_m$ and $c'_1<\cdots<c'_m$.
\end{claim}
We prove the claim $c_1<\cdots<c_m$.
Claim $c'_1<\cdots<c'_m$ is proved similarly.

If $j$, $j+1\in H_1\cup H_3$, then $c_j=a_j<a_{j+1}=c_{j+1}$
and if $j$, $j+1\in H_2$, then $c_j=b_j<b_{j+1}=c_{j+1}$.
Assume that $j\in H_1\cup H_3$ and $j+1\in H_2$.
Then $c_j=a_j<a_{j+1}\leq b_{j+1}=c_{j+1}$.
Finally, assume that $j\in H_2$ and $j+1\in H_1\cup H_3$.
Then $j=k(i+1)$ for some $i\in I_2$.
If $i=t$, then $j+1\in H_3$ and we see that $c_j=b_j<b_{j+1}=c_{j+1}$.
If $i<t$, then $i\in I_2$ and $i+1\in I_1$.
Therefore, $i+1\in I'$.
Since $\beta\in\Theta_{i+1}$, we see that $c_j=b_{k(i+1)}<a_{k(i+1)+1}=c_{j+1}$
and the claim is proved.

By Claim \ref{claim:in gamma}, we see that $[c_1, \ldots, c_m]$, $[c'_1,\ldots, c'_m]\in\Gamma(m\times n)$.
Set $\xi\define[c_1, \ldots, c_m]$ and $\xi'\define[c'_1, \ldots, c'_m]$.
Then, since $\xi$, $\xi'\geq\gamma$, we see that $\xi$, $\xi'\in\Gamma(m\times n;\gamma)$.
Moreover, since $c_{k(i+1)}=a_{k(i+1)}$ for $i\in I_1$ (resp.\ $c'_{k(i+1)}=a_{k(i+1)}$ for $i\in I_2$),
we see that $\xi\in\bigcap_{i\in I_1}\Omega_i$ (resp.\ $\xi'\in\bigcap_{i\in I_2}\Omega_i$).
Since $\xi\sqcap \xi'=\gamma$ and $\xi\sqcup\xi'=\beta$, we see that the standard representation
of $\xi\xi'$ is the following form.
$$
\xi\xi'=c\gamma\beta,\quad c\in\KKK, c\neq0.
$$
Since $\xi\in \bigcap_{i\in I_1} J_i$ and $\xi'\in\bigcap_{i\in I_2} J_i$, we see that
$$
\gamma\beta=c^{-1}\xi\xi'\in(\bigcap_{i\in I_1}J_i)(\bigcap_{i\in I_2} J_i)=\gamma\trace(\aaaa).
$$
This is what we wanted to show and we see that
$
\trace(\aaaa)=\bigcap_{i\in I'\cup I''}J(x;\sigma_i)$.
Since $J(x;\sigma_i)$ is a prime ideal for any $i$, we see that $\trace(\aaaa)$ is a radical ideal.

Next consider the case where $\kappa-\kappa'\geq 2$.
Since $\aaaa=\bigcap_{i=0}^t J_i^{\kappa_i}$, we see that $\aaaa$ is generated by
$\{\xi_1\cdots\xi_\kappa : \xi_1, \ldots, \xi_{\kappa_i}\in\Omega_i$ for $0\leq i\leq t\}$.
On the other hand, since $\gamma^\kappa \aaaa^{(-1)}=\bigcap_{i=0}^t J_i^{\kappa-\kappa_i}$,
$\gamma^\kappa\aaaa^{(-1)}$ is generated by 
$\{\xi_1\cdots\xi_{\kappa-\kappa'} : \xi_1, \ldots, \xi_{\kappa-\kappa_i}\in\Omega_i$ for $0\leq i\leq t\}$.
Therefore $\gamma^\kappa\trace(\aaaa)=\aaaa(\gamma^\kappa \aaaa^{(-1)})
=(\bigcap_{i=0}^t J_i^{\kappa_i})(\bigcap_{i=0}^t J_i^{\kappa-\kappa_i})$ is generated by homogeneous elements
of degree $2\kappa-\kappa'$.
Thus $\trace(\aaaa)$ is generated by homogeneous elements of degree $\kappa-\kappa'$.
In particular, $\gamma\not\in\trace(\aaaa)$, since $\kappa-\kappa'\geq 2$.

On the other hand, by the above description, we see that
$\gamma^\kappa\in\bigcap_{i=0}^t J_i^{\kappa_i}$ and $\gamma^{\kappa-\kappa'}\in\bigcap_{i=0}^t J_i^{\kappa-\kappa'}$.
Thus, we see that 
$\gamma^{2\kappa-\kappa'}\in(\bigcap_{i=0}^t J_i^{\kappa_i})(\bigcap_{i=0}^t J_i^{\kappa-\kappa_i})
=\gamma^\kappa\trace(\aaaa)$,
and therefore
$\gamma^{\kappa-\kappa'}\in\trace(\aaaa)$.
Thus, we see that $\trace(\aaaa)$ is not a radical ideal.
\end{proof}


\begin{remark}
\rm
Ficarra et al. \cite[Theorem 1.1]{fhst} showed that if $\KKK$ is a field,
$m$ and $n$ are integers with $2\leq m\leq n$,
$X=(X_{ij})$ is an $m\times n$ matrix of indeterminates and
$t$ is an integer with $2\leq t\leq m$ then
$$
\trace_R(\omega_R)=I_{t-1}(X)^{n-m}R,
$$
where $R=\KKK[X_{ij} : 1\leq i\leq m, 1\leq j\leq n]/I_t(X)$.
Since $I_{t-1}(X)R$ is a prime ideal of $R$, we see that $R$ is CTR if and only if
$n-m\leq 1$.
While by \cite[Corollary 8.9]{bv} $R$ is \gor\ if and only if $n-m=0$.
\end{remark}

