%We define the empty sum to be 0, i.e., if $B=\emptyset$, then $\xi^+(B)=0$.
\end{definition}



We call a graph $G$ a cycle graph if $G$ consists of one cycle only, i.e.
$V=\{v_0, v_1, \ldots, v_{n-1}\}$, $E=\{\{v_i, v_j\} : i-j\equiv 1 \pmod n\}$
for some $n$ with $n\geq 3$.
A graph $G=(V,E)$ is called a t-perfect graph if
$$
\stab(G)=\left\{f\in\RRR^V : \vcenter{\hsize=.5\textwidth\relax\noindent
$0\leq f(v)\leq 1$ for any $v\in V$,
$f^+(e)\leq 1$ for any $e\in E$ and
$f^+(C)\leq\frac{|C|-1}{2}$ for any odd cycle $C$ without chord%
}
\right\}.
$$
It is known that a cycle graph is t-perfect. See \cite{mah}.

Let $G=(V,E)$ be a t-perfect graph.
For $n\in\ZZZ$, set
$$
\tUUUUUn\define\left\{\mu\in\ZZZ^{V^-} :
\vcenter{\hsize=.5\textwidth\relax\noindent
$\mu(v)\geq n$ for any $v\in V$,
$\mu^+(K)+n\leq\mu(-\infty)$ for any maximal clique $K$ in $G$ and
$\mu^+(C)+n\leq\frac{|C|-1}{2}\mu(-\infty)$ for any odd cycle $C$ without chord and length at least 5}
\right\}.
$$
Since $G$ is t-perfect, there are no cliques with size greater than 3, we see by \cite[Remark 3.10]{mhperfect} that
$$
\omega_{\eksg}^{(n)}=\bigoplus_{\mu\in\tUUUUUn}\KKK T^\mu
$$
for any $n\in \ZZZ$.

Let $G=(V,E)$ be a cycle graph.
If the length of the cycle is even, then $G$ is a bipartite graph and therefore is a perfect graph whose maximal
cliques have size 2.
Thus, by \cite[Theorem 2.1 (b)]{oh}, we see that $\eksg$ is a \gor\ ring.
Further, if the length $n$ of the cycle is odd, then by \cite[Theorem 1]{ht}, $\eksg$ is \gor\ if and only if
$n\leq 5$.

Therefore, we assume in the following of this section that $G=(V,E)$ is a cycle graph of odd length $n$
with $n\geq 7$.
Set $n=2\ell+1$, $V=\{v_0, v_1, \ldots, v_{2\ell}\}$ and we consider indices modulo $2\ell+1$,
$E=\{\{v_i,v_j\}: i-j\equiv 1 \pmod{2\ell+1}\}$, $e_i=\{v_i, v_{i+1}\}$ for $0\leq i\leq 2\ell$.
Further, we denote by $\omega$ the canonical ideal of $\eksg$.

Set 
$$
\pppp_i\define\bigoplus_{{\mu\in\tUUUUU^{(0)}}, \atop\mu(v_i)>0\  \mathrm{ or }\  \mu^+(V)<\ell\mu(-\infty)}
\KKK T^\mu
$$
for $0\leq i\leq 2\ell$.
Then $\pppp_i$ is a prime ideal of $\eksg$ and
$$
\sqrt{\trace(\omega)}=\bigcap_{i=0}^{2\ell}\pppp_i
$$
by \cite[Theorem 3.1]{mcycle}.

Now we state the following criterion of CTR property of $\eksg$.

\begin{thm}
\mylabel{thm:cycle graph}
Let $G=(V,E)$ be a cycle graph of odd length $n$.
Then $\eksg$ is a CTR ring if and only if $n\leq 7$.
\end{thm}
%
\begin{proof}
Set $n=2\ell+1$ as above.
First we prove the ``if'' part.
Suppose $\ell=3$, $\mu\in\tUUUUU^{(0)}$ and $T^\mu\in\bigcap_{i=0}^{2\ell}\pppp_i$.
Then by the proof of \cite[Lemmas 3.4 and 3.5]{mcycle}, we see that $T^\mu$ in $\trace(\omega)$.
Therefore, we see that $\bigcap_{i=0}^{2\ell}\pppp_i\subset\trace(\omega)$.
Since $\sqrt{\trace(\omega)}=\bigcap_{i=0}^{2\ell}\pppp_i$, we see that 
$$
\sqrt{\trace(\omega)}=\trace(\omega)
$$
and $\eksg$ is a CTR ring.

Next we prove the contraposition of ``only if'' part.
Suppose that $\ell\geq 4$ and define $\mu\in\ZZZ^{V^-}$ by
$$
\mu(x)=
\left\{
\begin{array}{ll}
1&\mbox{ if $x\in\{v_2,v_4, \ldots, v_{2\ell-2}, -\infty\}$},\\
0&\mbox{ otherwise.}
\end{array}
\right.
$$
Then, $\mu\in\tUUUUU^{(0)}$ and $\mu^+(V)=\ell-1<\ell=\ell\mu(-\infty)$.
Therefore, we see that $T^\mu\in\bigcap_{i=0}^{2\ell}\pppp_i=\sqrt{\trace(\omega)}$.
We assume that $\mu$ can be expressed as a sum of elements in $\tUUUUU^{(1)}$ and $\tUUUUU^{(-1)}$
and deduce a contradiction.

Suppose $\mu=\eta+\zeta$, $\eta\in\tUUUUU^{(1)}$ and $\zeta\in\tUUUUU^{(-1)}$.
Since $\eta(x)\geq 1$ for any $x\in V$ and $\eta^+(V)+1\leq \ell\eta(-\infty)$,
we see that
$$
\eta(-\infty)\geq\left\lceil\frac{2\ell+2}{\ell}\right\rceil=3.
$$
Similarly, since $\zeta(x)\geq -1$ for any $x\in V$ and $\zeta^+(V)-1\leq\ell\zeta(-\infty)$,
we see that
$$
\zeta(-\infty)\geq\left\lceil\frac{-2\ell-2}{\ell}\right\rceil=-2.
$$
On the other hand, since $\eta(-\infty)+\zeta(-\infty)=\mu(-\infty)=1$, we see that
$$
\eta(-\infty)=3\quad\mbox{ and }\quad\zeta(-\infty)=-2.
$$
Moreover, since $\eta(v_i)+\eta(v_{i+1})+1=\eta^+(e_i)+1\leq\eta(-\infty)=3$
and $\eta(v_j)\geq 1$ for any $i$ and $j$, we see that $\eta(v_j)=1$ for any $j$.
Thus,
$$
\zeta(x)=
\left\{
\begin{array}{ll}
0&\mbox{ if $x\in\{v_2, v_4, \cdots, v_{2\ell-2}\}$},\\
-2&\mbox{ if $x=-\infty$},\\
-1&\mbox{ otherwise.}
\end{array}
\right.
$$
Therefore, $\zeta^+(V)=-\ell-2$ and we see that
$$
\zeta^+(V)-1=-\ell-3>-2\ell=\ell\zeta(-\infty),
$$
since $\ell\geq 4$.
This contradicts to the assumption that $\zeta\in\tUUUUU^{(-1)}$.
Therefore, we see that $T^\mu\not\in\trace(\omega)$ and $\trace(\omega)$ is not a radical ideal.
\end{proof}

