\section{A necessary condition for the Ehrhart ring of the stable set polytope of a 
perfect graph to be CTR}

In this section, we state a necessary condition of an Ehrhart ring of the stable set polytope of a
perfect graph to be CTR, 
which shows that CTR property is close to \gor\ property.
Let $G=(V,E)$ be a perfect graph and set
$k=\max\{|K| : K$ is a maximal clique of $G\}$ and
$k'=\min\{|K| : K$ is a maximal clique of $G\}$.

By Chv\'atal \cite[Theorem 3.1]{chv}, we see that
$$
\stab(G)=\left\{f\in\RRR^{V}: \vcenter{\hsize=.5\textwidth\relax\noindent
$f(x)\geq 0$ for any $x\in V$ and $f^+(K)\leq 1$ for any maximal clique $K$ of $G$}
\right\}.
$$
Further, by Ohsugi and Hibi \cite[Theorem 2.1 (b)]{oh}, $\eksg$ is \gor\ if and only if $k-k'=0$.
We recall notation and basic facts from \cite[Remark 3.8]{mhperfect}.
For $n\in\ZZZ$, we set
$$
\qUUUUUn\define\left\{
\mu\in\ZZZ^{V^-}:
\vcenter{\hsize=.5\textwidth\relax\noindent
$\mu(x)\geq n$ for any $x\in V$ and
$\mu^+(K)+n\leq \mu(-\infty)$ for any maximal clique $K$ of $G$}
\right\}.
$$
Then 
$$
\omega^{(n)}=\bigoplus_{\mu\in\qUUUUUn}\KKK T^\mu
$$
for $n\in\ZZZ$, where $\omega$ is the canonical ideal of $\eksg$.

Here, we state a very easily proved but very useful fact.

\begin{lemma}
\mylabel{lem:high school}
If $x\in V$, $\eta\in\qUUUUU^{(1)}$, $\zeta\in\qUUUUU^{(-1)}$ and $(\eta+\zeta)(x)=0$,
then $\eta(x)=1$ and $\zeta(x)=-1$.
\end{lemma}
%
Now we state the following necessary condition for $\eksg$ to be a CTR ring.

\begin{prop}
\mylabel{prop:perfect graph}
Let $G=(V,E)$ be a perfect graph.
If $\eksg$ is CTR, then $k-k'\leq 1$.
\end{prop}
%
\begin{proof}
We prove the contraposition of the proposition, so we assume that $k-k'\geq 2$.
Let $\mu$ be an element of $\ZZZ^{V^-}$ defined by
$$
\mu(x)=\left\{
\begin{array}{ll}
0&\mbox{ if $x\in V$},\\
1&\mbox{ if $x=-\infty$}.
\end{array}
\right.
$$
Then $\mu\in\qUUUUU^{(0)}$ and therefore $T^\mu\in\eksg$.
Further, if we define $\eta$, $\zeta\in\ZZZ^{V^-}$ by
$$
\eta(x)=\left\{
\begin{array}{ll}
1&\mbox{ if $x\in V$},\\
k+1&\mbox{ if $x=-\infty$},
\end{array}
\right.
\quad\mbox{ and }\quad
\zeta(x)=\left\{
\begin{array}{ll}
-1&\mbox{ if $x\in V$},\\
-k'-1&\mbox{ if $x=-\infty$},
\end{array}
\right.
$$
then $\eta\in\qUUUUU^{(1)}$, $\zeta\in\qUUUUU^{(-1)}$ and $(k-k')\mu=\eta+\zeta$.
Therefore,
$$
(T^\mu)^{k-k'}\in\trace(\omega).
$$

On the other hand, if there are $\eta'\in\qUUUUU^{(1)}$ and $\zeta'\in\qUUUUU^{(-1)}$ with
$\mu=\eta'+\zeta'$, then $\eta'(x)=1$ and $\zeta'(x)=-1$ for any $x\in V$ by Lemma \ref{lem:high school}.
Therefore, $\eta'(-\infty)\geq k+1$ and $\zeta'(-\infty)\geq -k'-1$.
Thus,
$$
1=\mu(-\infty)=\eta'(-\infty)+\zeta'(-\infty)\geq k-k'\geq 2.
$$
This is a contradiction.
Therefore, $T^\mu\not\in\trace(\omega)$ and we see that $\trace(\omega)$ is not a radical ideal.
\end{proof}

As the following example shows, the condition in the above proposition is not sufficient.

\begin{example}
\rm
Let $G=(V,E)$ be the following graph.
\begin{center}
\begin{tikzpicture}
\coordinate (Y1) at (0,0);
\coordinate (X1) at (1,0);
\coordinate (X2) at (2,0);
\coordinate (X3) at (3,0);
\coordinate (Y4) at (4,0);
\coordinate (Y2) at (1.5,.7);
\coordinate (Y3) at (3.5,.7);

\draw (Y1)--(X1)--(X2)--(X3)--(Y4);
\draw (X1)--(Y2)--(X2);
\draw (X3)--(Y3)--(Y4);

\draw[fill] (X1) circle [radius=0.1];
\draw[fill] (X2) circle [radius=0.1];
\draw[fill] (X3) circle [radius=0.1];
\draw[fill] (Y1) circle [radius=0.1];
\draw[fill] (Y2) circle [radius=0.1];
\draw[fill] (Y3) circle [radius=0.1];
\draw[fill] (Y4) circle [radius=0.1];

\node at (0,-.3) {$y_1$};
\node at (1,-.3) {$x_1$};
\node at (2,-.3) {$x_2$};
\node at (3,-.3) {$x_3$};
\node at (4,-.3) {$y_4$};
\node at (1.5,1) {$y_2$};
\node at (3.5,1) {$y_3$};


\end{tikzpicture}
\end{center}
This is a comparability graph of a poset $P$ whose Hasse diagram is

\begin{center}
\begin{tikzpicture}
\coordinate (y1) at (0,2);
\coordinate (x1) at (1,0);
\coordinate (y2) at (1,1);
\coordinate (x2) at (1,2);
\coordinate (x3) at (2,0);
\coordinate (y3) at (2,1);
\coordinate (y4) at (2,2);

\draw (y1)--(x1)--(x2)--(x3)--(y4);

\draw[fill] (y1) circle [radius=.1];
\draw[fill] (y2) circle [radius=.1];
\draw[fill] (y3) circle [radius=.1];
\draw[fill] (y4) circle [radius=.1];
\draw[fill] (x1) circle [radius=.1];
\draw[fill] (x2) circle [radius=.1];
\draw[fill] (x3) circle [radius=.1];

\node at (0,2.3) {$y_1$};
\node at (1,-.3) {$x_1$};
\node at (.7,1) {$y_2$};
\node at (1,2.3) {$x_2$};
\node at (2,-.3) {$x_3$};
\node at (2.3,1) {$y_3$};
\node at (2,2.3) {$y_4$};

\end{tikzpicture}
\end{center}
i.e.
$G=(V,E)$, $V=P$, $E=\{\{z,w\}: z,w\in P, z<w\}$.
In particular, $G$ is perfect.
Further, 
$\max\{|K|: K$ is a maximal clique in $G\}=3$ and
$\min\{|K|: K$ is a maximal clique in $G\}=2$.

Define $\mu\in\ZZZ^{V^-}$ by
$$
\mu(z)=\left\{
\begin{array}{ll}
1&\mbox{ if $z\in\{x_1, x_2, x_3\}$},\\
0&\mbox{ if $z\in\{y_1,y_2,y_3,y_4\}$},\\
2&\mbox{ if $z=-\infty$}.
\end{array}
\right.
$$
Then $\mu\in\qUUUUU^{(0)}$.

We first show that $T^\mu\not\in\trace(\omega)$.
Assume the contrary.
Then there are $\eta\in\qUUUUU^{(1)}$ and $\zeta\in\qUUUUU^{(-1)}$ with $\mu=\eta+\zeta$.
Then $\eta(y_i)=1$ and $\zeta(y_i)=-1$ for $1\leq i\leq 4$ by Lemma \ref{lem:high school}.
Further,
\begin{eqnarray*}
\eta(-\infty)+\zeta(-\infty)&=&\mu(-\infty)=2,\\
\eta(x_i)+\zeta(x_i)&=&\mu(x_i)=1\quad\mbox{ for $1\leq i\leq 3$},\\
\zeta(x_1)+\zeta(y_1)-1&\leq&\zeta(-\infty),\\
\eta(x_1)+\eta(x_2)+\eta(y_2)+1&\leq&\eta(-\infty),\\
\zeta(x_2)+\zeta(x_3)-1&\leq&\zeta(-\infty)\\
\noalign {and} \\
\eta(x_3)+\eta(y_3)+\eta(y_4)+1&\leq&\eta(-\infty).
\end{eqnarray*}
Therefore 
\begin{eqnarray*}
4&=&2\mu(-\infty)\\
&=&2\eta(-\infty)+2\zeta(-\infty)\\
&\geq&(\zeta(x_1)-2)+(\eta(x_1)+\eta(x_2)+2)+(\zeta(x_2)+\zeta(x_3)-1)+(\eta(x_3)+3)\\
&=&\eta(x_1)+\eta(x_2)+\eta(x_3)+\zeta(x_1)+\zeta(x_2)+\zeta(x_3)+2\\
&=&\mu(x_1)+\mu(x_2)+\mu(x_3)+2\\
&=&5.
\end{eqnarray*}
This is a contradiction.
Thus, we see that $T^\mu\not\in\trace(\omega)$.

Next, we show that $T^\mu\in\sqrt{\trace(\omega)}$.
Since $G$ is a comparability graph of $P$, $\stab(G)=\msCCC(P)$ by \cite[Theorem 3.1]{chv},
where $\msCCC(P)$ is the chain polytope of $P$.
See \cite{sta} for the definition of the chain polytope.
Therefore, by \cite[Theorem 3.7]{mp}, we see that $T^\mu\in\sqrt{\trace(\omega)}$.
In fact, by using the idea of the proof of \cite[Theorem 3.7]{mp}, we can construct $\eta\in\qUUUUU^{(1)}$ and
$\zeta\in\qUUUUU^{(-1)}$ as follows.
\begin{eqnarray*}
\eta(z)&=&
\left\{
\begin{array}{ll}
1&\mbox{ if $z\in\{y_1,y_2,y_3,y_4\}$},\\
2&\mbox{ if $z\in\{x_1,x_2\}$},\\
3&\mbox{ if $z=x_3$},\\
6&\mbox{ if $z=-\infty$},
\end{array}
\right.\\
\zeta(z)&=&
\left\{
\begin{array}{ll}
0&\mbox{ if $z\in\{x_1,x_2\}$},\\
-1&\mbox{ if $z\in\{x_3,y_1,y_2,y_3,y_4\}$},\\
-2&\mbox{ if $z=-\infty$}
\end{array}
\right.
\end{eqnarray*}
Then $\eta+\zeta=2\mu$ and therefore $(T^\mu)^2\in\trace(\omega)$.
\end{example}

We end with the following.

\begin{prob}
\rm
Give a criterion of the Ehrhart ring of the chain polytope of a poset to be CTR.
\end{prob}




