\subsection{Channel Model}

The network contains $I$ satellites, $U$ users, and a STAR-RIS array. We first define the $i$-th satellite as $\varsigma_i$. Then, we pay our attention to the large-scale fading channels of $\varsigma_i - user_u$, which can be expressed as
\begin{equation}\label{large-scale_satell-user}
{L_{iu}} = {G_T}{\left( {\frac{\lambda }{{4\pi {d_{iu}}}}} \right)^2},
\end{equation}
where ${G_T}$ denote the transmit antenna gain. $\lambda $ denotes the signal wavelength. $d_{iu}$ is the distance of satellite $i$ and user $u$.

Note that in the urban canyons, the direct link between satellite and ground users may not exist. Therefore, the STAR-RISs can provide supplementary links between satellite and ground users, and the large scale fading channels of $\varsigma_i -STAR-RIS - user_u$ can be given by:
\begin{equation}\label{large-scale_satell-RIS}
{L_{Riu}} = {G_T}{G_R}{\left( {\frac{\lambda }{{4\pi {d_{iR}}}}} \right)^2}{\left( {\frac{\lambda }{{4\pi {d_{Ru}}}}} \right)^2},
\end{equation}
where $d_{iR}$ and $d_{Ru}$ respectively represent the distance of $\varsigma_i -STAR-RIS$ and $STAR-RIS - user_u$ links.

We then define the small-scale fading channel gain of $\varsigma_i - user_u$ link, ${h_{iu}}$, which follows the shadowed Rician fading. Although $M$ TAs are deployed, based on the fixed beamforming strategy adopted in GNSS and Beidou system, the multi-antenna gain can be considered as a single variable. Therefore, the small-scale fading vector ${{\bf{h}}_{u}}$ received by user $u$ can be expressed as
\begin{equation}\label{small-scale-channel-satell-user}
{{\bf{h}}_u} = \left[ {\begin{array}{*{20}{c}}
{{h_{1u}}}\\
{{h_{2u}}}\\
 \vdots \\
{{h_{iu}}}
\end{array}} \right],
\end{equation}
where ${{\bf{h}}_{u}}$ is a $\left( {i \times 1} \right)$-element vector.
%Therefore, we combine the channel vector of all users into an effective channel matrix as:
%\begin{equation}\label{small-scale_channel_matrix_satell_user}
%{\bf{H}} = \left[ {\begin{array}{*{20}{c}}
%{{{\bf{h}}_1}}& \cdots &{{{\bf{h}}_j}}
%\end{array}} \right].
%\end{equation}
Note that when the direct link between satellite $i$ and user $u$ does not exist, the corresponded row in~\eqref{small-scale-channel-satell-user} can be simply set to 0. Each element follows shadowed Rician fading channel gains with parameters $\Omega$, $2b$ and $m$, where $\Omega$ and $2b$ denote the average power of the LoS component and the multipath component, respectively. $m$ is the Nakagami-$m$ parameter ranging
from zero to infinite.

The small-scale channel matrix of $\varsigma_i -STAR-RIS$ links is expressed as
\begin{equation}\label{small_scale_satel_RIS_column_i}
{{\bf{h}}_{Ri}} = \left[ {\begin{array}{*{20}{c}}
{\begin{array}{*{20}{c}}
{\begin{array}{*{20}{c}}
{{h_{R,i1}}}\\
{{h_{R,i2}}}
\end{array}}\\
 \vdots
\end{array}}\\
{{h_{R,iN}}}
\end{array}} \right],
\end{equation}
where ${{h_{R,in}}}$ denotes the small-scale fading gain between satellite $i$ and the $n$-th STAR-RIS element, which follows shadowed Rician fading gains.

Similarly, the small-scale channel matrix of $STAR-RIS - user_u$ is given by:
\begin{equation}\label{small_scale_matrix_RIS_user_row_j}
{{\bf{g}}_u} = \left[ {\begin{array}{*{20}{c}}
{{g_{R,1u}}}& \cdots &{{g_{R,Nu}}}
\end{array}} \right],
\end{equation}
where ${{g_{R,nu}}}$ denotes the small-scale channel gain between the $n$-th STAR-RIS element and user $u$, which follows the Rician fading channel gains.

The STAR-RIS adopts both the reflective and transmit layers, thus we define the reflection and transmission matrix as:
\begin{equation}\label{reflection coefficient}
{{\bf{\Psi }}_R}{\rm{ = diag}}\left[ {\begin{array}{*{20}{c}}
{{\beta _{1,R}}{\phi _{1,R}}}&{{\beta _{2,R}}{\phi _{2,R}}}& \cdots &{{\beta _{N,R}}{\phi _{N,R}}}
\end{array}} \right],
\end{equation}
and
\begin{equation}\label{transmission coefficient}
{{\bf{\Psi }}_T}{\rm{ = diag}}\left[ {\begin{array}{*{20}{c}}
{{\beta _{1,T}}{\phi _{1,T}}}&{{\beta _{2,T}}{\phi _{2,T}}}& \cdots &{{\beta _{N,T}}{\phi _{N,T}}}
\end{array}} \right],
\end{equation}
where $j = \sqrt { - 1} $, ${\phi _{n,R}} = \exp (j{\theta _{n,R}})$ and ${\phi _{n,T}} = \exp (j{\theta _{n,T}})$ respectively represent the phase shift of the reflected and transmitted signals of STAR-RIS element ${n}$. $ 0 \le {\theta _{n,R}} < 2\pi  $, $0 \le {\theta _{n,T}} < 2\pi $. $0 < {\beta _{n,R}} \le 1$ and $0 < {\beta _{n,T}} \le 1$ denote the reflection amplitude coefficient and transmission amplitude coefficient of the ${n}$-th STAR-RIS element with $\beta _{n,R}^2 + \beta _{n,T}^2 = 1$, respectively.

Regarding ground user $u$ located in the urban canyons, without loss of generality, it is assumed that the number of visible satellites for user $u$ is defined as ${I_v}, {I_v} \in I$.
In addition, some satellites are invisible for user $u$, which are defined by a set of ${I_n},{I_n} \in I$.
Hence, if user $u$ is located at the reflection space of STAR-RIS, the received signals of user $u$ can be expressed as
\begin{equation}\label{received_signal_reflected_user}
\begin{aligned}
{y_{u,R}}(t) = & \underbrace {\sum\limits_{i = 1,i \in {I_n}}^I {\left( {{{\bf{g}}_u}{{\bf{\Psi }}_R}{{\bf{h}}_{Ri}}} \right)\sqrt {{L_{Riu}}{p_i}} {s_i}(t)} }_{{\rm{Reflected~Signals}}} \\
 &+ \underbrace {\sum\limits_{i = 1,i \in {I_v}}^I {{h_{iu}}} \sqrt {{L_{iu}}{p_i}} {s_i}(t)}_{{\rm{Directed~Signals}}} + {n_0},
\end{aligned}
\end{equation}
where ${n_0}$ denotes the additive white Gaussian noise (AWGN), ${s_i}(t)$ denotes the information of the $i$-th satellite. ${p_i}$ represents the transmit power of satellites $i$.

On the other hand, if user $u$ is located in the indoor scenarios, the transmitted signals can be expressed as
\begin{equation}\label{received_signal_transsmited_user}
{y_{u,T}}(t) = \underbrace {\sum\limits_{i = 1,i \in {I_n}}^I {\left( {{{\bf{g}}_u}{{\bf{\Psi }}_T}{{\bf{h}}_{Ri}}} \right)\sqrt {{L_{Riu}}{p_i}} {s_i}(t)} }_{{\rm{Transmitted~Signals}}} + {n_0}.
\end{equation}


\subsection{Signal Model}

Due to the fact that the code division technique is deployed in satellite navigation, the users can separate the information of different satellites. Therefore, we simply assume that one INAC satellite is deployed. The SC and SIC techniques are employed at the INAC satellite and ground users to detect the composite signals, respectively. Then, the INAC satellite sends the following signal:
\begin{equation}\label{NOMA model}
{s}(t) = {\omega _N}{s_N}(t) + {\omega _C}{s_C}(t),
\end{equation}
where ${\omega _N}$ and ${\omega _C}$ represent the power allocation factors of navigation and communication signals, respectively. ${s_N}(t)$ and ${s_C}(t)$ denote navigation and communication signals, respectively. Under the NOMA protocol, the power allocation factors are constrained such that $\omega_N^2 + \omega_C^2 = 1$. As can be seen from~\eqref{NOMA model}, two potential cases with different power allocation factors, NO-INAC and CO-INAC, can be investigated.

\subsubsection{NO-INAC Case}
It is assumed that the power allocation factors satisfy
\begin{equation}
{\omega _C}>{\omega _N} .
\end{equation}

In this scenario, the INAC user initially decodes the communication signal, treating the navigation signal as interference, and the signal-to-interference-plus-noise ratio (SINR) can be expressed as follows:
\begin{equation}\label{snrn_NO_communication}
SINR_C^{NO} = \frac{{{{\left| {{{\tilde h}_u}} \right|}^2}\omega _C^2{p_i}}}{{{{\left| {{{\tilde h}_u}} \right|}^2}\omega _N^2{p_i} + {\sigma ^2}}},
\end{equation}
where ${\left| {{{\tilde h}_u}} \right|^2}$ denotes the channel gain of user $u$, ${{\sigma ^{\rm{2}}}}$ represents the power of AWGN.
On the one hand, when both the direct link and reflect link exist, the channel gain can be expressed as
\begin{equation}\label{channel gain both direct and reflect link}
{\left| {{{\tilde h}_u}} \right|^2} = {\left| {{{\bf{g}}_u}{{\bf{\Psi }}_R}{{\bf{h}}_{Ri}}\sqrt{{L_{Riu}}}} +{{h_{iu}}\sqrt{{L_{iu}}}} \right|^2}.
\end{equation}
On the other hand, when only the reflect link exists, the effective channel gain is given by
\begin{equation}\label{channel gain only refect link}
{\left| {{{\tilde h}_u}} \right|^2} = {\left| {{{\bf{g}}_u}{{\bf{\Psi }}_R}{{\bf{h}}_{Ri}}\sqrt{{L_{Riu}}}} \right|^2}.
\end{equation}

After the communication signals are subtracted from the received signals, the navigation signals can be detected, then the SINR of navigation signals is given by
\begin{equation}\label{snrc0}
SINR_N^{NO} = \frac{{{{\left| {{{\tilde h}_u}} \right|}^2}\omega _N^2{p_i}}}{{{\sigma ^{\rm{2}}}}}.
\end{equation}

Therefore, in the NO-INAC case, the achievable navigation rate and communication rate of the INAC user ca be given by
\begin{equation}\label{NO_navigation_rate}
{R^{NO}_N} = {\log _2}\left( {1 + SINR_N^{NO}} \right),
\end{equation}
and
\begin{equation}\label{NO_communication_rate}
{R^{NO}_C} = {\log _2}\left( {1 + SINR_C^{NO}} \right),
\end{equation}
respectively.

\subsubsection{CO-INAC Case}
In the CO-INAC scenarios, we prioritize communication services, leading to the condition where ${\omega _N}$ and ${\omega _C}$ satisfy ${\omega _C} < {\omega _N}$. Thus, following the NOMA protocol, navigation signals should be decoded prior to communication signals. Consequently, the SINR for decoding navigation signals can be formulated as:
\begin{equation}\label{snrn_CO_N}
SINR_N^{CO} = \frac{{{{\left| {{{\tilde h}_u}} \right|}^2}\omega _N^2{p_i}}}{{{{\left| {{{\tilde h}_u}} \right|}^2}\omega _C^2{p_i} + {\sigma ^2}}}.
\end{equation}


After the navigation signals are deleted from the received signal, the communication signals can be obtained with the following SINR
\begin{equation}\label{snrc1}
SINR_C^{CO} = \frac{{{{\left| {{{\tilde h}_u}} \right|}^2}\omega _C^2{p_i}}}{{{\sigma ^{\rm{2}}}}}.
\end{equation}

Therefore, the achievable rates of communication and navigation of users in the CO-INAC cases are given by
\begin{equation}\label{rate CO_C}
{R^{CO}_C} = {\log _2}\left( {1 + SINR_C^{CO}} \right),
\end{equation}
and
\begin{equation}
{R^{CO}_N} = {\log _2}\left( {1 + SINR_N^{CO}} \right),
\end{equation}
respectively.

\section{Problem Formulation}

\subsection{Geometric Positioning Principle}
In this subsection, we first describe the geometric positioning principle.
The locations of user $u$, satellite ${s_i}$ and STAR-RIS array are specified as $({x_u},{y_u},{z_u})$, $({x_i},{y_i},{z_i})$ and $({x_R},{y_R},{z_R})$, respectively.

The actual distance of $\varsigma_i - user_u$ link is denoted by ${r_{\tau ,iu}}$, where $i = 1, 2, \cdots, I$. The distances of $\varsigma_i -STAR-RIS$ and $STAR-RIS - user_u$ links are represented as ${r_{\tau iR}}$ and ${r_{\tau Ru}}$, respectively. The GNSS system utilizes a highly accurate clock system that precisely records the transmission time ${t_{si}}$ when satellite ${s_i}$ sends a message frame. Similarly, user $u$ records the reception time ${t_{ru}}$ of the message. The distance ${r_{\tau ,iu}}$ between satellite ${s_i}$ and user $u$ is then calculated using the speed of light. Likewise, by employing both the speed of light and the transmission times, the combined distance through the STAR-RIS array, expressed as ${r_{\tau iR}} + {r_{\tau Ru}}$, is also computed.



When a direct link between satellite ${s_i}$ and the ground user is established, the positioning equation for satellite ${s_i}$ can be derived from the Euclidean distance as follows:
\begin{equation}\label{e13}
{r_{\tau ,iu}} = \sqrt {{{({x_i} - {x_u})}^2} + {{({y_i} - {y_u})}^2}{\rm{ + }}{{({z_i} - {z_u})}^2}} ,
\end{equation}
where ${r_{\tau ,iu}}$ represents the distance of $\varsigma_i - user_u$ link, which can be estimated by pseudo-range.


\subsection{Pseudo-Range Positioning}

%From the above-mentioned papers, the calculation process can be divided into two steps, 1) estimate the location of the satellite. 2) calculate the actual distance between the satellite and User1.

In practical applications, the pseudo-range primarily comprises clock error and atmospheric delay error. It is assumed that satellite ${s_i}$ transmits a navigation message at its clock time ${t_{si}}$, and user $u$ receives this message at their local time ${t_{ru}}$. Thus, the estimated distance of $\varsigma_i - user_u$ link can be expressed as:
\begin{equation}\label{tranmit time}
{\rho _{t,iu}} = c({t_{ru}} - {t_{si}}).
\end{equation}

Given that the satellite clock is not perfectly synchronized with the standard time, it is assumed that the clock error between satellite ${s_i}$ and the standard clock to be $\Delta{t_{si}}$, and the clock error between user $u$'s clock and the standard clock to be $\Delta{t_{ru}}$. Additionally, the delays caused by the ionosphere and troposphere are represented as ${I_i}$ and ${T_i}$, respectively. Other systematic errors are $\Delta{\varepsilon _i}$. Considering all the above factors, the actual distance of $\varsigma_i - user_u$ can be further transformed into:
\begin{equation}\label{distance satellite user}
{r_{\tau ,iu}} = {\rho _{t,iu}} - c(\Delta {t_{ru}} - \Delta {t_{si}} + {I_i} + {T_i} + \Delta {\varepsilon _i}),
\end{equation}
where $\Delta {t_{si}}$ can be obtained by the navigation messages. Thus, the pseudo-range can be simplified to
\begin{equation}
{\rho _{ci}} = {\rho _{t,iu}} + c(\Delta {t_{si}} - {I_i} - {T_i}).
\end{equation}

By doing so, the actual distance of $\varsigma_i - user_u$ can be simplified to
\begin{equation}\label{e119}
{r_{\tau ,iu}} = {\rho _{ci}} - c\Delta {t_r}.
\end{equation}

Based on~\eqref{e13} to~\eqref{e119}, the goal of this article is to calculate four unknowns ${x_u}$, ${y_u}$, ${z_u}$, and ${\Delta{t_r}}$. Thus, we assume that user $u$ receives several signals from satellite, which are given by
\begin{equation}\label{e20}
\begin{aligned}
 \sqrt {{{\left( {{x_1} - {x_u}} \right)}^2} + {{\left( {{y_1} - {y_u}} \right)}^2} + {{\left( {{z_1} - {z_u}} \right)}^2}}  &= {\rho _{c1}} - c\Delta {t_r}, \\
&  \vdots \\
\sqrt {{{\left( {{x_i} - {x_u}} \right)}^2} + {{\left( {{y_i} - {y_u}} \right)}^2} + {{\left( {{z_i} - {z_u}} \right)}^2}}  &  = {\rho _{ci}} - c\Delta {t_r}.
\end{aligned}
\end{equation}

Note that in practice, at least four satellites are required for navigation positioning. However, in the urban canyons, the direct link between satellite and user may be blocked. Fortunately, the STAR-RIS is able to provide extended LoS path between satellite and user. Therefore, the positioning equation between satellite $v$ and user $u$ through STAR-RIS is given by
\begin{equation}\label{e191}
{r_{\tau ,vR}} + \sqrt {{{({x_R} - {x_u})}^2} + {{({y_R} - {y_u})}^2}{\rm{ + }}{{({z_R} - {z_u})}^2}} {\rm{ = }}{\rho _{cv}} - c\Delta {t_r},
\end{equation}
where ${\rho _{cv}}$ represents the modified pseudo-range between the $v$-th satellite to user $u$ via STAR-RIS. The Euclidean distance of the $v$-th satellite to STAR-RIS is defined by ${r_{\tau ,vR}}$ as:
\begin{equation}\label{e21}
{r_{\tau ,vR}} = \sqrt {{{({x_4} - {x_R})}^2} + {{({y_4} - {y_R})}^2}{\rm{ + }}{{({z_4} - {z_R})}^2}} .
\end{equation}

We can re-formulate multiple positioning equations as follows:
\begin{equation}\label{e30}
\begin{aligned}
{\rho _{c1}}\left( {{{\bf{x}}_r}} \right) & = \sqrt {{{\left( {{x_1} - {x_u}} \right)}^2} + {{\left( {{y_1} - {y_u}} \right)}^2} + {{\left( {{z_1} - {z_u}} \right)}^2}}  + c\Delta {t_r},\\
 & \vdots \\
{\rho _{ci}}\left( {{{\bf{x}}_r}} \right) & = \sqrt {{{\left( {{x_i} - {x_u}} \right)}^2} + {{\left( {{y_i} - {y_u}} \right)}^2} + {{\left( {{z_i} - {z_u}} \right)}^2}}  + c\Delta {t_r},\\
{\rho _{cv}}\left( {{{\bf{x}}_r}} \right) & = {r_{\tau ,vR}} + \sqrt {{{({x_R} - {x_u})}^2} + {{({y_R} - {y_u})}^2}{\rm{ + }}{{({z_R} - {z_u})}^2}} \; \\
&+ c\Delta {t_r},
\end{aligned}
\end{equation}
where ${{\bf{x}}_r} = {[{x_u},{y_u},{z_u},\Delta{t_r}]^T}$, ${\rho _{ci}}({{\bf{x}}_r})$ represent the corrected pseudo-range of $\varsigma_i - user_u$ link.

We adopt the least squares method (LSM) algorithm to evaluate the position of users, and the state equation is given by
\begin{equation}\label{equa0}
{\bf{b}} = {\bf{A}}{d}{\bf{x}} + {N_0},
\end{equation}
where \textbf{x} denotes a vector with $k \times 1$ unknowns, \textbf{b} represents an ${\rm{4}} \times {\rm{1}}$ vector.
${\bf{A}}$ is a $\left( {i + v} \right) \times {\rm{4}}$ matrix, which can be calculated from the navigation messages as follows:
\begin{equation}\label{V}
{\bf{A}} = {\left[ {\begin{array}{*{20}{c}}
{{{\bf{u}}_1}}& \cdots &{{{\bf{u}}_i}}&{{{\bf{u}}_v}}
\end{array}} \right]^T},
\end{equation}
where ${{\bf{u}}_i} = \left[ {\begin{array}{*{20}{c}}
{\frac{{{x_i} - {x_{u0}}}}{{{r_i}\left( {{{\bf{x}}_{r0}}} \right)}}}&{\frac{{{y_i} - {y_{u0}}}}{{{r_i}\left( {{{\bf{x}}_{r0}}} \right)}}}&{\frac{{{z_i} - {z_{u0}}}}{{{r_i}\left( {{{\bf{x}}_{r0}}} \right)}}}&c
\end{array}} \right]$, and $ d{{\bf{x}}_0} = \left[ {\begin{array}{*{20}{c}}
{{x_u} - {x_{u0}}}\\
{{y_u} - {y_{u0}}}\\
{{z_u} - {z_{u0}}}\\
{\left( {{\rm{\Delta }}{t_r} - {\rm{\Delta }}{t_{r0}}} \right)}
\end{array}} \right]$.


The cost function ${\bf{P}}({\bf{x}})$ is defined as
\begin{equation}\label{P(X)}
\begin{aligned}
\mathbf{P}(\mathbf{x}) &=(\mathbf{A x}-\mathbf{b})^{T}(\mathbf{A} \mathbf{x}-\mathbf{b}) \\
& = {{\bf{x}}^{\rm{T}}}{{\bf{A}}^{\rm{T}}}{\bf{Ax}} - 2{{\bf{x}}^{\rm{T}}}{{\bf{A}}^{\rm{T}}}{\bf{b}} + {{\bf{b}}^{\rm{T}}}{\bf{b}},
\end{aligned}
\end{equation}
where ${\mathbf{P}(\mathbf{x})}$ is the sum square error. The goal of LSM is to minimize the sum of squared errors by differentiating ${\mathbf{P}(\mathbf{x})}$ with respect to $x$, we can derive:

\begin{equation}\label{derivative of P(x)}
\frac{{\partial {\bf{P}}({\bf{x}})}}{{\partial {\bf{x}}}} = 2{{\bf{A}}^{\rm{T}}}{\bf{Ax}} - 2{{\bf{A}}^{\rm{T}}}{\bf{b}}.
\end{equation}

The extreme point of the cost function is
\begin{equation}\label{extreme point of P(x)}
{\bf{\hat x}} = {\left( {{{\bf{A}}^{\rm{T}}}{\bf{A}}} \right)^{ - 1}}{{\bf{A}}^{\rm{T}}}{\bf{b}}.
\end{equation}

Since the second derivative of ${\mathbf{P}(\mathbf{x})}$ with respect to $x$ $\frac{{{\partial ^2}{\bf{P}}({\bf{\hat x}})}}{{\partial {{{\bf{\hat x}}}^2}}} = 2{{\bf{A}}^{\rm{T}}}{\bf{A}}$ is positive definite, ${\mathbf{P}(\mathbf{x})}$ is minimized when the derivative is 0. Then the estimation error $\delta {\bf{x}}$ is defined as
\begin{equation}\label{delta x}
\begin{aligned}
\delta {\bf{x}}  &=\mathbf{x}-\left(\mathbf{A}^{\rm{T}} \mathbf{A}\right)^{-1} \mathbf{A}^{\rm{T}} \mathbf{b} \\
& ={\bf{x}}-\left(\mathbf{A}^{\rm{T}} \mathbf{A}\right)^{-1} \mathbf{A}^{\rm{T}}(\mathbf{A} {\bf{x}}+n) \\
& =-\left(\mathbf{A}^{\rm{T}} \mathbf{A}\right)^{-1} \mathbf{A}^{\rm{T}} \mathbf{n}.
\end{aligned}
\end{equation}

According to (\ref{delta x}), the least squares estimation is only related to the system transformation relation vector A and the system noise $N$. When  $N$ follows a Gaussian distribution with a mean of 0, the estimation of LSM is unbiased. Since LSM can only solve linear equations, it is necessary to transform the problem into a linear one.

We then define that ${{\rho _{ci}}\left( {{{\bf{x}}_{r0}}} \right)}$ denotes the corrected pseudo-range between satellite ${s_i}$ and initial solution, which is expressed as
\begin{equation}
\begin{array}{l}
{\rho _{ci}}\left( {{{\bf{x}}_{r0}}} \right) = \sqrt {{{\left( {{x_i} - {x_{u0}}} \right)}^2} + {{\left( {{y_i} - {y_{u0}}} \right)}^2} + {{\left( {{z_i} - {z_{u0}}} \right)}^2}} + c{\rm{\Delta }}{t_{r0}}\\
\ \ \ \ \ \ \  \ \ \ \ {\rm{ = }}{r_i}\left( {{{\bf{x}}_{r0}}} \right) + c{\rm{\Delta }}{t_{r0}},
\end{array}
\end{equation}
where ${r_i}\left( {{{\bf{x}}_{r0}}} \right)$ represents the Euclidean distance from satellite ${s_i}$ to initial solution.

Then, the positioning equations is transformed into
\begin{equation}\label{e31}
\begin{aligned}
& \left[ {\begin{array}{*{20}{c}}
{{\rho _{c1}}({{\bf{x}}_r}) - {\rho _{c1}}({{\bf{x}}_{r0}})}\\
{{\rho _{c2}}({{\bf{x}}_r}) - {\rho _{c2}}({{\bf{x}}_{r0}})}\\
{{\rho _{c3}}({{\bf{x}}_r}) - {\rho _{c3}}({{\bf{x}}_{r0}})}\\
{{\rho _{c4}}({{\bf{x}}_r}) - {\rho _{c4}}({{\bf{x}}_{r0}})}
\end{array}} \right]\; =\\
& \left[ {\begin{array}{*{20}{c}}
{\frac{{{x_1} - {x_{r0}}}}{{{r_1}\left( {{{\bf{x}}_{r0}}} \right)}}}&{\frac{{{y_1} - {y_{r0}}}}{{{r_1}\left( {{{\bf{x}}_{r0}}} \right)}}}&{\frac{{{z_1} - {z_{r0}}}}{{{r_1}\left( {{{\bf{x}}_{r0}}} \right)}}}&c\\
{\frac{{{x_2} - {x_{r0}}}}{{{r_2}\left( {{{\bf{x}}_{r0}}} \right)}}}&{\frac{{{y_2} - {y_{r0}}}}{{{r_2}\left( {{{\bf{x}}_{r0}}} \right)}}}&{\frac{{{z_2} - {z_{r0}}}}{{{r_2}\left( {{{\bf{x}}_{r0}}} \right)}}}&c\\
{\frac{{{x_3} - {x_{r0}}}}{{{r_3}\left( {{{\bf{x}}_{r0}}} \right)}}}&{\frac{{{y_3} - {y_{r0}}}}{{{r_3}\left( {{{\bf{x}}_{r0}}} \right)}}}&{\frac{{{z_3} - {z_{r0}}}}{{{r_3}\left( {{{\bf{x}}_{r0}}} \right)}}}&c\\
{\frac{{{x_4} - {x_{r0}}}}{{{r_4}\left( {{{\bf{x}}_{r0}}} \right)}}}&{\frac{{{y_4} - {y_{r0}}}}{{{r_4}\left( {{{\bf{x}}_{r0}}} \right)}}}&{\frac{{{z_4} - {z_{r0}}}}{{{r_4}\left( {{{\bf{x}}_{r0}}} \right)}}}&c
\end{array}} \right]\left[ {\begin{array}{*{20}{c}}
{{x_u} - {x_{r0}}}\\
{{y_u} - {y_{r0}}}\\
{{z_u} - {z_{r0}}}\\
{\Delta {t_r} - \Delta {t_{r0}}}
\end{array}} \right] \\
&+ \left[ {\begin{array}{*{20}{c}}
{{n_1}}\\
{{n_2}}\\
{{n_3}}\\
{{n_4}}
\end{array}} \right].\;
\end{aligned}
\end{equation}


Hence, we can calculate the positioning for satellite ${s_i}$ by the following equation
\begin{equation}\label{equa2}
\delta {\rho _{ci}} = {{\bf{u}}_i}{({{\bf{A}}^T}{\bf{A}})^{ - 1}}{{\bf{A}}^T}{\bf{b}} + {n_0}.
\end{equation}

The current solution ${{\bf{x}}_{r1}}$ can be then updated, which can be expressed as
\begin{equation}
{{\bf{x}}_{r1}} = {{\bf{x}}_{r0}} + {({{\bf{A}}^T}{\bf{A}})^{ - 1}}{{\bf{A}}^T}{\bf{b}}.
\end{equation}


