\subsection{Dynamics of the nematic tensor relative to moving coordinates}\label{dynamicsofq}
The time derivative $\bar{D}_t$ in Eq. \eqref{eqdyq} is defined as $(\bar{D}_t \textbf{Q})^{m\delta} = \partial_t (Q_{ij} \hat{e}_i \hat{e}_j):\hat{e}^m \hat{e}^{\delta} +a_{\delta} a_m ( -\bar{V}^{c} \nabla_c Q^{m \delta})$, where $a_i$ shows the scaling factor of the curvilinear coordinate along $x_i$ axis, and \( \mathbf{\bar{V}} = \mathbf{u} - \mathbf{V} \) shows the fluid velocity respect to the velocity of the coordinate $\textbf{V}$. 
In the evolving coordinate system, the $_{m \delta}$ component of the dynamics of the nematic tensor (Eq. \eqref{eqdyq}) is then written as:
\begin{align}
& \partial_t (Q_{ij} \hat{e}_i \hat{e}_j):\hat{e}_m \hat{e}_{\delta} = \partial_t Q_{m \delta} + Q_{\delta i} \hat{e}_m \cdot \partial_t \hat{e}_i + Q_{m i} \hat{e}_{\delta} \cdot \partial_t \hat{e}_i \nonumber \\
& = a_{\delta} a_m \Gamma (K \nabla^2 Q^{lm} - \mathcal{A}(1 + \mathcal{B} g_{\beta \gamma} g_{\alpha \delta} Q^{\alpha \beta} Q^{\gamma \delta}) \mathcal{B} Q^{ij}) \nonumber \\
& \quad + a_{\delta} a_m ( -V^{c} \nabla_c Q^{m \delta} + \frac{2}{d} \lambda E^{m \delta} + \Omega^m_\alpha Q^{\alpha \delta} - Q^{m \beta} \Omega_\beta^{\delta} ), \tag{S1} \label{eqmolecb}
\end{align}
where the strain rate $\textbf{E}$ and vorticity $\boldsymbol{\Omega}$ are computed using the velocities $\bar{\textbf{V}}$, which account for the evolution of the coordinate system.
\subsection{Laplacian of the nematic tensor}\label{nematicdiffusion}
We now define the Laplacian of contravariant nematic tensor used in Eq. \eqref{eqmolec} which reads
\begin{align}
\nabla^2 Q^{\mu \nu} =&  \nabla_k \nabla^k Q^{\mu \nu}= g^{\rho k} \nabla_k \nabla_\rho Q^{\mu \nu}= g^{\rho k} \nabla_k T^{\mu \nu}_\rho,\tag{S2}\label{lap}
\end{align}
where we have used the Christofel symbol $\boldsymbol{\Gamma}$ to define 
\begin{align}
T^{\mu \nu}_\rho= \nabla_\rho Q^{\mu \nu}= \partial_\rho Q^{\mu \nu}+\Gamma^\mu_{\alpha \rho} Q^{\alpha \nu}+\Gamma^\nu_{\alpha \rho} Q^{\mu \alpha}. \tag{S3}
\end{align}

Using the definition of $\textbf{T}$, Eq. \eqref{lap} then can be written as
\begin{align}
\nabla^2 Q^{\mu \nu} =&  g^{\rho k} (\partial_k T^{\mu \nu}_\rho+\Gamma^\mu_{k \alpha} T^{\alpha \nu}_\rho+\Gamma^\nu_{k \alpha} T^{\mu \alpha}_\rho-\Gamma^\alpha_{k \rho} T^{\mu \nu}_\alpha),\tag{S4}\label{lapb}
\end{align}
where
\begin{align}
\partial_k T^{\mu \nu}_\rho=& \partial_k \partial_\rho Q^{\mu \nu}+\partial_k \Gamma^\mu_{\alpha \rho} Q^{\alpha \nu}
+ \Gamma^\mu_{\alpha \rho} \partial_k Q^{\alpha \nu}+\partial_k \Gamma^\nu_{\alpha \rho} Q^{\mu \alpha} \nonumber\\&+ \Gamma^\nu_{\alpha \rho} \partial_k Q^{\mu \alpha}.\tag{S5}
\end{align}
\subsection{Liquid crystal dynamics}\label{sthetadynamics}
In this subsection, we show how to use 
the Pauli matrices $\boldsymbol{\Pi}_{q}$ to drive the dynamics of the nematic order parameter $S$ and the direction of the order $\theta$ in Eqs. \eqref{dynamicsofS}   and \eqref{dynamicsoftheta} from the dynamics of the nematic tensor in \eqref{eqdyq}. 
Using the definition of Pauli matrices, we obtain  
\begin{align}
(\boldsymbol{\Pi}_p \boldsymbol{\Pi}_p)_{ij} = (\boldsymbol{\pi} \boldsymbol{\pi})_{ij} = \delta_{ij} - \delta_{i3} \delta_{j3},\tag{S6}
\end{align}
which corresponds to the 3D identity matrix with the \((3,3)\) component subtracted.  
The time evolution of \(\boldsymbol{\Pi}_p\) is given by  
\begin{align}
\frac{d \boldsymbol{\Pi}_p}{dt} = 2 \boldsymbol{\pi} \frac{d \theta}{dt}.\tag{S7}
\end{align}
Consequently, the time evolution of the nematic tensor can be expressed as  
\begin{align}
\partial_t \boldsymbol{Q} &= \frac{3}{4} \left( \boldsymbol{\Pi}_p + \boldsymbol{G} \right) \frac{d S}{dt} + \frac{3 S}{4} \frac{d \boldsymbol{\Pi}_p}{dt} \nonumber \\
&= \frac{3}{4} \left( \boldsymbol{\Pi}_p + \boldsymbol{G} \right) \frac{d S}{dt} + \frac{3 S}{2} \boldsymbol{\pi} \frac{d \theta}{dt}.\tag{S8}
\end{align}
Multiplying Eq.~(1) on the left by \(\boldsymbol{\Pi}_p\), taking the trace, and using  
\begin{align}
\operatorname{Tr}(\boldsymbol{\Pi}_p \boldsymbol{\Pi}_p) = 2, \quad
\operatorname{Tr}(\boldsymbol{\Pi}_p \boldsymbol{G}) = \operatorname{Tr}(\boldsymbol{\Pi}_p \boldsymbol{\pi}) = 0,\tag{S9}
\end{align}
we obtain the dynamics of the nematic order in Eq. \eqref{dynamicsofS}. Similarly, multiplying Eq.~(1) on the left by \(\boldsymbol{\pi}\), taking the trace, and using  
\begin{align}
\operatorname{Tr}(\boldsymbol{\pi} \boldsymbol{\pi}) = 2, \quad
\operatorname{Tr}(\boldsymbol{\pi} \boldsymbol{G}) = \operatorname{Tr}(\boldsymbol{\pi} \boldsymbol{\Pi}_p) = 0,\tag{S10}
\end{align}
yields the dynamics of the orientation field in Eq. \eqref{dynamicsoftheta}.
\section{Stress free boundary conditions}\label{bcsection}
To find the stress free boundary condition at the interface, we define the unit vector normal to the interface as 
\begin{equation}
 \textbf{N}=\left|\frac{\partial \boldsymbol{r}}{\partial x_1} \times \frac{\partial \boldsymbol{r}}{\partial x_2}\right|^{-1}\left(\frac{\partial \boldsymbol{r}}{\partial x_1} \times \frac{\partial \boldsymbol{r}}{\partial x_2}\right),\tag{S11}
\end{equation}
where {$\boldsymbol{r}(x_1,x_2,t)= \textbf{r}_c(x_1,x_2,t)\pm \frac{h}{2} \textbf{n}(x_1,x_2,t)$}.
Substituting normal to the interface {$\textbf{N}(x_1,x_2,t)$} in the  stress free boundary conditions  $\boldsymbol{\sigma}\cdot\textbf{N}|_{n=\pm h/2}=0$, we have
\begin{align}
\sigma_{13} & = \pm \frac{1}{2 l_1} \frac{\partial h}{\partial x_1} \sigma_{11} \pm \frac{1}{2 l_2} \frac{\partial h}{\partial x_2} \sigma_{12}, \tag{S12}\label{bcs11}\\
\sigma_{23} & = \pm \frac{1}{2 l_1} \frac{\partial h}{\partial x_1} \sigma_{12} \pm \frac{1}{2 l_2} \frac{\partial h}{\partial x_2} \sigma_{22}, \tag{S13}\label{bcs22}\\
\sigma_{33} & = \pm \frac{1}{2 l_1} \frac{\partial h}{\partial x_1} \sigma_{13} \pm \frac{1}{2 l_2} \frac{\partial h}{\partial x_2} \sigma_{23},\tag{S14}\label{bcs33}
\end{align}
where the scaling factors are defined as
$l_1=a_1\left(1-\kappa_1 n\right)$, and
$ l_2=a_2\left(1-\kappa_2 n\right)$.
\subsection{Expansion of the stress tensor and the dynamics in a nearly flat film}\label{stressexpansion}  
In this subsection, we define the lowest order terms in the definition of the stress tensor and the Stokes equation. Using the scaling introduced in Sec. \ref{sectionflatlub}, we can write the following expansion for the stress tensor
\begin{align}
        &{\sigma}_{11}=2 \mu \partial_{1} {u}^{(0)}+m Q_{11}-P^{(0)}+\mathcal{O}(\epsilon),\tag{S15}\label{sad1}\\& 
    {\sigma}_{12}= \mu ( \partial_{1} {v}^{(0)}+ \partial_{2} {u}^{(0)})+m Q_{12}-P^{(0)}+\mathcal{O}(\epsilon),\tag{S16}\label{sad2}\\& 
{\sigma}_{22}=2\mu \partial_{2} {v}^{(0)}+m Q_{22}+\mathcal{O}(\epsilon),\tag{S17}\label{sad3}\\&
{\sigma}_{13}=\mu \epsilon^{-1} \partial_{n}  {u}^{(0)}+\mathcal{O}(\epsilon^0),\tag{S18}\label{sad4}\\& 
{\sigma}_{23}=\mu \epsilon^{-1} \partial_{n} {v}^{(0)}+\mathcal{O}(\epsilon^0),\tag{S19}\label{sad5}\\& 
{\sigma}_{33}=2\mu \partial_{n} {w}^{(0)} -P^{(0)}+m Q_{33}+\mathcal{O}(\epsilon),\tag{S20}\label{sad6}
\end{align}
The components of the Stokes equation (Eq. \eqref{stokesequa}), parallel to the plane, can then be written as 
\begin{align}
        & \mu(\epsilon^{-2} \partial_n^2 {u}^{(0)}+\partial_n^2 {u}^{(2)})+\mu (\partial_{1}^2+\partial_{2}^2) {u}^{(0)}-\partial_1 P^{(0)}\nonumber \\&+m (\partial_1 Q_{11}+\partial_2 Q_{12})+\mathcal{O}(\epsilon)=0,\tag{S21}\label{sadsad1}\\
        &\mu(\epsilon^{-2} \partial_n^2 {v}^{(0)}+\partial_n^2 {v}^{(2)})+\mu (\partial_{1}^2+\partial_{2}^2) {v}^{(0)}-\partial_2 P^{(0)}\nonumber \\&+m (\partial_2 Q_{22}+\partial_1 Q_{12})+\mathcal{O}(\epsilon)=0.\tag{S22}\label{sadsad2}
\end{align}
Stokes equation (Eq. \eqref{stokesequa}) perpendicular to the center surface can then be written as 
\begin{align}
        & \mu(\epsilon^{-1} \partial_n^2 {w}^{(0)}+\epsilon \partial_n^2 {w}^{(2)})+\epsilon \mu (\partial_{1}^2+\partial_{2}^2) {w}^{(0)}-\epsilon^{-1}\partial_n P^{(0)}\nonumber \\&-\epsilon \partial_n P^{(2)}+m (\partial_1 Q_{13}+\partial_2 Q_{23})+\mathcal{O}(\epsilon)=0.\tag{S23}\label{sadsadg1}
\end{align}
Finally, the {incompressibility} condition can be written as
\begin{align}
        & \partial_n {w}^{(0)} + \partial_1 {u}^{(0)} + \partial_2 {v}^{(0)} + \epsilon^2 (\partial_n {w}^{(2)} + \partial_1 {u}^{(2)} + \partial_2 {v}^{(2)})=0.\tag{S24}\label{incompnnn}
\end{align}
\subsection{Torque balance for a nearly flat film}\label{torquebalanceflat}
To find the torque balance governing the dynamics of the flat film, we need to use the first-order non-zero elements of the stress tensor. Inserting the solution for the zero-order pressure (Eq. \eqref{pressureflat}) into the stress tensor, the first-order non-zero elements of the stress tensor read
\begin{align}
    &{\sigma}_{11}^0=2 \mu (2 \partial_{1} {u}^{(0)}+\partial_{2} {v}^{(0)})+m (Q_{11}-Q_{33}),\tag{S25}\label{zerostress0}\\& 
    {\sigma}_{12}^0=2 \mu ( \partial_{1} {u}^{(0)}+2 \partial_{2} {v}^{(0)})+m Q_{12},\tag{S26}\label{zerostress1}\\& 
{\sigma}_{22}^0=\mu (\partial_{1} {u}^{(0)}+2\partial_{2} {v}^{(0)})+m (Q_{22}-Q_{33}).\tag{S27}\label{zerostress}
\end{align}
The torque balance on the elements of the film can then be written as 
\begin{align}
 &\partial_{1}^2\int_{n^-}^{n^{+}}  dz z {\sigma}_{11}^{(0)}+ \partial_{2}^2 \int_{n^-}^{n^{+}} dz z {\sigma}_{22}^{(0)}
       + 2 \partial_{12} \int_{n^-}^{n^{+}}  dz z {\sigma}_{12}^{(0)}=0,\tag{S28}\label{eq26b}
\end{align}
where $n^-={{H}_0-\frac{{h}_0}{2}}$, and $n^+={{H}_0+\frac{{h}_0}{2}}$.
Substituting the stress tensor from Eqs. \eqref{zerostress0}-\eqref{zerostress} into the torque balance Eq. \eqref{eq26b} and evaluating the integrals, we obtain Eq.~\eqref{torquebalance} in the manuscript.
\subsection{Dispersion relation of the nematic phase in a nearly  flat film}\label{nematicflat}
In Eq. \eqref{eqwe}, we showed the growth rate of perturbations in the nematic phase in the absence of the flow aligning parameter  {$\lambda$}. The full growth rate of the perturbations in the presence of the flow aligning parameter $\lambda$ reads
\begin{align}
&\omega=\frac{1}{192 \mu} (A_1\pm\sqrt{B_1})-\frac{3 K_Q q^2}{4 \gamma}(1\pm \frac{C_1}{\sqrt{B_1}}),\tag{S29}\label{fullw}\\&
A_1=-2 m (5 \lambda +3 \lambda  \cos (4 \phi)+9 \cos (2 \phi)-9),\nonumber \\&
B_1=2 m^2 (\lambda  (59 \lambda +108)+162 (5 \lambda +6) \cos (2 \phi) \nonumber\\&+2 m^2 (9 \lambda  (\lambda  \cos (8 \phi)+6 \cos (6 \phi))+1539))\nonumber\\&+3 (20 \lambda  (\lambda +3)+27) \cos (4 \phi)) ,\nonumber\\&
C_1=2m (9+5 \lambda+27 \cos (2\phi)+3 \lambda \cos(4\phi)),\nonumber
\end{align}
where $B_1>0$ independent of values for $\lambda$, $m$, and $\phi$, and as a result the imaginary part of   $\omega$ is zero, and there is no oscillations. Equation \eqref{fullw} simplifies to the Eqs. \eqref{eqwc} and \eqref{eqwe} in the manuscript for $\lambda=0$.
\subsection{Effective Stokes equation and mass conservation in curved films}\label{forcebalanceeffective}
In this subsection, we find the leading order effective stokes equation and mass conservation in curved films.
Noting that the metric tensor is diagonal, the total stress tensor, which includes viscous stress, pressure, and active stress can be expressed as  
\begin{align}
&\sigma^{ij} = \mu \left( g^{ii} [\partial_i u^j + u^m \Gamma_{i m}^j] + g^{jj} [\partial_j u^i + u^m \Gamma_{j m}^i] \right) -P \delta^{ij}\nonumber \\
&= \mu \left( \ell_i^{-2} [\partial_i u^j + u^m \Gamma_{i m}^j] + \ell_j^{-2} [\partial_j u^i + u^m \Gamma_{j m}^i] \right)-P \delta^{ij},\tag{S30}
\end{align}
where the scaling factors are defined as
$l_1=a_1\left(1-\kappa_1 n\right)$, and
$ l_2=a_2\left(1-\kappa_2 n\right)$, and $\kappa_1$ and $\kappa_2$ are principal curvatures of the center-surface. 
The stress components to the order $\mathcal{O}(\epsilon)$ are given by  
\begin{align}
{\sigma}_{11}  &=-P^{(0)}+\frac{2 \mu}{a_1^{(0)}}(\frac{\partial {u}^{(0)}}{\partial x_1}+\frac{{v}^{(0)}}{a_2^{(0)}} \frac{\partial a_1^{(0)}}{\partial x_2}-a_1^{(0)} \kappa_1^{(0)} V_3^{(0)})\nonumber \\&+  m Q_{11}+\mathcal{O}(\epsilon), \tag{S31}\\
{\sigma}_{22}  &=-P^{(0)}+\frac{2 \mu}{a_2^{(0)}}(\frac{\partial {v}^{(0)}}{\partial x_2}+\frac{{u}^{(0)}}{a_1^{(0)}} \frac{\partial a_2^{(0)}}{\partial x_1}-a_2^{(0)} \kappa_2^{(0)} V_3^{(0)})\nonumber \\&+  m Q_{22}+\mathcal{O}(\epsilon),\tag{S32}\\
{\sigma}_{33} &=-P^{(0)}+2 \mu (\frac{\partial {w}^{(1)}}{\partial n}+ \frac{\partial {w}^{(0)}}{\partial n} \epsilon^{-1})\nonumber \\&+ m Q_{33}^{(0)}+\mathcal{O}(\epsilon)\tag{S33}\\
 {\sigma}_{12} &= \frac{\mu}{a_1^{(0)} a_2^{(0)}}(a_1^{(0)} \frac{\partial {u}^{(0)}}{\partial x_2}-{u}^{(0)} \frac{\partial a_1^{(0)}}{\partial x_2}+a_2^{(0)} \frac{\partial {v}^{(0)}}{\partial x_1})\nonumber \\&-{v}^{(0)} \frac{\partial a_2^{(0)}}{\partial x_1}+ m Q_{12}+\mathcal{O}(\epsilon), \tag{S34}\\
 {\sigma}_{13} &= \mu(\frac{\partial {u}^{(1)}}{\partial n}+\frac{\partial {u}^{(0)}}{\partial n} \epsilon^{-1}+\kappa_1^{(0)} {u}^{(0)}+\frac{1}{a_1^{(0)}} \frac{\partial {w}_0}{\partial x_1})\nonumber \\&+ m Q_{13}+\mathcal{O}(\epsilon), \tag{S35} \\
 {\sigma}_{23} &= \mu(\frac{\partial {v}^{(0)} }{\partial n}\epsilon^{-1}+\frac{\partial {v}^{(1)}}{\partial n}+\kappa_2^{(0)} {v}^{(0)}+\frac{1}{a_2^{(0)}} \frac{\partial V_3^{(0)}}{\partial x_2})\nonumber \\&+ m Q_{23}+\mathcal{O}(\epsilon),\tag{S36}
\end{align}
 {and the} incompressibility condition (Eq.~\eqref{incomp}) can be expressed as 
\begin{align}
\frac{\partial}{\partial x_1} \left(l_2 u\right) + \frac{\partial}{\partial x_2} \left(l_1 v\right) + \frac{\partial}{\partial n} \left(l_1 l_2 w\right) = 0. \tag{S37}\label{incomcur}
\end{align}
 The incompressibility equation \eqref{incomcur} to the leading order reads
\begin{align}
\frac{\partial {w}^{(1)}}{\partial n} = &   
 -\frac{1}{a_1^{(0)} a_2^{(0)}} (\frac{\partial}{\partial x_1} (a_2^{(0)} {u}^{(0)}) + \frac{\partial}{\partial x_2} (a_1^{(0)} {v}^{(0)}) )\nonumber \\
&+(\kappa_1^{(0)}+\kappa_2^{(0)}) V_3^{(0)},\tag{S38}
\end{align}
 {and is} subject to the $\mathcal{O}(\epsilon)$ kinematic condition at $n = \pm \frac{1}{2} h^{(0)}$  {which reads}
\begin{align}
 &{w}^{(1)}-\boldsymbol{n}^{(1)} \cdot \frac{\partial \boldsymbol{r}_c^{(0)}}{\partial t}-\boldsymbol{n}^{(0)} \cdot \frac{\partial \boldsymbol{r}_c^{(1)}}{\partial t}= \pm \frac{1}{2} \frac{\partial h^{(0)}}{\partial t} \nonumber\\&\pm \frac{1}{2 a_1^{(0)}} \frac{\partial h^{(0)}}{\partial x_1}({u}^{(0)}-V_1^{(0)})  \pm \frac{1}{2 a_2^{(0)}} \frac{\partial h^{(0)}}{\partial x_2}({v}^{(0)}-V_2^{(0)}). \tag{S39} \label{w1kin}
\end{align}  
These expressions give an equation for ${w}^{(1)}$ 
\begin{align}
{w}^{(1)} &= \boldsymbol{n}^{(1)} \cdot \frac{\partial \boldsymbol{r}_c^{(0)}}{\partial t} + \boldsymbol{n}^{(0)} \cdot \frac{\partial \boldsymbol{r}_c^{(1)}}{\partial t} 
+ \frac{n}{a_1^{(0)} a_2^{(0)}} [a_1^{(0)} a_2^{(0)} (\kappa_1^{(0)} \nonumber \\ 
&\quad + \kappa_2^{(0)}) V_3^{(0)} - \frac{\partial}{\partial x_1} (a_2^{(0)} {u}^{(0)}) - \frac{\partial}{\partial x_2} (a_1^{(0)} {v}^{(0)}) ], \tag{S40}\label{wveloc}
\end{align}
and mass conservation (Eq.~\eqref{masscon} in the manuscript). 
The Stokes equation  {(Eq. \eqref{stokesequa})} in the transverse direction, combined with the stress-free boundary condition (Eq.~\eqref{bcs33}), yields the leading-order pressure:  
\begin{align}
P^{(0)} &= \frac{2 \mu}{a_1^{(0)} a_2^{(0)}} [a_1^{(0)} a_2^{(0)} (\kappa_1^{(0)} + \kappa_2^{(0)}) V_3^{(0)} \nonumber \\ 
&\quad - \partial_1 (a_2^{(0)} {u}^{(0)}) - \partial_2 (a_1^{(0)} {v}^{(0)}) ] + m Q_{33}. \tag{S41}\label{pres}
\end{align}
Substituting the leading-order velocity expressions (Eqs.~\eqref{vel1delta} and \eqref{vel2delta}) into Eq.~\eqref{pres}, we find that the nonzero stress components, \(\sigma_{13}\), \(\sigma_{23}\), and \(\sigma_{33}\), are of order \(\mathcal{O}(\epsilon)\). 
As a result, the $\mathcal{O}(\epsilon^0)$ terms in the transverse Stokes equation satisfy 
\begin{align}
\frac{\partial \sigma_{33}^{(1)}}{\partial n} + \kappa_1^{(0)} \sigma_{11}^{(0)} + \kappa_2^{(0)} \sigma_{22}^{(0)} = 0. \tag{S42}\label{stktr}
\end{align}  
Using the third component of the stress-free boundary condition,  
$$\sigma_{33}^{(1)} = 0 \quad \text{on} \quad n = \pm \frac{1}{2} h^{(0)},$$  
we can integrate Eq. \eqref{stktr} across the thickness and obtain the effective transverse stress balance, as given in Eq.~\eqref{forcebalancentop}.
