Note that $|H_i \cap V_j| \leq 1$. For given pair $H_i$ and $V_j$, we denote their intersecting vertex by $x_{a_ib_j}$. To each cycle $\sigma: h_{i_1},v_{j_1},h_{i_2},v_{j_2},\ldots,h_{i_r},v_{i_r}$ in $G(\mathcal{C})$, where $r\geq 2$, we associate a binomial defined by: 
$$f_{\sigma}=x_{a_{i_1},b_{j_1}}\cdots x_{a_{i_r},b_{j_r}} - x_{a_{i_2},b_{j_1}}\cdots x_{a_{i_1},b_{j_r}}.$$ 

Let $J_{\mcC}$ be an ideal generated by all the binomials $f_{\sigma}$, where $\sigma$ is a cycle in $G(\mathcal{C})$.

\begin{example}
    Let $\mcC$ be the corner-interval minors as shown in Figure \ref{fig.maxC}. Then the ideal 
    $$J_\mcC= I(\mcC)+(x_{12}x_{23}x_{34}-x_{14}x_{22}x_{33}).$$
\end{example}

In \cite{Q2012}, it is shown that $J_{\mcC}$ is the toric ideal of the edge ring of $G(\mathcal{C})$; we recall it below. 

\vspace{2mm}

Let  $K[G(\mathcal{C})]=K[h_iv_j \mid \{i,j\}\in E(G(\mcC))]$ be the subalgebra of polynomial algbera $T=K[h_1,\ldots,h_q,v_1,\ldots,v_p]$. Let $\phi:S \rightarrow T$ be the surjective $K$-algebra homomorphism defined by $\phi(x_{ij})=h_iv_j$, where $x_{ij}=h_i\cap v_j$. We denote by $J_\mcC$ the toric ideal of $K[G(\mathcal{C})]$. Thus, $J_\mcC$ is a prime ideal. From \cite{Q2012} it is known that the kernel $J_\mcC$ of $\phi$ is generated by the binomials $f_\sigma$, where $\sigma$ is a cycle of $G(\mcC)$. 

\vspace{2mm}

The following remarks and Proposition \ref{prop.1} describe some key properties of $J_\mcC$ and $G(\mcC)$.

\begin{remark}
    Let $\mathcal{C}$ be an arbitrary set of corner-interval minors. Then one has $I(\mcC) \subset J_{\mcC}$.
\end{remark}

%A corner-interval minors $\mcC$ is said to be connected if $\{x_{11},x_{21},\ldots,x_{m1}\}$ is a vertical interval. 

\begin{remark} \label{remark.1}
    Let $\mathcal{C}$ be an arbitrary set of corner-interval minors. Suppose $V_1=\{x_{11},x_{21},\ldots,x_{m1}\}$ be a maximal vertical interval of $\mcC$. Let $\sigma: h_{i_1},v_{j_1},h_{i_2},v_{j_2},\ldots,h_{i_r},v_{i_r}$ be a cycle in $G(\mathcal{C})$. If $r>2$ and $v_{j_k}=v_1$ for some $k$, then $\sigma$ has a chord. The assertion follows from the fact that every maximal horizontal interval intersects with the vertical interval $V_1$. In particular, the edge $\{h_{i_{k-1}},v_{j_k}\}$ or $\{h_{i_{k+2}},v_{j_k}\}$ forms a chord in the cycle $\sigma$. 
\end{remark}

\begin{remark} \label{remark.corner}
    Let $\mathcal{C}$ be an arbitrary collection of corner minors. Denote by $H_1$ and $V_1$ the maximal horizontal and vertical intervals that contain the vertex $x_{11}$, respectively. Let $\sigma: h_{i_1},v_{j_1},h_{i_2},v_{j_2},\ldots,h_{i_r},v_{i_r}$ be a cycle in $G(\mathcal{C})$. If $r>2$ and $v_{j_k}=v_1$ or $h_{j_k}=h_1$ for some $k$, then $\sigma$ has a chord. Since each maximal horizontal interval intersects with the vertical interval $V_1$ and each maximal vertical interval intersects with the horizontal interval $H_1$.
\end{remark}

\begin{proposition} \label{prop.1}
    Let $\mathcal{C}$ be an arbitrary set of corner-interval minors. Then, for every vertical interval $\{x_{ij},x_{lj}\}$ in $\mcC$, with $j\neq 1$, one has $x_{i1}x_{lj}-x_{l1}x_{ij} \in J_{\mcC}$. 
\end{proposition}
\begin{proof}
    Let $\{x_{ij},x_{lj}\}$ be a vertical interval in $\mcC$. If $\{x_{ij},x_{lj}\} \in E(\mcC)$, then it follows that $x_{i1}x_{lj}-x_{l1}x_{ij} \in I(\mcC) \subset J_{\mcC}$. Suppose $\{x_{ij},x_{lj}\} \notin E(\mcC)$, then by the definition of vertical interval there exists a sequence of vertical edges $x_{ij}=x_{i_1j},x_{i_2j},\ldots,x_{i_kj}=x_{lj}$ with $\{x_{i_rj},x_{i_{r+1}j}\} \in E(\mcC)$ for $r=1,\ldots,k-1$. This implies that the minors $x_{i_r1}x_{i_{r+1}j}-x_{i_{r+1}1}x_{i_rj} \in I(\mcC)$, for all $r$. Then it follows that the sequence of vertices $h_{i_r},v_1,h_{i_{r+1}},v_j$ of $G(\mcC)$ forms a cycle, where $H_{i_{r}}\cap V_{1} =x_{i_r1}, H_{i_{r+1}}\cap V_{1} =x_{i_{r+1}1}, H_{i_{r}}\cap V_{j}=x_{i_rj}, H_{i_{r+1}}\cap V_{j} =x_{i_{r+1}j}$ are the associated vertical and horizontal intervals (misuse of notation) of the vertices of $\mcC$, for all $r$. Thus, one has the edges $\{h_{i_{1}},v_1\}$ and $\{h_{i_{k}},v_1\}$ belongs to $G(\mcC)$. Therefore, we have that the sequence of vertices $h_{i_1},v_1,h_{i_{k}},v_j$ forms a cycle in $G(\mcC)$, as desired.
\end{proof}

In the following lemma, we study the minimal prime ideals of $I(\mcC)$ that do not contain any variables.

\begin{lemma} \label{lemma.primenovar}
    Let $\mathcal{C}$ be an arbitrary collection of corner-interval minors. Then the ideal $J_{\mcC}$ is a minimal prime of $I(\mathcal{C})$.
\end{lemma}
\begin{proof}
   Let $x=\prod x_{ij}$. We claim that $I(\mathcal{C}):x^{\infty}=J_{\mcC}$. Since $I(\mathcal{C}) \subset J_{\mcC}$ and $J_{\mcC}$ is a prime ideal, it follows that $I(\mathcal{C}):x^{\infty} \subseteq J_{\mcC}$. To show the other side containment, let $f_\sigma \in J_{\mcC}$, where $\sigma$ an arbitrary cycle in $G(\mcC)$. We will claim that $f_\sigma \in I(\mathcal{C}):x^{\infty}$. 

    Suppose $\sigma$ is a cycle of length $4$ in $G(\mcC)$, and let $f_\sigma=x_{ij}x_{lk}-x_{ik}x_{lj}$ be the corresponding binomial. Then $\{x_{ij},x_{lj}\}$ and $\{x_{ik},x_{lk}\}$ are the two vertical intervals in $\mcC$ corresponding to the cycle $\sigma$. Suppose either $j=1$ or $k=1$. Assume $j=1$. Then, since $\{x_{ik},x_{lk}\}$ is a vertical interval of $\mcC$ with $k\neq 1$, from Proposition \ref{prop.1} it follows that $f_{\sigma} \in J_{\mcC}$, which implies the assertion. If $j\neq 1$ and $k\neq 1$, then from Proposition \ref{prop.1} one has the elements $f=x_{i1}x_{lj}-x_{l1}x_{ij}$ and $g=x_{i1}x_{lk}-x_{l1}x_{ik}$ belongs to $J_\mcC$. Since $x_{l1}f_{\sigma}=x_{lk}f-x_{lj}g$, it follows that $f_{\sigma} \in I({\mcC}):x^{\infty}$. 

    Suppose $\sigma: h_{i_1},v_{j_1},h_{i_2},v_{j_2},\ldots,h_{i_r},v_{i_r}$ is a cycle of length $2r$ in $G(\mcC)$ with $r\geq 3$, and let $f_{\sigma}=x_{a_{i_1},b_{j_1}}\cdots x_{a_{i_r},b_{j_r}} - x_{a_{i_2},b_{j_1}}\cdots x_{a_{i_1},b_{j_r}}$ be the corresponding binomial. Assume that $x_{a_{i_k}b_{j_k}} \neq x_{a_{i_k}1}$ for all $k$; otherwise, the cycle $\sigma$ contains a chord by Remark \ref{remark.1}. Since $\{x_{a_{i_k}b_{j_k}},x_{a_{i_{k+1}}b_{j_k}}\}$ is a vertical interval in $\mcC$ for each $k$ (this vertical interval associated with the edges $\{v_{i_k},h_{i_k}\}$ and $\{v_{i_{k+1}},h_{i_k}\}$ of $\sigma$), it follows from Proposition \ref{prop.1} that $\mu_k=x_{a_{i_k}1}x_{a_{i_{k+1}}b_{j_k}}-x_{a_{i_{k+1}}1}x_{a_{i_k}b_{j_k}} \in J_{\mcC}$, where $k=1,\ldots,r$ and $i_{r+1}=i_1$. 

    First, we claim that the element $\lambda_{\ell}= x_{a_{i_{1}}1}x_{a_{i_2}b_{j_1}}\cdots x_{a_{i_\ell}b_{j_{\ell-1}}} - x_{a_{i_{\ell}}1}x_{a_{i_1}b_{j_1}}\cdots x_{a_{i_{\ell-1}}b_{j_{\ell-1}}} \in J_{\mcC}$, for $\ell = 2,\ldots,r$. The claim is proved by induction on $\ell$. For $\ell =2$, this is the case by $\mu_1$. Suppose now that $\ell >2$. By applying induction hypothesis, we have that $\lambda_{r-1} =x_{a_{i_{1}}1}x_{a_{i_2}b_{j_1}}\cdots x_{a_{i_{r-1}}b_{j_{r-2}}} - x_{a_{i_{r-1}}1}x_{a_{i_1}b_{j_1}}\cdots x_{a_{i_{r-2}}b_{j_{r-2}}}$ belongs to $J_{\mcC}$. Since $\lambda_r= x_{a_{i_{r}}b_{j_{r-1}}}\lambda_{r-1}-x_{a_{i_1}b_{j_1}}\cdots x_{a_{i_{r-2}}b_{j_{r-2}}}\mu_{r-1}$, it follows that $\lambda_r \in J_{\mcC}$. Then, one may write $x_{a_{i_{1}}}f_\sigma=x_{a_{i_{1}}b_{j_{r}}}\lambda_r - x_{a_{i_1}b_{j_1}}\cdots x_{a_{i_{r-1}}b_{j_{r-1}}}\mu_r$, thus it follows that $f_\sigma \in I(\mathcal{C}):x^{\infty}$. Hence, we prove the claim.

   Now, if $P$ is a minimal prime ideal of $I(\mcC)$ containing no variable, such a prime exists since $J_\mcC$ is a prime ideal, then $ J_{\mcC}=I(\mathcal{C}):x^{\infty} \subset P:x^{\infty}=P$, hence $J_{\mcC}$ is a minimal prime of $I(\mathcal{C})$.
\end{proof} 



\begin{corollary}
    Let $\mathcal{C}$ be an arbitrary corner-interval minors. Then $I(\mcC)$ is prime if and only if $I(\mcC)=J_\mcC$.
\end{corollary}



\vspace{2mm}

Next, to study the minimal prime ideals of $I(\mcC)$ containing variables, we first present the following definitions.

\vspace{2mm}

\begin{definition}
    Let $\mcC=\delta_1,\delta_2,\ldots,\delta_r$ be a set of corner minors. A subset $W\subset V(\mcC)$ is called admissible if for each index $i$ either $W\cap V(\delta_i)=\emptyset$ or $W\cap V(\delta_i)\neq \emptyset$ contains an edge of $\delta_i$. 
\end{definition}


\begin{definition} \label{def.pw}
    Let  $W\subset V(\mcC)$ be an admissible set. We define an ideal $P_W(\mcC)$ as follows:
    $$P_W(\mcC)=(x_{ij}\mid x_{ij}\in W) + J_{\mcC'} \subset S,$$
    where $\mcC'=\{\delta \in \mcC \mid V(\delta)\cap W= \emptyset\}$.
\end{definition}

Notice that for an admissible set $W$ of $\mcC$, the associated ideal satisfies $P_W(\mcC)=W+P_\emptyset(\mcC')$, where $\mcC'=\{\delta \in \mcC \mid V(\delta)\cap W= \emptyset\}$.

\begin{example}
    Let $\mcC$ be the corner-interval minors as shown in Figure \ref{fig.maxC}. Then the admissible sets of $\mcC$ are the following:
    $$\emptyset,\{x_{12},x_{22}\},\{x_{32},x_{42}\},\{x_{23},x_{33}\},\{x_{14},x_{34}\},\{x_{41},x_{42}\},\{x_{11},x_{12},x_{14}\},\ldots,V(\mcC).$$ 
    For instance, if $W=\{x_{12},x_{22}\}$ then 
    \begin{equation*}
        \begin{split}
            P_{W}(\mcC)&=(x_{12},x_{22})+J_{\mcC'}, \text{ where } \mcC'=\{\delta \in \mcC \mid V(\delta)\cap W= \emptyset\},\\
            &=(x_{12},x_{22},x_{23}x_{31}-x_{21}x_{33},x_{14}x_{31}-x_{11}x_{34},x_{32}x_{41}-x_{31}x_{42}).
        \end{split}
    \end{equation*}
\end{example}

\begin{remark} \label{remak.prime}
    Let $\mathcal{C}$ be an arbitrary corner-interval minors. Then the ideal $P_W(\mcC)$ is a prime ideal, for every admissible set $W$ of $\mcC$. Since the ideals $J_{\mcC'}$ and $W$ are prime and generated in different set of variables. 
\end{remark}

The subsequent results highlights the significance of admissible sets in the study of the minimal prime ideals of $I(\mcC)$.

\begin{lemma} \label{lemma.admissible}
    Let $\mathcal{C}$ be an arbitrary set of corner-interval minors. Let $P$ be a prime ideal containing $I(\mcC)$, and let $W=\{x_{ij} \mid x_{ij}\in P\}$. Then $W$ is an admissible set.
\end{lemma}
\begin{proof}
    Let $f_{\delta}=x_{ij}x_{kl}-x_{kj}x_{il}$ be an element of $I(\mcC)$. Suppose that $W \cap V(\delta) \neq \emptyset$. Say $x_{ij} \in W$. Then $x_{kj}x_{il} \in P$. Since $P$ is a prime, it follows that either $x_{kj} \in P$ or $x_{il} \in P$. This implies that $W$ contains the edge either $\{x_{ij},x_{kj}\}$ or $\{x_{ij},x_{il}\}$ of $\delta$.
\end{proof}

\begin{theorem} \label{thm.prime}
    Let $\mathcal{C}$ be an arbitrary set of corner-interval minors and $P$ be a minimal prime ideal of $I(\mcC)$. Then there exists an admissible set $W\subset V(\mcC)$ such that $P=P_W(\mcC)$.
\end{theorem}
\begin{proof}
    Let $P$ be a minimal prime of $I(\mcC)$. From Lemma \ref{lemma.admissible} it follows that there exists a set $W$ such that $(W,I(\mcC)) \subset P$. From the definition of $W$, one has $(W,I(\mcC))=(W,I(\mcC'))$, where $\mcC'=\{\delta \in \mcC \mid V(\delta)\cap W = \emptyset\}$. From Remark \ref{remak.prime} it follows that the ideal $(W,J_{\mcC'})=P_W(\mcC)$ is a prime ideal containing $(W,I(\mcC'))$. Thus, it suffices to prove that $(W,J_{\mcC'}) \subset P$. Since $\mcC'$ is a corner-interval minors and $P$ modulo $W$ is a minimal prime ideal containing $I(\mcC')$, it follows from Lemma \ref{lemma.primenovar} that $J_{\mcC'} \subset P \mod W$, as desired.
\end{proof}

\begin{lemma} \label{lemma.primecontainment}
    Let $\mathcal{C}$ be an arbitrary corner-interval minors. Let $W$ and $V$ be two admissible sets of $\mcC$, and let $P_W(\mcC)=(W,J_{\mcC'})$ and $P_V(\mcC)=(V,J_{\mcC''})$ be the corresponding prime ideals, where $\mcC'=\{\delta \in \mcC \mid V(\delta)\cap W= \emptyset\}$ and $\mcC''=\{\delta \in \mcC \mid V(\delta)\cap V= \emptyset\}$ (see Definition \ref{def.pw}). Then the following conditions are equivalent:
    \begin{enumerate}
        \item[(a)] $P_W(\mcC) \subset P_V(\mcC)$.
        \item[(b)] $W \subset V$ and for all elements $f_{\sigma} \in J_{\mcC'}\setminus J_{\mcC''}$ one has that the vertices $x_{a_{i_k},b_{j_k}}$ and $x_{a_{i_{l+1}},b_{j_l}}$ belongs to $V$ for some $k,l$, where $\sigma: h_{i_1},v_{j_1},h_{i_2},v_{j_2},\ldots,h_{i_r},v_{i_r}$ a cycle in $G(\mathcal{C'})$, $r\geq 2$ and $i_{r+1}=i_{1}$.
    \end{enumerate}
\end{lemma}
\begin{proof}
    $(a)\implies (b)$. Let $x_{ij} \in W$. Since $x_{ij} \in P_W(\mcC) \subset P_V(\mcC)$, it follows that $x_{ij} \in V$. Therefore, $W \subset V$.  Let $f_{\sigma} \in J_{\mcC'}\setminus J_{\mcC''}$, where $\sigma$ a cycle in $G(\mcC')$, be an element of $J_{\mcC'}$. The inclusion $(a)$ implies that for all $f_{\sigma} \in J_{\mcC'}$ we have $f_{\sigma} \in (V,J_{\mcC''})$. Suppose $x_{a_{i_k},b_{j_k}}$ and $x_{a_{i_{k+1}},b_{j_k}}$ does not belongs to $V$ for all $k=1,\ldots,r$, where $i_{r+1}=i_{1}$. Then $f_{\sigma} \in J_{\mcC''}$. Since $\sigma$ a cycle, it follows that  $f_{\sigma}$ is primitive. Therefore, $f_{\sigma} \in J_{\mcC''}$, which is a contradiction to the hypothesis. This implies that there exists some $k$ such that either $x_{a_{i_k},b_{j_k}}$ or $x_{a_{i_{k+1}},b_{j_k}}$ belongs to $V$. Without loss of generality, we assume that $x_{a_{i_k},b_{j_k}} \in V$. Then it follows that $x_{a_{i_2},b_{j_1}}\cdots x_{a_{i_1},b_{j_r}} \in P_V(\mcC)$, since $f_{\sigma} \in P_V(\mcC)$. Since $P_V(\mcC)$ is a prime ideal, one can conclude that 
    $x_{a_{i_{l+1}},b_{j_l}} \in V$ for some $l$.


    $(b)\implies (a)$. Suppose for all $f_{\sigma} \in J_{\mcC'}\setminus J_{\mcC''}$ we have the vertices $x_{a_{i_k},b_{j_k}}$ and $x_{a_{i_{l+1}},b_{j_l}}$ belongs to $V$ for some $k,l$. Then it follows that $f_{\sigma} \in V$. Thus, combined with the inclusion $W \subset V$, it follows that $P_W(\mcC) \subset P_V(\mcC)$.
\end{proof}

We are now in a position to present the main theorem of this section.

\begin{theorem} \label{thm.minimal}
    Let $\mathcal{C}$ be an arbitrary corner-interval minors. Let $W$ and $V$ be two admissible sets of $\mcC$, and let $P_W(\mcC)=(W,J_{\mcC'})$ and $P_V(\mcC)=(V,J_{\mcC''})$ be the corresponding prime ideals. Then $P_V(\mcC)$ is a minimal prime for $I(\mcC)$ if and only if for all admissible subsets $W \subset V$, there exists $f_{\sigma} \in J_{\mcC'}\setminus J_{\mcC''}$ such that the vertices $x_{a_{i_k},b_{j_k}}$ or $x_{a_{i_{l+1}},b_{j_l}}$ does not belongs to $V$, for all $1 \leq k,l \leq r$, where $\sigma: h_{i_1},v_{j_1},h_{i_2},v_{j_2},\ldots,h_{i_r},v_{i_r}$ a cycle in $G(\mathcal{C'})$, $r\geq 2$ and $i_{r+1}=i_1$.
\end{theorem}
\begin{proof}
    It follows from Theorem \ref{thm.prime} and Lemma \ref{lemma.primecontainment}. 
\end{proof}


\section{Corner minors} \label{sec.cor}

In this section, we focus on binomial ideals generated by corner minors, with the objective of characterizing their radicality. As a first step, we examine the structure of their minimal prime ideals below.

\begin{lemma} \label{lemma.w11}
    Let $\mcC$ be an arbitrary corner minors of $M$. Let $W$ be an admissible set of $\mcC$ such that $P_W(\mcC)$ is a minimal prime of $I(\mcC)$. If the admissible set $W \neq \emptyset$, then $x_{11} \in W$. In particular, if $W \neq \emptyset$ then the minimal prime $P_W(\mcC)$ is generated by variables.
\end{lemma}

\begin{proof}
    Let $W \neq \emptyset$ and $P_W(\mcC)$ a minimal prime of $I(\mcC)$. Suppose $x_{11} \notin W$ and $x_{ij} \in W$ with $i>1$ and $j>1$. Since $x_{11}x_{ij}-x_{1j}x_{i1} \subset I(\mcC) \subset P_W(\mcC)$, and since $x_{ij} \in P_W(\mcC)$ it follows that $x_{1j}x_{i1} \in P_W(\mcC)$. Since $P_W(\mcC)$ is prime, either $x_{i1} \in P_W(\mcC)$ or $x_{1j} \in P_W(\mcC)$.

    Without loss of generality, assume that $x_{i1} \in W \subset V(\mcC)$, for some fixed $i \neq 1$. Since $x_{11}x_{ij}-x_{1j}x_{i1} \subset I(\mcC) \subset P_W(\mcC)$, and since $x_{i1} \in P_W(\mcC)$, it follows that $x_{11}x_{ij} \in P_W(\mcC)$. Thus, since $P_W(\mcC)$ is prime and $x_{11}\notin P_W(\mcC)$, one has $x_{ij} \in W$. Using a similar argument, we conclude that for the fixed $i$, all $x_{ij} \in V(\mcC)$ satisfy $x_{ij} \in W$. Let $U=\{x_{kl} \mid k=i, l \in [n] \text{ and }  x_{kl} \in V(\mcC)\}$. Note that $U$ is a maximal horizontal interval of $\mcC$ and $U \subseteq W$. Let $\mcC'=\{\delta \in \mcC \mid V(\delta)\cap W= \emptyset\})$ and $\mcC''=\{\delta \in \mcC \mid V(\delta)\cap W\setminus U= \emptyset\})$. Consider the cycle $\sigma: h_{i_1},v_{j_1},h_{i_2},v_{j_2},\ldots,h_{i_r},v_{i_r}$ in $G(\mcC'')$. We will show that $f_\sigma \in P_W(\mcC)$. 

    Case I. If $h_{i_k} \neq u$ for all $k$, where $u$ is a vertex of $G(\mcC)$ associated with the maximal horizontal interval $U$, then one has $\sigma \in G(\mcC')$. 

    Case II. If $h_{i_k} = u$ for some $k$, then the vertices $x_{a_{i_k}b_{j_k}}$ and $x_{a_{i_{k}}b_{j_{k+1}}}$ belongs to $W$, where $j_{r+1}=j_{1}$. Because the vertices $x_{a_{i_k}b_{j_k}}$ and $x_{a_{i_{k}}b_{j_{k+1}}}$ belongs to $U$.

    Then, from Lemma \ref{lemma.primecontainment} it follows that $P_{W\setminus U}(\mcC) \subset  P_W(\mcC)$. This contradicts the minimality of the prime ideal $P_W(\mcC)$. 

    The second part of the assertion follows from Lemma \ref{lemma.admissible}, since for every element $x_{11}x_{ij}-x_{1j}x_{i1}$ in $I(\mcC)$, either $x_{11},x_{i1} \in W$ or $x_{11},x_{1j} \in W$. Therefore, there are no cycles in $G(\mcC')$, where $\mcC'=\{\delta \in \mcC \mid V(\delta)\cap W= \emptyset\} = \emptyset$, which implies that $P_W(\mcC)$ is generated by variables. This completes the proof.
\end{proof}

\begin{notation}
    Let $\mcC$ be an arbitrary collection of corner-minors of the matrix $M$. We denote by $\mathcal{W}$ the set of all admissible subsets $W\subset V(\mcC)$ such that the ideal $P_W(\mcC)$ is a minimal prime ideal of $I(\mcC)$. 
\end{notation}

\begin{corollary} \label{cor.intersW}
    Let $\mcC$ be an arbitrary collection of corner minors of $M$. Let $W$ be an admissible set of $\mcC$ such that $P_W(\mcC)$ is a minimal prime of $I(\mcC)$. Then
    \begin{equation*}
        \bigcap_{W\in \mathcal{W} \setminus \emptyset} P_W(\mcC) = (x_{11})+(\ini(f_\delta) \mid \delta \in \mcC).
    \end{equation*}
\end{corollary}


\begin{lemma} \label{lemma.x11f}
    Let $\mcC$ be an arbitrary set of corner minors of $M$, and let $\sigma$ be a cycle in the associated graph $G(\mcC)$. Denote by $H_1$ and $V_1$ the maximal horizontal and vertical intervals of $\mcC$ that contain the vertex $x_{11}$, respectively. Then $x_{11}f_\sigma \in I(C)$ if and only if $\sigma \cap v_1 \neq \emptyset$ or $\sigma \cap h_1 \neq \emptyset$.
\end{lemma}
\begin{proof}
Let $\sigma: h_{i_1},v_{j_1},h_{i_2},\ldots, h_{i_r},v_{j_r}$ be a cycle in $G(\mcC)$, where $r\geq 2$.  Suppose $\sigma \cap v_1 \neq \emptyset$ or $\sigma \cap h_1 \neq \emptyset$. Then from Remark \ref{remark.corner} it follows that $r=2$. Without loss of generality, assume that $\sigma \cap v_1 \neq \emptyset$ and $v_{j_1}=v_1$. Let $\sigma: h_{i_1},v_{1},h_{i_2},v_{j_2}$ be a cycle in $G(\mcC)$. Since $x_{a_{i_1}b_{j_2}}$ and $x_{a_{i_2}b_{j_2}}$ belongs to $V(\mcC)$, it follows that $\sigma_1: h_{1},v_{1},h_{i_2},v_{j_2}$ and $\sigma_1: h_{1},v_{1},h_{i_1},v_{j_2}$ are cycles in $G(\mcC)$ (in particular, $f_{\sigma_1}$ and $f_{\sigma_2}$ belongs to $I(\mcC)$). Then $x_{a_1,b_1}f_\sigma=x_{a_{i_1},b_1}f_{\sigma_1}-x_{a_{i_2},b_1}f_{\sigma_2}$, where $a_1=1$ and $b_1 =1$. Therefore, we have $x_{11}f_\sigma \in I(C)$.

Conversely, suppose that $\sigma \cap v_1 = \emptyset$ or $\sigma \cap h_1 = \emptyset$ and $x_{11}f_{\sigma} \in I(\mcC)$. Remark \ref{rem.bwalk} implies that there exits a $\mathcal{B}_\mcC$-walk from $\alpha=x_{11}x_{a_{i_1},b_{j_1}}\cdots x_{a_{i_r},b_{j_r}}$ to $\beta = x_{11}x_{a_{i_1},b_{j_r}}x_{a_{i_2},b_{j_1}} \cdots x_{a_{i_{r}},b_{j_{r-1}}}$. Since $x_{11}$ is the only variable in $\alpha$ which intersects with $H_1$ and $V_1$, it follows that the only possible $\mathcal{B}_\mcC$-walk from $\alpha$ is the following.
\begin{equation*}
    \alpha \rightarrow \alpha_k = x_{a_{i_k},1}x_{1,b_{j_k}}x_{a_{i_1},b_{j_1}}\cdots x_{a_{i_{k-1}},b_{j_{k-1}}}x_{a_{i_{k+1}},b_{j_{k+1}}}\cdots x_{a_{i_r},b_{j_r}}
\end{equation*}
for some $1\leq k \leq r$. Since $x_{a_{i_k},1}$ is the only variable in $\alpha_k$ which intersects with $V_1$ and $x_{1,b_{j_k}}$ is the only variable in $\alpha_k$ which intersects with $H_1$, it follows that the only possible  $\mathcal{B}_\mcC$-walk from $\alpha_k$ is the walk $\alpha_k \rightarrow \alpha$. Therefore, every $\mathcal{B}_\mcC$-walk from $\alpha$ returns to $\alpha$ via $\alpha_k$, forming a loops of the form
\begin{equation*}
    \alpha \rightarrow \alpha_k \rightarrow \alpha
\end{equation*}
for all $1\leq k \leq r$. Note that $\alpha_k \neq \beta$ for all $k$. This contradicts the existence of a $\mathcal{B}_\mcC$-walk from $\alpha$ to $\beta$. Hence, the theorem is proved.
\end{proof}

Since the ideal $P_W(\mcC)$ is generated by variables when $W\neq \emptyset$, we can explicitly compute their intersection in the following theorem. 

\begin{theorem} \label{lemma.rad}
    Let $\mcC$ be an arbitrary collection of corner minors of $M$.  Let $W$ be an admissible set of $\mcC$ such that $P_W(\mcC)$ is a minimal prime of $I(\mcC)$. Then one has
    \begin{equation} \label{eq.pw}
        \bigcap_{W \in \mathcal{W}} P_W(\mcC)=I(\mcC)+(x_{11}f_\sigma \mid \sigma \text{ a cycle in } G(\mcC) \text{ such that } \sigma \cap v_1 = \emptyset \text{ and } \sigma \cap h_1 = \emptyset),
    \end{equation} where $H_1$ and $V_1$ are maximal horizontal and maximal vertical intervals of $\mcC$ containing the vertex $x_{11}$, respectively.
\end{theorem}
\begin{proof}
    It is easy to see that $I(\mcC) \subset \bigcap_{W \in \mathcal{W}} P_W(\mcC)$, since $P_W(\mcC)$'s are minimal prime ideals of $I(\mcC)$. From Lemma \ref{lemma.w11} it follows that $x_{11} \in \bigcap_{W\in \mathcal{W} \setminus \emptyset} P_W(\mcC)$. This implies that $x_{11}f_\sigma \in \bigcap_{W\in \mathcal{W} \setminus \emptyset} P_W(\mcC)$. Since $\sigma$ is a cycle in $G(\mcC)$, it follows that $f_\sigma \in P_\emptyset(\mcC)$. Thus, it follows that $x_{11}f_\sigma \in P_\emptyset(\mcC)$. Therefore, the right hand side of Equation (\ref{eq.pw}) contained in the left hand side. For inclusion on the other side, consider $g \in  \bigcap_{W \in \mathcal{W}} P_W(\mcC)$. Since $g \in P_\emptyset(\mcC)$ and $g \in \bigcap_{W\in \mathcal{W} \setminus \emptyset}P_W(\mcC)$, then using Corollary \ref{cor.intersW}, we can write $g$ as 
    $$g=\sum  x_{11}a_\sigma f_{\sigma} + \sum x_{i1}x_{1j}b_{ij\sigma'}f_{\sigma'},$$
    where $x_{i1}x_{1j}=\ini_<(f_\delta)$ for some $\delta \in \mcC, a_\sigma, b_{ij\sigma'} \in S$, and $\sigma,\sigma'$ are cycles in $G(\mcC)$. Then using Lemma \ref{lemma.x11f} we can rewrite $g$ as 
    $$g=\sum a_\delta f_\delta +\sum  x_{11}a_\sigma'' f_{\sigma''} + \sum x_{i1}x_{1j}b_{ij\sigma'}f_{\sigma'},$$
    where $a_\delta,a_\sigma'' \in S$, $\delta \in \mcC$, and $\sigma''$ is a cycle in $G(\mcC)$ such that $\sigma'' \cap v_1 = \emptyset$  and  $\sigma'' \cap h_1 = \emptyset$. Since $x_{i1}x_{1j}f_{\sigma'}=x_{ij}x_{11}f_{\sigma'}-f_{\sigma'}(x_{11}x_{ij}-x_{i1}x_{1j})$, it follows that $\sum x_{i1}x_{1j}b_{ij\sigma'}f_{\sigma'} \in I(\mcC) +  (x_{11} f_{\sigma''} \mid \sigma''$ is a cycle in $G(\mcC)$ such that $\sigma'' \cap v_1 = \emptyset$  and  $\sigma'' \cap h_1 = \emptyset)$. Thus, the containment follows. Hence, the equality.
\end{proof}

As a consequence, we provide a characterization of the radicality and the primary decomposition of the ideal generated by an arbitrary set of $2$-corner minors of $M$, as below.

\begin{corollary} \label{thm.rad}
    Let $\mcC$ be an arbitrary corner minors of $M$. Denote by $H_1$ and $V_1$ the maximal horizontal and vertical intervals that contain the vertex $x_{11}$, respectively. Then $I(\mcC)$ is radical if and only if $G(\mcC)$ does not have a cycle in the induced subgraph $G(\mcC)\setminus v_1,h_1$. Moreover, if $G(\mcC)$ does not have a cycle in the induced subgraph $G(\mcC)\setminus v_1,h_1$ then $ \bigcap_{W \in \mathcal{W}}P_W(\mcC)$ is the primary decomposition of $I(\mcC)$. 
\end{corollary} 



\begin{proposition} \label{prop.decomp}
        Let $\mcC$ be an arbitrary corner minors of $M$. Then one has 
    \begin{equation} \label{eq.thm}
       I(\mcC)= \bigcap_{W \in \mathcal{W}} P_W(\mcC) \cap \bigcap_{W\in \mathcal{W} \setminus \emptyset}I(\mcC)+(P_W(\mcC))^2.
    \end{equation}
\end{proposition}

\begin{proof}
    It is easy to see that $I(\mcC)$ is contained  the right hand side of Equation (\ref{eq.thm}), since $P_W(\mcC)$'s are minimal primes of $I(\mcC)$. For other containment, first, we claim that
    \begin{equation} \label{eq.interx11}
        \bigcap_{W\in \mathcal{W} \setminus \emptyset}I(\mcC)+(P_W(\mcC))^2= I(\mcC) + (x_{11})^2.
    \end{equation}
    From Lemma \ref{lemma.w11} it follows that $x_{11} \in \bigcap_{W\in \mathcal{W} \setminus \emptyset} P_W(\mcC)$. Thus it is clear that $I(\mcC) + (x_{11})^2 \subseteq \bigcap_{W\in \mathcal{W} \setminus \emptyset}I(\mcC)+(P_W(\mcC))^2$. To establish the other inclusion, we take modulo $I(\mcC)$ on both side of Equation (\ref{eq.interx11}). Then show that 
    $$\bigcap_{W\in \mathcal{W} \setminus \emptyset}I(\mcC)+(P_W(\mcC))^2 \mod I(\mcC) \subset \bigcap_{W\in \mathcal{W} \setminus \emptyset}(P_W(\mcC))^2 \mod I(\mcC)\subset (x_{11}^2) \mod I(\mcC).$$
    Consider a element $g \in \bigcap_{W\in \mathcal{W} \setminus \emptyset}(P_W(\mcC))^2$. Since $P_W(\mcC)$'s are generated by variables, see for instance Lemma \ref{lemma.primenovar}, by using Corollary \ref{cor.intersW} we can write $g$ as 
    $$g= ax_{11}^2 +\sum b_\delta x_{11}\ini_<(f_\delta)+ \sum c_{\delta \delta'}\ini_<(f_\delta)\ini_<(f_\delta'),$$
    where $a, b_\delta, c_{\delta \delta'} \in S$, and $\delta, \delta' \in \mcC$. Since $x_{11}\ini_<(f_\delta)=x_{11}f_{\delta} \mod I(\mcC) \in (x_{11}^2) \mod I(\mcC)$ and $\ini_<(f_\delta)\ini_<(f_{\delta'})=f_{\delta}f_{\delta'}-(f_{\delta'}-\ini_<(f_{\delta'}))f_\delta-(f_\delta-\ini_<(f_\delta))f_{\delta'} \mod I(\mcC) \in (x_{11}^2) \mod I(\mcC)$, it follows that $g \in (x_{11}^2) \mod I(\mcC)$, as desired. Now, by using Equations (\ref{eq.pw}) and (\ref{eq.interx11}) for the inclusion it is enough to show that 
    $$(I(\mcC)+(x_{11}f_\sigma)) \cap (I(\mcC) + (x_{11})^2) \subseteq I(\mcC),$$
    where $\sigma$ is a cycle in $G(\mcC)$ such that $\sigma \cap v_1 = \emptyset$ and $\sigma \cap h_1 = \emptyset$. By using similar arguments as above, one obtains $(I(\mcC)+(x_{11}f_\sigma)) \cap (I(\mcC) + (x_{11}^2))= I(\mcC)+x_{11}^2(f_\sigma)$. Thus it remains to show that  $x_{11}^2(f_\sigma) \subseteq I(\mcC)$. 


     Let $\sigma: h_{i_1},v_{j_1},h_{i_2},\ldots, h_{i_r},v_{j_r}$ be a cycle in $G(\mcC)\setminus v_1,h_1$, where $r\geq 2$. Observe that for  each $k$ the vertices $x_{a_{i_k},b_{j_k}}$ and $x_{a_{i_k},b_{j_{k+1}}}$, one has $[1,a_{i_k}|1,b_{j_k}]$ and $[1,a_{i_k}|1,b_{j_{k+1}}]$ belongs to $\mcC$. By Remark \ref{rem.bwalk} it suffices to show the existence of a $\mathcal{B}_\mcC$-walk from $x_{11}^2x_{a_{i_1},b_{j_1}}\cdots x_{a_{i_r},b_{j_r}}$ to $x_{11}^2x_{a_{i_1},b_{j_r}}x_{a_{i_2},b_{j_1}}\cdots x_{a_{i_{r}},b_{j_{r-1}}}$. We construct a $\mathcal{B_C}$-walk below:

    \begin{gather*}
        x_{11}^2x_{a_{i_1},b_{j_1}}\cdots x_{a_{i_r},b_{j_r}} 
        \rightarrow 
        x_{11}(x_{1,b_{j_1}}x_{a_{i_1},1})x_{a_{i_2},b_{j_2}}\cdots x_{a_{i_r},b_{j_r}}  
        \rightarrow \\ 
         (x_{1,b_{j_1}}x_{a_{i_1},1})(x_{1,b_{j_r}}x_{a_{i_r},1})x_{a_{i_2},b_{j_2}}\cdots x_{a_{i_{r-1}},b_{j_{r-1}}} \\
        \downarrow (\text{ since } [1,a_{i_1}|1,b_{j_{r}}] \in \mcC)\\
        x_{11}(x_{a_{i_1},b_{j_r}})(x_{1,b_{j_1}})(x_{a_{i_r},1})x_{a_{i_2},b_{j_2}}\cdots x_{a_{i_{r-1}},b_{j_{r-1}}}\\
        \downarrow (\text{ since } [1,a_{i_2}|1,b_{j_{2}}] \in \mcC)\\
        (x_{a_{i_1},b_{j_r}})(x_{1,b_{j_1}})(x_{a_{i_r},1})(x_{1,b_{j_2}}x_{a_{i_2},1})x_{a_{i_3},b_{j_3}}\cdots x_{a_{i_{r-1}},b_{j_{r-1}}}\\
         \downarrow (\text{ since } [1,a_{i_2}|1,b_{j_{1}}] \in \mcC)\\
         x_{11}(x_{a_{i_1},b_{j_r}})(x_{a_{i_2},b_{j_1}})(x_{a_{i_r},1})(x_{1,b_{j_2}})x_{a_{i_3},b_{j_3}}\cdots x_{a_{i_{r-1}},b_{j_{r-1}}} \rightarrow\\
          \vdots  \\
         \rightarrow x_{11}(x_{a_{i_1},b_{j_r}})(x_{a_{i_2},b_{j_1}})\cdots(x_{a_{i_{r-1}},b_{j_{r-2}}})(x_{a_{i_r},1})(x_{1,b_{j_{r-1}}})\\
         \downarrow (\text{ since } [1,a_{i_{r}}|1,b_{j_{r-1}}] \in \mcC)\\
         x_{11}^2(x_{a_{i_1},b_{j_r}})(x_{a_{i_2},b_{j_1}})\cdots(x_{a_{i_{r}},b_{j_{r-1}}}).
    \end{gather*} 
    Hence $x_{11}^2f_\sigma \in I(\mcC)$, as desired.
\end{proof}

In the following corollary, we discuss the connectedness of contingency tables with respect to an arbitrary set of corner moves.

\begin{corollary}
     Let $\mcC$ be an arbitrary set of corner minors of $M$. Let $U=(a_{ij} \mid x_{ij} \in V(\mcC))$ and $V=(b_{ij} \mid x_{ij} \in V(\mcC))$ be two contingency tables. Then $U$ and $V$ are connected via $\mathcal{B}_\mcC$ if  
     \begin{enumerate}
         \item \label{cor1} the inequalities $$\sum_{x_{ij}\in W}a_{ij} \geq 2 \text{ and }\sum_{x_{ij}\in W}b_{ij} \geq 2$$ holds, for all $W\in \mathcal{W}\setminus \emptyset$; and 
         \item \label{cor2} the tables $U$ and $V$ have the same row and column sums such that the non zero entries of $U$ and $V$ corresponds to vertices of a cycle in $G(\mcC)$. 
     \end{enumerate}
\end{corollary}
\begin{proof}
    By Remark \ref{rem.bwalk} $U$ and $V$ are connected with respect to $\mathcal{B_C}$ moves if and only if the binomial $f=\prod_{x_{ij}\in V(\mcC)}x_{ij}^{a_{ij}}-\prod_{x_{ij}\in V(\mcC)}x_{ij}^{b_{ij}}$ belongs to $I(\mcC$. The decomposition of $I(\mcC)$ as in Equation (\ref{eq.thm}) implies that 
    $$I(\mcC) \supseteq P_{\emptyset}(\mcC) \cap \bigcap_{W\in \mathcal{W} \setminus \emptyset}(P_W(\mcC))^2.$$ By using the fact \cite[Lemma 4.6]{S1995} that the minimal generating set of $P_{\emptyset}(\mcC)$ forms a Gr\"obner basis. One can conclude that condition (\ref{cor2}) implies $f \in P_{\emptyset}(\mcC)$. Since $P_W(\mcC)$ is generated by variables when $W \neq \emptyset$, condition (\ref{cor1}) implies that $f \in (P_{W}(\mcC))^2$. Therefore, we have $f \in I(\mcC)$.
\end{proof}




\section{Betti numbers} \label{sec.bet}

In this section, we compute the Hilbert–Poincar\'e polynomial of the generalized binomial edge ideals of star graphs. We then compute the Castelnuovo–Mumford regularity of the ideal generated by binomials corresponding to all corner minors of $M$. Finally, we compare the graded Betti numbers of powers of the ideal generated by binomials associated with arbitrary corner-interval minors of $M$ with those of its subcorner-interval minors. We begin by introducing the notation that will be used throughout this section.


\begin{notation} \label{nota.i_t1}
    Denote by $M_{r,s}:= (x_{ij})_{i=r,\ldots,m \atop j=s,\ldots,n}$ the submatrix of $M$. 
    \begin{itemize}
        \item We denote by $I_{\mcC}:= \{x_{i1}x_{jk}-x_{j1}x_{ik} \mid 1 \leq i<j \leq m, 2 \leq k \leq n\}$ the minimal generating set of all corner-interval minors of $M$.
        \item The set of all $2$-minors of the submatrix $M_{r,s}$ is denoted by $I_{r,s}=\{x_{ij}x_{kl}-x_{il}x_{kj} \mid  r \leq i<k \leq m,  s \leq j<l \leq n\}$, and the ideal generated by $I_{r,s}$ is denoted by $I_2(M_{r,s})$.
    \end{itemize} 
\end{notation}

\begin{remark} \cite[Theorem 2]{R2013}
    \label{rem.gr}
    Let $\mcC$ be the set of all corner-interval minors of $M$. Let $<$ be the reverse lexicographic order on $S$ induced by $x_{11}<\cdots<x_{1n}<x_{21}<\cdots<x_{mn}$. Then the following set of binomials 
    $$\mathcal{G}= I_{\mcC} \cup \bigcup_{r=1}^{m-1} x_{r1}I_{r,2}$$
    is a Gr\"obner basis of $I(\mcC)$.
\end{remark} 

\begin{theorem} \label{thm.hpp}
    Let $\mcC$ be the set of all corner-interval minors of $M$. Then the Hilbert-Poincar\'e polynomial of $S/I(\mcC)$ is 
    \begin{equation*}
        \hp_{S/ I(\mcC)}(z)=\sum_{t=1}^{m-1} \hp_{S/ I_2(M_{t,1})}(z)(z(1-z)^{n(t-1)})+z(1-z)^{(m-1)(n-1)}+(1-z)^{m},
    \end{equation*}
    where $I_2(M_{t,1})$ as defined in Notation \ref{nota.i_t1}.
\end{theorem}
\begin{proof}
     Let $<$ be the monomial order introduced in Remark \ref{rem.gr}. From Remark \ref{rem.gr}, one has $\ini_<(I(\mcC))=\alpha + \sum_{r=1}^{m-1} \beta_r$, where $\alpha= (x_{j1}x_{ik} \mid 1 \leq i<j \leq m, 2 \leq k \leq n)$ and $\beta_r=(x_{r1}x_{il}x_{kj} \mid r \leq i<k \leq m, 2 \leq j<l \leq n)$. Set $x_{01}= 0 \in S$. Consider the following sequence of short exact sequence 
    \begin{equation} \label{eq:inik}
    \begin{split}
        0 \longrightarrow \frac{S}{\ini_<(I(\mcC))+x_{01}+\cdots+x_{t-1,1}:x_{t1}}(-1) &\longrightarrow \frac{S}{\ini_<(I(\mcC))+x_{01}+\cdots+x_{t-1,1}} \\
     &\longrightarrow \frac{S}{\ini_<(I(\mcC))+x_{11}+\cdots+x_{t1}}   \longrightarrow  0,
    \end{split}
    \end{equation}
where $t=1,\ldots,m-1$. Since the Hilbert-Poincar\'e polynomial is additive over short exact sequences, computing the Hilbert-Poincar\'e polynomial of first and third modules in Equation (\ref{eq:inik}) one yields the desired formula.

First, observe that, for $t=2, \ldots, m$ one has 
\begin{equation*}
\begin{split}
    \ini_<(I(\mcC))+x_{11}+\ldots +x_{t-1,1}=&x_{11}+\ldots +x_{t-1,1} + (x_{j1}x_{ik} \mid j\geq t, 1 \leq i < j \leq m, 2 \leq k \leq n) \\
    &+ (x_{r1}x_{il}x_{kj} \mid r \geq t, r \leq i<k \leq m, 2 \leq j<l \leq n).
\end{split}
\end{equation*} Since  $x_{j1}x_{ik},x_{r1}x_{il}x_{kj} \subset (x_{11},\ldots,{x_{t-1,1}})$ for all $j \leq t-1$ and $r \leq t-1$, the above equality follows. Notice that when $t=m$, the ideal $\ini_<I(\mcC)$ corresponds to the edge ideal of a star graph, as described below: $$\ini_<(I(\mcC))+(x_{i1} \mid 1 \leq i \leq m-1)=(x_{i1} \mid 1 \leq i \leq m-1) + (x_{m1}x_{ik} \mid  1 \leq i \leq m-1, 2 \leq k \leq n).$$ 
Then from Remark \ref{rem.starhp} it follows that $\hp_{S/\ini_<(I(\mcC))+(x_{i1} \mid 1 \leq i \leq m-1)} (z)=z(1-z)^{(m-1)(n-1)}+(1-z)^m$. Next, for $t=1, \ldots, m-1$ one has 
    \begin{equation*}
    \begin{split}
    \ini_<(I(\mcC))+x_{01}+\ldots +x_{t-1,1}:x_{t1}=&(x_{i1} \mid 1 \leq i \leq t-1)+ (x_{ik} \mid 1 \leq i < t , 2 \leq k \leq n)\\
    &+(x_{j1}x_{ik} \mid t \leq i < j \leq m, 2 \leq k \leq n)\\
    &+ (x_{il}x_{kj} \mid t \leq i<k \leq m, 2 \leq j<l \leq n) \\
    =& (x_{ik} \mid 1 \leq i \leq t-1 , 1 \leq k \leq n) +\ini_<(I_2(M_{t,1})).
    \end{split}
    \end{equation*}
    Since the minimal generating set $I_{t,1}$ is a Gr\"obner basis of $I_2(M_{t,1})$ (see Remark \ref{rem.Mgb}), the second equality follows. The first equality follows from the fact that $\{u/\gcd(u,x_{t1}) \mid u \in \text{mingens}(I)\}$ is the minimal generating set of $I:x_{t1}$, where $I=\ini_<(I(\mcC))+x_{01}+\ldots +x_{t-1,1}$. Then we have that $\hp_{S/\ini_<(I(\mcC))+x_{01}+\ldots +x_{t-1,1}:x_{t1}} (z)= \hp_{S/ \ini_<(I_2(M_{t,1}))}(z)((1-z)^{n(t-1)})$. Now, by substituting the values into short exact sequence (\ref{eq:inik}) for $t=m-1, \ldots,1$,  we obtain the Hilbert-Poincar\'e series of $\hp_{S/\ini_<(I(\mcC))}(z)$. Since the initial ideals are compatible with Hilbert-poincar\'e polynomial the assertion follows.
\end{proof}

\begin{remark}
    In \cite{QRR2022}, the authors computed the Hilbert–Poincar\'e series of the ideal generated by all $2$-minors of the matrix $M$ (see also \cite{BGS1982}). Therefore, by substituting the Hilbert–Poincar\'e polynomial of $I_2(M_{t,1})$ into Theorem \ref{thm.hpp}, we obtain the Hilbert–Poincar\'e polynomial of the ideal $I(\mcC)$, where $\mcC$ is the set of all corner-interval minors of $M$.
\end{remark}


We denote by $H=\{x_{11},x_{12},\ldots,x_{1n}\}$ the first row and $V=\{x_{11},x_{21},\ldots,x_{m1}\}$ the first column of variables.



\begin{theorem} \label{thm.regc}
    Let $\mcC$ be the set of all corner minors of $M$ and $m,n>2$. Then, one has $\reg(S/I(\mcC))=\min(m,n)$.
\end{theorem}

To complete the proof of Theorem \ref{thm.regc}, we need the following results.

\begin{lemma} \label{lemma.reg,i11}
    Let $I_2(M)$ be the ideal generated by all $2$-minors of $M$ and $m,n>2$ (see, Notation \ref{nota.i_t1}). Then $\reg(S/(I_2(M)\cap H \cap V))=\min(m,n)$.
\end{lemma}
\begin{proof}
    First, we claim that $I_2(M)\cap H \cap V=I(\mcC)+x_{11}I_2(M_{2,2})$, where $\mcC$ is the set of all corner minors of $M$. It is clear that $I(\mcC)+x_{11}I_2(M_{2,2}) \subset I_2(M)\cap H \cap V$. For the other inclusion, we consider $g \in I_2(M)\cap H \cap V$. Let $\delta$ be a $2$-minor of $M$.

    Case I. Suppose $\delta$ does not contain the variables of $H$ and $V$. Since $g \in H \cap V$, we can write $g= \sum x_{s1}(\sum k_\delta f_\delta)= \sum x_{1t}(\sum k_\delta' f_\delta)$, where $k_\delta,k_\delta' \in S$. Thus, $g$ can be written as $g=\sum_{r=1}^ng_r$, such that $g_r$ is divisible by $x_{1r}$. We will show that each $g_r$ belongs to the ideal $I(\mcC)+x_{11}I_2(M_{2,2})$. Fix some $t$, since $x_{1t}$ divides $g_t$ and $\delta$ does not contain the variables of $H$ it follows that some terms of $k_\delta$ are divisible by $x_{1t}$, for all $\delta$. By separating out $x_{1t}$, we rewrite $g=\sum x_{s1}(\sum x_{1t}\ell_\delta f_\delta + F)$, where no term of $F$ divisible by $x_{1t}$. Since $g_t$ is divisible by $x_{1t}$ and no term of $F$ is divisible by $x_{1t}$ implies that $F=0$. Therefore, we have $g_t=\sum x_{s1}x_{1t}\sum \ell_\delta f_\delta$. Now, one can see that, for every fixed $s$ and $f_\delta=x_{il}x_{kj}-x_{ij}x_{kl}$, we have $\ell_\delta x_{s1}x_{1t}f_\delta=\ell_\delta ((x_{s1}x_{1t}-x_{11}x_{st})x_{il}x_{kj}-(x_{s1}x_{1t}-x_{11}x_{st})x_{ij}x_{kl}-x_{st}(x_{11}(x_{il}x_{kj}-x_{ij}x_{kl}))) \in I(\mcC)+x_{11}I_2(M_{2,2})$. Since each element in the sum belongs to $I(\mcC)+x_{11}I_2(M_{2,2})$, it follows that $g_t \in I(\mcC)+x_{11}I_2(M_{2,2})$. Hence $g \in I(\mcC)+x_{11}I_2(M_{2,2})$.

    Case II. Suppose $\delta$ contains the variable $x_{11}$. Then $\delta$ is a corner minor of $M$. Thus, it is clear that edge of $\delta$ contained in $H$ and $V$. Therefore, we have $f_\delta$ belongs to $H \cap V$ and $I(\mcC)$. Hence the containment.

    Case III. Suppose $\delta$ contains the variables of $H$ or $V$. We assume that $\delta$ contains the variables of $H$, as the argument for the other case is analogous.  Then, we can write $g= x_{s1}(\sum k_\delta f_\delta)$, where $s>1$ and $k_\delta \in S$. Then, for each fixed $f_\delta=x_{il}x_{1j}-x_{ij}x_{1l}$, we have $k_\delta x_{s1}(f_\delta) = k_\delta (x_{il}(x_{s1}x_{1j}-x_{11}x_{sj})-x_{ij}(x_{s1}x_{1l}-x_{11}x_{sl})+x_{11}(x_{il}x_{sj}-x_{sl}x_{ij})$. Hence, we have $g\in I(\mcC)+x_{11}I_2(M_{2,2})$. 


   Next, we claim that $I(\mcC)+x_{11}I_2(M_{2,2}) : x_{11}=I_2(M)$. It is clear that $I(\mcC)+x_{11}I_2(M_{2,2}) \subset I_2(M)$. Since $I_2(M)$ is prime and does contain the variable $x_{11}$, it follows that $I(\mcC)+x_{11}I_2(M_{2,2}) : x_{11} \subset I_2(M):x_{11}=I_2(M)$. Then, from \cite[Proposition 3.3.]{K2020} one has $\reg(S/I_2(M))=\min\{m-1,n-1\}$. 

   It is easy to see that $I(\mcC)+x_{11}I_2(M_{2,2}) + x_{11}=x_{11}+(x_{i1}x_{1j} \mid 1<i\leq m, 1<j\leq n)$. Note that the ideal $(x_{i1}x_{1j} \mid 1<i\leq m, 1<j\leq m)$ is the edge ideal of the complete bipartite graph on vertex set $H\setminus x_{11} \sqcup V \setminus x_{11}$. Since it is the edge ideal of a cochordal graph, thus it follows from Remark \ref{rem.froberg} that $\reg(S/I(\mcC)+x_{11}I_2(M_{2,2}) + x_{11})=1$. Consider the following short exact sequence \begin{equation} \label{eq:I:11}
    0 \longrightarrow \frac{S}{I(\mcC)+x_{11}I_2(M_{2,2}):x_{11}}(-1) \longrightarrow \frac{S}{I(\mcC)+x_{11}I_2(M_{2,2})}  \longrightarrow \frac{S}{I(\mcC)+x_{11}I_2(M_{2,2})+x_{11}}   \longrightarrow  0.
    \end{equation}
    Then by applying Remark \ref{rem.Reg} to short exact sequence (\ref{eq:I:11}) we get  $\reg(S/I(\mcC)+x_{11}I_2(M_{2,2}))=\min(m,n)$.
\end{proof}

\begin{remark} \label{rem.reg,i11}
    From \cite[Equation 3.6]{DES1998} it follow that $\ini_<(I(\mcC)+H^2+V^2)=(H+V)^2$ with respect to the term order defined in Remark \ref{rem.gr}. After polarization, the ideal $(H+V)^2$ corresponds to the edge ideal of a graph obtained by attaching a whisker to each vertex of a complete graph on the vertex set $\{H,V\}$. Since it is a cochordal graph, it follows from Remark \ref{rem.froberg} that $\reg(S/\ini_<(I(\mcC)+H^2+V^2))=1$.
\end{remark}

\begin{proof}[Proof of Theorem \ref{thm.regc}]
    Form \cite[Theorem 3.2]{DES1998} it follows that $I(\mcC)=I_2(M_{1,1})\cap H \cap V\cap (I(\mcC)+H^2+V^2)$, where $I_2(M_{1,1})$ as defined in Notation \ref{nota.i_t1}. Consider the following short exact sequence 
    \begin{equation} \label{eq:IJ}
    0 \longrightarrow \frac{S}{I(\mcC)=I\cap J} \longrightarrow \frac{S}{I} \oplus \frac{S}{J}
    \longrightarrow \frac{S}{I+J}   \longrightarrow  0,
    \end{equation}
    where $I=I_2(M_{1,1})\cap H \cap V$ and $J=I(\mcC)+H^2+V^2$. Form Lemma \ref{lemma.reg,i11} and Remark \ref{rem.reg,i11}, it follows that the regularity of the middle module in Equation (\ref{eq:IJ}) is equal to $\min\{m,n\}$. To compute the regularity of the third module in short exact sequence (\ref{eq:IJ}). We first show that $I(\mcC)+x_{11}I_2(M_{2,2})+H^2+V^2:x_{11}=H+V+I_2(M_{2,2})$. It is clear that  $H+V+I_2(M_{2,2}) \subset I(\mcC)+x_{11}I_2(M_{2,2})+H^2+V^2:x_{11}$. For other inclusion, first we establish that the minimal generating set of $I(\mcC)+x_{11}I_2(M_{2,2})+H^2+V^2$ form a Gr\"obner basis with respect to term order defined in Remark \ref{rem.gr}. 
    From Remark \ref{rem.Mgb} it follows that the minimal generating set of $H+V+I_2(M_{2,2})$ form a Gr\"obner basis. Then, using [Proposition 15.12]\cite{E1995} we get that $\ini_<(I(\mcC)+x_{11}I_2(M_{2,2})+H^2+V^2:x_{11})=\ini_<(H+V+I_2(M_{2,2}))$, and thus are equal. Thus, it is reduce to show that $S(f,g)$ reduce to $0$ for any $f,g$ in the minimal generating set of $I(\mcC)+x_{11}I_2(M_{2,2})+H^2+V^2$. It is known that $S(f,g)$ reduce to $0$ if $\ini_<f$ and $\ini_<g$ are coprime or $f$ and $g$ are monomials. In the following we will show the remaining cases:
    \begin{enumerate}
        \item $S(x_{i1}x_{1j}-x_{11}x_{ij},x_{i1}x_{1j'}-x_{11}x_{ij'}) = x_{11}x_{ij'}x_{1j}-x_{11}x_{ij}x_{1j'} \in H^2$, 
        \item $S(x_{i1}x_{1j}-x_{11}x_{ij},x_{i1}x_{j'1}) = x_{11}x_{ij}x_{j'1} \in V^2$,
    \end{enumerate}
    for any $i\in [m]$, and  $j,j' \in [n]$. Other pairs can be treated similarly. Note that the $S$-pair $S(x_{11}(x_{il}x_{kj}-x_{kl}x_{ij}),x_{11}(x_{i'l'}x_{k'j'}-x_{k'l'}x_{i'j'}))$ reduce to $0$, since the minimal generating set $x_{11}I_2(M_{2,2})$ form a Gr\"obner basis (see Remark \ref{rem.Mgb}). Likewise, the $S$-pair $S(x_{i1}x_{1j}-x_{11}x_{ij},x_{11}(x_{i'l'}x_{k'j'}-x_{k'l'}x_{i'j'}))$ reduce to $0$, because the initial terms are coprime, as desired. 


    Then, from \cite[Proposition 3.3]{K2020} it follows that  $\reg(S/(H+V+I_2(M_{2,2})))=\reg(S/(I(\mcC)+x_{11}I_2(M_{2,2})+H^2+V^2):x_{11})=\min\{m-2,n-2\}$.

    Since $I(C)+x_{11}=(H\setminus x_{11})(V\setminus x_{11})$, it is easy to verify that  $I(\mcC)+x_{11}I_2(M_{2,2})+H^2+V^2 + x_{11}=x_{11}+(H\setminus x_{11}+V\setminus x_{11})^2$.     Polarization of  the ideal $(H\setminus x_{11})^2+(V\setminus x_{11})^2$ is the edge ideal of  graph obtained by attaching a whisker to each vertex of a complete graph on vertex set $\{H\setminus \{x_{11}\},V\setminus \{x_{11}\}\}$. Then from Remark \ref{rem.froberg} it follows that  $\reg(S/(x_{11}+(H\setminus x_{11}+V\setminus x_{11})^2))=1$. Applying Remark \ref{rem.Reg} to the following short exact sequence 
    \begin{equation*} 
    \begin{split}
       0 \longrightarrow \frac{S}{I(\mcC)+x_{11}I_2(M_{2,2})+H^2+V^2:x_{11}}(-1) \longrightarrow \frac{S}{I(\mcC)+x_{11}I_2(M_{2,2})+H^2+V^2} \\
    \longrightarrow \frac{S}{I(\mcC)+x_{11}I_2(M_{2,2})+H^2+V^2+x_{11}}   \longrightarrow  0, 
    \end{split}
    \end{equation*}
    yields $\reg(S/I(\mcC)+x_{11}I_2(M_{2,2})+H^2+V^2)=\min\{m-1,n-1\}$. Since we obtain the regularity of the middle and the last modules of Equation (\ref{eq:IJ}), again applying Remark \ref{rem.Reg} to Equation (\ref{eq:IJ}) one yields $\reg(S/I(\mcC))=\min\{m,n\}$, as desired.
\end{proof}



In the following proposition, we obtain a bound for the regularity of powers of the ideal generated by binomials that corresponds to an arbitrary collection of corner-interval minors in terms of its subcorner-interval minors.


\begin{proposition}
    Let $\mcC$ be an arbitrary set of corner-interval minors and let $H_1,\ldots,H_r$ be the maximal vertical interval of $\mcC$. If $\mcC'$ be a subcorner-interval minors obtained by removing $H_k$ from $\mcC$, for some $k$, then 
    $$\beta_{ij}(S/I(\mcC')^t) \leq \beta_{ij}(S/I(\mcC)^t)$$
    for all $i,j \geq 0$ and $t\geq 1$.
\end{proposition}
\begin{proof}
    Let $\mcC'$ be a subcorner-interval minors of $\mcC$ and $S_{\mcC'}=K[x_{ij} \mid x_{ij} \in \mcC']$ be a polynomial ring. First, we claim that $I(\mcC')^t=I(\mcC)^t \cap S_{\mcC'}$, for all $t \geq 1$, where $I(\mcC')$ is the binomial ideal of $\mcC'$ in the ring $S_{\mcC'}$. Since generators of the ideal $I(\mcC')^t$ contained in the ideal $I(\mcC)^t$, it follows that $I(\mcC')^t \subseteq I(\mcC)^t \cap S_{\mcC'}$. For the other inclusion, consider the map $\psi: S \rightarrow S_{\mcC'}$ by setting $\psi(x_{ij})=0$ if $x_{ij} \notin V(\mcC')$ and $\psi(x_{ij})=x_{ij}$ if $x_{ij} \in V(\mcC')$. Let $g=\sum_{\delta_{1},\ldots,\delta_t \in \mcC}a_{\delta_{1},\ldots,\delta_t}f_{\delta_1}\cdots f_{\delta_t}$ be an element in $I(\mcC)$, where $a_{\delta_{1},\ldots,\delta_t} \in S$. Then, we have 
    \begin{equation*}
    \begin{split}
        \psi(g) &=\sum_{\delta_{1},\ldots,\delta_t \in \mcC}\psi(a_{\delta_{1},\ldots,\delta_t})\psi(f_{\delta_1}\cdots f_{\delta_t})\\
        &=\sum_{\delta_{1},\ldots,\delta_t \in \mcC'}\psi(a_{\delta_{1},\ldots,\delta_t})f_{\delta_1}\cdots f_{\delta_t} \in I(\mcC').
    \end{split}
    \end{equation*}
    Therefore, we have  $I(\mcC)\cap S_{\mcC'} \subseteq I(\mcC')$. Then the statement follows from \cite[Corollary 2.5]{OHH2000} that if $S_{\mcC'}/I(\mcC')^t$ is an algebra retract of ${S}/{I(\mcC)^t}$.
      Consider, ${S_{\mcC'}}/{I(\mcC')^t} \xhookrightarrow{i} {S}/{I(\mcC)^t} \xrightarrow{\bar{\psi}} {S_{\mcC'}}/{I(\mcC')^t}$, where $\bar{\psi}$ is an induced by the map $\phi$. Then one can see that $\bar{\psi} \circ i$ is identity on ${S_{\mcC'}}/{I(\mcC')^t}$ as desired.
\end{proof}

\begin{remark}
    The above result also holds when maximal vertical intervals are considered in place of maximal horizontal intervals. In this case, a lower bound can be obtained by applying Theorem \ref{thm.regc} after removing the appropriate intervals.
\end{remark}

