\section{Expansion of the collision term\label{app:ExpCol}}

The collision term contains the small parameter $\hsg$.
Therefore, we will first consider the expansions of the integrand of the collision term with respect to $\hsg$, although $\ve$ and $\hsg$ are related to each other by $\ve=\kappa\hsg$. 
The expansion of $\hf$ with respect to $\ve$ will be treated later.

Before starting the procedure, it should be noted that
the $\vr_s$ and $\nabla\vr_s$ are treated as the same order quantities
in the CE method.
Hence, the method is applicable to the spatial region
away from the boundary.
This implies that we do not have to worry about possible truncations of the integral domain near the boundary. This situation makes the required procedure of expansions straightforward.

Keeping the above observation in mind,
first carry out the following expansion with respect to $\hsg$
%
\begin{subequations}\label{eq:sigma_expansion}
\begin{align}
\hg(\bx,\bx_{\hsg\bm{\alpha}}^\pm)
=&\hg(\bx,\bx)\pm\hsg\alpha_i\frac{\partial \hg(\bx,\bm{y})}{\partial y_i}\big|_{\bm{y}=\bx}+O(\hsg^2) \\
=&\hg^{[0]}(\bx,\bx)+\hsg\Big(\hg^{[1]}(\bx,\bx)\pm\alpha_i\frac{\partial \hg^{[0]}(\bx,\bm{y})}{\partial y_i}\big|_{\bm{y}=\bx}\Big)+O(\hsg^2),\notag\\
%
\hf_*^\prime(\bx_{\hsg\bm{\alpha}}^+)
=&\hf_*^\prime(\bx)+\hsg\alpha_i\frac{\partial \hf_*^\prime(\bm{x})}{\partial x_i}+O(\hsg^2),\\
%
\hf_*(\bx_{\hsg\bm{\alpha}}^-)
=&\hf_*(\bx)-\hsg\alpha_i\frac{\partial \hf_*(\bm{x})}{\partial x_i}+O(\hsg^2),
\end{align}
\end{subequations}
%
where the parameter dependence of the form of $\hg$ itself has been taken into account by the expansion $\hg(\bx,\by)=\hg^{[0]}(\bx,\by)+\hsg\hg^{[1]}(\bx,\by)+\cdots$.
Note that $\hg^{[0]}(\bx,\by)=\lim_{\hsg\to0}\hg(\bx,\by)$ 
and $\hg^{[1]}(\bx,\by)=\lim_{\hsg\to0}\partial\hg(\bx,\by)/\partial\hsg$.
If a new notation $\mG(\bx)\equiv\hg^{[0]}(\bx,\bx)$ is introduced,
\begin{equation}
  \frac{\partial \mG(\bx)}{\partial x_i}
=2\frac{\partial \hg^{[0]}(\bx,\by)}{\partial y_i}\big|_{\by=\bx},
\end{equation}
%
because of the symmetry $\hg^{[0]}(\bx,\by)=\hg^{[0]}(\by,\bx)$.
Then, using these notation and relation, it is readily seen that
%
\begin{multline}
\hg(\bx_{\hsg\bm{\alpha}}^+,\bx)
\hf_*^\prime(\bx_{\hsg\bm{\alpha}}^+) \\
=[\mG(\bx)+\hsg\Big(\hg^{[1]}(\bx,\bx)+\frac12\alpha_i\frac{\partial \mG(\bx)}{\partial x_i}\Big)+O(\hsg^2)]\\
\times [\hf_*^\prime(\bx)+\hsg\alpha_i\frac{\partial \hf_*^\prime(\bm{x})}{\partial x_i}+O(\hsg^2)] \\
=\mG(\bx)\hf_*^\prime(\bx)
 +\hsg\Big[\Big(\hg^{[1]}(\bx,\bx)+\frac12\alpha_i\frac{\partial \mG(\bx)}{\partial x_i}\Big)\hf_*^\prime(\bx) \\
+\mG(\bx)\alpha_i\frac{\partial \hf_*^\prime(\bm{x})}{\partial x_i}
\Big]+O(\hsg^2).
\end{multline}
%
A similar expression can be obtained for $\hg(\bx_{\hsg\bm{\alpha}}^-,\bx)
\hf_*(\bx_{\hsg\bm{\alpha}}^-)$.
Then, the substitution into $\hJ(\hf)$ leads to the expansion \eqref{eq:J_exp1} 
with the form of $\mJ^{[0]}$ and $\mJ^{[1]}$ given by \eqref{eq:mJ0_def} and \eqref{eq:mJ1_def}.

%Finally, substitution of \eqref{eq:f_exp} and the relation $\hsg=\kappa\ve$
%yield the expansion of $\hJ(\hf)$
%in the form \eqref{eq:hJ_exp_eps} with \eqref{eq:Col_exp}.

\section{Expansions of $\hp_{ij}^\col$ and $\hq_i^\col$ \label{app:hpq_col}}

We will derive the expansions of $\hp_{ij}^{\col}$ and $\hq_{i}^{\col}$ 
on the basis of the expression \eqref{eq:pqcol}.
Since $\hspa$ varies between $0$ and $\hsg$ in \eqref{eq:pqcol}, 
we can use the following expansion, which is similar to that in Appendix~\ref{app:ExpCol}:
%
\begin{align}
&\hg(\bx_{\hspa\bm{\alpha}}^{+},\bx_{(\hspa-\hsg)\bm{\alpha}}^{+})
 \hf_{*}(\bx_{(\hspa-\hsg)\bm{\alpha}}^{+})\hf(\bx_{\hspa\bm{\alpha}}^{+}) \\
=&[\hg^{[0]}(\bx,\bx)+\hsg\hg^{[1]}(\bx,\bx)]\hf_*(\bx)\hf(\bx)
 +\frac{\partial\hg^{[0]}(\bx,\by)}{\partial y_i}\big|_{\by=\bx}(2\hspa-\hsg)\alpha_i\hf_*(\bx)\hf(\bx)\notag\\
 & +\hg^{[0]}(\bx,\bx)\hf(\bx)\frac{\partial \hf_*(\bx)}{\partial x_i}(\hspa-\hsg)\alpha_i
 +\hg^{[0]}(\bx,\bx)\hf_*(\bx)\frac{\partial \hf(\bx)}{\partial x_i}\hspa\alpha_i
 +O(\hsg^2) \notag\\
=&[\mG(\bx)+\hsg\hg^{[1]}(\bx,\bx)]\hf_*(\bx)\hf(\bx)
 +\frac12\frac{\partial\mG(\bx)}{\partial x_i}(2\hspa-\hsg)\alpha_i\hf_*(\bx)\hf(\bx)\notag\\
 & +\mG(\bx)\hf(\bx)\frac{\partial \hf_*(\bx)}{\partial x_i}(\hspa-\hsg)\alpha_i
 +\mG(\bx)\hf_*(\bx)\frac{\partial \hf(\bx)}{\partial x_i}\hspa\alpha_i
 +O(\hsg^2).\notag
\end{align}
%
\noindent
Once this result is substituted into \eqref{eq:pqcol},
the integration with respect to $\hspa$ can be carried out immediately.
Furthermore, using the formulas
%
\begin{equation}
  \int \alpha_i\alpha_j\hV_\alpha^2\theta(\hV_\alpha)d\Omega(\bm{\alpha})
= \frac{4\pi}{15}(\hV_i\hV_j+\frac12\hbV^2\delta_{ij}),
\end{equation}%
\begin{equation}
  \int \alpha_i\alpha_j\alpha_k\hV_\alpha^2\theta(\hV_\alpha)d\Omega(\bm{\alpha})
= \frac{\pi}{12}
  \Big(
  \frac{\hV_i\hV_j\hV_k}{|\hbV|}+|\hbV|(\hV_i\delta_{jk}+\hV_j\delta_{ki}+\hV_k\delta_{ij})
  \Big),
\end{equation}
%
\noindent
the integration with respect to $\bm{\alpha}$ can also be carried out to yield
%
\begin{align}
\hp_{ij}^{\col}= & \frac{\kappa}{2\sqrt{2\pi}}\mG
\int \alpha_{i}\alpha_{j}\hV_{\alpha}^{2}\theta(\hV_{\alpha}) \Big\{ (1+\frac{g^{[1]}}{\mG}\hsg)\hf_*\hf \\
 & +\frac12\hsg(\hf_*\frac{\partial \hf}{\partial x_k}
 -\hf\frac{\partial \hf_*}{\partial x_k})\alpha_k
 \Big\} d\Omega(\bm{\alpha})d\bz_{*}d\bz+O(\hsg^2)
\notag\\
=&\frac{2}{15}\sqrt{\frac{\pi}{2}}\kappa\mG
\int\Big\{
    (\hV_i\hV_j+\frac12\hV^2\delta_{ij})(1+\frac{g^{[1]}}{\mG}\hsg)
    \hf_*\hf 
 \notag\\
 & +\frac{5}{32}\hsg
  \Big(
   \frac{\hV_i\hV_j\hV_k}{\hV}+{\hV}(\hV_i\delta_{jk}+\hV_j\delta_{ki}+\hV_k\delta_{ij})
  \Big)\notag\\
  &\times (\hf_*\frac{\partial \hf}{\partial x_k}
 -\hf\frac{\partial \hf_*}{\partial x_k})
  \Big\} d\bz_{*}d\bz+O(\hsg^2),\notag
\end{align}
\begin{align}
\hq_{i}^{\col}
= & \frac{1}{4\sqrt{2\pi}}\kappa\mG
\int \alpha_{i}[(\hbC+\hbC_{*})\cdot\bm{\alpha}]
     \hV_{\alpha}^{2}\theta(\hV_{\alpha})
  \{(1+\frac{g^{[1]}}{\mG}\hsg)\hf_*\hf \\
 & +\frac12\hsg[\hf_*\frac{\partial \hf}{\partial x_k}
 -\hf\frac{\partial \hf_*}{\partial x_k}]\alpha_k
 \} d\Omega(\bm{\alpha})d\bz_{*}d\bz+O(\hsg^2) \notag \\
= & \frac{1}{15}\sqrt{\frac{\pi}{2}}\kappa\mG
\int (\hC_j+\hC_{*j})\Big\{
    (\hV_i\hV_j+\frac12\hV^2\delta_{ij})(1+\frac{g^{[1]}}{\mG}\hsg)
    \hf_*\hf 
 \notag\\
 & +\frac{5}{32}\hsg
  \Big(
   \frac{\hV_i\hV_j\hV_k}{\hV}+{\hV}(\hV_i\delta_{jk}+\hV_j\delta_{ki}+\hV_k\delta_{ij})
  \Big)\notag\\
  &\times (\hf_*\frac{\partial \hf}{\partial x_k}
 -\hf\frac{\partial \hf_*}{\partial x_k})
  \Big\}  d\bz_{*}d\bz+O(\hsg^2),\notag
\end{align}
%
\noindent
where the argument $\bx$ has been suppressed in the above expressions.
Substitution of the expansion of $\hf$ [i.e., \eqref{eq:f_exp}] 
and the relation $\hsg=\kappa\ve$ finally yields \eqref{eq:hpq_exps}.

\section{Specific form of $\mG$\label{app:g_specf}}
%
In this appendix, we briefly discuss the form of $\mG$ and $\hg^{[1]}$. 
%
Because of the definition \eqref{eq:hg_def},
%
\[
\hg(\bx,\bx)=2\hmS(\hmR(\bx)),\quad
\frac{\partial\hg(\bx,\by)}{\partial y_i}\Big|_{\by=\bx}
=\frac{\partial\hmS(\hmR(\bx))}{\partial x_i}
=\frac{d\hmS(\hmR(\bx))}{d\hmR(\bx)}
 \frac{\partial\hmR(\bx)}{\partial x_i},
\]
%
\noindent
in the bulk away from the boundary.$^2$%
\footnote{$^2$ Note that $\chi_\hD(\bx)$ can be regarded as unity if the position $\bx$ is away from the boundary.}
\noindent
However, since 
\[
\hmR(\bx)=\hr(\bx)+O(\hsg^2),
\]
%
\noindent
by \eqref{eq:hR_def} in the bulk, we have
%
\begin{align}
& \mG(\bx)\big(=\hg^{[0]}(\bx,\bx)\big)
 \equiv\lim_{\hsg\to0}\hg(\bx,\bx)=2\hmS(\hr(\bx)),
\quad \hg^{[1]}(\bx,\bx)=0,\\
& \frac{\partial\hg^{[0]}(\bx,\by)}{\partial y_i}\Big|_{\by=\bx}
= \frac{\partial\hmS(\hr(\bx))}{\partial x_i}
%= \frac12\frac{\partial\hg^{[0]}(\bx,\bx)}{\partial x_i}
= \frac12\frac{\partial\mG(\bx)}{\partial x_i}.
\end{align}
%

In the case of the OEE, 
since $\hg(\bx,\by)$ takes the form
\[
\hg(\bx,\by)= \hmY(\hr(\frac{\bx+\by}{2}))
\Big(\equiv\frac{1}{\sfg_0}\mY(\rho_0\hr(\frac{\bx+\by}{2}))\Big),
\]
%
\noindent
by the definition of \eqref{eq:gY},
the expansion of $\hg$ in terms of $\hsg$ is not necessary, so that
we may put
\begin{align}
& \mG(\bx)\equiv\hg^{[0]}(\bx,\bx)=\hg(\bx,\bx)=\hmY(\hr(\bx)),
\quad \hg^{[1]}(\bx,\bx)=0,\displaybreak[0]\\
& \frac{\partial\hg^{[0]}(\bx,\by)}{\partial y_i}\Big|_{\by=\bx}
= \frac{\partial\hg(\bx,\by)}{\partial y_i}\Big|_{\by=\bx}
= \frac12\frac{\partial\hmY(\hr(\bx))}{\partial x_i},
\end{align}
%
\noindent
again in the bulk away from the boundary.
Hence, 
as far as the EoS is taken to be common,
i.e., $2\hmS(\hr(\bx))$ and $\hmY(\hr(\bx))$ (or $2\mS(\rho(\bX))$ and $\mY(\rho(\bX))$) are identical  (see Sec.~\ref{sec:Eos}),
$\mG$ is also common between the EESM and the OEE.


