 \frac{\hV_\alpha\theta(\hV_\alpha)}{2\sqrt{2\pi}}d\Omega(\bm{\alpha})d\bz_*
 \notag \\
% 
=&\mG
 \int  2\alpha_i\hf^{(0)}\hf_*^{(0)}
  [\frac{\partial}{\partial x_i} \ln\hr
   +\frac{\hC_{*j}^\prime+\hC_{*j}}{\hT}\frac{\partial\hv_j}{\partial x_i} \notag \\
&+(\frac{\hbC_*^2+\hbC_*^{\prime 2}}{2\hT}-\frac32)\frac{\partial}{\partial x_i}\ln\hT] 
  \frac{\hV_\alpha\theta(\hV_\alpha)}{2\sqrt{2\pi}}
