   +\frac{2\hC_{*j}}{\hT}\frac{\partial\hv_j}{\partial x_i}
   +(\frac{\hbC_*^2}{\hT}-\frac32)\frac{\partial}{\partial x_i}\ln\hT \notag \\
&  -\frac{\hV_\alpha\alpha_j}{\hT}(\frac{\partial\hv_j}{\partial x_i}
 +\hC_{*j}\frac{\partial}{\partial x_i}\ln\hT)
  +(\frac{\hV_\alpha^2}{2\hT})\frac{\partial}{\partial x_i}\ln\hT] 
  \frac{\hV_\alpha\theta(\hV_\alpha)}{\sqrt{2\pi}}
  d\Omega(\bm{\alpha})d\bz_*  \notag\\
&  -\frac13\sqrt{\frac{\pi}{2}}\hr\hC_i\hf^{(0)}\frac{\partial \mG}{\partial x_i}
   \notag \\
%
=&\mG
 \int  \hf^{(0)}\hf_*^{(0)}
  [\frac{2\pi}{3}\hV_i\frac{\partial}{\partial x_i} \ln\hr
