  \frac{1}{\hT}(\frac{\partial\hv_j}{\partial x_i}
 +\hC_{*j}\frac{\partial}{\partial x_i}\ln\hT)
 \notag\\
&+\frac{2\pi}{5}\hV_i\hbV^2\frac{1}{2\hT}\frac{\partial}{\partial x_i}\ln\hT] 
  \frac{1}{\sqrt{2\pi}} d\bz_* 
  -\frac13\sqrt{\frac{\pi}{2}}\hr\hC_i\hf^{(0)}\frac{\partial \mG}{\partial x_i}
   \notag \\
%
=&\mG
 \int \hf^{(0)}\hf_*^{(0)}
  [ \frac{4\pi}{3}\hC_{*i}\hC_{*j}\frac{1}{\hT}\frac{\partial\hv_j}{\partial x_i}
%  \notag\\
%&
 -\frac{4\pi}{15}(\hC_{*i}\hC_{*j}+\hC_i\hC_j
 \notag \\
&+\frac12(\hbC_*^2+\hbC^2)\delta_{ij})
  \frac{1}{\hT}\frac{\partial\hv_j}{\partial x_i}
