\section{Derivation of $\hp_{ij}^{\kin(1)}$ and $\hq_i^{\kin(1)}$\label{app:pq_kin1}}

Once $\hf^{(1)}$ is obtained in the form \eqref{eq:hf1_final},
the expressions of $\hp_{ij}^{\kin(1)}$ and $\hq_i^{\kin(1)}$ can be derived essentially by following the procedure
in the case of Boltzmann equation.
Note that the odd and the even part of $\hf^{(1)}$ with respect to $\hbC$ does not contribute to the stress tensor and the heat-flow vector respectively.
Hence, these parts can be omitted from the beginning in the reduction
of the corresponding quantities. Consequently, we have
%
\begin{align}
 \hp_{ij}^{\kin(1)}
=&2\int \hC_i\hC_j\hf^{(1)}d\bz  \\
=&-\frac{1}{\hr\mG}( 1+\frac25\Lambda )
   \sqrt{\hT} {\frac{\partial \hv_k}{\partial x_l}} \notag\\
 &\times \int\frac{2\hC_i\hC_j}{\hT}
    B(\frac{|\hbC|}{\sqrt{\hT}})
           \frac{1}{\hT} (\hC_k\hC_l-\frac13\hbC^2\delta_{kl})
            \hf^{(0)} d\hbC \notag\\
=&-\frac{1}{\hr\mG}( 1+\frac25\Lambda )
   \hT^2{\frac{\partial \hv_k}{\partial x_l}}
   \frac{8\pi}{15}\int_0^\infty Z^6B(Z)\exp(-Z^2)dZ\notag\\
 & \times\frac{\hr}{(\pi\hT)^{3/2}}(\delta_{ik}\delta_{lj}+\delta_{il}\delta_{jk}-\frac23\delta_{ij}\delta_{kl})\notag\\
=&-\frac{1}{\mG}( 1+\frac25\Lambda )
   \gamma_1\sqrt{\hT}\overline{\frac{\partial \hv_i}{\partial x_j}},\notag
\end{align}
%
\noindent
and
\begin{align}
 \hq_i^{\kin(1)}
=&\int\hC_i\hbC^2\hf^{(1)}d\bz   \\
=& -\frac{\sqrt{\hT}}{\hr\mG}(1+\frac35\Lambda )
   \frac{\partial\hT}{\partial x_i}
   \int \frac13(\frac{|\hbC|}{\sqrt{\hT}})^4
       A(\frac{|\hbC|}{\sqrt{\hT}})\hf^{(0)}d\hbC \notag\\
=& -\frac{\sqrt{\hT}}{\mG}\frac{4}{3\sqrt{\pi}}(1+\frac35\Lambda )
   \frac{\partial\hT}{\partial x_i}
   \int_0^\infty Z^6 A(Z) \exp(-Z^2) dZ\notag\\
=& -\frac{1}{\mG}(1+\frac35\Lambda )
    \frac{5}{4}\gamma_2\sqrt{\hT}
   \frac{\partial\hT}{\partial x_i}.\notag
\end{align}


\section{Derivation of $\hp_{ij}^{\col(1)}$ and $\hq_i^{\col(1)}$\label{app:pq_col1}}

We first make a reduction of $\hp_{ij}^{\col(1)}$ from \eqref{eq:hp1}
mainly by using that $\langle \psi_s \hf^{(1)}\rangle=0$ and that $\hf^{(0)}$
is even with respect to $\hbC$:
%
\begin{align}
    \hp_{ij}^{\col(1)}
= & \frac{2}{15}\sqrt{\frac{\pi}{2}}\kappa\mG
    \int \{(\hV_i\hV_j+\frac12\hbV^2\delta_{ij})
          (\hf^{(0)}_*\hf^{(1)}+\hf_*^{(1)}\hf^{(0)}\\
          &+\frac{\kappa\hg^{[1]}}{\mG}\hf_*^{(0)}\hf^{(0)}) \displaybreak[0]       +\frac{5}{32}\kappa
           \Big(\frac{\hV_i\hV_j\hV_k}{|\hbV|}+|\hbV|(\hV_i\delta_{jk}+\hV_j\delta_{ki}\notag\\
           &+\hV_k\delta_{ij})\Big)  (\hf^{(0)}_*\frac{\partial \hf^{(0)}}{\partial x_k}
          -\hf^{(0)}\frac{\partial \hf^{(0)}_*}{\partial x_k})
         \} d\bz_{*}d\bz\notag\displaybreak[0]\\
= & \frac{4}{15}\sqrt{\frac{\pi}{2}}\kappa\mG
    \int (\hC_{*i}\hC_{*j}+\hC_{i}\hC_{j}+\frac12(\hbC_*^2+\hbC^2)\delta_{ij})
           (\hf^{(0)}_*\hf^{(1)}\notag\\
           &\quad+\frac12\frac{\kappa\hg^{[1]}}{\mG}\hf_*^{(0)}\hf^{(0)}) d\bz_{*}d\bz
            +\frac{1}{24}\sqrt{\frac{\pi}{2}}
    \kappa^2\mG
    \int   \Big(\frac{\hV_i\hV_j\hV_k}{|\hbV|}\notag \\
    &\quad+|\hbV|(\hV_i\delta_{jk}+\hV_j\delta_{ki}+\hV_k\delta_{ij})\Big)
            \hf^{(0)}_*\frac{\partial \hf^{(0)}}{\partial x_k}
          d\bz_{*}d\bz\notag\\
\equiv & \hp_{ij}^{\col(1)a}+\hp_{ij}^{\col(1)b}.\notag
\end{align}
%
\noindent
Then, on one hand, the $a$-part is readily transformed as
\begin{align}
    \hp_{ij}^{\col(1)a}
= & \frac{4}{15}\sqrt{\frac{\pi}{2}}\kappa\mG
    \int (\hC_{*i}\hC_{*j}+\hC_{i}\hC_{j}+\frac12(\hbC_*^2+\hbC^2)\delta_{ij})
          (\hf^{(0)}_*\hf^{(1)}  \\
          &+\frac12\frac{\kappa\hg^{[1]}}{\mG}\hf_*^{(0)}\hf^{(0)}) d\bz_{*}d\bz \notag\displaybreak[0]\\
= & \frac{4}{15}\sqrt{\frac{\pi}{2}}\kappa\hr\mG
    \int ( \hC_{i}\hC_{j}+\frac12\hbC^2\delta_{ij}+\frac54\hT\delta_{ij})
    (\hf^{(1)}+\frac12\frac{\kappa\hg^{[1]}}{\mG}\hf^{(0)})d\bz \notag\displaybreak[0]\\
= & \frac{4}{15}\sqrt{\frac{\pi}{2}}\kappa\hr
    \Big(\mG\int \hC_{i}\hC_{j}\hf^{(1)}d\bz 
    +\frac{5}{4}\kappa\hg^{[1]}\hr\hT\delta_{ij}
    \Big)\notag\displaybreak[0]\\
= & \frac{2}{15}\sqrt{\frac{\pi}{2}}\kappa\hr
    \Big(\mG \hp_{ij}^{\mathrm{kin}(1)}
    +\frac{5}{2}\kappa\hg^{[1]}\hr\hT\delta_{ij}
    \Big).\notag
\end{align}
%
\noindent
On the other hand, the $b$-part
needs a change of variables from $(\bz,\bz_*)$ to $(\hbV,\hbU)$
with $\hbV=\hbC_*-\hbC$ and $\hbU=\hbC_*+\hbC$ for further reductions.
Since $d\bz d\bz_*=(1/8)d\hbU d\hbV$, 
it holds that
\begin{align}        
    \hp_{ij}^{\col(1)b}
  =&\frac{1}{24}\sqrt{\frac{\pi}{2}}
    \kappa^2\mG
    \int   \Big(\frac{\hV_i\hV_j\hV_k}{|\hbV|} \\
    &\qquad +|\hbV|(\hV_i\delta_{jk}+\hV_j\delta_{ki}+\hV_k\delta_{ij})\Big)
            \hf^{(0)}_*\frac{\partial \hf^{(0)}}{\partial x_k}
          d\bz_{*}d\bz \notag\displaybreak[0]\\
  =&\frac{1}{192}\sqrt{\frac{\pi}{2}}
    \kappa^2\mG
    \int  \Big(\frac{\hV_i\hV_j\hV_k}{|\hbV|}+|\hbV|(\hV_i\delta_{jk}+\hV_j\delta_{ki}+\hV_k\delta_{ij})\Big) \notag \\
 &          \times\frac{\hr^2}{(\pi\hT)^3} \Big(
               \frac{\partial\ln\hr}{\partial x_k} 
              +\big(
               \frac{(\hbU-\hbV)^2}{4\hT}-\frac32
               \big)
               \frac{\partial\ln\hT}{\partial x_k}\notag\\
 &\qquad
              +\frac{\hU_l-\hV_l}{\hT}\frac{\partial\hv_l}{\partial x_k}
            \Big)\exp(-\frac{\hbV^2+\hbU^2}{2\hT})
          d\hbV d\hbU \notag\displaybreak[0]\\
  =&-\frac{1}{192}\sqrt{\frac{\pi}{2}}
    \kappa^2\mG
    \int  \Big(\frac{\hV_i\hV_j\hV_k}{|\hbV|}+|\hbV|(\hV_i\delta_{jk}+\hV_j\delta_{ki}+\hV_k\delta_{ij})\Big)  \notag \\
 &          \times \frac{\hr^2}{(\pi\hT)^3} 
             \frac{\hV_l}{\hT}\frac{\partial\hv_l}{\partial x_k}
             \exp(-\frac{\hbV^2+\hbU^2}{2\hT})
          d\hbV d\hbU \notag\displaybreak[0]\\
  =&-\frac{\sqrt{\hT}}{12\pi}\kappa^2\hr^2\mG
     \frac{\partial\hv_l}{\partial x_k}
    (\frac{4\pi}{15}+\frac{4\pi}{3})(\delta_{ij}\delta_{kl}+\delta_{ik}\delta_{jl}+\delta_{il}\delta_{jk}) \notag\displaybreak[0]\\
  =&-\frac{2}{15}\sqrt{\hT}\kappa^2\hr^2\mG
     (\overline{\frac{\partial\hv_i}{\partial x_j}}
     +\frac53\frac{\partial\hv_k}{\partial x_k}\delta_{ij}).\notag
\end{align}
%
\noindent
Consequently, since $\hg^{[1]}=0$ for both EESM and OEE (see Appendix~\ref{app:g_specf}), we have
\begin{align}        
    \hp_{ij}^{\col(1)}
& = \frac{2}{15}\sqrt{\frac{\pi}{2}}\kappa\hr\mG
    \hp_{ij}^{\kin(1)} 
    -\frac{2}{15}\sqrt{\hT}\kappa^2\hr^2\mG
     (\overline{\frac{\partial\hv_i}{\partial x_j}}
     +\frac53\frac{\partial\hv_k}{\partial x_k}\delta_{ij})\\
& =  \frac{2}{5}\Lambda \hp_{ij}^{\kin(1)} 
    -\frac{12}{5\pi}\frac{\sqrt{\hT}}{\mG}\Lambda^2
     \overline{\frac{\partial\hv_i}{\partial x_j}}
    -\frac{4}{\pi}\frac{\sqrt{\hT}}{\mG}\Lambda^2
     \frac{\partial\hv_k}{\partial x_k}\delta_{ij},\notag
\end{align}
%
\noindent
which is identical to \eqref{eq:hp_col1_final}.

In the same way, we first transform $\hq_i^{\col(1)}$ from \eqref{eq:hq1} as
\begin{align}
\hq_{i}^{\col(1)}
= & \frac{1}{15}\sqrt{\frac{\pi}{2}}\kappa\mG
\int (\hC_j+\hC_{*j})\Big\{
    (\hV_i\hV_j+\frac12\hbV^2\delta_{ij})
    (\hf_*^{(1)}\hf^{(0)}+\hf_*^{(0)}\hf^{(1)}\\
    & +\frac{\kappa\hg^{[1]}}{\mG}\hf^{(0)}\hf_*^{(0)})
