   \notag \\
   &+\hV_k\delta_{ij})
  \Big) (\hf_*^{(0)}\frac{\partial \hf^{(0)}}{\partial x_k}
 -\hf^{(0)}\frac{\partial \hf_*^{(0)}}{\partial x_k})
  \Big\} d\bz_{*}d\bz \notag \displaybreak[0]\\
= & \frac{2}{15}\sqrt{\frac{\pi}{2}}\kappa\mG
\int (\hC_j+\hC_{*j})
    (\hV_i\hV_j+\frac{\hbV^2}{2}\delta_{ij})
    (\hf_*^{(1)}\hf^{(0)}\notag\\
    &+\frac{\kappa\hg^{[1]}}{2\mG}\hf^{(0)}\hf_*^{(0)}) d\bz_{*}d\bz
     -\frac{1}{48}\sqrt{\frac{\pi}{2}}\kappa^2\mG
\int
  \Big(
   \frac{\hV_i\hV_j\hV_k}{|\hbV|}\notag\\
   &+|\hbV|(\hV_i\delta_{jk}+\hV_j\delta_{ki}+\hV_k\delta_{ij})
  \Big) (\hC_j+\hC_{*j}) \hf^{(0)}\frac{\partial \hf_*^{(0)}}{\partial x_k}
   d\bz_{*}d\bz \notag \\
= & \frac{2}{15}\sqrt{\frac{\pi}{2}}\kappa\mG
\int (\hC_j+\hC_{*j})
    (\hV_i\hV_j+\frac{\hbV^2}{2}\delta_{ij})
    \hf_*^{(1)}\hf^{(0)} d\bz_{*}d\bz\notag\\
    &-\frac{1}{48}\sqrt{\frac{\pi}{2}}\kappa^2\mG
\int
  \Big(
   \frac{\hV_i\hV_j\hV_k}{|\hbV|}+|\hbV|(\hV_i\delta_{jk}+\hV_j\delta_{ki}
   \notag\\
   &+\hV_k\delta_{ij})
  \Big) (\hC_j+\hC_{*j}) \hf^{(0)}\frac{\partial \hf_*^{(0)}}{\partial x_k}
