\equiv & \hq_i^{\col(1)a}+\hq_i^{\col(1)b},\notag
\end{align}
%
\noindent
where the contribution from $\hg^{[1]}$ has already vanished,
irrespective of its value.
The $a$-part is further transformed as
\begin{align}
\hq_i^{\col(1)a}
= &\frac{2}{15}\sqrt{\frac{\pi}{2}}\kappa\mG
   \int (\hC_j+\hC_{*j})
    (\hV_i\hV_j+\frac12\hV^2\delta_{ij})
    \hf^{(1)}_*\hf^{(0)} d\bz_{*}d\bz  \displaybreak[0]\\
= &\frac{2}{15}\sqrt{\frac{\pi}{2}}\kappa\mG
   \int (\hC_j+\hC_{*j})
    [(\hC_{*i}-\hC_i)(\hC_{*j}-\hC_j)\notag \\
    & \quad +\frac12(\hbC_*-\hbC)^2\delta_{ij}]
    \hf^{(1)}_*\hf^{(0)} d\bz_{*}d\bz \notag\displaybreak[0]\\
= &\frac{2}{15}\sqrt{\frac{\pi}{2}}\kappa\mG
   \int 
    [(\hC_{*i}-\hC_i)(\hbC_*^2-\hbC^2)\notag \\
    &\quad +\frac12(\hC_i+\hC_{*i})(\hbC_*-\hbC)^2]
    \hf^{(1)}_*\hf^{(0)} d\bz_{*}d\bz \notag\displaybreak[0]\\
= &\frac{2}{15}\sqrt{\frac{\pi}{2}}\kappa\mG
   \int 
    [\hC_{*i}(\hbC_*^2-\hbC^2)\notag \\
    &\quad +\frac12(\hC_i+\hC_{*i})(\hbC_*^2+\hbC^2-2\hC_{*l}\hC_l)]
    \hf^{(1)}_*\hf^{(0)} d\bz_{*}d\bz \notag\displaybreak[0]\\
= &\frac{2}{15}\sqrt{\frac{\pi}{2}}\kappa\mG
   \int 
    [\hC_{*i}(\hbC_*^2-\hbC^2)+\frac12\hC_i(-2\hC_{*l}\hC_l)\notag \\
    &\quad +\frac12\hC_{*i}(\hbC_*^2+\hbC^2)]
    \hf^{(1)}_*\hf^{(0)} d\bz_{*}d\bz \notag\displaybreak[0]\\
= &\frac{2}{15}\sqrt{\frac{\pi}{2}}\kappa\mG
   \int 
    [\hC_{*i}\hbC_*^2+\frac12\hC_{*i}\hbC_*^2]
    \hf^{(1)}_*\hf^{(0)} d\bz_{*}d\bz \notag\displaybreak[0]\\
= &\frac{1}{5}\sqrt{\frac{\pi}{2}}\kappa\mG
   \int \hC_{*i}\hbC_*^2
    \hf^{(1)}_*\hf^{(0)} d\bz_{*}d\bz \notag\displaybreak[0]\\
= &\frac{1}{5}\sqrt{\frac{\pi}{2}}\kappa\hr\mG\hq_i^{\kin(1)}
   =\frac{3}{5}\Lambda \hq_i^{\kin(1)},\notag
\end{align}
%
\noindent
while the $b$-part is, again by the change of variables, further reduced to
\begin{align}
\hq_i^{\col(1)b}
=&-\frac{1}{48}\sqrt{\frac{\pi}{2}}\kappa^2\mG
\int
  \Big(
   \frac{\hV_i\hV_j\hV_k}{|\hbV|}+|\hbV|(\hV_i\delta_{jk}+\hV_j\delta_{ki}+\hV_k\delta_{ij})
  \Big) \\
  &\quad \times  \hU_j\hf^{(0)}\frac{\partial \hf_*^{(0)}}{\partial x_k}
   d\bz_{*}d\bz \notag \displaybreak[0]\\
= & -\frac{1}{48}\sqrt{\frac{\pi}{2}}\kappa^2\mG
\int 
 (\frac{\hV_i\hV_j\hV_k}{|\hbV|}+|\hbV|(\hV_i\delta_{jk}+\hV_j\delta_{ik}+\hV_k\delta_{ij}))\notag\\
&\quad\times \hU_j
 \frac{\hr^2}{\pi^3}\exp(-\frac{\hbV^2+\hbU^2}{2\hT}) \big(
  \frac{\hU_l}{\hT}\frac{\partial \hv_l}{\partial x_k}
 +\frac{\hV_l\hU_l}{2\hT}\frac{\partial \ln\hT}{\partial x_k}\big)
  \frac{d\hbU d\hbV}{8\hT^3} \notag\displaybreak[0]\\
= & -\frac{1}{48}\sqrt{\frac{\pi}{2}}\kappa^2\mG
\int \hU_j
 \frac{\hr^2}{\pi^3}\exp(-\frac{\hbV^2+\hbU^2}{2\hT})
 (\frac{\hV_i\hV_j\hV_k}{|\hbV|} \notag\\
&\quad
 +|\hbV|(\hV_i\delta_{jk}+\hV_j\delta_{ik}+\hV_k\delta_{ij}))
  \frac{\hV_l\hU_l}{2\hT}\frac{\partial \ln\hT}{\partial x_k}
  \frac{d\hbU d\hbV}{8\hT^3} \notag\displaybreak[0]\\
= & -\frac{\sqrt{\pi}}{48}\kappa^2\mG
\int 
 \frac{\hr^2}{\pi^{3/2}}\exp(-\frac{\hbV^2}{2\hT}) \notag\\
&\times 
 (\frac{\hV_i\hV_j\hV_k}{|\hbV|}+|\hbV|(\hV_i\delta_{jk}+\hV_j\delta_{ik}+\hV_k\delta_{ij}))
  \hV_j\frac{\partial \ln\hT}{\partial x_k}
  \frac{d\hbV}{8\hT^{3/2}} \notag\displaybreak[0]\\
= & -\frac{1}{48\pi}\kappa^2\mG
  \int \hr^2\exp(-\frac{\hbV^2}{2\hT}) 
  |\hbV|(3\hV_i\hV_k+\hbV^2\delta_{ik})
  \frac{\partial \ln\hT}{\partial x_k}
  \frac{d\hbV}{8\hT^{3/2}} \notag\displaybreak[0]\\
= & -\frac{1}{6}\kappa^2\hr^2\mG\hT^{3/2}
  \frac{\partial \ln\hT}{\partial x_i} 
= -\frac{3}{\pi}\frac{\Lambda^2}{\mG}\sqrt{\hT}
  \frac{\partial \hT}{\partial x_i}.\notag
\end{align}
%
\noindent
Consequently, we have
%
\begin{equation}
\hq_i^{\col(1)}
=\frac{3}{5}\Lambda \hq_i^{\kin(1)}
-\frac{3}{\pi}\frac{\Lambda^2}{\mG}\sqrt{\hT}
  \frac{\partial \hT}{\partial x_i},
\end{equation}
%
\noindent
which is identical to \eqref{eq:hq_col1final}.

