\section{Extension to the Enskog--Vlasov equation}

In the case of the Enskog--Vlasov equation, an external force term $F_{i}{\partial f}/{\partial\xi_{i}}$ is added on the left-hand side of \eqref{eq:2.1}, where
\begin{equation}
F_{i}=-\int_{D}\frac{\partial}{\partial X_{i}}\Phi(|\bm{Y}-\bm{X}|)\rho(\bm{Y})d\bm{Y},\label{Vlasov}
\end{equation}
\noindent
and $\Phi$ is the attractive isotropic force potential between molecules. 

The contribution of the Vlasov term to the momentum conservation 
is written as
\begin{equation}
\langle \xi_j F_{i}\frac{\partial f}{\partial\xi_{i}}\rangle
=-\rho F_{j}
=\rho(\bm{X}) \int_{D}\frac{\partial}{\partial X_{j}}\Phi(|\bm{Y}-\bm{X}|)\rho(\bm{Y})d\bm{Y},
\end{equation}
\noindent
for $\bm{X}\in D$.
Since $\bm{Y}$ can be expressed in two ways $\bm{Y}=\bm{X}\pm\bm{r}$,
it follows that 
\begin{align}
 &\rho(\bm{X}) \int_{D}\frac{\partial}{\partial X_{j}}\Phi(|\bm{Y}-\bm{X}|)\rho(\bm{Y})d\bm{Y} \notag \\
=&\frac12 \int \frac{r_j}{|\bm{r}|}\Phi^\prime(|\bm{r}|)
[\rho(\bm{X})\rho(\bm{X}_{\bm{r}}^{-})\chi_D(\bm{X}_{\bm{r}}^{-})\chi_D(\bm{X})
-\rho(\bm{X})\rho(\bm{X}_{\bm{r}}^{+})\chi_D(\bm{X}_{\bm{r}}^{+})\chi_D(\bm{X})]
 d\bm{r} \notag \displaybreak[0]\\
=&-\frac12 \int \frac{r_j}{|\bm{r}|}\Phi^\prime(|\bm{r}|)
\int_0^1 \frac{\partial}{\partial \spa}[\rho(\bm{X}^+_{(\spa-1)\bm{r}})\chi_D(\bm{X}^+_{(\spa-1)\bm{r}})
\rho(\bm{X}^+_{\spa\bm{r}})\chi_D(\bm{X}^+_{\spa\bm{r}})]
d\spa d\bm{r} \notag \displaybreak[0] \\
=&-\frac12 \int \frac{r_j}{|\bm{r}|}\Phi^\prime(|\bm{r}|)
\int_0^1 r_i\frac{\partial}{\partial X_i}[\rho(\bm{X}^+_{(\spa-1)\bm{r}})\chi_D(\bm{X}^+_{(\spa-1)\bm{r}})
\rho(\bm{X}^+_{\spa\bm{r}})\chi_D(\bm{X}^+_{\spa\bm{r}})]
d\spa d\bm{r} \notag \displaybreak[0] \\
=&-\frac12 \frac{\partial}{\partial X_i}
\int \frac{r_ir_j}{|\bm{r}|}\Phi^\prime(|\bm{r}|)
\int_0^1 \rho(\bm{X}^+_{(\spa-1)\bm{r}})\chi_D(\bm{X}^+_{(\spa-1)\bm{r}})
\rho(\bm{X}^+_{\spa\bm{r}})\chi_D(\bm{X}^+_{\spa\bm{r}})
d\spa d\bm{r}, 
\end{align}
\noindent
where $\Phi^\prime(x)=d\Phi(x)/dx$, which is non-negative because $\Phi$ is the attractive potential.

Similarly,
the contribution to the energy conservation is written as
\begin{align}
\langle\frac{1}{2}\bm{\xi}^{2}F_{i}\frac{\partial f}{\partial\xi_{i}}\rangle
=& -\rho v_{i}F_{i} \notag \\
=&\rho(\bm{X}) v_i(\bm{X})
  \int_{D}\frac{\partial}{\partial X_{i}}\Phi(|\bm{Y}-\bm{X}|)\rho(\bm{Y})d\bm{Y} \notag\displaybreak[0] \\
=&\frac{\partial}{\partial X_{i}}
[\rho(\bm{X}) v_i(\bm{X})
  \int_{D}\Phi(|\bm{Y}-\bm{X}|)\rho(\bm{Y})d\bm{Y}] 
 -\frac{\partial\rho v_i}{\partial X_{i}}
  \int_{D}\Phi(|\bm{Y}-\bm{X}|)\rho(\bm{Y})d\bm{Y}
  \notag \displaybreak[0]\\
=&\frac{\partial}{\partial X_{i}}
[\rho(\bm{X}) v_i(\bm{X})
  \int_{D}\Phi(|\bm{Y}-\bm{X}|)\rho(\bm{Y})d\bm{Y}] 
 +\frac{\partial\rho(\bm{X})}{\partial t}
  \int_{D}\Phi(|\bm{Y}-\bm{X}|)\rho(\bm{Y})d\bm{Y}
  \notag \displaybreak[0]\\
=&\frac{\partial}{\partial X_{i}}
[\rho(\bm{X}) v_i(\bm{X})
  \int_{D}\Phi(|\bm{Y}-\bm{X}|)\rho(\bm{Y})d\bm{Y}] \notag\\
& +\frac12\int_{D}\Phi(|\bm{Y}-\bm{X}|)[\frac{\partial\rho(\bm{X})}{\partial t}\rho(\bm{Y})-\frac{\partial\rho(\bm{Y})}{\partial t}\rho(\bm{X})]d\bm{Y}
  \notag \\
& +\frac12\int_{D}\Phi(|\bm{Y}-\bm{X}|)[\frac{\partial\rho(\bm{X})}{\partial t}\rho(\bm{Y})+\frac{\partial\rho(\bm{Y})}{\partial t}\rho(\bm{X})]d\bm{Y}
  \notag\displaybreak[0] \\
=&\frac{\partial}{\partial X_{i}}
[\rho(\bm{X}) v_i(\bm{X})
  \int_{D}\Phi(|\bm{Y}-\bm{X}|)\rho(\bm{Y})d\bm{Y}] \notag\\
& +\frac12\int_{\mathbb{R}^3} \Phi(|\bm{r}|)[\frac{\partial\rho(\bm{X})}{\partial t}\rho(\bm{X}^+_{\bm{r}})\chi_D(\bm{X})\chi_D(\bm{X}^+_{\bm{r}})-\frac{\partial\rho(\bm{X}^-_{\bm{r}})}{\partial t}\rho(\bm{X})\chi_D(\bm{X})\chi_D(\bm{X}^-_{\bm{r}})]d\bm{r}
  \notag \\
 & +\frac12\frac{\partial}{\partial t}
  \int_{D}\Phi(|\bm{Y}-\bm{X}|)\rho(\bm{X})\rho(\bm{Y})d\bm{Y}
  \notag \displaybreak[0]\\
=&\frac{\partial}{\partial X_{i}}
[\rho(\bm{X}) v_i(\bm{X})
  \int_{D}\Phi(|\bm{Y}-\bm{X}|)\rho(\bm{Y})d\bm{Y}] \notag\\
& +\frac12\int_{\mathbb{R}^3} \int_0^1\Phi(|\bm{r}|)\frac{\partial}{\partial\spa}
[\frac{\partial\rho(\bm{X}^+_{(\spa-1)\bm{r}})}{\partial t}\rho(\bm{X}^+_{\spa\bm{r}})\chi_D(\bm{X}^+_{(\spa-1)\bm{r}})\chi_D(\bm{X}^+_{\spa\bm{r}})]d\spa d\bm{r}
  \notag \\
 & +\frac12\frac{\partial}{\partial t}
  \int_{D}\Phi(|\bm{Y}-\bm{X}|)\rho(\bm{X})\rho(\bm{Y})d\bm{Y}
  \notag\displaybreak[0] \\
=&\frac{\partial}{\partial X_{i}}
[\rho(\bm{X}) v_i(\bm{X})
  \int_{D}\Phi(|\bm{Y}-\bm{X}|)\rho(\bm{Y})d\bm{Y} \notag\\
& +\frac12\int_{\mathbb{R}^3} \int_0^1 r_i \Phi(|\bm{r}|)
\frac{\partial\rho(\bm{X}^+_{(\spa-1)\bm{r}})}{\partial t}\rho(\bm{X}^+_{\spa\bm{r}})\chi_D(\bm{X}^+_{(\spa-1)\bm{r}})\chi_D(\bm{X}^+_{\spa\bm{r}}) d\spa d\bm{r} ]
  \notag \\
 & +\frac12\frac{\partial}{\partial t}
  \int_{D}\Phi(|\bm{Y}-\bm{X}|)\rho(\bm{X})\rho(\bm{Y})d\bm{Y}.
\end{align}
\noindent
These results lead to the concept of additional contributions
to the stress tensor, the heat-flow vector, and the internal energy  from the Vlasov term. If respectively denoted by $p_{ij}^{(v)}$,  $q_i^{(v)}$, and $e^{(v)}$, they are expressed as follows:
\begin{subequations}
\begin{align}
 p_{ij}^{(v)}=&-\frac12
\int_{\mathbb{R}^3} \frac{r_ir_j}{|\bm{r}|}\Phi^\prime(|\bm{r}|)
\int_0^1 \rho(\bm{X}^+_{(\spa-1)\bm{r}})\chi_D(\bm{X}^+_{(\spa-1)\bm{r}})
\rho(\bm{X}^+_{\spa\bm{r}})\chi_D(\bm{X}^+_{\spa\bm{r}})
d\spa d\bm{r}, \label{eq:pijV}\displaybreak[0]\\
 q_{i}^{(v)}=&\frac12
\int_{\mathbb{R}^3} r_i\Phi(|\bm{r}|)
\int_0^1 \frac{\partial\rho(\bm{X}^+_{(\spa-1)\bm{r}})}{\partial t}\chi_D(\bm{X}^+_{(\spa-1)\bm{r}})
\rho(\bm{X}^+_{\spa\bm{r}})\chi_D(\bm{X}^+_{\spa\bm{r}})
d\spa d\bm{r} \notag\\
&+\frac12 v_j\int_{\mathbb{R}^3} \int \frac{r_ir_j}{|\bm{r}|}\Phi^\prime(|\bm{r}|)
\int_0^1 \rho(\bm{X}^+_{(\spa-1)\bm{r}})\chi_D(\bm{X}^+_{(\spa-1)\bm{r}})
\rho(\bm{X}^+_{\spa\bm{r}})\chi_D(\bm{X}^+_{\spa\bm{r}})
d\spa d\bm{r} \notag \\
&+\frac12 \rho v_i \int_D \Phi(|\bm{X}-\bm{Y}|)\rho(\bm{Y})d\bm{Y}, \displaybreak[0]\\
 e^{(v)}=&\frac{1}{2}\int_D \Phi(|\bm{Y}-\bm{X}|)\rho(\bm{Y})d\bm{Y}.
\end{align}
\end{subequations}
\noindent
Hence, 
by redefining the stress tensor, heat-vector, and internal energy as
\begin{equation}
p_{ij}=p_{ij}^{\kin}+p_{ij}^{\col}+p_{ij}^{(v)},\quad
q_i=q_i^{\kin}+q_i^{\col}+q_i^{(v)},\quad
e=e+e^{(v)},\label{eq:kin+col+vl}
\end{equation}
\noindent
\eqref{eq:mom_div} and \eqref{eq:eng_div} are recovered and form the usual system of the conservation equations, together with the continuity equation \eqref{eq:continuity} that remains unchanged.
\cite{fn:anglmom}

In the uniform equilibrium state in the bulk,
$p_{ij}^{(v)}$ and $e^{(v)}$ are reduced to
\begin{subequations}
\begin{align}
& p_{ij}^{(v)}=-\frac{2\pi}{3}\rho^2
\int_0^\infty {x}^3 \Phi^\prime(x) dx\delta_{ij},\displaybreak[0] \\
& e^{(v)}=2\pi\rho \int_0^\infty x^2\Phi(x) dx,
\end{align}
\end{subequations}
\noindent
and thus the attractive part $p^{(v)}$ defined by
\begin{equation}
p^{(v)}=-a\rho^2,\quad
a\equiv \frac{2\pi}{3} \int_0^\infty x^3 \Phi^\prime(x) dx (>0),
\end{equation}
\noindent
is added to the right-hand side of the equation of state,
e.g., \eqref{eq:EoSvdW} and \eqref{eq:EoSCS}.
In this way, the attractive part of the equation of state, if exists,
is recovered by the Vlasov term.
Incidentally, as far as $x^3\Phi(x)=0$ for $x=0$ and $x\to\infty$,
$e^{(v)}$ can be rewritten as $e^{(v)}=-a\rho$
and this is consistent with the equilibrium-thermodynamic relation
$e=e_\mathrm{ideal}+\int (p-T\partial p/\partial T)/\rho^2 d\rho$,
where $e_\mathrm{ideal}=(3/2)RT$ is the internal energy of ideal monatomic gases.

