\section*{Appendix}
For a sample $\tilde y=(y_1,\dots,y_n)$ of size $n$, the log-likelihood function for the negative binomial regression model is proportional to
\begin{eqnarray}
\ell(\tilde y;r,\pmb{\beta}) & \propto & \sum_{i=1}^{n}\left\{\log\Gamma(r^{-1}+y_i)-(r^{-1}+y_i)\log(1+r\theta_i(\pmb{x}))+y_i\left[\log r+\log\theta_i(\pmb{x})\right]\right\}\nonumber\\
&& -n \log\Gamma(r^{-1}).
\label{loglike}
\end{eqnarray}

For the hurdle model the log-likelihood function is given by,
\begin{eqnarray}
\ell(\tilde y;r,\pmb{\beta},\pmb{\delta}) &=& \sum_{i=1}^{n}\left\{I_{y_i=0}\log(\phi(\pmb{x}))+I_{y_i>0}\log(1-\phi(\pmb{x}))-I_{y_i>0}\log(1-p(0|\pmb{x}))\right\}\nonumber\\
&&+\sum_{i=1}^{n}I_{y_i>0}\left\{\log\Gamma(r^{-1}+y_i)-(r^{-1}+y_i)\log(1+r\theta_i(\pmb{x}))\right.\nonumber\\
&& \left.+y_i\left[\log r+\log\theta_i(\pmb{x})\right]\right\},\label{loglhm}
\end{eqnarray}
where $I$ is the indicator function, $I_A(z)=1$, if $x\in A$ and 0 otherwise.


The NB model's expression for deviance is given by,
\begin{equation}
d_i^2=
\left\{
\begin{array}{lr}
2\left[y_i\log\left(\frac{y_i}{\theta_i}\right)-\left(y_i+r^{-1}\right)\log\left(\frac{1+r y_i}{1+r\theta_i}\right)\right],\quad y_i>0,\\
2 r^{-1}\ln(1+r\theta_i),\quad y_i=0.
\end{array}
\right.
\label{dnb}
\end{equation}

